(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("demosthenes-private-1-e", [{"sp": "HDR", "t": "Λόγοι ἰδιωτικοί ΚΖʹ–Μʹ"}, {"sp": "HDR", "t": "Κατὰ Ἀφόβου ἐπιτροπῆς Αʹ", "st": "27"}, {"sp": "N", "t": "εἰ μὲν ἐβούλετ’ Ἄφοβος, ὦ ἄνδρες δικασταί, τὰ δίκαια ποιεῖν ἢ περὶ ὧν διεφερόμεθα τοῖς οἰκείοις ἐπιτρέπειν, οὐδὲν ἂν ἔδει δικῶν οὐδὲ πραγμάτων· ἀπέχρη γὰρ ἂν τοῖς ὑπ’ ἐκείνων γνωσθεῖσιν ἐμμένειν, ὥστε μηδεμίαν ἡμῖν εἶναι πρὸς τοῦτον διαφοράν. ἐπειδὴ δ’ οὗτος τοὺς μὲν σαφῶς εἰδότας τὰ ἡμέτερ’ ἔφυγε μηδὲν διαγνῶναι περὶ αὐτῶν, εἰς δ’ ὑμᾶς τοὺς οὐδὲν τῶν ἡμετέρων ἀκριβῶς ἐπισταμένους ἐλήλυθεν, ἀνάγκη ἐστὶν ἐν ὑμῖν παρ’ αὐτοῦ πειρᾶσθαι τῶν δικαίων τυγχάνειν.", "st": "27.1"}, {"sp": "N", "t": "οἶδα μὲν οὖν, ὦ ἄνδρες δικασταί, ὅτι πρὸς ἄνδρας καὶ λέγειν ἱκανοὺς καὶ παρασκευάσασθαι δυναμένους χαλεπόν ἐστιν εἰς ἀγῶνα καθίστασθαι περὶ τῶν ὄντων ἁπάντων, ἄπειρον ὄντα παντάπασι πραγμάτων διὰ τὴν ἡλικίαν· ὅμως δέ, καίπερ πολὺ τούτων καταδεέστερος ὤν, πολλὰς ἐλπίδας ἔχω καὶ παρ’ ὑμῖν τεύξεσθαι τῶν δικαίων καὶ μέχρι γε τοῦ τὰ γεγενημένα διεξελθεῖν καὶ αὐτὸς ἀρκούντως ἐρεῖν, ὥσθ’ ὑμᾶς μήτ’ ἀπολειφθῆναι τῶν πραγμάτων μηδὲ καθ’ ἓν μήτ’ ἀγνοῆσαι περὶ ὧν δεήσει τὴν ψῆφον ἐνεγκεῖν.", "st": "27.2"}, {"sp": "N", "t": "δέομαι δ’ ὑμῶν, ὦ ἄνδρες δικασταί, μετ’ εὐνοίας τέ μου ἀκοῦσαι, κἂν ἠδικῆσθαι δοκῶ, βοηθῆσαί μοι τὰ δίκαια. ποιήσομαι δ’ ὡς ἂν δύνωμαι διὰ βραχυτάτων τοὺς λόγους. ὅθεν οὖν ῥᾷστα μαθήσεσθε περὶ αὐτῶν, ἐντεῦθεν ὑμᾶς καὶ ἐγὼ πρῶτον πειράσομαι διδάσκειν.", "st": "27.3"}, {"sp": "N", "t": "Δημοσθένης γὰρ οὑμὸς πατήρ, ὦ ἄνδρες δικασταί, κατέλιπεν οὐσίαν μὲν σχεδὸν τεττάρων καὶ δέκα ταλάντων, ἐμὲ δ’ ἕπτ’ ἐτῶν ὄντα καὶ τὴν ἀδελφὴν πέντε, ἔτι δὲ τὴν ἡμετέραν μητέρα πεντήκοντα μνᾶς εἰς τὸν οἶκον εἰσενηνεγμένην. βουλευσάμενος δὲ περὶ ἡμῶν, ὅτ’ ἔμελλε τελευτᾶν, ἅπαντα ταῦτ’ ἐνεχείρισεν Ἀφόβῳ τε τουτῳὶ καὶ Δημοφῶντι τῷ Δήμωνος υἱεῖ, τούτοιν μὲν ἀδελφιδοῖν ὄντοιν, τῷ μὲν ἐξ ἀδελφοῦ, τῷ δ’ ἐξ ἀδελφῆς γεγονότοιν, ἔτι δὲ Θηριππίδῃ τῷ Παιανιεῖ, γένει μὲν οὐδὲν προσήκοντι, φίλῳ δ’ ἐκ παιδὸς ὑπάρχοντι.", "st": "27.4"}, {"sp": "N", "t": "κἀκείνῳ μὲν ἔδωκεν ἐκ τῶν ἐμῶν ἑβδομήκοντα μνᾶς καρπώσασθαι τοσοῦτον χρόνον, ἕως ἐγὼ ἀνὴρ εἶναι δοκιμασθείην, ὅπως μὴ δι’ ἐπιθυμίαν χρημάτων χεῖρόν τι τῶν ἐμῶν διοικήσειεν· Δημοφῶντι δὲ τὴν ἐμὴν ἀδελφὴν καὶ δύο τάλαντ’ εὐθὺς ἔδωκεν ἔχειν, αὐτῷ δὲ τούτῳ τὴν μητέρα τὴν ἐμὴν καὶ προῖκ’ ὀγδοήκοντα μνᾶς, καὶ τὴν οἰκίαν ⟨οἰκεῖν⟩ καὶ σκεύεσι χρῆσθαι τοῖς ἐμοῖς, ἡγούμενος, καὶ τούτους ἔτ’ οἰκειοτέρους εἴ μοι ποιήσειεν, οὐκ ἂν χεῖρόν μ’ ἐπιτροπευθῆναι ταύτης τῆς οἰκειότητος προσγενομένης.", "st": "27.5"}, {"sp": "N", "t": "λαβόντες δ’ οὗτοι ταῦτα πρῶτον σφίσιν αὐτοῖς ἐκ τῶν χρημάτων, καὶ τὴν ἄλλην οὐσίαν ἅπασαν διαχειρίσαντες, καὶ δέκ’ ἔτη ἡμᾶς ἐπιτροπεύσαντες, τὰ μὲν ἄλλα πάντ’ ἀπεστερήκασιν, τὴν οἰκίαν δὲ καὶ ἀνδράποδα τέτταρα καὶ δέκα καὶ ἀργυρίου μνᾶς τριάκοντα, μάλιστα σύμπαντα ταῦτ’ εἰς ἑβδομήκοντα μνᾶς παραδεδώκασι.", "st": "27.6"}, {"sp": "N", "t": "καὶ τὸ μὲν κεφάλαιον τῶν ἀδικημάτων, ὡς ἂν συντομώτατ’ εἴποι τις, τοῦτ’ ἔστιν, ὦ ἄνδρες δικασταί· τὸ δὲ πλῆθος τῆς οὐσίας ὅτι τοῦτ’ ἦν τὸ καταλειφθέν, μέγιστοι μὲν αὐτοὶ μάρτυρές μοι γεγόνασιν· εἰς γὰρ τὴν συμμορίαν ὑπὲρ ἐμοῦ συνετάξαντο κατὰ τὰς πέντε καὶ εἴκοσι μνᾶς πεντακοσίας δραχμὰς εἰσφέρειν, ὅσονπερ Τιμόθεος ὁ Κόνωνος καὶ οἱ τὰ μέγιστα κεκτημένοι τιμήματ’ εἰσέφερον· δεῖ δὲ καὶ καθ’ ἕκαστον ὑμᾶς ἀκοῦσαι τά τ’ ἐνεργὰ αὐτῶν καὶ ὅσ’ ἦν ἀργὰ καὶ ὅσου ἦν ἄξι’ ἕκαστα. ταῦτα γὰρ μαθόντες ἀκριβῶς εἴσεσθε, ὅτι τῶν πώποτ’ ἐπιτροπευσάντων οὐδένες ἀναιδέστερον οὐδὲ περιφανέστερον ἢ οὗτοι τὰ ἡμέτερα διηρπάκασιν.", "st": "27.7"}, {"sp": "N", "t": "πρῶτον μὲν οὖν ὡς συνετιμήσανθ’ ὑπὲρ ἐμοῦ ταύτην τὴν εἰσφορὰν εἰς τὴν συμμορίαν, παρέξομαι τούτων μάρτυρας, ἔπειθ’ ὅτι οὐ πένητα κατέλιπέν μ’ ὁ πατὴρ οὐδ’ ἑβδομήκοντα μνῶν οὐσίαν κεκτημένον, ἀλλὰ τοσαύτην ὅσην οὐδ’ αὐτοὶ οὗτοι ἀποκρύψασθαι διὰ τὸ μέγεθος πρὸς τὴν πόλιν ἐδυνήθησαν. καί μοι ἀναγίγνωσκε λαβὼν ταύτην τὴν μαρτυρίαν.", "st": "27.8"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "27.8"}, {"sp": "N", "t": "δῆλον μὲν τοίνυν καὶ ἐκ τούτων ἐστὶν τὸ πλῆθος τῆς οὐσίας. πεντεκαίδεκα ταλάντων γὰρ τρία τάλαντα τίμημα· ταύτην ἠξίουν εἰσφέρειν τὴν εἰσφοράν. ἔτι δ’ ἀκριβέστερον εἴσεσθε τὴν οὐσίαν αὐτὴν ἀκούσαντες· ὁ γὰρ πατήρ, ὦ ἄνδρες δικασταί, κατέλιπεν δύ’ ἐργαστήρια, τέχνης οὐ μικρᾶς ἑκάτερον, μαχαιροποιοὺς μὲν τριάκοντα καὶ δύ’ ἢ τρεῖς, ἀνὰ πέντε μνᾶς καὶ ἕξ, τοὺς δ’ οὐκ ἐλάττονος ἢ τριῶν μνῶν ἀξίους, ἀφ’ ὧν τριάκοντα μνᾶς ἀτελεῖς ἐλάμβανεν τοῦ ἐνιαυτοῦ τὴν πρόσοδον, κλινοποιοὺς δ’ εἴκοσι τὸν ἀριθμόν, τετταράκοντα μνῶν ὑποκειμένους, οἳ δώδεκα μνᾶς ἀτελεῖς αὐτῷ προσέφερον, ἀργυρίου δ’ εἰς τάλαντον ἐπὶ δραχμῇ δεδανεισμένου, οὗ τόκος ἐγίγνετο τοῦ ἐνιαυτοῦ ἑκάστου πλεῖν ἢ ἑπτὰ μναῖ.", "st": "27.9"}, {"sp": "N", "t": "καὶ ταῦτα μὲν ἐνεργὰ κατέλιπεν, ὡς καὶ αὐτοὶ οὗτοι ὁμολογήσουσιν· ὧν γίγνεται τοῦ μὲν ἀρχαίου κεφάλαιον τέτταρα τάλαντα καὶ πεντακισχίλιαι, τὸ δ’ ἔργον αὐτῶν πεντήκοντα μναῖ τοῦ ἐνιαυτοῦ ἑκάστου. χωρὶς δὲ τούτων ἐλέφαντα μὲν καὶ σίδηρον, ὃν κατηργάζοντο, καὶ ξύλα κλίνει’ εἰς ὀγδοήκοντα μνᾶς ἄξια, κηκῖδα δὲ καὶ χαλκὸν ἑβδομήκοντα μνῶν ἐωνημένα, ἔτι δ’ οἰκίαν τρισχιλίων, ἔπιπλα δὲ καὶ ἐκπώματα καὶ χρυσία καὶ ἱμάτια, τὸν κόσμον τῆς μητρός, ἄξια σύμπαντα ταῦτ’ εἰς μυρίας δραχμάς, ἀργυρίου δ’ ἔνδον ὀγδοήκοντα μνᾶς.", "st": "27.10"}, {"sp": "N", "t": "καὶ ταῦτα μὲν οἴκοι κατέλιπεν πάντα, ναυτικὰ δ’ ἑβδομήκοντα μνᾶς, ἔκδοσιν παρὰ Ξούθῳ, τετρακοσίας δὲ καὶ δισχιλίας ἐπὶ τῇ τραπέζῃ τῇ Πασίωνος, ἑξακοσίας δ’ ἐπὶ τῇ Πυλάδου, παρὰ Δημομέλει δὲ τῷ Δήμωνος υἱεῖ χιλίας καὶ ἑξακοσίας, κατὰ διακοσίας δὲ καὶ τριακοσίας ὁμοῦ τι τάλαντον διακεχρημένον. καὶ τούτων αὖ τῶν χρημάτων τὸ κεφάλαιον πλέον ἢ ὀκτὼ τάλαντα καὶ πεντήκοντα μναῖ γίγνονται. συμπάντων δ’ εἰς τέτταρα καὶ δέκα τάλανθ’ εὑρήσετε σκοποῦντες.", "st": "27.11"}, {"sp": "N", "t": "καὶ τὸ μὲν πλῆθος τῆς οὐσίας τοῦτ’ ἦν τὸ καταλειφθέν, ὦ ἄνδρες δικασταί. ὅσα δ’ αὐτῆς διακέκλεπται καὶ ὅσ’ ἰδίᾳ ἕκαστος εἴληφεν καὶ ὁπόσα κοινῇ πάντες ἀποστεροῦσιν, οὐκ ἐνδέχεται πρὸς ταὐτὸ ὕδωρ εἰπεῖν, ἀλλ’ ἀνάγκη χωρὶς ἕκαστον διελεῖν ἐστίν. ἃ μὲν οὖν Δημοφῶν ἢ Θηριππίδης ἔχουσι τῶν ἐμῶν, τότ’ ἐξαρκέσει περὶ αὐτῶν εἰπεῖν, ὅταν κατ’ αὐτῶν τὰς γραφὰς ἀπενέγκωμεν· ἃ δὲ τοῦτον ἔχοντ’ ἐξελέγχουσιν ἐκεῖνοι καὶ ἐγὼ οἶδ’ αὐτὸν εἰληφότα, περὶ τούτων ἤδη ποιήσομαι τοὺς λόγους πρὸς ὑμᾶς. πρῶτον μὲν οὖν ὡς ἔχει τὴν προῖκα, τὰς ὀγδοήκοντα μνᾶς, τοῦθ’ ὑμῖν ἐπιδείξω, μετὰ δὲ ταῦτα καὶ περὶ τῶν ἄλλων, ὡς ἂν δύνωμαι διὰ βραχυτάτων.", "st": "27.12"}, {"sp": "N", "t": "οὗτος γὰρ εὐθὺς μετὰ τὸν τοῦ πατρὸς θάνατον ᾤκει τὴν οἰκίαν εἰσελθὼν κατὰ τὴν ἐκείνου διαθήκην, καὶ λαμβάνει τά τε χρυσία τῆς μητρὸς καὶ τὰ ἐκπώματα τὰ καταλειφθέντα. καὶ ταῦτα μὲν ὡς εἰς πεντήκοντα μνᾶς εἶχεν, ἔτι δὲ τῶν ἀνδραπόδων τῶν πιπρασκομένων παρά τε Θηριππίδου καὶ Δημοφῶντος τὰς τιμὰς ἐλάμβανεν, ἕως ἀνεπληρώσατο τὴν προῖκα, τὰς ὀγδοήκοντα μνᾶς.", "st": "27.13"}, {"sp": "N", "t": "καὶ ἐπειδὴ εἶχεν, ἐκπλεῖν μέλλων εἰς Κέρκυραν τριήραρχος, ἀπέγραψε ταῦτα πρὸς Θηριππίδην ἔχονθ’ ἑαυτὸν καὶ ὡμολόγει κεκομίσθαι τὴν προῖκα. καὶ πρῶτον μὲν τούτων Δημοφῶν καὶ Θηριππίδης, οἱ τούτου συνεπίτροποι, μάρτυρές εἰσιν· ἔτι δὲ καὶ ὡς αὐτὸς ὡμολόγει ταῦτ’ ἔχειν, Δημοχάρης θ’ ὁ Λευκονοεύς, ὁ τὴν τηθίδα τὴν ἐμὴν ἔχων, καὶ ἄλλοι πολλοὶ μάρτυρες γεγόνασιν.", "st": "27.14"}, {"sp": "N", "t": "οὐ γὰρ διδόντος τούτου σῖτον τῇ μητρί, τὴν προῖκ’ ἔχοντος, οὐδὲ τὸν οἶκον μισθοῦν ἐθέλοντος, ἀλλὰ μετὰ τῶν ἄλλων ἐπιτρόπων διαχειρίζειν ἀξιοῦντος, ἐποιήσατο λόγους περὶ τούτων ὁ Δημοχάρης. οὗτος δ’ ἀκούσας οὔτ’ ἠμφεσβήτησεν μὴ ἔχειν οὔτε χαλεπῶς ἤνεγκεν ὡς οὐκ εἰληφώς, ἀλλ’ ὡμολόγει καὶ ἔτι μικρὸν ἔφη πρὸς τὴν ἐμὴν μητέρα περὶ χρυσιδίων ἀντιλέγεσθαι· τοῦτ’ οὖν διευκρινησάμενος, καὶ περὶ τῆς τροφῆς καὶ περὶ τῶν ἄλλων ποιήσειν οὕτως ὥστ’ ἔχειν μοι πάντα καλῶς.", "st": "27.15"}, {"sp": "N", "t": "καίτοι εἰ φανήσεται πρός τε τὸν Δημοχάρη ταῦθ’ ὡμολογηκὼς καὶ πρὸς τοὺς ἄλλους οἳ παρῆσαν, παρά τε τοῦ Δημοφῶντος καὶ τοῦ Θηριππίδου τῶν ἀνδραπόδων εἰς τὴν προῖκα τὰς τιμὰς εἰληφώς, αὐτός θ’ ἑαυτὸν ἔχειν τὴν προῖκ’ ἀπογράψας πρὸς τοὺς συνεπιτρόπους, οἰκῶν τε τὴν οἰκίαν ἐπειδὴ τάχιστ’ ἐτελεύτησεν ὁ πατήρ, πῶς οὐκ ἐκ πάντων ὁμολογουμένου τοῦ πράγματος εὑρεθήσεται φανερῶς τὴν προῖκα, τὰς ὀγδοήκοντα μνᾶς, κεκομισμένος, καὶ λίαν ἀναιδῶς μὴ λαβεῖν ἐξαρνούμενος.", "st": "27.16"}, {"sp": "N", "t": "ἀλλὰ μὴν ὡς ἀληθῆ λέγω, λαβὲ τὰς μαρτυρίας καὶ ἀνάγνωθι.", "st": "27.17"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "27.17"}, {"sp": "N", "t": "τὴν μὲν τοίνυν προῖκα τοῦτον τὸν τρόπον ἔχει λαβών. μὴ γήμαντος δ’ αὐτοῦ τὴν μητέρα τὴν ἐμήν, ὁ μὲν νόμος κελεύει τὴν προῖκ’ ὀφείλειν ἐπ’ ἐννέ’ ὀβολοῖς, ἐγὼ δ’ ἐπὶ δραχμῇ μόνον τίθημι. γίγνεται δ’, ἐάν τις συντιθῇ τό τ’ ἀρχαῖον καὶ τὸ ἔργον τῶν δέκ’ ἐτῶν, μάλιστα τρία τάλαντα.", "st": "27.17"}, {"sp": "N", "t": "καὶ ταῦτα μὲν οὕτως ὑμῖν ἐπιδείκνυμι λαβόντα καὶ ἔχειν ὁμολογήσαντα μαρτύρων ἐναντίον τοσούτων· ἄλλας τοίνυν ἔχει τριάκοντα μνᾶς, τοῦ ἐργαστηρίου λαβὼν τὴν πρόσοδον, καὶ ἀναισχυντότατ’ ἀνθρώπων ἀποστερεῖν ἐπικεχείρηκεν. ἐμοὶ δ’ ὁ πατὴρ κατέλιπεν τριάκοντα μνᾶς ἀπ’ αὐτῶν τὴν πρόσοδον· ἀποδομένων δὲ τούτων τὰ ἡμίσεα τῶν ἀνδραπόδων, πεντεκαίδεκά μοι μνᾶς γίγνεσθαι κατὰ λόγον προσῆκε.", "st": "27.18"}, {"sp": "N", "t": "Θηριππίδης μὲν οὖν ἕπτ’ ἔτη τῶν ἀνδραπόδων ἐπιμεληθεὶς ἕνδεκα μνᾶς τοῦ ἐνιαυτοῦ ἀπέφηνε, τέτταρσι μναῖς καθ’ ἕκαστον ἐνιαυτὸν ἔλαττον ἢ ὅσον προσῆκε λογιζόμενος. οὗτος δὲ δύ’ ἔτη τὰ πρῶτ’ ἐπιμεληθεὶς οὐδ’ ὁτιοῦν ἀποδείκνυσιν, ἀλλ’ ἐνίοτε μέν φησιν ἀργῆσαι τὸ ἐργαστήριον, ἐνίοτε δ’ ὡς αὐτὸς μὲν οὐκ ἐπεμελήθη τούτων, ὁ δ’ ἐπίτροπος Μιλύας, ὁ ἀπελεύθερος ὁ ἡμέτερος, διῴκησεν αὐτά, καὶ παρ’ ἐκείνου μοι προσήκει λόγον λαβεῖν. ἂν οὖν καὶ νῦν εἴπῃ τινὰ τούτων τῶν λόγων, ῥᾳδίως ἐξελεγχθήσεται ψευδόμενος.", "st": "27.19"}, {"sp": "N", "t": "ἂν μὲν οὖν ἀργὸν φῇ γενέσθαι, λόγον αὐτὸς ἀπενήνοχεν ἀναλωμάτων οὐκ εἰς σιτία τοῖς ἀνθρώποις, ἀλλ’ εἰς ἔργα, τὸν εἰς τὴν τέχνην ἐλέφαντα καὶ μαχαιρῶν λαβὰς καὶ ἄλλας ἐπισκευάς, ὡς ἐργαζομένων τῶν δημιουργῶν. ἔτι δὲ Θηριππίδῃ τριῶν ἀνδραπόδων, ἃ ἦν αὐτῷ ἐν τῷ ἐμῷ ἐργαστηρίῳ, μισθὸν ἀποδεδωκέναι λογίζεται. καίτοι μὴ γενομένης ἐργασίας οὔτ’ ἐκείνῳ λαβεῖν μισθὸν οὔτ’ ἐμοὶ τὰ ἀναλώματα ταῦτα λογισθῆναι προσῆκεν.", "st": "27.20"}, {"sp": "N", "t": "εἰ δ’ αὖ γενέσθαι μὲν φήσει, τῶν δ’ ἔργων ἀπρασίαν εἶναι, δεῖ δήπου τά γ’ ἔργ’ αὐτὸν ἀποδεδωκότα μοι φαίνεσθαι, καὶ ὧν ἐναντίον ἀπέδωκε παρασχέσθαι μάρτυρας. εἰ δὲ μηδὲν τούτων πεποίηκεν, πῶς οὐκ ἔχει τὴν πρόσοδον δυοῖν ἐτοῖν τὴν ἐκ τοῦ ἐργαστηρίου, τὰς τριάκοντα μνᾶς, φανερῶς οὕτως τῶν ἔργων γεγενημένων.", "st": "27.21"}, {"sp": "N", "t": "εἰ δ’ αὖ τούτων μὲν μηδὲν ἐρεῖ, Μιλύαν δ’ αὐτὰ φήσει πάντα διῳκηκέναι, πῶς χρὴ πιστεύειν, ὅταν φῇ τὰ μὲν ἀναλώματ’ αὐτὸς ἀνηλωκέναι, πλέον ἢ πεντακοσίας δραχμάς, λῆμμα δ’ εἴ τι γέγονεν, ἐκεῖνον ἔχειν; ἐμοὶ μὲν γὰρ δοκεῖ τοὐναντίον ἂν γενέσθαι τούτων, εἰ καὶ Μιλύας αὐτῶν ἐπεμελεῖτο, τὰ μὲν ἀναλώματ’ ἐκεῖνος ἀναλῶσαι, τὰ δὲ λήμμαθ’ οὗτος λαβεῖν, εἴ τι δεῖ τεκμαίρεσθαι πρὸς τὸν ἄλλον αὐτοῦ τρόπον καὶ τὴν ἀναίδειαν. λάβ’ οὖν τὰς μαρτυρίας ταύτας, καὶ ἀνάγνωθ’ αὐτοῖς.", "st": "27.22"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "27.22"}, {"sp": "N", "t": "ταύτας τοίνυν ἔχει τριάκοντα μνᾶς ἀπὸ τοῦ ἐργαστηρίου, καὶ τὸ ἔργον αὐτῶν ὀκτὼ ἐτῶν· ὃ ἂν ἐπὶ δραχμῇ τις τιθῇ μόνον, ἄλλας τριάκοντα μνᾶς εὑρήσει. καὶ ταῦτα μὲν ἰδίᾳ μόνος εἴληφεν· ἃ συντεθέντα πρὸς τὴν προῖκα μάλιστα τέτταρα τάλαντα γίγνεται σὺν τοῖς ἀρχαίοις. ἃ δὲ μετὰ τῶν ἄλλων ἐπιτρόπων κοινῇ διήρπακεν, καὶ ὅσ’ ἔνια μηδὲ καταλειφθῆναι παντάπασιν ἠμφεσβήτηκεν, ταῦθ’ ὑμῖν ἤδη ἐπιδείξω καθ’ ἕκαστον.", "st": "27.23"}, {"sp": "N", "t": "πρῶτον μὲν οὖν περὶ τῶν κλινοποιῶν, οὓς κατέλιπεν μὲν ὁ πατήρ, ἀφανίζουσι δ’ οὗτοι, τετταράκοντα μὲν μνῶν ὑποκειμένους, εἴκοσι δ’ ὄντας τὸν ἀριθμόν, ἐπιδείξω ὑμῖν ὡς λίαν ἀναιδῶς καὶ φανερῶς μ’ ἀποστεροῦσι. τούτους γὰρ καταλειφθῆναι μὲν οἴκοι παρ’ ἡμῖν πάντες ὁμολογοῦσιν, καὶ τὰς δώδεκα μνᾶς ἑκάστου τοῦ ἐνιαυτοῦ τῷ πατρὶ γίγνεσθαί φασιν· αὐτοὶ δὲ λῆμμα μὲν παρ’ αὐτῶν ἐν δέκ’ ἔτεσιν οὐδὲν ἐμοὶ γεγενημένον ἀποφαίνουσιν ἀλλ’ οὐδὲ μικρόν, ἀναλώματος δὲ κεφάλαιον εἰς αὐτοὺς οὗτος ὀλίγου δεῖν λογίζεται χιλίας· εἰς τοῦτ’ ἀναιδείας ἐλήλυθεν.", "st": "27.24"}, {"sp": "N", "t": "αὐτοὺς δὲ τοὺς ἀνθρώπους, εἰς οὓς ταῦτ’ ἀνηλωκέναι φησίν, οὐδαμοῦ μοι παραδεδώκασιν, ἀλλὰ πάντων κενότατον λόγον λέγουσιν, ὡς ὁ ὑποθεὶς τῷ πατρὶ τἀνδράποδα πονηρότατος ἀνθρώπων ἐστὶν καὶ ἐράνους τε λέλοιπε πλείστους καὶ ὑπέρχρεως γέγονε, καὶ τούτων οὐκ ὀλίγους κεκλήκασι κατ’ ἐκείνου μάρτυρας. τὰ δ’ ἀνδράποδ’ ὅστις ἐστὶν ὁ λαβών, ἢ πῶς ἐκ τῆς οἰκίας ἐξῆλθεν, ἢ τίς ἀφείλετο, ἢ πρὸς τίνα δίκην ἥττηνται περὶ αὐτῶν, οὐκ ἔχουσιν εἰπεῖν.", "st": "27.25"}, {"sp": "N", "t": "καίτοι εἴ τι ἔλεγον ὑγιές, οὐκ ἂν κατὰ τῆς ἐκείνου πονηρίας παρείχοντο μάρτυρας, ἧς οὐδέν μοι προσήκει φροντίζειν, ἀλλὰ τούτων ἂν ἀντελαμβάνοντο καὶ τοὺς λαβόντας ἀπεδείκνυσαν καὶ οὐδὲν ἂν αὐτῶν παρέλειπον. νῦν δ’ ὠμότατ’ ἀνθρώπων, ὁμολογοῦντες καταλειφθῆναι καὶ λαβόντες ὡς αὑτοὺς καὶ καρπωσάμενοι δέκ’ ἔτη τοὺς ἀνθρώπους, ἄρδην ὅλον τὸ ἐργαστήριον ἀφανίζουσι. καὶ ταῦθ’ ὡς ἀληθῆ λέγω, λαβέ μοι τὰς μαρτυρίας καὶ ἀναγίγνωσκε.", "st": "27.26"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "27.26"}, {"sp": "N", "t": "ὅτι τοίνυν οὐκ ἄπορος ἦν ὁ Μοιριάδης, οὐδ’ ἦν τῇ πατρὶ τοῦτο τὸ συμβόλαιον εἰς τἀνδράποδ’ ἠλιθίως συμβεβλημένον, μεγίστῳ τεκμηρίῳ γνώσεσθε· λαβὼν γὰρ ὡς ἑαυτὸν Ἄφοβος τοῦτο τὸ ἐργαστήριον, ὡς αὐτοὶ τῶν μαρτύρων ἠκούσατε, καὶ δέον αὐτόν, εἰ καί τις ἄλλος ἐβούλετ’ εἰς ταῦτα συμβαλεῖν, τοῦτον διακωλύειν ἐπίτροπόν γ’ ὄντα, αὐτὸς ἐπὶ τούτοις τοῖς ἀνδραπόδοις τῷ Μοιριάδῃ πεντακοσίας δραχμὰς ἐδάνεισεν, ἃς ὀρθῶς καὶ δικαίως παρ’ ἐκείνου κεκομίσθαι ὡμολόγηκεν.", "st": "27.27"}, {"sp": "N", "t": "καίτοι πῶς οὐ δεινόν, εἰ ἡμῖν μὲν πρὸς τῷ λῆμμ’ ἀπ’ αὐτῶν μηδὲν γεγονέναι καὶ αὐτὰ τὰ ὑποτεθέντ’ ἀπόλωλεν, οἳ πρότερον συνεβάλομεν, τῷ δ’ εἰς τὰ ἡμέτερα δανείσαντι καὶ τοσούτῳ χρόνῳ πράξαντι καὶ οἱ τόκοι καὶ τἀρχαῖ’ ἐκ τῶν ἡμετέρων ἀποδέδοται καὶ οὐδεμί’ ἀπορία γέγονεν; ἀλλὰ μὴν ὡς ἀληθῆ λέγω, λαβὲ τὴν μαρτυρίαν καὶ ἀνάγνωθι.", "st": "27.28"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "27.28"}, {"sp": "N", "t": "σκέψασθε τοίνυν ὅσον ἀργύριον οὗτοι παρὰ τοὺς κλινοποιοὺς κλέπτουσι, τετταράκοντα μὲν μνᾶς αὐτὸ τὸ ἀρχαῖον, δέκα δ’ ἐτῶν τὸ ἔργον αὐτῶν δύο τάλαντα· δώδεκα γὰρ μνᾶς ἑκάστου τοῦ ἐνιαυτοῦ τὴν πρόσοδον αὐτῶν ἐλάμβανον. ἆρα μικρόν τι καὶ ἐξ ἀφανοῦς ποθεν καὶ παραλογίσασθαι. ῥᾴδιον, ἀλλ’ οὐ φανερῶς οὑτωσὶ μικροῦ δεῖν τρία τάλαντα ταῦτ’ ἀνηρπάκασιν; ὧν κοινῇ διαπεφορημένων τὸ τρίτον δήπου μέρος παρὰ τούτου μοι προσήκει κεκομίσθαι.", "st": "27.29"}, {"sp": "N", "t": "καὶ μήν, ὦ ἄνδρες δικασταί, καὶ τὰ περὶ τοῦ ἐλέφαντος καὶ σιδήρου τοῦ καταλειφθέντος παραπλήσιά πως τούτοις πεποιήκασιν· οὐδὲ γὰρ ταῦτ’ ἀποφαίνουσιν. καίτοι κεκτημένον μὲν τοσούτους κλινοποιούς, κεκτημένον δὲ μαχαιροποιοὺς οὐχ οἷόν τε μὴ οὐχὶ καὶ σίδηρον καὶ ἐλέφαντα καταλιπεῖν, ἀλλ’ ἀνάγκη ταῦτά γ’ ὑπάρχειν· τί γὰρ ἂν ἠργάζοντο τούτων μὴ ὑπαρξάντων.", "st": "27.30"}, {"sp": "N", "t": "τὸν τοίνυν πλέον ἢ πεντήκοντ’ ἀνδράποδα κεκτημένον καὶ δυοῖν τέχναιν ἐπιμελούμενον, ὧν θάτερον ἐργαστήριον εἰς τὰς κλίνας ῥᾳδίως δύο μνᾶς τοῦ μηνὸς ἀνήλισκεν ἐλέφαντος, τὸ δὲ μαχαιροποιεῖον οὐκ ἔλαττον ἢ τοσοῦτον ἕτερον σὺν σιδήρῳ, τοῦτον οὔ φασιν καταλιπεῖν οὐδὲν τούτων· εἰς τοῦτ’ ἀναιδείας ἐληλύθασιν.", "st": "27.31"}, {"sp": "N", "t": "ὅτι μὲν οὖν οὐ πιστὰ λέγουσιν, καὶ ἐκ τούτων αὐτῶν ῥᾴδιόν ἐστι μαθεῖν· ὅτι δ’ ἐκεῖνος κατέλιπε τοσοῦτον τὸ πλῆθος ὥστε μὴ μόνον ἱκανὸν εἶναι κατεργάζεσθαι τοῖς ἑαυτοῦ δημιουργοῖς, ἀλλὰ καὶ τῷ βουλομένῳ πρὸς ὠνεῖσθαι τῶν ἄλλων, ἐκεῖθεν φανερόν, ὅτι αὐτός τ’ ἐπώλει ζῶν καὶ Δημοφῶν καὶ οὗτος τοῦ πατρὸς ἤδη τετελευτηκότος ἐκ τῆς οἰκίας τῆς ἐμῆς ἀπεδίδοντο τοῖς βουλομένοις.", "st": "27.32"}, {"sp": "N", "t": "καίτοι πόσον τινὰ χρὴ τὸν καταλειφθέντα νομίζειν εἶναι, ὅταν φαίνηται τηλικούτοις τ’ ἐργαστηρίοις ἐξαρκῶν καὶ χωρὶς ὑπὸ τῶν ἐπιτρόπων πιπρασκόμενος; ἆρ’ ὀλίγον, ἀλλ’ οὐ πολλῷ πλείω τῶν ἐγκεκλημένων; λαβὲ τοίνυν τὰς μαρτυρίας ταυτασὶ καὶ ἀνάγνωθ’ αὐτοῖς.", "st": "27.33"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ", "st": "27.33"}, {"sp": "N", "t": "τούτου τοίνυν τοῦ ἐλέφαντός ἐστι πλέον ἢ τάλαντον, ὃν οὔτ’ αὐτὸν οὔτε τὸ ἔργον μοι ἀποφαίνουσιν, ἀλλὰ καὶ τοῦτον ἄρδην ἀφανίζουσιν ὅλον.", "st": "27.33"}, {"sp": "N", "t": "ἔτι τοίνυν, ὦ ἄνδρες δικασταί, παρὰ τὸν λόγον ὃν ἀποφέρουσιν, ἐξ ὧν αὐτοὶ λαβεῖν ὁμολογοῦσιν, ἐπιδείξω ὑμῖν τρεῖς μὲν ὄντας αὐτοὺς πλέον ἢ ὀκτὼ τάλαντ’ ἐκ τῶν ἐμῶν ἔχοντας, ἰδίᾳ δ’ ἐκ τούτων Ἄφοβον τρία τάλαντα καὶ χιλίας εἰληφότα, τά τ’ ἀνηλωμένα χωρὶς τούτων πλείω τιθεὶς καὶ ὅσ’ ἐκ τούτων ἀπέδοσαν ἀφαιρῶν, ἵν’ εἰδῆθ’ ὅτι οὐ μικρᾶς ἀναιδείας τὰ ἐγχειρήματ’ αὐτῶν ἐστίν.", "st": "27.34"}, {"sp": "N", "t": "λαβεῖν γὰρ ἐκ τῶν ἐμῶν ὁμολογοῦσιν οὗτος μὲν ὀκτὼ καὶ ἑκατὸν μνᾶς, χωρὶς ὧν ἔχοντ’ αὐτὸν ἐγὼ ἐπιδείξω νῦν, Θηριππίδης δὲ δύο τάλαντα, Δημοφῶν δ’ ἑπτὰ καὶ ὀγδοήκοντα μνᾶς. τοῦτο δ’ ἐστὶ πέντε τάλαντα καὶ πεντεκαίδεκα μναῖ. τούτου τοίνυν ὃ μὲν οὐχ ἅθρουν ἐλήφθη, σχεδόν εἰσιν ἑβδομήκοντα μναῖ καὶ ἑπτά, ἡ πρόσοδος ἡ ἀπὸ τῶν ἀνδραπόδων, ὃ δ’ εὐθὺς ἔλαβον οὗτοι, μικροῦ δέοντα τέτταρα τάλαντα· οἷς τὸ ἔργον ἂν προσθῆτ’ ἐπὶ δραχμῇ μόνον τῶν δέκ’ ἐτῶν, ὀκτὼ τάλανθ’ εὑρήσετε σὺν τοῖς ἀρχαίοις καὶ χιλίας γιγνομένας.", "st": "27.35"}, {"sp": "N", "t": "τὴν μὲν τοίνυν τροφὴν ἀπὸ τῶν ἑβδομήκοντα μνῶν καὶ ἑπτὰ λογιστέον τῶν ἀπὸ τοῦ ἐργαστηρίου γενομένων. Θηριππίδης γὰρ ἑπτὰ μνᾶς ἐδίδου καθ’ ἕκαστον τὸν ἐνιαυτὸν εἰς ταῦτα, καὶ ἡμεῖς τοῦτο λαβεῖν ὁμολογοῦμεν. ὥσθ’ ἑβδομήκοντα μνῶν ἐν τοῖς δέκ’ ἔτεσιν τροφὴν τούτων ἡμῖν ἀνηλωκότων, τὸ περιὸν τὰς ἑπτακοσίας προστίθημ’ αὐτοῖς, καὶ τούτων πλείω εἰμὶ τεθηκώς. ὃ δ’ ἐμοὶ δοκιμασθέντι παρέδοσαν καὶ ὅσον εἰς τὴν πόλιν εἰσενηνόχασιν, τοῦτ’ ἀπὸ τῶν ὀκτὼ ταλάντων καὶ τοῦ προσόντος ἀφαιρετέον ἐστίν.", "st": "27.36"}, {"sp": "N", "t": "ἀπέδοσαν μὲν τοίνυν οὗτος καὶ Θηριππίδης μίαν καὶ τριάκοντα μνᾶς, εἰσφορὰς δ’ εἰσενηνοχέναι λογίζονται δυοῖν δεούσας εἴκοσι μνᾶς. ἐγὼ δ’ ὑπερβαλὼν τοῦτο ποιήσω τριάκοντα μνᾶς, ἵνα πρὸς ταῦτα μηδ’ ἀντειπεῖν ἔχωσιν. οὐκοῦν ἂν ἀφέλητε τὸ τάλαντον ἀπὸ τῶν ὀκτὼ ταλάντων, ἑπτὰ τὰ λειπόμεν’ ἐστί, καὶ ταῦτα, ἐξ ὧν αὐτοὶ λαβεῖν ὁμολογοῦσι, τούτους ἔχειν ἐστὶν ἀναγκαῖον. τοῦτο τοίνυν, εἰ καὶ τἄλλα πάντ’ ἀποστεροῦσιν ἀρνούμενοι μὴ ἔχειν, ἀποδοῦναι προσῆκεν, ὁμολογοῦντάς γε λαβεῖν ταῦτ’ ἐκ τῶν ἐμῶν.", "st": "27.37"}, {"sp": "N", "t": "νῦν δὲ τί ποιοῦσιν; ἔργον μὲν οὐδὲν ἀποφαίνουσι τοῖς χρήμασιν, αὐτὰ δὲ τὰ ἀρχαῖα πάντ’ ἀνηλωκέναι φασὶ σὺν ταῖς ἑπτὰ καὶ ἑβδομήκοντα μναῖς· Δημοφῶν δὲ καὶ πρὸς ὀφείλοντας ἡμᾶς ἐνέγραψε. ταῦτ’ οὐ μεγάλη καὶ περιφανὴς ἀναισχυντία; ταῦτ’ οὐχ ὑπερβολὴ δεινῆς αἰσχροκερδίας; τί οὖν ποτ’ ἐστὶ τὸ δεινόν, εἰ μὴ ταῦτα δόξει τηλικαύτας ὑπερβολὰς ἔχοντα.", "st": "27.38"}, {"sp": "N", "t": "οὗτος τοίνυν τὸ καθ’ αὑτὸν ὀκτὼ καὶ ἑκατὸν μνᾶς λαβεῖν ὁμολογῶν, ἔχει καὶ αὐτὰς καὶ τὸ ἔργον δέκ’ ἐτῶν, μάλιστα τρία τάλαντα καὶ χιλίας. καὶ ταῦθ’ ὡς ἀληθῆ λέγω, καὶ ἐν τοῖς λόγοις τῆς ἐπιτροπῆς τὸ λῆμμ’ ἕκαστος τοῦθ’ ὁμολογῶν λαβεῖν ἅπαν ἀνηλωκέναι λογίζεται, λαβὲ τὰς μαρτυρίας καὶ ἀνάγνωθι.", "st": "27.39"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "27.39"}, {"sp": "N", "t": "νομίζω τοίνυν, ὦ ἄνδρες δικασταί, περὶ τούτων ἱκανῶς μὲν ὑμᾶς μεμαθηκέναι, καὶ ὅσα κλέπτουσιν καὶ κακουργοῦσιν ἕκαστος αὐτῶν· ἔτι δ’ ἀκριβέστερον ἔγνωτ’ ἄν, εἴ μοι τὰς διαθήκας, ἃς ὁ πατὴρ κατέλιπεν, οὗτοι ἀποδοῦναι ἠθέλησαν. ἐν γὰρ ἐκείναις ἐγέγραπτο, ὥς φησιν ἡ μήτηρ, ἃ κατέλιπεν ὁ πατὴρ πάντα, καὶ ἐξ ὧν ἔδει τούτους λαβεῖν τὰ δοθέντα, καὶ τὸν οἶκον ὅπως μισθώσουσι.", "st": "27.40"}, {"sp": "N", "t": "νῦν δ’ ἀπαιτοῦντος ἐμοῦ καταλειφθῆναι μὲν ὁμολογοῦσιν, αὐτὰς δ’ οὐκ ἀποφαίνουσι. ταῦτα δὲ ποιοῦσι τό τε πλῆθος οὐ βουλόμενοι καταφανὲς ποιῆσαι τῆς οὐσίας τὸ καταλειφθέν, ὃ διηρπάκασιν οὗτοι, τάς τε δωρεὰς ἵνα μὴ δοκῶσιν ἔχειν, ὥσπερ οὐκ ἐξ αὐτοῦ τοῦ πράγματος ἐξελεγχθησόμενοι ῥᾳδίως. λαβὲ δ’ αὐτοῖς τὰς μαρτυρίας ὧν ἐναντίον ἀπεκρίναντο, καὶ ἀνάγνωθι.", "st": "27.41"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "27.41"}, {"sp": "N", "t": "οὗτος διαθήκην μὲν γενέσθαι φησίν, καὶ τὰ δύο τάλαντα Δημοφῶντι καὶ τὰς ὀγδοήκοντα μνᾶς τούτῳ δοθῆναι μαρτυρεῖ· τὰς δ’ ἑβδομήκοντα μνᾶς, ἃς Θηριππίδης ἔλαβεν, οὐ προσγραφῆναί φησιν, οὐδὲ τὸ πλῆθος τῆς οὐσίας τὸ καταλειφθέν, οὐδὲ τὸν οἶκον ὅπως μισθώσουσιν· οὐ γὰρ αὐτῷ συμφέρει προσομολογῆσαι ταῦτα. λαβὲ δὴ τὴν τούτου ἀπόκρισιν.", "st": "27.42"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "27.42"}, {"sp": "N", "t": "οὗτος αὖ τὴν μὲν διαθήκην γενέσθαι φησίν, καὶ τὸ ἀργύριον ἐκ τοῦ χαλκοῦ καὶ τῆς κηκῖδος ἀποδοθῆναι τῷ Θηριππίδῃ, ὃ ἐκεῖνος οὔ φησιν, καὶ τὰ δύο τάλαντα τῷ Δημοφῶντι· περὶ δὲ τῶν αὐτῷ δοθέντων γραφῆναι μέν φησιν, οὐχ ὁμολογῆσαι δ’ αὐτός, ἵνα μὴ δοκῇ λαβεῖν. τὸ δὲ πλῆθος τῆς οὐσίας οὐδ’ οὗτος ἀποφαίνει καθόλου, οὐδὲ τὸ μισθοῦν τὸν οἶκον· οὐδὲ γὰρ οὐδὲ τούτῳ συμφέρει προσομολογῆσαι ταῦτα.", "st": "27.43"}, {"sp": "N", "t": "δῆλον τοίνυν ἐστὶν οὐδὲν ἧττον τὸ πλῆθος τῶν καταλειφθέντων, καίπερ ἀφανιζόντων τούτων τὴν οὐσίαν ἐκ τῶν διαθηκῶν, ἐξ ὧν τοσαῦτα χρήματ’ ἀλλήλοις φασὶ δοθῆναι. ὅστις γὰρ ἐκ τεττάρων ταλάντων καὶ τρισχιλίων τοῖς μὲν τρία τάλαντα καὶ δισχιλίας προῖκα δέδωκεν, τῷ δ’ ἑβδομήκοντα μνᾶς καρποῦσθαι, φανερὸν δήπου πᾶσιν ὅτι οὐκ ἀπὸ μικρᾶς οὐσίας, ἀλλὰ πλέον ἢ διπλασίας ἧς ἐμοὶ κατέλειπεν ταῦτ’ ἀφεῖλεν.", "st": "27.44"}, {"sp": "N", "t": "οὐ γὰρ δήπου τὸν μὲν υἱὸν ἐμὲ πένητ’ ἐβούλετο καταλιπεῖν, τούτους δὲ πλουσίους ὄντας ἔτι πλουσιωτέρους ποιῆσαι ἐπεθύμησεν, ἀλλ’ ἕνεκα τοῦ πλήθους τῶν ἐμοὶ καταλειπομένων Θηριππίδῃ τε τοσοῦτον ἀργύριον καὶ Δημοφῶντι τὰ δύο τάλαντα, οὔπω μέλλοντι τῇ ἀδελφῇ τῇ ἐμῇ συνοικήσειν, καρποῦσθαι ἔδωκεν, ἵνα δυοῖν θάτερον διαπράξαιτο, ἢ διὰ τὰ διδόμενα βελτίους αὐτοὺς εἶναι τὰ περὶ τὴν ἐπιτροπὴν προτρέψειεν, ἢ εἰ κακοὶ γίγνοιντο, μηδεμιᾶς συγγνώμης παρ’ ὑμῶν τυγχάνοιεν, εἰ τοσούτων ἀξιωθέντες τοιαῦτ’ εἰς ἡμᾶς ἐξαμαρτάνοιεν.", "st": "27.45"}, {"sp": "N", "t": "οὗτος τοίνυν καὶ αὐτὸς πρὸς τῇ προικὶ καὶ θεραπαίνας λαβὼν καὶ τὴν οἰκίαν οἰκῶν, ἐπειδὴ δεῖ λόγον αὐτὸν δοῦναι τούτων, τὰ ἑαυτοῦ πράττειν φησίν· καὶ εἰς τοσοῦτον αἰσχροκερδίας ἦλθεν, ὥστε καὶ τοὺς διδασκάλους τοὺς μισθοὺς ἀπεστέρηκεν καὶ τῶν εἰσφορῶν ἔστιν ἃς οὐ κατέθηκεν, ἐμοὶ δὲ λογίζεται. λαβὲ δὴ καὶ ταύτας αὐτοῖς τὰς μαρτυρίας καὶ ἀνάγνωθι.", "st": "27.46"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "27.46"}, {"sp": "N", "t": "πῶς οὖν ἄν τις σαφέστερον ἐπιδείξειεν πάντα διηρπακότα καὶ μηδὲ τῶν μικρῶν ἀπεσχημένον, ἢ τοῦτον τὸν τρόπον ἐπιδεικνὺς μετὰ τοσούτων μαρτύρων καὶ τεκμηρίων; τὴν μὲν προῖκα λαβεῖν ὁμολογήσαντα καὶ ἔχειν αὐτὸν πρὸς τοὺς ἐπιτρόπους ἀπογράψαντα, τὸ δ’ ἐργαστήριον κεκαρπωμένον αὐτὸν καὶ τὴν πρόσοδον οὐκ ἀποφαίνοντα.", "st": "27.47"}, {"sp": "N", "t": "τῶν δ’ ἄλλων τὰ μὲν πεπρακότα καὶ τὰς τιμὰς οὐκ ἀποδεδωκότα, τὰ δ’ ὡς ἑαυτὸν λαβόντα καὶ ταῦτ’ ἠφανικότα, ἔτι δὲ παρὰ τὸν λόγον ὃν αὐτὸς ἀπέδωκε τοσαῦτα κλέπτοντα, πρὸς δὲ τούτοις τὴν διαθήκην ἠφανικότα, τὰ ἀνδράποδα πεπρακότα, τἄλλ’ οὕτω πάντα διῳκηκότα, ὡς οὐδ’ ἂν οἱ ἔχθιστοι διοικήσειαν; ἐγὼ μὲν οὐκ οἶδ’ ὅπως ἄν τις σαφέστερον ἐπιδείξειεν.", "st": "27.48"}, {"sp": "N", "t": "ἐτόλμα τοίνυν πρὸς τῷ διαιτητῇ λέγειν, ὡς ἀπὸ τῶν χρημάτων χρέα τε πάμπολλ’ ἐκτέτεικεν ὑπὲρ ἐμοῦ Δημοφῶντι καὶ Θηριππίδῃ τοῖς συνεπιτρόποις, καὶ ὡς πολλὰ τῶν ἐμῶν λάβοιεν, οὐδέτερ’ ἔχων ἐπιδεικνύναι τούτων. οὔτε γὰρ ὡς ὀφείλοντά με κατέλιπεν ὁ πατὴρ ἐν τοῖς γράμμασιν ἀπέφηνεν, οὐδ’ οἷς ἀποδεδωκέναι ταῦτ’ ἔφη παρέσχηται μάρτυρας, οὔτ’ αὖ τὸν ἀριθμὸν τῶν χρημάτων εἰς τοὺς συνεπιτρόπους ἐπανέφερεν ὅσον αὐτὸς φαίνεται λαβών, ἀλλὰ πολλοῖς ἐλάττω χρήμασιν.", "st": "27.49"}, {"sp": "N", "t": "ἐρωτηθεὶς δ’ ὑπὸ τοῦ διαιτητοῦ ταῦτά τε καθ’ ἕκαστον, καὶ τὴν οὐσίαν τὴν αὑτοῦ πότερον ἐκ τῶν ἐπικαρπιῶν ἢ τἀρχαῖ’ ἀναλίσκων διῴκηκεν, καὶ πότερον ἐπιτροπευθεὶς ἀπεδέξατ’ ἂν τοῦτον τὸν λόγον παρὰ τῶν ἐπιτρόπων ἢ τἀρχαῖ’ ἂν ἀπολαβεῖν ἠξίου σὺν τοῖς ἔργοις τοῖς γεγενημένοις, πρὸς μὲν ταῦτ’ ἀπεκρίνατ’ οὐδέν, προὐκαλεῖτο δ’ ἐθέλειν ἐπιδεῖξαί μοι τὴν οὐσίαν δέκα ταλάντων οὖσαν· εἰ δέ τι ἐλλείποι, αὐτὸς ἔφη προσθήσειν.", "st": "27.50"}, {"sp": "N", "t": "κελεύοντος δ’ ἐμοῦ πρὸς τὸν διαιτητὴν ἐπιδεικνύναι ταῦτ’ οὐκ ἐπέδειξεν, οὐδ’ ὡς οἱ συνεπίτροποι παρέδοσαν (οὐ γὰρ ἂν αὐτοῦ κατεδιῄτησεν), μαρτυρίαν δ’ ἐνεβάλετο τοιαύτην, περὶ ἧς πειράσεταί τι λέγειν. ἂν μὲν οὖν καὶ νῦν ἔχειν με φῇ, τίνος παραδόντος ἐρωτᾶτ’ αὐτόν, καὶ καθ’ ἕκαστον παρασχέσθαι μάρτυρας ἀξιοῦτε.", "st": "27.51"}, {"sp": "N", "t": "ἐὰν δ’ εἶναί μοι φῇ τοῦτον τὸν τρόπον, λογιζόμενος τὰ παρ’ ἑκατέρῳ τῶν ἐπιτρόπων, διπλασίοις ἐλάττω φανήσεται λέγων, ἔχοντα δ’ οὐδὲν μᾶλλον ἀποφαίνων. ἐγὼ γὰρ ὥσπερ καὶ τοῦτον τοσαῦτ’ ἔχοντ’ ἐξήλεγξα, οὕτως κἀκείνων ἑκάτερον οὐκ ἐλάττω τούτων ἔχοντ’ ἐπιδείξω. ὥστ’ οὐ τοῦτ’ αὐτῷ λεκτέον, ἀλλ’ ὡς ἢ αὐτὸς ἢ οἱ συνεπίτροποι παρέδοσαν. εἰ δὲ μὴ τοῦτ’ ἐπιδείξει, πῶς χρὴ ταύτῃ τῇ προκλήσει προσέχειν ὑμᾶς τὸν νοῦν; οὐδὲν γὰρ μᾶλλον ἔχοντά μ’ ἐπιδείκνυσι.", "st": "27.52"}, {"sp": "N", "t": "πολλὰ τοίνυν ἀπορηθεὶς πρὸς τῷ διαιτητῇ περὶ πάντων τούτων, καὶ καθ’ ἕκαστον ἐξελεγχόμενος ὥσπερ νυνὶ παρ’ ὑμῖν, ἐτόλμησε ψεύσασθαι πάντων δεινότατον, ὡς τέτταρά μοι τάλανθ’ ὁ πατὴρ κατέλιπε κατορωρυγμένα καὶ τούτων κυρίαν τὴν μητέρ’ ἐποίησεν. ταῦτα δ’ εἶπεν, ἵν’ εἰ μὲν καὶ νῦν προσδοκήσαιμ’ αὐτὸν ἐρεῖν, ἀπολογούμενος περὶ αὐτῶν διατρίβοιμι, δέον ἕτερά μ’ αὐτοῦ κατηγορεῖν πρὸς ὑμᾶς· εἰ δ’ ὡς οὐ ῥηθησομένων παραλίποιμι, νῦν αὐτὸς εἴποι, ἵνα δοκῶν εἶναι πλούσιος ἧττον ὑφ’ ὑμῶν ἐλεοίμην.", "st": "27.53"}, {"sp": "N", "t": "καὶ μαρτυρίαν μὲν οὐδεμίαν ἐνεβάλετο τούτων ὁ ταῦτ’ εἰπεῖν ἀξιώσας, ψιλῷ δὲ λόγῳ χρησάμενος ὡς πιστευθησόμενος δι’ ἐκείνων. καὶ ὅταν μὲν ἔρηταί τις αὐτόν, εἰς τί τῶν ἐμῶν τοσαῦτα χρήματ’ ἀνήλωκεν, χρέα φησὶν ὑπὲρ ἐμοῦ ἐκτετεικέναι καὶ πένητ’ ἐνταυθοῖ ζητεῖ ποιεῖν· ὅταν δὲ βούληται, πλούσιον ὡς ἔοικεν, εἴπερ γε καὶ τοσοῦτον ἐκεῖνος ἀργύριον οἴκοι κατέλιπεν. ὡς δ’ οὐκ ἀληθῆ λέγειν οἷόν τ’ αὐτόν, ἀλλ’ ἀδύνατόν τι γενέσθαι τούτων, ἐκ πολλῶν ῥᾴδιον μαθεῖν.", "st": "27.54"}, {"sp": "N", "t": "εἰ μὲν γὰρ ὁ πατὴρ ἠπίστει τούτοις, δῆλον ὅτι οὔτ’ ἂν τἄλλ’ ἐπέτρεπεν οὔτ’ ἂν ταῦθ’ οὕτω καταλείπων αὐτοῖς ἔφραζε· μανία γὰρ δεινὴ τὰ κεκρυμμέν’ εἰπεῖν, μηδὲ τῶν φανερῶν μέλλοντ’ ἐπιτρόπους καταστήσειν. εἰ δ’ ἐπίστευεν, οὐκ ἂν δήπου τὰ μὲν πλεῖστ’ αὐτοῖς τῶν χρημάτων ἐνεχείρισεν, τῶν δ’ οὐκ ἂν κυρίους ἐποίησεν. οὐδ’ ἂν τῇ μὲν μητρί μου ταῦτα φυλάττειν ἔδωκεν, αὐτὴν δ’ ἐκείνην ἑνὶ τῶν ἐπιτρόπων τούτῳ γυναῖκ’ ἔδωκεν· οὐ γὰρ ἔχει λόγον, σῴζειν μὲν τὰ χρήματα διὰ τῆς ἐμῆς μητρὸς ζητεῖν, ἕνα δὲ τῶν ἀπιστουμένων καὶ αὐτῆς καὶ τῶν χρημάτων κύριον ποιεῖν.", "st": "27.55"}, {"sp": "N", "t": "ἔτι δέ, τούτων εἴ τι ἦν ἀληθές, οἴεσθ’ οὐκ ἂν αὐτὴν λαβεῖν δοθεῖσαν ὑπὸ τοῦ πατρός; ὃς τὴν μὲν προῖκ’ αὐτῆς ἤδη, τὰς ὀγδοήκοντα μνᾶς, ἔχων ὡς συνοικήσων αὐτῇ, τὴν Φιλωνίδου τοῦ Μελιτέως θυγατέρ’ ἔγημεν· τεττάρων δὲ ταλάντων ἔνδον ὄντων, καὶ ταῦτ’ ἐκείνης ἐχούσης, ὡς οὗτός φησιν, οὐκ ἂν ἡγεῖσθ’ αὐτὸν κἂν ἐπιδραμεῖν, ὥστε γενέσθαι μετ’ ἐκείνης αὐτῶν κύριον.", "st": "27.56"}, {"sp": "N", "t": "ἢ τὴν μὲν φανερὰν οὐσίαν, ἣν καὶ ὑμῶν οἱ πολλοὶ συνῄδεσαν ὅτι κατελείφθη, μετὰ τῶν συνεπιτρόπων οὕτως αἰσχρῶς διήρπασεν, ὧν δ’ οὐκ ἐμέλλεθ’ ὑμεῖς ἔσεσθαι μάρτυρες, ἀπέσχετ’ ἂν ἐξὸν αὐτῷ λαβεῖν; καὶ τίς ἂν πιστεύσειεν; οὐκ ἔστιν ταῦτ’, ὦ ἄνδρες δικασταί, οὐκ ἔστιν, ἀλλὰ τὰ μὲν χρήματα, ὅσα κατέλιπεν ὁ πατήρ, πάντα τούτοις παρέδωκεν, οὗτος δ’, ἵν’ ἧττον ἐλεηθῶ παρ’ ὑμῖν, τούτοις τοῖς λόγοις χρήσεται.", "st": "27.57"}, {"sp": "N", "t": "πολλὰ μὲν οὖν ἔγωγ’ ἔχω καὶ ἄλλα τούτου κατηγορεῖν· ἓν δὲ περὶ πάντων κεφάλαιον εἰπών, πάσας αὐτοῦ διαλύσω τὰς ἀπολογίας. τούτῳ γὰρ ἐξῆν μηδὲν ἔχειν τούτων τῶν πραγμάτων, μισθώσαντι τὸν οἶκον κατὰ τουτουσὶ τοὺς νόμους. λαβὲ τοὺς νόμους καὶ ἀνάγνωθι.", "st": "27.58"}, {"sp": "N", "t": "ΝΟΜΟΙ.", "st": "27.58"}, {"sp": "N", "t": "κατὰ τούτους τοὺς νόμους Ἀντιδώρῳ μὲν ἐκ τριῶν ταλάντων καὶ τρισχιλίων ἐν ἓξ ἔτεσιν ἓξ τάλαντα καὶ πλέον ἐκ τοῦ μισθωθῆναι παρεδόθη, καὶ ταῦθ’ ὑμῶν τινὲς εἶδον· Θεογένης γὰρ ὁ Προβαλίσιος, ὁ μισθωσάμενος αὐτοῦ τὸν οἶκον, ἐν τῇ ἀγορᾷ ταῦτα τὰ χρήματ’ ἐξηρίθμησεν.", "st": "27.58"}, {"sp": "N", "t": "ἐμοὶ δ’ ἐκ τεττάρων καὶ δέκα ταλάντων ἐν δέκ’ ἔτεσιν πρὸς τὸν χρόνον τε καὶ τὴν ἐκείνου μίσθωσιν πλέον ἢ τριπλάσια κατὰ τὸ εἰκὸς προσῆκον γενέσθαι, τοῦτο διὰ τί οὐκ ἐποίησεν, ἐρωτᾶτ’ αὐτόν. εἰ μὲν γάρ φησι βέλτιον εἶναι μὴ μισθωθῆναι τὸν οἶκον, δειξάτω μὴ διπλάσια μηδὲ τριπλάσιά μοι γεγενημένα, ἀλλ’ αὐτὰ τὰ ἀρχαῖ’ ἐμοὶ πάντ’ ἀποδεδομένα. εἰ δ’ ἐκ τεττάρων καὶ δέκα ταλάντων ἐμοὶ μὲν μηδ’ ἑβδομήκοντα μνᾶς παραδεδώκασιν, ὁ δὲ καὶ πρὸς ὀφείλοντά μ’ αὑτῷ ἀπέγραψεν, πῶς ἀποδέξασθαί τι προσήκει τούτων λεγόντων; οὐδαμῶς δήπουθεν.", "st": "27.59"}, {"sp": "N", "t": "τοσαύτης τοίνυν οὐσίας μοι καταλειφθείσης ὅσην ἐξ ἀρχῆς ἠκούσατε, καὶ τοῦ τρίτου μέρους πρόσοδον αὐτῆς φερούσης πεντήκοντα μνᾶς, ἐξὸν τούτοις τοῖς ἀπληστοτάτοις χρημάτων, καὶ εἰ μὴ μισθοῦν τὸν οἶκον ἐβούλοντο, ἀπὸ μὲν τούτων τῶν προσιόντων, ἐῶντας ὥσπερ εἶχεν κατὰ χώραν, ἡμᾶς τε τρέφειν καὶ τὰ πρὸς τὴν πόλιν διοικεῖν, καὶ ὅσ’ ἐξαὐτῶν περιεγίγνετο.", "st": "27.60"}, {"sp": "N", "t": "ταῦτα προσπεριποιεῖν, τὴν δ’ ἄλλην οὐσίαν ἐνεργὸν ποιήσασιν, οὖσαν ταύτης διπλασίαν, αὑτοῖς τε, εἰ χρημάτων ἐπεθύμουν, μέτρι’ ἐξ αὐτῶν λαβεῖν, ἐμοί τε σὺν τοῖς ἀρχαίοις τὸν οἶκον ἐκ τῶν προσόδων μείζω ποιῆσαι, τούτων μὲν οὐδὲν ἐποίησαν, ἀποδόμενοι δ’ ἀλλήλοις τὰ πλείστου ἄξια τῶν ἀνδραπόδων, τὰ δὲ παντάπασιν ἀφανίσαντες, ἐμοῦ μὲν ἀνεῖλον καὶ τὴν ὑπάρχουσαν πρόσοδον, σφίσι δ’ αὐτοῖς οὐ μικρὰν ἐκ τῶν ἐμῶν κατεσκευάσαντο.", "st": "27.61"}, {"sp": "N", "t": "λαβόντες δὲ καὶ τἄλλ’ αἰσχρῶς οὑτωσὶ πάντα, πλέον ἢ τὰ ἡμίσεα τῶν χρημάτων μηδὲ καταλειφθῆναι κοινῇ πάντες ἀμφισβητοῦσιν, ὡς πεντεταλάντου δὲ μόνον τῆς οὐσίας οὔσης ἐκ τοσαύτης τοὺς λόγους ἀπενηνόχασιν, οὐ πρόσοδον μὲν ἐξ αὐτῶν οὐκ ἀποφαίνοντες, τὰ δὲ κεφάλαια φανερὰ ἀποδεικνύντες, ἀλλ’ αὐτὰ τὰ ἀρχαῖ’ οὕτως ἀναιδῶς ἀνηλῶσθαι φάσκοντες. καὶ οὐδ’ αἰσχύνονται ταῦτα τολμῶντες.", "st": "27.62"}, {"sp": "N", "t": "καίτοι τί ποτ’ ἂν ἔπαθον ὑπ’ αὐτῶν, εἰ πλείω χρόνον ἐπετροπεύθην; οὐκ ἂν ἔχοιεν εἰπεῖν. ὅπου γὰρ δέκ’ ἐτῶν διαγενομένων παρὰ μὲν τῶν οὕτω μικρὰ κεκόμισμαι, τῷ δὲ καὶ πρὸς ὀφείλων ἐγγέγραμμαι, πῶς οὐκ ἄξιον διαγανακτεῖν; δῆλον δὲ παντάπασιν· εἰ κατελείφθην μὲν ἐνιαύσιος, ἓξ ἔτη δὲ πρὸς ἐπετροπεύθην ὑπ’ αὐτῶν, οὐδ’ ἂν τὰ μικρὰ ταῦτα παρ’ αὐτῶν ἀπέλαβον. εἰ γὰρ ἐκεῖν’ ἀνήλωται ὀρθῶς, οὐδὲν ἂν τῶν νῦν παραδοθέντων ἐξήρκεσεν εἰς ἕκτον ἔτος, ἀλλ’ ἢ παρ’ αὑτῶν ἄν μ’ ἔτρεφον ἢ τῷ λιμῷ περιεῖδον ἀπολόμενον.", "st": "27.63"}, {"sp": "N", "t": "καίτοι πῶς οὐ δεινόν, εἰ ἕτεροι μὲν οἶκοι ταλαντιαῖοι καὶ διτάλαντοι καταλειφθέντες ἐκ τοῦ μισθωθῆναι διπλάσιοι καὶ τριπλάσιοι γεγόνασιν, ὥστ’ ἀξιοῦσθαι λῃτουργεῖν, ὁ δ’ ἐμὸς τριηραρχεῖν εἰθισμένος καὶ μεγάλας εἰσφορὰς εἰσφέρειν μηδὲ μικρὰς δυνήσεται διὰ τὰς τούτων ἀναισχυντίας; τίνας δ’ οὗτοι λελοίπασιν ὑπερβολὰς εἰπεῖν; οἳ καὶ τὴν διαθήκην ἠφανίκασιν ὡς λήσοντες, καὶ τὰς μὲν σφετέρας αὐτῶν οὐσίας ἐκ τῶν ἐπικαρπιῶν διῳκήκασι καὶ τἀρχαῖα τῶν ὑπαρχόντων ἐκ τῶν ἐμῶν πολλῷ μείζω πεποιήκασι, τῆς δ’ ἐμῆς οὐσίας, ὥσπερ τὰ μέγισθ’ ὑφ’ ἡμῶν ἀδικηθέντες, ὅλον τὸ κεφάλαιον ἀνῃρήκασι.", "st": "27.64"}, {"sp": "N", "t": "καὶ ὑμεῖς μὲν οὐδὲ τῶν εἰς ὑμᾶς ἁμαρτανόντων ὅταν τινὸς καταψηφίσησθε, οὐ πάντα τὰ ὄντ’ ἀφείλεσθε, ἀλλ’ ἢ γυναῖκας ἢ παιδί’ αὐτῶν ἐλεήσαντες μέρος τι κἀκείνοις ὑπελίπετε· οὗτοι δὲ τοσοῦτον διαφέρουσιν ὑμῶν, ὥστε καὶ δωρεὰς παρ’ ἡμῶν προσλαβόντες ἵνα δικαίως ἐπιτροπεύσωσι, τοιαῦτ’ εἰς ἡμᾶς ὑβρίκασι. καὶ οὐδ’ ᾐσχύνθησαν, εἰ μὴ ἠλέησαν, τὴν ἐμὴν ἀδελφήν, εἰ δυοῖν ταλάντοιν ὑπὸ τοῦ πατρὸς ἀξιωθεῖσα, μηδενὸς τεύξεται τῶν προσηκόντων, ἀλλ’ ὥσπερ ἔχθιστοί τινες, ἀλλ’ οὐ φίλοι καὶ συγγενεῖς καταλειφθέντες οὐδὲν τῆς οἰκειότητος ἐφρόντισαν.", "st": "27.65"}, {"sp": "N", "t": "ἀλλ’ ἐγὼ μὲν ὁ πάντων ταλαιπωρότατος πρὸς ἀμφότερ’ ἀπορῶ, ταύτην θ’ ὅπως ἐκδῶ καὶ τἄλλ’ ὁπόθεν διοικῶ. προσεπίκειται δ’ ἡ πόλις ἀξιοῦσ’ εἰσφέρειν, δικαίως· οὐσίαν γὰρ ἱκανὴν πρὸς ταῦτα κατέλιπέν μοι ὁ πατήρ. τὰ δὲ χρήματα τὰ καταλειφθένθ’ οὗτοι πάντ’ εἰλήφασιν.", "st": "27.66"}, {"sp": "N", "t": "καὶ νῦν κομίσασθαι τἀμαυτοῦ ζητῶν εἰς κίνδυνον καθέστηκα τὸν μέγιστον. ἂν γὰρ ἀποφύγῃ μ’ οὗτος, ὃ μὴ γένοιτο, τὴν ἐπωβελίαν ὀφλήσω μνᾶς ἑκατόν. καὶ τούτῳ μέν, ἐὰν καταψηφίσησθε, τιμητόν, κοὐκ ἐκ τῶν ἑαυτοῦ χρημάτων, ἀλλ’ ἐκ τῶν ἐμῶν ποιήσεται τὴν ἔκτεισιν· ἐμοὶ δ’ ἀτίμητον τοῦτ’ ἔστιν, ὥστ’ οὐ μόνον ἔσομαι τῶν πατρῴων ἀπεστερημένος, ἀλλὰ καὶ πρὸς ἠτιμωμένος, ἂν μὴ νῦν ἡμᾶς ὑμεῖς ἐλεήσητε.", "st": "27.67"}, {"sp": "N", "t": "δέομαι οὖν ὑμῶν, ὦ ἄνδρες δικασταί, καὶ ἱκετεύω καὶ ἀντιβολῶ, μνησθέντας καὶ τῶν νόμων καὶ τῶν ὅρκων οὓς ὀμόσαντες δικάζετε, βοηθῆσαι ἡμῖν τὰ δίκαια, καὶ μὴ περὶ πλείονος τὰς τούτου δεήσεις ἢ τὰς ἡμετέρας ποιήσασθαι. δίκαιοι δ’ ἔστ’ ἐλεεῖν οὐ τοὺς ἀδίκους τῶν ἀνθρώπων, ἀλλὰ τοὺς παραλόγως δυστυχοῦντας, οὐδὲ τοὺς ὠμῶς οὕτως τἀλλότρι’ ἀποστεροῦντας, ἀλλ’ ἡμᾶς τοὺς πολὺν χρόνον ὧν ὁ πατὴρ ἡμῖν κατέλιπεν στερομένους καὶ πρὸς ὑπὸ τούτων ὑβριζομένους καὶ νῦν περὶ ἀτιμίας κινδυνεύοντας.", "st": "27.68"}, {"sp": "N", "t": "μέγα δ’ ἂν οἶμαι στενάξαι τὸν πατέρ’ ἡμῶν, εἰ αἴσθοιτο τῶν προικῶν καὶ τῶν δωρεῶν ὧν αὐτὸς τούτοις ἔδωκεν, ὑπὲρ τούτων τῆς ἐπωβελίας τὸν αὑτοῦ υἱὸν ἐμὲ κινδυνεύοντα, καὶ ἄλλους μέν τινας ἤδη τῶν πολιτῶν οὐ μόνον συγγενῶν, ἀλλὰ καὶ φίλων ἀνδρῶν ἀπορούντων θυγατέρας παρὰ σφῶν αὐτῶν ἐκδόντας, Ἄφοβον δὲ μηδ’ ἣν ἔλαβεν προῖκ’ ἐθέλοντ’ ἀποδοῦναι, καὶ ταῦτ’ ἔτει δεκάτῳ.", "st": "27.69"}, {"sp": "HDR", "t": "Κατὰ Ἀφόβου Βʹ", "st": "28"}, {"sp": "N", "t": "πολλὰ καὶ μεγάλ’ ἐψευσμένου πρὸς ὑμᾶς Ἀφόβου, τοῦτ’ αὐτὸν ἐλέγξαι πειράσομαι πρῶτον, ἐφ’ ᾧ μάλιστ’ ἠγανάκτησα τῶν ῥηθέντων. εἶπεν γὰρ ὡς ὁ πάππος ὤφειλε τῷ δημοσίῳ, καὶ διὰ ταῦθ’ ὁ πατὴρ οὐκ ἐβούλετο μισθωθῆναι τὸν οἶκον, ἵνα μὴ κινδυνεύσῃ. καὶ τὴν μὲν πρόφασιν ποιεῖται ταύτην, ὡς δ’ ὀφείλων ἐτελεύτησεν ἐκεῖνος, οὐδεμίαν παρέσχετο μαρτυρίαν· ἀλλ’ ὡς μὲν ὦφλεν, ἐνεβάλετο τηρήσας τὴν τελευταίαν ἡμέραν, ταύτην δ’ εἰς τὸν ὕστερον λόγον ὑπελίπετο, ὡς διαβαλεῖν τὸ πρᾶγμ’ ἐξ αὐτῆς δυνησόμενος.", "st": "28.1"}, {"sp": "N", "t": "ἐὰν οὖν ἀναγνῷ, προσέχετ’ αὐτῇ τὸν νοῦν· εὑρήσετε γὰρ οὐχ ὡς ὀφείλει μεμαρτυρημένην, ἀλλ’ ὡς ὦφλεν. τοῦτ’ οὖν ἐλέγξαι πειράσομαι πρῶτον, ἐφ’ ᾧ φρονεῖ μάλιστα· ὃ καὶ ἡμεῖς ἀμφισβητοῦμεν. εἰ μὲν οὖν τότ’ ἐξεγένετο καὶ μὴ τῷ χρόνῳ τοῦτ’ ἐνηδρεύθημεν, παρεσχόμεθ’ ἂν μάρτυρας ὡς ἐξετείσθη τὰ χρήματα καὶ πάντ’ αὐτῷ διελέλυτο τὰ πρὸς τὴν πόλιν· νῦν δὲ τεκμηρίοις μεγάλοις ἐπιδείξομεν ὡς οὔτ’ ὤφειλεν οὔτ’ ἦν κίνδυνος οὐδεὶς ἡμῖν φανερὰ κεκτημένοις τὰ ὄντα.", "st": "28.2"}, {"sp": "N", "t": "πρῶτον μὲν γὰρ Δημοχάρης, ἔχων ἀδελφὴν τῆς ἐμῆς μητρός, θυγατέρα δὲ Γύλωνος, οὐκ ἀποκέκρυπται τὴν οὐσίαν, ἀλλὰ χορηγεῖ καὶ τριηραρχεῖ καὶ τὰς ἄλλας λῃτουργίας λῃτουργεῖ καὶ οὐδὲν τῶν τοιούτων δέδοικεν. ἔπειτ’ αὐτὸς ὁ πατὴρ τήν τ’ ἄλλην οὐσίαν καὶ τέτταρα τάλαντα καὶ τρισχιλίας φανερὰς ἐποίησεν, ἃς οὗτοι γραφῆναί τ’ ἐν ταῖς διαθήκαις καὶ λαβεῖν σφᾶς αὐτοὺς κατ’ ἀλλήλων καταμαρτυροῦσιν.", "st": "28.3"}, {"sp": "N", "t": "ἔτι δὲ καὶ αὐτὸς Ἄφοβος μετὰ τῶν συνεπιτρόπων τῇ πόλει τὸ πλῆθος τῶν καταλειφθέντων χρημάτων ἐμφανὲς ἐποίησεν, ἡγεμόνα με τῆς συμμορίας καταστήσας οὐκ ἐπὶ μικροῖς τιμήμασιν, ἀλλ’ ἐπὶ τηλικούτοις ὥστε κατὰ τὰς πέντε καὶ εἴκοσι μνᾶς πεντακοσίας εἰσφέρειν. καίτοι εἴ τι τούτων ἦν ἀληθές, οὐδὲν ἂν αὐτῶν ἐποίησεν, ἀλλὰ πάντ’ ἂν ηὐλαβήθη. νῦν δὲ καὶ Δημοχάρης καὶ ὁ πατὴρ καὶ αὐτοὶ οὗτοι φαίνονται φανερὰ ποιοῦντες, καὶ οὐδένα τοιοῦτον κίνδυνον δεδιότες.", "st": "28.4"}, {"sp": "N", "t": "πάντων δ’ ἀτοπώτατόν ἐστιν, λέγοντας ὡς ὁ πατὴρ οὐκ εἴα μισθοῦν τὸν οἶκον, τὴν μὲν διαθήκην μηδαμοῦ ταύτην ἀποφαίνειν, ἐξ ἧς ἦν εἰδέναι τἀκριβές, τηλικαύτην δ’ ἀνελόντας μαρτυρίαν οὕτως οἴεσθαι δεῖν εἰκῇ πιστεύεσθαι παρ’ ὑμῖν. ἀλλ’ ἐχρῆν, ἐπειδὴ τάχιστ’ ἐτελεύτησεν ὁ πατήρ, εἰσκαλέσαντας μάρτυρας πολλοὺς παρασημήνασθαι κελεῦσαι τὰς διαθήκας, ἵν’ εἴ τι ἐγίγνετ’ ἀμφισβητήσιμον, ἦν εἰς τὰ γράμματα ταῦτ’ ἐπανελθεῖν καὶ τὴν ἀλήθειαν πάντων εὑρεῖν.", "st": "28.5"}, {"sp": "N", "t": "νῦν δ’ ἕτερα μὲν παρασημήνασθαι ἠξίωσαν, ἐν οἷς πολλὰ τῶν καταλειπομένων οὐκ ἐγέγραπτο, ὑπομνήματα δ’ ἦν· αὐτὴν δὲ τὴν διαθήκην, δι’ ἧς τούτων ὧν ἐσημήναντο γραμμάτων καὶ τῶν ἄλλων ἁπάντων χρημάτων ἐγίγνοντο κύριοι, καὶ τοῦ μὴ μισθοῦν τὸν οἶκον τῆς αἰτίας ἀπελέλυντο, ταύτην δ’ οὐκ ἐσημήναντο, οὐδ’ αὐτὴν ἀπέδοσαν. ἄξιόν γε πιστεύειν αὐτοῖς ὅ τι ἂν περὶ τούτων λέγωσιν.", "st": "28.6"}, {"sp": "N", "t": "ἀλλ’ ἐγὼ οὐκ οἶδ’ ὅ τι τοῦτ’ ἔστιν. οὐκ εἴα μισθοῦν τὸν οἶκον οὐδ’ ἐμφανῆ τὰ χρήματα ποιεῖν ὁ πατήρ. πότερον ἐμοί; ἢ τῇ πόλει; φαίνεσθε γὰρ τοὐναντίον ἐκείνῃ μὲν φανερὰ ποιήσαντες, ἐμοὶ δὲ παντάπασιν ἀφανῆ πεποιηκότες, καὶ οὐδὲ ταῦτ’ ἀποφαίνοντες ἐξ ὧν τιμησάμενοι τὰς εἰσφορὰς εἰσεφέρετε. δείξατε γὰρ ταύτην τὴν οὐσίαν, τίς ἦν καὶ ποῦ παρέδοτέ μοι καὶ τίνος ἐναντίον.", "st": "28.7"}, {"sp": "N", "t": "τὰ μὲν γὰρ δύο τάλαντα καὶ τὰς ὀγδοήκοντα μνᾶς ἀπὸ τῶν τεττάρων ταλάντων καὶ τρισχιλίων ἐλάβετε, ὥστ’ οὐδὲ ταύτας ὑπὲρ ἐμοῦ εἰς τὸ δημόσιον ἐτιμήσασθε· ὑμέτεραι γὰρ ἦσαν ἐν ἐκείνοις τοῖς χρόνοις. ἀλλὰ μὴν ἔκ γε τῆς οἰκίας καὶ τῶν τεττάρων καὶ δέκ’ ἀνδραπόδων καὶ τῶν τριάκοντα μνῶν, ἅ μοι παρεδώκατε, τὴν εἰσφορὰν οὐχ οἷόν τε γενέσθαι τοσαύτην ὅσην ὑμεῖς συνετάξασθε πρὸς τὴν συμμορίαν.", "st": "28.8"}, {"sp": "N", "t": "ἀλλ’ ἀνάγκη μεγάλη τὰ καταλειφθέντα, πολλῷ πλείον’ ὄντα τούτων, πάνθ’ ὑμᾶς ἔχειν ἐστίν, ἃ φανερῶς ὅτι διηρπάκατ’ ἐξελεγχόμενοι τοιαῦτα πλάττεσθαι τολμᾶτε. καὶ τοτὲ μὲν εἰς ἀλλήλους ἀναφέρετε, πάλιν δ’ εἰληφέναι κατ’ ἀλλήλων μαρτυρεῖτε. φάσκοντες δ’ οὐ πολλὰ λαβεῖν μεγάλων ἀναλωμάτων λόγους ἀπενηνόχατε.", "st": "28.9"}, {"sp": "N", "t": "πάντες δὲ κοινῇ μ’ ἐπιτροπεύσαντες ἰδίᾳ μετὰ ταῦθ’ ἕκαστος μηχανᾶσθε. καὶ τὴν μὲν διαθήκην ἠφανίκατε, ἐξ ἧς ἦν εἰδέναι περὶ πάντων τὴν ἀλήθειαν, φαίνεσθε δ’ οὐδέποτε ταὐτὰ περὶ ἀλλήλων λέγοντες.", "st": "28.10"}, {"sp": "N", "t": "λαβὲ δὴ τὰς μαρτυρίας καὶ ἀνάγνωθ’ αὐτοῖς πάσας ἐφεξῆς, ἵνα μνησθέντες καὶ τῶν μεμαρτυρημένων καὶ τῶν εἰρημένων ἀκριβέστερον διαγιγνώσκωσι περὶ αὐτῶν.", "st": "28.10"}, {"sp": "N", "t": "ΜΑΡΤΥΡIΑΙ.", "st": "28.10"}, {"sp": "N", "t": "ταῦθ’ οὗτοι πρὸς πεντεκαιδεκαταλάντους οἴκους συνετιμήσανθ’ ὑπὲρ ἐμοῦ· μνῶν δ’ οὐδ’ ἑβδομήκοντ’ ἀξίαν μοι παραδεδώκασι τὴν οὐσίαν τρεῖς ὄντες. λέγε τὰς ἐφεξῆς.", "st": "28.11"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "28.11"}, {"sp": "N", "t": "ταύτην τὴν προῖκα οἵ τ’ ἐπίτροποι καταμαρτυροῦσιν αὐτὸν λαβεῖν, ἄλλοι τε πρὸς οὓς ἔχειν ὡμολόγησεν. ταύτην οὔτ’ αὐτὴν οὔτε τὸν σῖτον ἀποδέδωκεν. λαβὲ τὰς ἄλλας καὶ ἀναγίγνωσκε.", "st": "28.11"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "28.11"}, {"sp": "N", "t": "δύ’ ἔτη τὸ ἐργαστήριον διοικήσας Θηριππίδῃ μὲν ἀποδέδωκε τὴν μίσθωσιν· ἐμοὶ δέ, δυοῖν ἐτοῖν λαβὼν τὴν πρόσοδον, τριάκοντα μνᾶς, οὔτ’ αὐτὰς οὔτε τὸ ἔργον ἀποδέδωκεν. λάβ’ ἑτέραν καὶ ἀνάγνωθι.", "st": "28.12"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "28.12"}, {"sp": "N", "t": "ταῦτα τἀνδράποδ’ ὡς αὑτὸν λαβὼν οὗτος, καὶ τἄλλα τὰ μετὰ τούτων ὑποτεθένθ’ ἡμῖν, ἀνάλωμα μὲν εἰς αὐτὰ τοσοῦτο λελόγισται, λῆμμα δ’ ἀπ’ αὐτῶν οὐδ’ ὁτιοῦν, καὶ αὐτοὺς δὲ τοὺς ἀνθρώπους ἠφάνικεν, οἳ δώδεκα μνᾶς ἀτελεῖς ἑκάστου τοῦ ἐνιαυτοῦ προσέφερον. λέγ’ ἑτέραν.", "st": "28.12"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ", "st": "28.12"}, {"sp": "N", "t": "τοῦτον τὸν ἐλέφαντα καὶ τὸν σίδηρον πεπρακὼς οὐδὲ καταλειφθῆναί φησιν, ἀλλὰ καὶ τούτων τὴν τιμὴν ἀποστερεῖ με, μάλιστα τάλαντον. λέγε ταυτασί.", "st": "28.13"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "28.13"}, {"sp": "N", "t": "ταῦθ’ οὗτος τρία τάλαντα καὶ χιλίας ἔχει χωρὶς τῶν ἄλλων. τοῦ μὲν οὖν ἀρχαίου πέντε τάλανθ’ ἃ εἴληφεν· σὺν δὲ τοῖς ἔργοις, ἂν ἐπὶ δραχμῇ τις τιθῇ μόνον, πλέον ἢ δέκα τάλαντ’ ἔχει. λέγε τὰς ἐφεξῆς.", "st": "28.13"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "28.13"}, {"sp": "N", "t": "ταῦθ’ οὗτοι γραφῆναι μὲν ἐν ταῖς διαθήκαις καὶ λαβεῖν σφᾶς αὐτοὺς κατ’ ἀλλήλων μαρτυροῦσιν. οὗτος δὲ καὶ μεταπεμφθῆναι φάσκων ὑπὸ τοῦ πατρός, καὶ ἐλθὼν εἰς τὴν οἰκίαν, εἰσελθεῖν μὲν οὔ φησιν ὡς τὸν μεταπεμψάμενον, οὐδ’ ὁμολογῆσαι περὶ τούτων οὐδέν, Δημοφῶντος δ’ ἀκοῦσαι γραμματεῖον ἀναγιγνώσκοντος καὶ Θηριππίδου λέγοντος ὡς ἐκεῖνος ταῦτα διέθετο, καὶ προεισεληλυθὼς καὶ ἅπαντα διωμολογημένος πρὸς τὸν πατέρα, ὅσαπερ ἐκεῖνος γράψας κατέλιπεν.", "st": "28.14"}, {"sp": "N", "t": "ὁ γὰρ πατήρ, ὦ ἄνδρες δικασταί, ὡς ᾔσθετο τὴν νόσον οὐκ ἀποφευξόμενος, συγκαλέσας τούτους τρεῖς ὄντας, καὶ συμπαρακαθισάμενος Δήμωνα τὸν ἀδελφόν, τὰ σώμαθ’ ἡμῶν εἰς τὰς χεῖρας ἐνέθηκεν παρακαταθήκην ἐπονομάζων, τὴν μὲν ἀδελφὴν Δημοφῶντι καὶ δύο τάλαντα προῖκα διδοὺς εὐθύς, καὶ γυναῖκ’ αὐτῷ ταύτην ἐγγυῶν, ἐμὲ δὲ πᾶσιν κοινῇ μετὰ τῶν χρημάτων παρακατατιθέμενος, καὶ ἐπισκήπτων μισθῶσαί τε τὸν οἶκον καὶ συνδιασῷσαί μοι τὴν οὐσίαν,", "st": "28.15"}, {"sp": "N", "t": "διδοὺς ἅμα τε Θηριππίδῃ τὰς ἑβδομήκοντα μνᾶς, καὶ τούτῳ τήν τ’ ἐμὴν μητέρ’ ἐγγυῶν ἐπὶ ταῖς ὀγδοήκοντα μναῖς, κἄμ’ εἰς τὰ τούτου γόνατα τιθείς· ὧν οὗτος ὁ πάντων ἀνθρώπων ἀνοσιώτατος οὐδένα λόγον ἐποιήσατο, κύριος τῶν ἐμῶν γενόμενος ἐπὶ τούτοις, ἀλλὰ τὰ χρήματά με πάντ’ ἀπεστερηκὼς μετὰ τῶν συνεπιτρόπων, ἐλεεῖσθαι νῦν ὑφ’ ὑμῶν ἀξιώσει, μνῶν οὐδ’ ἑβδομήκοντ’ ἄξια τρίτος αὐτὸς ἀποδεδωκώς, εἶτα καὶ τούτοις αὐτοῖς πάλιν ἐπιβεβουλευκώς.", "st": "28.16"}, {"sp": "N", "t": "ὡς γὰρ τὰς δίκας ταύτας ἔμελλον εἰσιέναι κατ’ αὐτῶν, ἀντίδοσιν ἐπ’ ἐμὲ παρεσκεύασαν, ἵν’ εἰ μὲν ἀντιδοίην, μὴ ἐξείη μοι πρὸς αὐτοὺς ἀντιδικεῖν, ὡς καὶ τῶν δικῶν τούτων τοῦ ἀντιδόντος γιγνομένων, εἰ δὲ μηδὲν τούτων ποιοίην, ἵν’ ἐκ βραχείας οὐσίας λῃτουργῶν παντάπασιν ἀναιρεθείην. καὶ τοῦτ’ αὐτοῖς ὑπηρέτησε Θρασύλοχος ὁ Ἀναγυράσιος· ᾧ τούτων οὐδὲν ἐνθυμηθεὶς ἀντέδωκα μέν, ἀπέκλεισα δ’ ὡς διαδικασίας τευξόμενος· οὐ τυχὼν δὲ ταύτης, τῶν χρόνων ὑπογύων ὄντων, ἵνα μὴ στερηθῶ τῶν δικῶν, ἀπέτεισα τὴν λῃτουργίαν ὑποθεὶς τὴν οἰκίαν καὶ τἀμαυτοῦ πάντα, βουλόμενος εἰς ὑμᾶς εἰσελθεῖν τὰς πρὸς τουτουσὶ δίκας.", "st": "28.17"}, {"sp": "N", "t": "ἆρ’ οὐ μεγάλα μὲν ἐξ ἀρχῆς ἠδίκημαι, μεγάλα δ’, ὅτι δίκην ζητῶ λαβεῖν, νῦν ὑπ’ αὐτῶν βλάπτομαι; τίς δ’ οὐκ ἂν ὑμῶν τούτῳ μὲν φθονήσειε δικαίως, ἡμᾶς δ’ ἐλεήσειεν, ὁρῶν τῷ μὲν πρὸς τῇ οὐσίᾳ τῇ παραδοθείσῃ πλεῖν ἢ δέκα ταλάντων τὴν ἐμὴν τοσαύτην οὖσαν προσγεγενημένην, ἡμᾶς δὲ μὴ μόνον τῶν πατρῴων διημαρτηκότας, ἀλλὰ καὶ τῶν νῦν παραδοθέντων διὰ τὴν τούτων πονηρίαν ἀπεστερημένους; ποῖ δ’ ἂν τραποίμεθα, εἴ τι ἄλλο ψηφίσαισθ’ ὑμεῖς περὶ αὐτῶν; εἰς τὰ ὑποκείμενα τοῖς δανείσασιν; ἀλλὰ τῶν ὑποθεμένων ἐστίν. ἀλλ’ εἰς τὰ περιόντ’ αὐτῶν; ἀλλὰ τούτου γίγνεται, τὴν ἐπωβελίαν ἐὰν ὄφλωμεν.", "st": "28.18"}, {"sp": "N", "t": "μηδαμῶς, ὦ ἄνδρες δικασταί, γένησθ’ ἡμῖν τοσούτων αἴτιοι κακῶν· μηδὲ τὴν μητέρα κἀμὲ καὶ τὴν ἀδελφὴν ἀνάξια παθόντας περιίδητε, οὓς ὁ πατὴρ οὐκ ἐπὶ ταύταις ταῖς ἐλπίσιν κατέλιπεν, ἀλλὰ τὴν μὲν ὡς Δημοφῶντι συνοικήσουσαν ἐπὶ δυοῖν ταλάντοιν προικί, τὴν δ’ ἐπ’ ὀγδοήκοντα μναῖς τούτῳ τῷ σχετλιωτάτῳ πάντων ἀνθρώπων, ἐμὲ δ’ ὑμῖν διάδοχον ἀνθ’ αὑτοῦ τῶν λῃτουργιῶν ἐσόμενον.", "st": "28.19"}, {"sp": "N", "t": "βοηθήσατ’ οὖν ἡμῖν, βοηθήσατε, καὶ τοῦ δικαίου καὶ ὑμῶν αὐτῶν ἕνεκα καὶ ἡμῶν καὶ τοῦ πατρὸς τοῦ τετελευτηκότος. σῴσατε, ἐλεήσατε, ἐπειδή μ’ οὗτοι συγγενεῖς ὄντες οὐκ ἠλέησαν. εἰς ὑμᾶς καταπεφεύγαμεν. ἱκετεύω, ἀντιβολῶ πρὸς παίδων, πρὸς γυναικῶν, πρὸς τῶν ὄντων ἀγαθῶν ὑμῖν. οὕτως ὄναισθε τούτων, μὴ περιίδητέ με, μηδὲ ποιήσητε τὴν μητέρα καὶ τῶν ἐπιλοίπων ἐλπίδων εἰς τὸν βίον στερηθεῖσαν ἀνάξιον αὑτῆς τι παθεῖν·", "st": "28.20"}, {"sp": "N", "t": "ἣ νῦν μὲν οἴεται τυχόντα με τῶν δικαίων παρ’ ὑμῖν ὑποδέξεσθαι καὶ τὴν ἀδελφὴν ἐκδώσειν· εἰ δ’ ὑμεῖς ἄλλο τι γνώσεσθε, ὃ μὴ γένοιτο, τίν’ οἴεσθ’ αὐτὴν ψυχὴν ἕξειν, ὅταν ἐμὲ μὲν ἴδῃ μὴ μόνον τῶν πατρῴων ἀπεστερημένον, ἀλλὰ καὶ πρὸς ἠτιμωμένον, περὶ δὲ τῆς ἀδελφῆς μηδ’ ἐλπίδ’ ἔχουσαν ὡς τεύξεταί τινος τῶν προσηκόντων διὰ τὴν ἐσομένην ἀπορίαν;", "st": "28.21"}, {"sp": "N", "t": "οὐκ ἄξιος, ὦ ἄνδρες δικασταί, οὔτ’ ἐγὼ δίκης ἐν ὑμῖν μὴ τυχεῖν, οὔθ’ οὗτος τοσαῦτα χρήματ’ ἀδίκως κατασχεῖν. ἐμοῦ μὲν γὰρ εἰ καὶ μήπω πεῖραν εἰλήφατε, ποῖός τις ἂν εἰς ὑμᾶς εἴην, ἐλπίζειν προσήκει μὴ χείρω τοῦ πατρὸς ἔσεσθαι. τούτου δὲ πεῖραν ἔχετε, καὶ σαφῶς ἴσθ’ ὅτι πολλὴν οὐσίαν παραλαβὼν οὐ μόνον οὐδὲν πεφιλοτίμηται πρὸς ὑμᾶς, ἀλλὰ καὶ τἀλλότρι’ ἀποστερῶν ἀποδέδεικται.", "st": "28.22"}, {"sp": "N", "t": "ταῦτ’ οὖν σκοποῦντες καὶ τἄλλα μνησθέντες, ᾗ δίκαιόν ἐστι, ταύτῃ ψηφίσασθε. πίστεις δ’ ἔχεθ’ ἱκανὰς ἐκ μαρτύρων, ἐκ τεκμηρίων, ἐκ τῶν εἰκότων, ἐξ ὧν οὗτοι λαβεῖν ὁμολογοῦντες ἁθρόα τἀμά, ταῦτ’ ἀνηλωκέναι φασὶν οὐκ ἀνηλωκότες, ἀλλ’ αὐτοὶ πάντ’ ἔχοντες.", "st": "28.23"}, {"sp": "N", "t": "ὧν ἐνθυμουμένους χρὴ ποιήσασθαί τιν’ ἡμῶν πρόνοιαν, εἰδότας ὅτι ἐγὼ μὲν τἀμαυτοῦ δι’ ὑμῶν κομισάμενος εἰκότως λῃτουργεῖν ἐθελήσω, χάριτας ὀφείλων ὅτι μοι δικαίως ἀπέδοτε τὴν οὐσίαν, οὗτος δ’, ἐὰν αὐτὸν ποιήσητε τῶν ἐμῶν κύριον, οὐδὲν ποιήσει τοιοῦτον. μὴ γὰρ οἴεσθ’ αὐτόν, ὑπὲρ ὧν ἤρνηται μὴ λαβεῖν, ὑπὲρ τούτων ὑμῖν λῃτουργεῖν ἐθελήσειν, ἀλλ’ ἀποκρύψεσθαι μᾶλλον, ἵνα δικαίως ἀποπεφευγέναι δοκῇ.", "st": "28.24"}, {"sp": "HDR", "t": "Πρὸς Ἄφοβον ὑπὲρ Φάνου ψευδομαρτυριῶν Γʹ", "st": "29"}, {"sp": "N", "t": "εἰ μὴ πρότερόν μοι δίκης γενομένης πρὸς Ἄφοβον, ὦ ἄνδρες δικασταί, συνῄδειν πολλῷ τούτων μείζω καὶ δεινότερ’ αὐτοῦ ψευσαμένου ῥᾳδίως ἐξελέγξας διὰ τὴν περιφάνειαν τῶν ἀδικημάτων, θαυμασίως ἂν ὡς ηὐλαβούμην μὴ καὶ νῦν οὐ δυνηθῶ δεῖξαι, πῇ παρακρούεταί ποθ’ ἕκασθ’ ὑμᾶς αὐτῶν. νῦν δὲ σὺν θεοῖς εἰπεῖν, ἄνπερ ἴσοι καὶ κοινοὶ γένησθ’ ἡμῶν ἀκροαταί, πολλὰς ἐλπίδας ἔχω μηδὲν ἧττον ὑμᾶς τὴν ἀναίδειαν τὴν τούτου γνώσεσθαι τῶν πρότερον δικασάντων. καὶ ταῦτ’ εἰ μὲν ἐδεῖτο λόγου τινὸς ἢ ποικιλίας, ἔγωγε κατώκνουν ἂν τὴν ἐμαυτοῦ καταμεμφόμενος ἡλικίαν· νῦν δ’ ἁπλῶς δεῖ διδάξαι καὶ διηγήσασθαι τὰ τούτῳ πεπραγμένα περὶ ἡμῶν· ἐκ δὲ τούτων οἶμαι πᾶσιν ὑμῖν εὔγνωστον ἔσεσθαι, πότερός ποθ’ ἡμῶν ἐσθ’ ὁ πονηρός.", "st": "29.1"}, {"sp": "N", "t": "οἶδα μὲν οὖν ὅτι τὴν δίκην οὗτος εἴληχε ταύτην, οὐχὶ τῷ τὰ ψευδῆ τιν’ αὑτοῦ καταμεμαρτυρηκέναι ἐξελέγξειν πιστεύων, ἀλλ’ ἡγούμενος διὰ τὸ μέγεθος τοῦ τιμήματος τῆς δίκης, ἣν ὦφλεν, ἐμοὶ μὲν ἂν γενέσθαι τινὰ φθόνον, αὑτῷ δ’ ἔλεον. καὶ διὰ ταῦτα περὶ τῆς γεγενημένης δίκης νῦν ἀπολογεῖται, περὶ ἧς τότ’ οὐδὲν ἔσχε δίκαιον εἰπεῖν. ἐγὼ δ’, ὦ ἄνδρες δικασταί, εἰ μὲν ἐπεπράγμην τοῦτον τὴν δίκην ἢ μηδὲν ἤθελον μέτριον συγχωρεῖν, ἠδίκουν μὲν οὐδ’ ἂν οὕτως, τὰ παρ’ ὑμῖν γνωσθέντα πραττόμενος αὐτόν, ὅμως δ’ ἂν εἶχέν τις εἰπεῖν, ὡς λίαν ὠμῶς καὶ πικρῶς ὄντα συγγενῆ τοῦτον ἐκ τῆς οὐσίας ἁπάσης ἐκβέβληκα.", "st": "29.2"}, {"sp": "N", "t": "νῦν δὲ τοὐναντίον ἐστίν· οὗτος ἐμὲ τῶν πατρῴων ἁπάντων μετὰ τῶν συνεπιτρόπων ἀπεστέρηκεν, καὶ οὐδ’ ἐν ὑμῖν φανερῶς ἐξελεγχθεὶς οἴεται δεῖν οὐδὲν τῶν μετρίων ποιεῖν, ἀλλὰ διασκευασάμενος τὴν οὐσίαν, καὶ παραδοὺς τὴν μὲν συνοικίαν Αἰσίῳ, τὸν δ’ ἀγρὸν Ὀνήτορι, πρὸς μὲν ἐκείνους δίκην καὶ πράγματ’ ἔχειν ἐμὲ πεποίηκεν, ἐκ δὲ τῆς οἰκίας αὐτὸς τὰ σκεύη λαβὼν καὶ τἀνδράποδ’ ἐξαγαγὼν καὶ τὸν λάκκον συντρίψας καὶ τὰ θυρώματ’ ἀποσπάσας καὶ μόνον οὐκ αὐτὴν τὴν οἰκίαν ἐμπρήσας Μέγαράδ’ ἐξῴκηκεν κἀκεῖ μετοίκιον τέθηκεν. ὥστε πολὺ ἂν δικαιότερον διὰ ταῦτα τὰ ἔργα τοῦτον μισήσαιτε ἢ ἐμοῦ τιν’ ἀνεπιείκειαν καταγνοίητε.", "st": "29.3"}, {"sp": "N", "t": "περὶ μὲν οὖν τῆς αἰσχροκερδίας τῆς τούτου καὶ μιαρίας ὕστερόν μοι δοκεῖ διεξελθεῖν πρὸς ὑμᾶς· καὶ νῦν δ’ ὡς ἐν κεφαλαίοις ἀκηκόατε· περὶ δὲ τῶν μεμαρτυρημένων, ὡς ἔστιν ἀληθῆ, περὶ ὧνπερ οἴσετε τὴν ψῆφον, ἤδη πειράσομαι διδάσκειν ὑμᾶς. δέομαι δ’ ὑμῶν, ὦ ἄνδρες δικασταί, δικαίαν δέησιν, ἐξ ἴσου ἡμῶν ἀμφοτέρων ἀκοῦσαι. τοῦτο δ’ ἐστὶ καὶ ὑπὲρ ὑμῶν ὁμοίως· ὅσῳ γὰρ ἂν ἀκριβέστερον τὰ πεπραγμένα μάθητε, τοσούτῳ δικαιοτέραν καὶ εὐορκοτέραν θήσεσθε τὴν ψῆφον περὶ αὐτῶν.", "st": "29.4"}, {"sp": "N", "t": "ἐπιδείξω δὲ τοῦτον οὐ μόνον ὡμολογηκότ’ εἶναι τὸν Μιλύαν ἐλεύθερον, ἀλλὰ καὶ φανερὸν τοῦτ’ ἔργῳ πεποιηκότα, καὶ πρὸς τούτοις ⟨τοὺς⟩ ἐκ βασάνου περὶ αὐτῶν πεφευγότα τοῦτον τοὺς ἀκριβεστάτους ἐλέγχους, καὶ οὐκ ἐθελήσαντ’ ἐκ τούτων ἐπιδεῖξαι τὴν ἀλήθειαν, ἀλλὰ πανουργοῦντα καὶ μάρτυρας ψευδεῖς παρεχόμενον καὶ διακλέπτοντα τοῖς ἑαυτοῦ λόγοις τὴν ἀλήθειαν τῶν πεπραγμένων, οὕτω μεγάλοις καὶ φανεροῖς ἐλέγχοις ὥσθ’ ὑμᾶς πάντας εἴσεσθαι σαφῶς, ὅτι ἡμεῖς μὲν ἀληθῆ λέγομεν, οὗτος δ’ οὐδὲν ὑγιὲς εἴρηκεν. ἄρξομαι δ’ ἐντεῦθεν ὅθεν καὶ ὑμεῖς ῥᾷστ’ ἂν μάθοιτε κἀγὼ τάχιστ’ ἂν διδάξαιμι.", "st": "29.5"}, {"sp": "N", "t": "ἐγὼ γάρ, ὦ ἄνδρες δικασταί, Δημοφῶντι καὶ Θηριππίδῃ καὶ τούτῳ δίκας ἔλαχον ἐπιτροπῆς ἀποστερηθεὶς ἁπάντων τῶν ὄντων. γενομένης δέ μοι τῆς δίκης πρὸς τοῦτον πρῶτον, ἐπέδειξα σαφῶς τοῖς δικάζουσιν, ὥσπερ ὑμῖν ἐπιδείξω, πάνθ’ ὅσ’ ἡμῖν κατελείφθη χρήματ’ ἀπεστερηκότα τοῦτον μετ’ ἐκείνων, οὐ καταψευδομαρτυρησάμενος.", "st": "29.6"}, {"sp": "N", "t": "τεκμήριον δὲ μέγιστον· μαρτυριῶν γὰρ πλέον ἢ πάνυ πολλῶν τῶν ἁπασῶν ἀναγνωσθεισῶν ἐπὶ τῇ δίκῃ, καὶ τούτων τῶν μὲν ὡς ἔδοσάν τι τούτῳ τῶν ἐμῶν καταμαρτυρουσῶν, τῶν δ’ ὡς παρῆσαν κομιζομένῳ, τῶν δ’ ὡς πριάμενοι παρὰ τούτου τούτῳ τὰς τιμὰς διέλυσαν, οὐδ’ ᾗ τινι τούτων τῶν ψευδομαρτυρίων ἐπεσκήψατο, οὐδὲ τετόλμηκεν διώκειν ἀλλ’ ἢ ταύτην μίαν οὖσαν, ἐν ᾗ δραχμὴν οὐκ ἂν ἔχοι δεῖξαι μεμαρτυρημένην.", "st": "29.7"}, {"sp": "N", "t": "καίτοι τό γε τίμημα τῶν χρημάτων ὧν ἀπεστερήμην, οὐκ ἐκ ταύτης συντιθεὶς ἐλογιζόμην τοσοῦτον (οὐ γὰρ ἔνεστ’ ἀργύριον), ἀλλ’ ἐξ ἐκείνων καθ’ ἕκαστα τιθείς, αἷς οὗτος οὐκ ἐπεσκήψατο. ὅθεν οἱ τότ’ ἀκούσαντες οὐ μόνον αὐτοῦ κατέγνωσαν, ἀλλὰ καὶ τῶν ἐπιγεγραμμένων ἐτίμησαν. τίνος οὖν ἕνεκ’ ἐκείνας μὲν εἴασε, τῇδε δ’ ἐπεσκήψατο; ἐγὼ καὶ τοῦτο διδάξω.", "st": "29.8"}, {"sp": "N", "t": "τῶν μαρτυριῶν ὅσαι μὲν αὐτοῦ χρήματ’ ἔχειν κατεμαρτύρουν, ᾔδει σαφῶς ὅτι τοσούτῳ μᾶλλον ἐξελεγχθήσεται ταῦτ’ ἔχων, ὅσῳ πλείων λόγος δοθήσεται καθ’ ἓν περὶ ἑκάστου. τοῦτο δ’ ἔμελλεν ἐν τῇ τῶν ψευδομαρτυρίων ἔσεσθαι κρίσει· ὃ γὰρ τότ’ ἐν μικρῷ μέρει τινὶ τοῦ παντὸς ὕδατος μετὰ τῶν ἄλλων κατηγορήσαμεν, νῦν πρὸς ἅπαν τὸ ὕδωρ αὐτὸ καθ’ αὑτὸ διδάξειν ἐμέλλομεν.", "st": "29.9"}, {"sp": "N", "t": "ἀποκρίσει δ’ ἐπισκηψάμενος ἐνόμιζεν, ὥσπερ τόθ’ ὡμολόγησεν, οὕτω πάλιν ἔξαρνος γενέσθαι ταῦτ’ ἐφ’ ἑαυτῷ γενήσεσθαι. διὰ ταῦτα τήνδε διώκει. βούλομαι δὴ ταύτην, ὡς ἔστιν ἀληθής, ἐπιδεῖξαι σαφῶς πᾶσιν ὑμῖν, οὐκ ἐξ εἰκότων οὐδὲ λόγων πρὸς τὸ παρὸν μεμηχανημένων, ἀλλ’ ἐκ τοῦ παρὰ πᾶσιν ὑμῖν δόξοντος, ὡς ἐγὼ νομίζω, δικαίου. σκοπεῖτε δ’ ἀκούσαντες.", "st": "29.10"}, {"sp": "N", "t": "ἐγὼ γάρ, ὦ ἄνδρες δικασταί, περὶ τῆς μαρτυρίας τῆς ἐν τῷ γραμματείῳ γεγραμμένης εἰδὼς ὄντα μοι τὸν ἀγῶνα, καὶ περὶ τούτου τὴν ψῆφον ὑμᾶς οἴσοντας ἐπιστάμενος, ᾠήθην δεῖν μηδὲν ἄλλο τούτου πρότερον ἢ τοῦτον προκαλούμενος ἐλέγξαι. καὶ τί ποιῶ; παραδοῦναι παῖδ’ ἤθελον αὐτῷ γράμματ’ ἐπιστάμενον βασανίζειν, ὃς παρῆν ὅθ’ ὡμολόγει ταῦθ’ οὗτος, καὶ τὴν μαρτυρίαν ἔγραφεν, οὐδὲν ὑφ’ ἡμῶν κελευσθεὶς κακοτεχνεῖν, οὐδὲ τὸ μὲν γράφειν, τὸ δ’ ἀφαιρεῖν ὧν οὗτος εἰρήκει περὶ τούτων, ἀλλ’ ἁπλῶς ὑπὲρ τοῦ πάντα τἀληθῆ καὶ τὰ τούτῳ ῥηθέντα γράψαι.", "st": "29.11"}, {"sp": "N", "t": "καίτοι τί κάλλιον ἦν τοῦ τὸν παῖδα στρεβλοῦντ’ ἐλέγξαι ψευδομένους ἡμᾶς; ἀλλὰ συνῄδει πάντων μάλιστ’ ἀνθρώπων ὅτι τἀληθῆ μεμαρτύρηται· διόπερ ἔφευγε τὴν βάσανον. ἀλλὰ μὴν οὐχ εἷς οὐδὲ δύο ταῦτ’ ἴσασιν, οὐδ’ ὑπὸ μάλης ἡ πρόκλησις γέγονεν, ἀλλ’ ἐν τῇ ἀγορᾷ μέσῃ πολλῶν παρόντων. καί μοι κάλει τούτων τοὺς μάρτυρας.", "st": "29.12"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "29.12"}, {"sp": "N", "t": "οὕτω τοίνυν οὗτός ἐστιν σοφιστὴς καὶ σφόδρ’ ἑκὼν τὰ δίκαι’ ἀγνοεῖν προσποιούμενος, ὥστε ψευδομαρτυρίων διώκων, καὶ περὶ τούτου τὴν ψῆφον ὑμῶν μελλόντων οἴσειν καὶ ὀμωμοκότων, περὶ τῆς μαρτυρίας μὲν ἔφευγε τὴν βάσανον, περὶ οὗ μάλιστα προσῆκεν αὐτῷ τὸν λόγον ποιεῖσθαι, περὶ δ’ ἄλλων φησὶν ἐξαιτεῖν, ψευδόμενος.", "st": "29.13"}, {"sp": "N", "t": "καίτοι πῶς οὐχ ὑπερφυές, αὑτὸν μὲν δεινὰ πεπονθέναι φάσκειν, εἰ τὸν ἐλεύθερον ἐξαιτῶν, ὡς ἐγὼ σαφῶς ὑμῖν ἐπιδείξω, μὴ παρέλαβεν, τοὺς δὲ μάρτυρας οὐ δεινὰ πάσχειν νομίζειν, τὸν ὁμολογουμένως δοῦλον περὶ ὧν ἐμαρτύρησαν ἐκδιδόντος, οὐκ ἐθέλοντος τούτου παραλαβεῖν; οὐ γὰρ δὴ τοῦτό γ’ ἔνεστιν εἰπεῖν, ὡς περὶ μὲν τινῶν ὧν αὐτὸς βούλεται σαφὴς ἡ βάσανος, περὶ δ’ αὖ τινῶν οὐ σαφής.", "st": "29.14"}, {"sp": "N", "t": "ἔτι τοίνυν, ὦ ἄνδρες δικασταί, ταύτην τὴν μαρτυρίαν ἐμαρτύρησεν ἁδελφὸς ὁ τούτου πρῶτος Αἴσιος, ὃς νῦν μὲν ἔξαρνός ἐστιν τούτῳ συναγωνιζόμενος, τότε δ’ ἐμαρτύρησεν ταῦτα μετὰ τῶν ἄλλων, οὔτ’ ἐπιορκεῖν οὔτ’ εὐθὺς παραχρῆμα δίκην ὀφλισκάνειν βουλόμενος. ὃν οὐκ ἂν δήπου, ψευδῆ μαρτυρίαν εἰ παρεσκευαζόμην, ἐνέγραψ’ ἂν εἰς τοὺς μάρτυρας, ὁρῶν μὲν Ἀφόβῳ χρώμενον μάλιστ’ ἀνθρώπων ἁπάντων, εἰδὼς δὲ συνεροῦντ’ αὐτῷ τὴν δίκην, ἔτι δ’ ἐμαυτοῦ ὄντ’ ἀντίδικον· οὐ γὰρ ἔχει λόγον τὸν ἑαυτοῦ διάφορον καὶ τούτου ἀδελφὸν μὴ ἀληθινῆς μαρτυρίας ἐγγράψαι μάρτυρα.", "st": "29.15"}, {"sp": "N", "t": "τούτων τοίνυν εἰσὶ μὲν πολλοὶ μάρτυρες, ἔτι δ’ οὐκ ἐλάττω τεκμήρια τῶν μαρτύρων. πρῶτον μὲν γάρ, εἴπερ ὡς ἀληθῶς ταῦτα μὴ ἐμαρτύρησεν, οὐκ ἂν νῦν ἔξαρνος ἦν, ἀλλὰ τότ’ εὐθὺς ἐπὶ τοῦ δικαστηρίου τῆς μαρτυρίας ἀναγιγνωσκομένης, ἡνίκα μᾶλλον ἂν αὐτὸν ἢ νῦν ὠφέλει. δεύτερον δ’ οὐκ ἂν ἡσυχίαν ἦγεν, ἀλλὰ δίκην ἄν μοι βλάβης ἔλαχεν, εἰ ψευδομαρτυρίων ὑπόδικον αὐτὸν ἐποίουν κατὰ τἀδελφοῦ οὐ προσῆκον, ἐν ᾗ καὶ περὶ χρημάτων καὶ περὶ ἀτιμίας ἄνθρωποι κινδυνεύουσιν.", "st": "29.16"}, {"sp": "N", "t": "ἔτι δὲ τὸ πρᾶγμ’ ἂν ἐξελέγξαι ζητῶν, ἐξῄτησεν ἄν με τὸν παῖδα τὸν γράφοντα τὰς μαρτυρίας, ἵν’ εἰ μὴ παρεδίδουν, μηδὲν δίκαιον λέγειν ἐδόκουν. νῦν δὲ τοσούτου ποιῆσαί τι τούτων ἐδέησεν, ὥστ’ οὐδ’ ἐμοῦ παραδιδόντος, ἐπειδὴ ταῦτ’ ἔξαρνος ἐγένεθ’ οὗτος, παραλαβεῖν ἠθέλησεν, ἀλλ’ ὁμοίως φαίνονται καὶ περὶ τούτων φεύγοντες τὰς βασάνους.", "st": "29.17"}, {"sp": "N", "t": "καὶ ταῦθ’ ὡς ἀληθῆ λέγω, καὶ ἔν τε τοῖς μάρτυσιν μεμαρτυρηκὼς [Αἴσιος] οὐκ ἠρνήθη ταῦτ’ ἐπὶ τοῦ δικαστηρίου τούτῳ παρεστηκὼς τῆς μαρτυρίας ἀναγιγνωσκομένης, ἐμοῦ τ’ ἐκδιδόντος τὸν παῖδα περὶ ἁπάντων τούτων βασανίζειν αὐτοῖς οὐκ ἠθέλησε παραλαβεῖν, καθ’ ἕκαστον ὑμῖν παρέξομαι τοὺς μάρτυρας. καί μοι κάλει δεῦρ’ αὐτούς.", "st": "29.18"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "29.18"}, {"sp": "N", "t": "ὃ τοίνυν, ὦ ἄνδρες δικασταί, πάντων τῶν εἰρημένων οἶμαι μέγιστον ὑμῖν ἐρεῖν σημεῖον τοῦ ταῦτ’ ἀποκρίνασθαι τοῦτον, βούλομαι διελθεῖν. ἐπειδὴ γὰρ ἐξῄτει με τὸν ἄνθρωπον ταῦθ’ ὡμολογηκὼς ἃ μεμαρτύρηται, βουλόμενος καὶ τότ’ αὐτὸν ἐξελέγξαι τεχνάζοντα τί ποιῶ;", "st": "29.19"}, {"sp": "N", "t": "προσκαλοῦμαι κατὰ Δήμωνος εἰς μαρτυρίαν, ὄντος αὐτῷ θείου καὶ κοινωνοῦ τῶν ἀδικημάτων, καὶ συγγράψας ταῦτ’ ἐκέλευον μαρτυρεῖν, ἃ νῦν διώκει τῶν ψευδομαρτυρίων. οὗτος δὲ τὸ μὲν πρῶτον ἀπηναισχύντει, τοῦ δὲ διαιτητοῦ κελεύοντος μαρτυρεῖν ἢ ἐξομνύειν ἐμαρτύρησεν πάνυ μόγις. καίτοι εἴ γ’ ἦν δοῦλος ἅνθρωπος καὶ μὴ προωμολόγητο πρὸς τοῦδ’ ἐλεύθερος εἶναι, τί μαθὼν ἐμαρτύρησεν, ἀλλ’ οὐκ ἐξομόσας ἀπηλλάγη τοῦ πράγματος;", "st": "29.20"}, {"sp": "N", "t": "ἀλλὰ μὴν καὶ περὶ τούτων ἤθελον παραδοῦναι τὸν παῖδα τὸν γράφοντα τὴν μαρτυρίαν, ὃς τά τε γράμματ’ ἔμελλεν γνώσεσθαι τὰ ἑαυτοῦ καὶ τοῦτον ἐμνημόνευεν ἀκριβῶς μαρτυρήσαντα ταῦτα. καὶ ταῦτ’ ἤθελον οὐχὶ μαρτύρων ἀπορῶν οἳ παρῆσαν (ἦσαν γάρ), ἀλλ’ ἵνα μὴ τούτους αἰτιῷτο τὰ ψευδῆ μαρτυρεῖν, ἀλλὰ τὸ πιστὸν ἐκ τῆς βασάνου τούτοις ὑπάρχοι. καίτοι πῶς ἄξιόν ἐστι καταγνῶναι τῶν μαρτύρων διὰ τοῦτο, οἳ μόνοι τῶν πώποτ’ ἠγωνισμένων δίκην ἐν ὑμῖν τὸν διώκοντ’ αὐτὸν αὑτοῖς μάρτυρα τούτων ἐπιδεικνύουσιν γεγενημένον; ἀλλὰ μὴν ὡς ἀληθῆ λέγω, λαβὲ τὴν πρόκλησιν καὶ τὴν μαρτυρίαν.", "st": "29.21"}, {"sp": "N", "t": "ΠΡΟΚΛΗΣΙΣ. ΜΑΡΤΥΡΙΑ.", "st": "29.21"}, {"sp": "N", "t": "τηλικαῦτα τοίνυν δίκαια φυγὼν οὗτος, καὶ ἐκ τοσούτων τεκμηρίων ἐπιδεικνύμενος ὅτι συκοφαντεῖ, τοῖς μὲν αὑτοῦ μάρτυσιν ἀξιοῖ πιστεύειν ὑμᾶς, τοὺς δ’ ἐμοὺς διαβάλλει καί φησιν οὐ τἀληθῆ μαρτυρεῖν. βούλομαι δὴ καὶ ἐκ τῶν εἰκότων περὶ αὐτῶν εἰπεῖν. οἶδ’ οὖν ὅτι πάντες ἂν ὁμολογήσαιτε τοὺς τὰ ψευδῆ μαρτυροῦντας ἢ κέρδεσιν δι’ ἀπορίαν ἐπαιρομένους ἢ δι’ ἑταιρίαν ἢ καὶ δι’ ἔχθραν τῶν ἀντιδίκων ἐθέλειν ἄν τι τοιοῦτον ποιῆσαι.", "st": "29.22"}, {"sp": "N", "t": "τούτων τοίνυν οὐδὲ δι’ ἓν ἂν εἶεν ἐμοὶ μεμαρτυρηκότες. οὔτε γὰρ ἑταιρίᾳ (πῶς γάρ; οἵ γε μήτ’ ἐν ταῖς αὐταῖς διατριβαῖς μήτε καθ’ ἡλικίαν, μὴ ὅτι ἐμοί τινες αὐτῶν, ἀλλ’ οὐδὲ σφίσιν αὐτοῖς εἰσίν), οὔτ’ ἔχθρᾳ τούτου· φανερὸν γὰρ καὶ τοῦτ’ ἔστιν· ὁ μὲν γὰρ ἀδελφὸς καὶ σύνδικος, Φᾶνος δ’ ἐπιτήδειος καὶ φυλέτης, Φίλιππος δ’ οὔτε φίλος οὔτ’ ἐχθρός, ὥστ’ οὐδὲ ταύτην ἄν τις ἐπενέγκοι δικαίως τὴν αἰτίαν.", "st": "29.23"}, {"sp": "N", "t": "καὶ μὴν οὐδὲ δι’ ἀπορίαν ἄν τις φήσειεν· πάντες γὰρ κέκτηνται τοσαύτην οὐσίαν ὥστε καὶ λῃτουργεῖν ὑμῖν προθύμως καὶ τὰ προσταττόμενα ποιεῖν. χωρὶς δὲ τούτων οὔτ’ ἀγνῶτες ὑμῖν οὔτ’ ἐπὶ τὰ χείρω γιγνωσκόμενοι, μέτριοι δ’ ὄντες ἄνθρωποι. καίτοι εἰ μήτ’ ἄποροι μήτ’ ἐχθροὶ τούτου μήτ’ ἐμοὶ φίλοι, πῶς χρὴ κατὰ τούτων λαβεῖν τιν’ ὑποψίαν ὡς τὰ ψευδῆ μαρτυροῦσιν; ἐγὼ μὲν γὰρ οὐκ οἶδα.", "st": "29.24"}, {"sp": "N", "t": "ταῦτα τοίνυν οὗτος εἰδώς, καὶ πάντων μάλιστ’ ἐπιστάμενος τἀληθῆ μεμαρτυρηκότας αὐτούς, ὅμως συκοφαντεῖ καί φησιν οὐ μόνον οὐκ εἰπεῖν ταῦτα, ἃ πῶς τις ἂν μᾶλλον ἐξελέγξειεν εἰρηκότα; ἀλλὰ καὶ δοῦλον εἶναι τὸν ἄνθρωπον τῷ ὄντι. βούλομαι δὲ διὰ βραχέων εἰπὼν πρὸς ὑμᾶς ἐξελέγξαι καὶ ταῦτ’ αὐτὸν ψευδόμενον. ἐγὼ γάρ, ὦ ἄνδρες δικασταί, καὶ περὶ τούτων ἠθέλησα τούτῳ παραδοῦναι βασανίζειν τὰς θεραπαίνας, αἳ τελευτῶντος τοῦ πατρὸς μνημονεύουσιν ἀφεθέντα τοῦτον ἐλεύθερον εἶναι τότε.", "st": "29.25"}, {"sp": "N", "t": "καὶ πρὸς τούτοις ἡ μήτηρ κατ’ ἐμοῦ καὶ τῆς ἀδελφῆς, οἳ μόνοι παῖδές ἐσμεν αὐτῇ, δι’ οὓς κατεχήρευσε τὸν βίον, πίστιν ἤθελεν ἐπιθεῖναι παραστησαμένη, τὸν ἄνθρωπον τοῦτον ἀφεῖναι τὸν πατέρ’ ἡνίκ’ ἐτελεύτα, καὶ νομίζεσθαι παρ’ ἡμῖν τοῦτον ἐλεύθερον· ἣν μηδεὶς ὑμῶν νομιζέτω καθ’ ἡμῶν ποτ’ ἂν ὀμνύναι ταῦτ’ ἂν ἐθέλειν, εἰ μὴ σαφῶς ᾔδει τὰ εὔορκ’ ὀμουμένη. ἀλλὰ μὴν ὡς ἀληθῆ λέγω καὶ ταῦτ’ ἦμεν ἕτοιμοι ποιεῖν, κάλει τούτων τοὺς μάρτυρας.", "st": "29.26"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "29.26"}, {"sp": "N", "t": "τοσαῦτα τοίνυν δίκαια λέγειν ἐχόντων ἡμῶν καὶ καταφεύγειν εἰς τοὺς μεγίστους ἐλέγχους ἐθελόντων περὶ τῶν μεμαρτυρημένων, πάντα ταῦτα φυγὼν οὗτος οἴεται, περὶ τῆς γεγενημένης δίκης διαβάλλων καὶ κατηγορῶν ἐμοῦ, τοῦ μάρτυρος ὑμᾶς πείσειν καταψηφίσασθαι, πάντων οἶμαι πρᾶγμα κατασκευάσας ἀδικώτατον καὶ πλεονεκτικώτατον.", "st": "29.27"}, {"sp": "N", "t": "αὐτὸς μὲν γὰρ μάρτυρας ψευδεῖς παρεσκεύασται περὶ τούτων, συγχορηγὸν ἔχων Ὀνήτορα τὸν κηδεστὴν καὶ Τιμοκράτην· ἡμεῖς δ’ οὐχὶ προειδότες, ἀλλ’ ὑπὲρ αὐτῆς τῆς μαρτυρίας ἡγούμενοι τὸν ἀγῶν’ ἔσεσθαι, τοὺς περὶ τῶν ἐκ τῆς ἐπιτροπῆς χρημάτων μάρτυρας οὐ παρεσκευάσμεθα νῦν. ὅμως δέ, καίπερ οὕτως τούτου σεσοφισμένου, τὰ πράγματ’ αὐτὰ διεξιὼν οἶμαι ῥᾳδίως ὑμῖν ἐπιδείξειν δικαιότατ’ ἀνθρώπων τοῦτον ὠφληκότα τὴν δίκην,", "st": "29.28"}, {"sp": "N", "t": "οὐχ ὅτι τὸν Μιλύαν ἐκώλυον βασανίζειν, οὐδ’ ὅτι τοῦτον ἐλεύθερον ὡμολόγησεν, οἱ δὲ μάρτυρες οἵδ’ ἐμαρτύρησαν, ἀλλ’ ὅτι πολλὰ τῶν ἐμῶν ἐξηλέγχθη λαβὼν καὶ τὸν οἶκον οὐκ ἐμίσθωσεν τῶν νόμων κελευόντων καὶ τοῦ πατρὸς ἐν τῇ διαθήκῃ γράψαντος, ὡς ἐγὼ σαφῶς ὑμῖν ἐπιδείξω· ταῦτα μὲν γὰρ ἦν πᾶσιν ἰδεῖν, οἱ νόμοι καὶ τὸ πλῆθος ὧν οὗτοι διηρπάκεσαν χρημάτων· τὸν Μιλύαν δ’ οὐδ’ ὅστις ἔστιν οὐδεὶς ᾔδει. γνώσεσθε δ’ ἐκ τῶν ἐγκεκλημένων ὅτι ταῦθ’ οὕτως ἔχοντ’ ἐστίν.", "st": "29.29"}, {"sp": "N", "t": "ἐγὼ γάρ, ὦ ἄνδρες δικασταί, τὴν δίκην ἔλαχον τούτῳ τῆς ἐπιτροπῆς οὐχ ἓν τίμημα συνθείς, ὥσπερ ἂν εἴ τις συκοφαντεῖν ἐπιχειρῶν, ἀλλ’ ἕκαστον ἐγγράψας καὶ πόθεν λαβὼν καὶ πόσον τὸ πλῆθος καὶ παρὰ τοῦ, καὶ οὐδαμοῦ τὸν Μιλύαν παρέγραψ’ ὡς εἰδότα τι τούτων.", "st": "29.30"}, {"sp": "N", "t": "ἔστιν οὖν τοῦ μὲν ἐγκλήματος ἀρχή “τάδ’ ἐγκαλεῖ Δημοσθένης Ἀφόβῳ· ἔχει μου χρήματ’ Ἄφοβος ἀπ’ ἐπιτροπῆς ἐχόμενα, ὀγδοήκοντα μὲν μνᾶς, ἣν ἔλαβεν προῖκα τῆς μητρὸς κατὰ τὴν διαθήκην τοῦ πατρός”. τοῦτο πρῶτόν ἐστιν τῶν χρημάτων ὧν ἀπεστερῆσθαί φημι. τοῖς δὲ μάρτυσιν τί μεμαρτύρηται; “μαρτυροῦσιν παραγενέσθαι πρὸς τῷ διαιτητῇ Νοθάρχῳ, ὅτε Ἄφοβος ὡμολόγει Μιλύαν ἐλεύθερον εἶναι, ἀφεθέντα ὑπὸ τοῦ Δημοσθένους πατρός.”", "st": "29.31"}, {"sp": "N", "t": "σκοπεῖτε τοίνυν παρ’ ὑμῖν αὐτοῖς, εἴ τις ἂν ὑμῖν ἢ ῥήτωρ ἢ σοφιστὴς ἢ γόης οὕτω θαυμάσιος δοκεῖ γενέσθαι καὶ λέγειν δεινός, ὥστ’ ἐκ ταύτης τῆς μαρτυρίας διδάξαι τιν’ ἀνθρώπων, ὡς ἔχει τὴν προῖκ’ Ἄφοβος τῆς μητρὸς τῆς ἑαυτοῦ. καὶ τί λέγων, ὦ πρὸς Διός; “ὡμολόγησεν εἶναι Μιλύαν ἐλεύθερον;” καὶ τί μᾶλλον ἔχων τὴν προῖκα; οὐδὲν ἂν δήπου διὰ τοῦτό γε δόξειεν.", "st": "29.32"}, {"sp": "N", "t": "ἀλλὰ πόθεν τοῦτ’ ἐπεδείχθη; πρῶτον μὲν Θηριππίδης ὢν αὐτῷ συνεπίτροπος κατεμαρτύρησε δοῦναι· δεύτερον δὲ Δήμων θεῖος ὢν καὶ τῶν ἄλλων οἱ παρόντες ἐμαρτύρησαν σῖτον τῇ μητρὶ δώσειν ὁμολογεῖν τοῦτον ὡς ἔχοντα τὴν προῖκα. καὶ τούτοις οὐκ ἐπεσκήψατο, δῆλον ὅτι τἀληθῆ μεμαρτυρηκότας εἰδώς. ἔτι τοίνυν ἡ μήτηρ πίστιν ἠθέλησεν ἐπιθεῖναι κατ’ ἐμοῦ καὶ τῆς ἀδελφῆς παραστησαμένη, λαβεῖν τὴν προῖκα τοῦτον τὴν ἑαυτῆς κατὰ τὴν τοῦ πατρὸς διαθήκην.", "st": "29.33"}, {"sp": "N", "t": "ταύτας τὰς ὀγδοήκοντα μνᾶς πότερ’ αὐτὸν ἔχειν φῶμεν ἢ μή; καὶ πότερον διὰ τούσδ’ ὀφλεῖν τοὺς μάρτυρας ἢ διὰ τούσδε; ἐγὼ μὲν γὰρ οἶμαι διὰ τὴν ἀλήθειαν. ταύτας τοίνυν δέκ’ ἔτη κεκαρπωμένος, καὶ οὐδὲ δίκην ὀφλὼν ἀποδοῦναι τετολμηκώς, δεινὰ πεπονθέναι φησὶν καὶ διὰ τούσδε τοὺς μάρτυρας ὠφληκέναι. καίτοι τούτων γ’ οὐδεὶς αὐτὸν ἔχειν ταύτην ἐμαρτύρησεν.", "st": "29.34"}, {"sp": "N", "t": "περὶ τοίνυν τῆς ἐκδόσεως καὶ τῶν κλινοποιῶν καὶ τοῦ σιδήρου καὶ τοῦ καταλειφθέντος ἡμῖν ἐλέφαντος καὶ τῆς προικὸς τῆς ἀδελφῆς, ἣν οὗτος καθυφεῖκεν ὑπὲρ τοῦ καὶ αὐτὸς ἔχειν ὅσα βούλοιτο τῶν ἐμῶν, ἀκούσατε, καὶ σκοπεῖθ’ ὡς δικαίως τ’ ὤφληκεν καὶ οὐδὲν ἦν Μιλύαν περὶ τούτων βασανιστέον.", "st": "29.35"}, {"sp": "N", "t": "περὶ μὲν γὰρ ὧν καθυφεῖκας, νόμος ἔστιν, διαρρήδην ὃς κελεύει σ’ ὁμοίως ὀφλισκάνειν ὥσπερ ἂν αὐτὸς ἔχῃς· ὥστε τί τῷ νόμῳ καὶ τῇ βασάνῳ; περὶ δ’ αὖ τῆς ἐκδόσεως, ἐπικοινωνήσαντες τῷ Ξούθῳ καὶ διανειμάμενοι τὰ χρήματα καὶ τὰς συγγραφὰς ἀνελόντες, καὶ πάνθ’ ὃν τρόπον ἐβούλεσθε κατασκευάσαντες, καὶ διαφθείραντες τὰ γράμματα, ὡς ὑμῶν ὁ Δήμων κατεμαρτύρει, φενακίζετε καὶ τουτουσὶ παρακρούσασθαι ζητεῖτε.", "st": "29.36"}, {"sp": "N", "t": "περὶ τοίνυν τῶν κλινοποιῶν, εἰ σὺ λαβὼν ἀργύριον καὶ πόλλ’ ἰδίᾳ κερδάνας ἐπὶ τοῖς ἐμοῖς δανείζων, ὃν καὶ τοὺς ἄλλους προσῆκε κωλύειν, εἶτ’ ἀφανεῖς πεποίηκας, τί σοι ποιήσωσιν οἱ μάρτυρες; οὐ γὰρ οὗτοί γε μεμαρτυρήκασιν, ὡς ὡμολόγεις ἐπὶ τοῖς ἐμοῖς δανείζειν καὶ λαβεῖν τἀνδράποδ’ ὡς σαυτόν, ἀλλ’ ἐν τῷ λόγῳ τοῦτ’ ἔγραψας σύ, κατεμαρτύρησαν δ’ οἱ μάρτυρες.", "st": "29.37"}, {"sp": "N", "t": "ἀλλὰ μὴν περί γε τοῦ ἐλέφαντος καὶ τοῦ σιδήρου, πάντας ἐγώ φημι τοὺς οἰκέτας εἰδέναι τοῦτον πωλοῦντα, καὶ παραδοῦναι καὶ τότε καὶ νῦν ἤθελον αὐτῷ τούτων ὅντινα βούλοιτο λαβὼν βασανίζειν. εἰ τοίνυν φήσει με, τὸν εἰδότ’ οὐκ ἐθέλοντα δοῦναι, τοὺς οὐκ εἰδότας ἐκδιδόναι, πολὺ δὴ μᾶλλον αὐτῷ παραλαβεῖν φανήσεται προσῆκον· εἰ γάρ, οὓς ὡς εἰδότας ἐξεδίδουν ἐγώ, μηδὲν ἔχειν ἔφασαν τούτων αὐτόν, ἀπήλλακτο δήπουθεν ἂν τῆς αἰτίας.", "st": "29.38"}, {"sp": "N", "t": "ἀλλ’ οὐχὶ τοιοῦτόν ἐστιν, ἀλλὰ σαφῶς ἂν ἐξηλέγχθη πωλῶν καὶ τὴν τιμὴν κεκομισμένος. διόπερ τοὺς ὁμολογουμένως δούλους παραβὰς τὸν ἐλεύθερον ἠξίου βασανίζειν, ὃν οὐδ’ ὅσιον παραδοῦναι, τὸ πρᾶγμ’ οὐκ ἄγειν εἰς ἔλεγχον ζητῶν, ἀλλὰ μὴ παραλαμβάνων βουλόμενός τι δοκεῖν λέγειν. περὶ τοίνυν πάντων τούτων, πρῶτον μὲν περὶ τῆς προικός, εἶθ’ ὑπὲρ ὧν καθυφεῖκεν, εἶθ’ ὑπὲρ τῶν ἄλλων, ἀναγνώσεται τούς τε νόμους καὶ τὰς μαρτυρίας, ἵν’ εἰδῆτε.", "st": "29.39"}, {"sp": "N", "t": "ΝΟΜΟΙ. ΜΑΡΤΥΡΙΑΙ.", "st": "29.39"}, {"sp": "N", "t": "οὐ τοίνυν μόνον ἐκ τούτων ἂν γνοίητε, ὅτι δεινὸν οὐδ’ ὁτιοῦν πέπονθεν τὸν ἄνθρωπον οὐκ ἐκδόντος ἐμοῦ βασανίζειν, ἀλλὰ καὶ τὸ πρᾶγμ’ αὔτ’ εἰ σκέψαισθε. θῶμεν γὰρ δὴ τὸν Μιλύαν ἐπὶ τοῦ τροχοῦ στρεβλοῦσθαι, καὶ τί μάλιστ’ ἂν αὐτὸν εὔξαιτο λέγειν σκοπῶμεν. οὐχ ὅτι τῶν χρημάτων οὐδ’ ὁτιοῦν οἶδεν τοῦτον ἔχοντα; καὶ δὴ λέγει. διὰ τοῦτ’ ἄρ’ οὐκ ἔχει; πολλοῦ γε δεῖ· τοὺς γὰρ εἰδότας καὶ παρόντας μάρτυρας παρεσχόμην ἐγώ. τεκμήριον δὲ καὶ πίστις ἐστίν, οὐκ εἴ τίς τι μὴ οἶδε τοῦτον ἔχοντα (πολλοὶ γὰρ ἂν εἶεν), ἀλλ’ εἴ τις οἶδεν.", "st": "29.40"}, {"sp": "N", "t": "καταμαρτυρησάντων τοίνυν τοσούτων σου μαρτύρων, τίνι τῶν ψευδομαρτυρίων ἐπεσκήψω; δεῖξον. ἀλλ’ οὐκ ἂν ἔχοις δεῖξαι. καίτοι πῶς οὐ σαφῶς σὺ σαυτὸν ἐξελέγχεις, ὅτι ψεύδει δεινὰ πεπονθέναι φάσκων καὶ τὴν δίκην ἀδίκως ὠφληκέναι τὸν ἄνθρωπον οὐ παραλαβών, ὃς τοὺς ταῦτα μαρτυρήσαντας ἔχειν σε καὶ λαβεῖν, περὶ ὧν ὡς οὐ καταλειφθέντων σὺ τὸν Μιλύαν ἐξῄτεις, ἀφῆκας τῶν ψευδομαρτυρίων; οὓς πολὺ κάλλιον ἦν, εἴπερ ἠδίκησο, διώκειν. ἀλλ’ οὐκ ἠδικημένος σὺ συκοφαντεῖς.", "st": "29.41"}, {"sp": "N", "t": "πολλαχόθεν μὲν οὖν ἄν τις ἴδοι τὴν σὴν πονηρίαν, μάλιστα δ’ εἰ περὶ τῆς διαθήκης ἀκούσειεν. τοῦ γὰρ πατρός, ὦ ἄνδρες δικασταί, τὰ καταλειφθέντα πάντ’ ἐν τῇ διαθήκῃ γράψαντος, καὶ τὸν οἶκον ὅπως μισθώσουσιν, ταύτην μὲν οὐκ ἀπέδωκεν, ἵνα μὴ τὸ πλῆθος εὕροιμ’ ἐγὼ τῶν χρημάτων ἐξ αὐτῆς, ὡμολόγει δὲ [κεκτῆσθαι] ταῦτα, ἃ μάλιστ’ οὐχ οἷόν τ’ ἦν ἐξάρνῳ γενέσθαι διὰ τὴν περιφάνειαν.", "st": "29.42"}, {"sp": "N", "t": "ἦν δὲ ταῦθ’ ἃ γεγράφθαι φησὶν ἐν τῇ διαθήκῃ, δύο μὲν τάλαντα Δημοφῶντα λαβεῖν εὐθύς, τὴν δ’ ἀδελφὴν ὅταν ἡλικίαν ἔχῃ (τοῦτο δ’ ἔμελλεν εἰς ἔτος δέκατον γενήσεσθαι), τοῦτον δ’ ὀγδοήκοντα μνᾶς καὶ τὴν μητέρα τὴν ἐμὴν καὶ τὴν οἰκίαν οἰκεῖν, Θηριππίδην δ’ ἑβδομήκοντα μνᾶς λαβόντα καρπώσασθαι, τέως ἀνὴρ ἐγὼ γενοίμην. τὰ δ’ ἄλλ’ ὅσ’ ἐμοὶ χωρὶς τούτων κατελείφθη, καὶ τὸ μισθοῦν τὸν οἶκον ἠφάνιζεν ἐκ τῆς διαθήκης, οὐ συμφέρον αὑτῷ νομίζων ταῦτ’ ἐπιδειχθῆναι παρ’ ὑμῖν.", "st": "29.43"}, {"sp": "N", "t": "ἐπειδὴ τοίνυν ὡμολόγηθ’ ὑπ’ αὐτοῦ τούτου τὸν πατέρ’ ἡμῶν τελευτῶντα τοσοῦτον ἀργύριον τούτων ἑκάστῳ δοῦναι, τεκμήριον οἱ δικάζοντες τότε τὰς ὁμολογίας ἐποιήσαντο ταύτας τοῦ πλήθους τῶν χρημάτων· ὅστις γὰρ ἀπὸ τῶν ὄντων τέτταρα τάλαντα καὶ τρισχιλίας προῖκα καὶ δωρεὰν ἔδωκεν, φανερὸν ἦν ὅτι οὐκ ἀπὸ μικρᾶς οὐσίας, ἀλλὰ πλέον ἢ διπλασίας ἧς ἐμοὶ κατέλειπεν ταῦτ’ ἀφεῖλεν.", "st": "29.44"}, {"sp": "N", "t": "οὐ γὰρ ἂν ἐδόκει τὸν μὲν υἱὸν ἐμὲ πένητα βούλεσθαι καταστῆσαι, τούτους δὲ πλουσίους ὄντας ἔτι πλουσιωτέρους ποιῆσαι ἐπιθυμεῖν, ἀλλ’ ἕνεκα τοῦ πλήθους τῶν ἐμοὶ καταλειπομένων Θηριππίδῃ τε τὰς ἑβδομήκοντα μνᾶς καὶ Δημοφῶντι τὰ δύο τάλαντα, οὔπω μέλλοντι τῇ ἀδελφῇ τῇ ἐμῇ συνοικήσειν, καρποῦσθαι δοῦναι. ταῦτα δὴ τὰ χρήματ’ οὐδαμοῦ παραδοὺς ἐφαίνετο, οὐδ’ ἐλάττω μικροῖς· ἀλλὰ τὰ μὲν ἀνηλωκέναι, τὰ δ’ οὐ λαβεῖν ἔφη, τὰ δ’ οὐκ εἰδέναι, τὰ δὲ τὸν δεῖν’ ἔχειν, τὰ δ’ ἔνδον εἶναι, τὰ δὲ πάντα μᾶλλον ἢ ὅπου παρέδωκεν εἶχεν λέγειν.", "st": "29.45"}, {"sp": "N", "t": "περὶ δὲ τοῦ μὴ καταλειφθῆναι τὰ χρήματ’ ἔνδον, βούλομαι σαφῶς ὑμῖν ἐπιδεῖξαι ψευδόμενον. τοῦτον γὰρ τὸν λόγον καθεῖκεν, ἐπειδὴ τὰ χρήματα μὲν πολλὰ πέφηνεν ὄντα, οὐκ ἔχει δ’ ἐπιδεῖξαι ταῦθ’ ὡς ἀποδέδωκεν, ἵν’ ἐξ εἰκότος οὐδὲν προσῆκον ἡμῖν φανῇ κομίζεσθαι τά γ’ ὄντα παρ’ ἡμῖν.", "st": "29.46"}, {"sp": "N", "t": "εἰ μὲν τοίνυν ὁ πατὴρ ἠπίστει τούτοις, δῆλον ὅτι οὔτ’ ἂν τἄλλ’ ἐπέτρεπεν, οὔτ’ ἂν ἐκεῖν’ οὕτω καταλείπων αὐτοῖς ἔφραζεν· ὥστε πόθεν ἴσασιν; εἰ δ’ ἐπίστευεν, οὐκ ἂν δήπου τὰ μὲν πλεῖστ’ αὐτοῖς τῶν χρημάτων ἐνεχείρισεν, τῶν δ’ οὐκ ἂν κυρίους ἐποίησεν. οὐδ’ ἂν τῇ μὲν μητρί μου ταῦτα φυλάττειν παρέδωκεν, αὐτὴν δὲ ταύτην ἑνὶ τῶν ἐπιτρόπων τούτῳ γυναῖκ’ ἠγγύησεν· οὐ γὰρ ἔχει λόγον, σῷσαι μὲν τὰ χρήματα δι’ ἐκείνης ζητεῖν, ἕνα δὲ τῶν ἀπιστουμένων ταύτης κἀκείνων κύριον ποιεῖν.", "st": "29.47"}, {"sp": "N", "t": "ἔτι δὲ τοῦτον, εἴ τι τούτων ἀληθὲς ἦν, οἴεσθ’ οὐκ ἂν αὐτὴν λαβεῖν δοθεῖσαν ὑπὸ τοῦ πατρός; ὃς τὴν μὲν προῖκ’ αὐτῆς ἤδη, τὰς ὀγδοήκοντα μνᾶς, ἔχων ὡς αὐτῇ συνοικήσων, τὴν Φιλωνίδου τοῦ Μελιτέως θυγατέρ’ ἔγημεν δι’ αἰσχροκερδίαν, ἵνα πρὸς αἷς εἶχεν παρ’ ἡμῶν, ἑτέρας ὀγδοήκοντα μνᾶς λάβοι παρ’ ἐκείνου· τεττάρων δὲ ταλάντων ἔνδον ὄντων καὶ ταῦτ’ ἐκείνης ἐχούσης, ὡς οὗτός φησιν, οὐκ ἂν ἡγεῖσθ’ αὐτὸν κἂν ἐπιδραμεῖν, ὥστε γενέσθαι μετ’ ἐκείνης αὐτῶν κύριον;", "st": "29.48"}, {"sp": "N", "t": "ἢ τὴν μὲν φανερὰν οὐσίαν, ἣν καὶ ὑμῶν πολλοὶ συνῄδεσαν ὅτι κατελείφθη, μετὰ τῶν συνεπιτρόπων οὕτως αἰσχρῶς διήρπασεν, ὧν δ’ οὐκ ἐμέλλεθ’ ὑμεῖς ἔσεσθαι μάρτυρες, ἀπέσχετ’ ἂν ἐξὸν αὐτῷ λαβεῖν; καὶ τίς ἂν πιστεύσειεν; οὐκ ἔστι ταῦτ’, ὦ ἄνδρες δικασταί, οὐκ ἔστιν· ἀλλὰ τὰ μὲν χρήματα, ὅσα κατέλιπεν ὁ πατήρ, ἐκείνῃ τῇ ἡμέρᾳ κατωρύττετο, ὅτ’ εἰς τὰς τούτων χεῖρας ἦλθεν, οὗτος δ’ οὐκ ἔχων ἂν εἰπεῖν ὅπου τι τούτων ἀπέδωκεν, ἵν’ εὔπορος εἶναι δοκῶν μηδενὸς τύχω παρ’ ὑμῶν ἐλέου, τούτοις χρῆται τοῖς λόγοις.", "st": "29.49"}, {"sp": "N", "t": "πολλὰ μὲν οὖν ἔγωγ’ ἔχω καὶ ἄλλα τούτου κατηγορεῖν· οὐκ ἐνδέχεται δέ μοι, τῷ μάρτυρι τοῦ κινδύνου περὶ τῆς ἐπιτιμίας ὄντος, περὶ ὧν αὐτὸς ἠδίκημαι λέγειν. ἀλλὰ βούλομαι πρόκλησιν ὑμῖν ἀναγνῶναι· γνώσεσθε γὰρ ἐξ αὐτῆς ἀκούσαντες, τὰ μεμαρτυρημέν’ ὡς ἔστιν ἀληθῆ, καὶ τὸν Μιλύαν ὅτι νῦν μὲν περὶ πάντων φησὶν ἐξαιτεῖν, τὸ δὲ πρῶτον ὑπὲρ τριάκοντα μόνον μνῶν ἐξῄτει, καὶ προσέτι ζημιοῦται κατὰ τὴν μαρτυρίαν οὐδέν.", "st": "29.50"}, {"sp": "N", "t": "ἐγὼ γὰρ πανταχῇ τοῦτον ἐλέγξαι βουλόμενος, καὶ τὰς τέχνας αὐτοῦ καὶ τὰς πανουργίας ἐμφανεῖς ὑμῖν καταστῆσαι πειρώμενος, ἠρόμην αὐτὸν πόσ’ εἴη τὰ χρήματα τὸ πλῆθος, καθ’ ἃ τὸν Μιλύαν ὡς συνειδότ’ ἐξῄτησεν· οὗτος δὲ ψευσάμενος περὶ πάντων ἔφησεν. “περὶ μὲν τοίνυν” ἔφην ἐγώ “τούτου παραδώσω σοι τὸν ἔχοντα τἀντίγραφα ὧν σύ με προὐκαλέσω.”", "st": "29.51"}, {"sp": "N", "t": "“προομόσαντος δέ μου τὸν ἄνθρωπον ὡς ὡμολόγησας ἐλεύθερον εἶναι καὶ κατὰ Δήμωνος ἐμαρτύρησας, ἂν ἀπομόσῃς τἀναντία τούτων κατὰ τῆς θυγατρός, ἀφίημί σοι πάνθ’ ὑπὲρ ὧν ἂν ἐξαιτήσας φανῇς τὸ πρῶτον βασανιζομένου τοῦ παιδός, καὶ τοσούτῳ σοι γενέσθω τὸ τίμημ’ ἔλαττον ὧν ὦφλες, καθ’ ἃ τὸν Μιλύαν ἐξῄτησας, ἵνα μηδὲν ζημιωθῇς παρὰ τοὺς μάρτυρας.”", "st": "29.52"}, {"sp": "N", "t": "ταῦτ’ ἐμοῦ προκαλεσαμένου πολλῶν παρόντων, οὐκ ἂν ἔφη ποιῆσαι. καίτοι ὅστις αὐτὸς αὑτῷ ταῦτ’ ἔφυγεν δικάσαι, πῶς ὑμᾶς χρὴ τοὺς ὀμωμοκότας τούτῳ πειθομένους καταγνῶναι τῶν μαρτύρων, ἀλλ’ οὐ τοῦτον ἀναισχυντότατον πάντων ἀνθρώπων εἶναι νομίζειν; ἀλλὰ μὴν ὡς ἀληθῆ λέγω, κάλει τούτων τοὺς μάρτυρας.", "st": "29.53"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "29.53"}, {"sp": "N", "t": "οὐ τοίνυν ἐγὼ μὲν ταῦθ’ ἕτοιμος ἦν, οἱ δὲ μάρτυρες οὐ τὴν αὐτὴν γνώμην ἐμοὶ εἶχον, ἀλλ’ ἐκεῖνοι παραστησάμενοι τοὺς παῖδας, ὑπὲρ ὧν ἐμαρτύρησαν, πίστιν ἐπιθεῖναι ἠθέλησαν κατ’ ἐκείνων. ὁ δ’ οὔτ’ ἐκείνοις οὔτ’ ἐμοὶ δοῦναι τὸν ὅρκον ἠξίωσεν, ἀλλ’ ἐπὶ λόγοις μεμηχανημένοις καὶ μάρτυσιν οὐ τἀληθῆ μαρτυρεῖν εἰθισμένοις τὸ πρᾶγμα καταστήσας, ἐλπίζει ῥᾳδίως ὑμᾶς ἐξαπατήσειν. λάβ’ οὖν αὐτοῖς καὶ ταύτην τὴν μαρτυρίαν.", "st": "29.54"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "29.54"}, {"sp": "N", "t": "πῶς οὖν ἄν τις σαφέστερον ἐξελέγξειεν συκοφαντουμένους ἡμᾶς καὶ καταμεμαρτυρημένα τἀληθῆ καὶ τὴν δίκην δικαίως ὠφλημένην, ἢ τοῦτον τὸν τρόπον ἐπιδεικνύς; οἰκέτην τὸν τὴν μαρτυρίαν γράφοντ’ οὐκ ἐθελήσαντα τοῦτον βασανίζειν περὶ αὐτῶν τῶν μεμαρτυρημένων· αἴσιον τὸν ἀδελφὸν αὐτοῦ ταῦτα μεμαρτυρηκότα, ἅ φησιν εἶναι ψευδῆ·", "st": "29.55"}, {"sp": "N", "t": "τοῦτον αὐτὸν ταὐτὰ τοῖς μάρτυσιν οὓς διώκει μεμαρτυρηκότα μοι κατὰ Δήμωνος, ὄντος αὐτῷ θείου καὶ συνεπιτρόπου· τὰς θεραπαίνας οὐκ ἐθελήσανθ’ ὑπὲρ τοῦ τὸν ἄνθρωπον ἐλεύθερον εἶναι βασανίζειν· τὴν μητέρα τὴν ἐμαυτοῦ πίστιν περὶ τούτων ἐπιθεῖναι καθ’ ἡμῶν ἐθέλουσαν· τῶν ἄλλων οἰκετῶν οὐκ ἐθέλοντα τοῦτον παραλαμβάνειν οὐδένα, τῶν πάντ’ εἰδότων μᾶλλον ἢ Μιλύας· τῶν μαρτύρων οἳ κατεμαρτύρουν χρήματ’ ἔχειν αὐτόν, οὐδενὶ τῶν ψευδομαρτυρίων ἐπεσκημμένον·", "st": "29.56"}, {"sp": "N", "t": "τὴν διαθήκην οὐκ ἀποδόντα, οὐδὲ τὸν οἶκον μισθώσαντα τῶν νόμων κελευόντων· πίστιν ἐπιθεῖναι προομνύντος ἐμοῦ καὶ τῶν μαρτύρων, ὥστ’ ἀφεῖσθαι τοῦτον τῶν χρημάτων καθ’ ἃ τὸν Μιλύαν ἐξῄτησεν, οὐκ οἰηθέντα δεῖν; μὰ τοὺς θεούς, ἐγὼ μὲν οὐκ ἂν ἔχοιμ’ ἐπιδεῖξαι ταῦτ’ ἀκριβέστερον ἢ τοῦτον τὸν τρόπον. οὕτω τοίνυν φανερῶς τῶν μαρτύρων καταψευδόμενος καὶ ἐκ τῶν πραγμάτων οὐδὲν ζημιούμενος καὶ τὴν δίκην δικαίως ὠφληκώς, ὅμως ἀναισχυντεῖ.", "st": "29.57"}, {"sp": "N", "t": "καὶ εἰ μὲν μὴ καὶ παρὰ τοῖς αὑτοῦ φίλοις καὶ παρὰ τῷ διαιτητῇ προεγνωσμένος ἀδικεῖν τούτους ἐποιεῖτο τοὺς λόγους, ἧττον ἂν ἦν ἄξιον θαυμάζειν· νῦν δ’ ἐπιτρέψαι με πείσας Ἀρχένεῳ καὶ Δρακοντίδῃ καὶ Φάνῳ τουτῳί, τῷ νῦν ὑπ’ αὐτοῦ φεύγοντι τῶν ψευδομαρτυρίων, τούτους μὲν ἀφῆκεν ἀκούσας αὐτῶν ὅτι, εἰ μεθ’ ὅρκου ταῦτα διαιτήσουσιν, καταγνώσονται τὴν ἐπιτροπήν, ἐπὶ τὸν κληρωτὸν δὲ διαιτητὴν ἐλθὼν καὶ οὐδὲν ἔχων ἀπολύσασθαι τῶν ἐγκεκλημένων ὦφλεν τὴν δίαιταν.", "st": "29.58"}, {"sp": "N", "t": "οἱ δικασταὶ δ’ ἀκούσαντες, εἰς οὓς ἐφῆκεν, ταὐτὰ καὶ τοῖς τούτου φίλοις καὶ τῷ διαιτητῇ περὶ αὐτῶν ἔγνωσαν καὶ δέκα ταλάντων ἐτίμησαν, οὐ μὰ Δί’ οὐχ ὅτι τὸν Μιλύαν ὡμολόγησεν εἶναι ἐλεύθερον (τοῦτο μὲν γὰρ οὐδὲν ἦν), ἀλλ’ ὅτι πεντεκαίδεκα ταλάντων οὐσίας μοι καταλειφθείσης τὸν μὲν οἶκον οὐκ ἐμίσθωσεν, δέκα δ’ ἔτη μετὰ τῶν συνεπιτρόπων διαχειρίσας πρὸς μὲν τὴν συμμορίαν ὑπὲρ παιδὸς ὄντος ἐμοῦ πέντε μνᾶς συνετάξατ’ εἰσφέρειν, ὅσονπερ Τιμόθεος ὁ Κόνωνος καὶ οἱ τὰ μέγιστα κεκτημένοι τιμήματ’ εἰσέφερον,", "st": "29.59"}, {"sp": "N", "t": "χρόνον δὲ τοσοῦτον τὰ χρήματα ταῦτ’ ἐπιτροπεύσας, ὑπὲρ ὧν τηλικαύτην αὐτὸς εἰσφορὰν ἠξίου εἰσφέρειν, ἐμοὶ μὲν τὸ καθ’ αὑτὸν οὐδ’ εἴκοσι μνῶν ἄξια παρέδωκεν, μετὰ δ’ ἐκείνων ὅλα τὰ κεφάλαια καὶ τὰς ἐπικαρπίας ἀπεστέρηκεν. θέντες οὖν οἱ δικασταὶ τοῖς πᾶσι χρήμασιν οὐκ ἐφ’ ὅσῳ μισθοῦσιν τοὺς οἴκους τόκον, ἀλλ’ ὃς ἦν ἐλάχιστος, ηὗρον τὸ σύμπαν πλέον ἢ τριάκοντα τάλαντ’ αὐτοὺς ἀποστεροῦντας· διὸ τούτῳ τῶν δέκα ταλάντων ἐτίμησαν.", "st": "29.60"}, {"sp": "HDR", "t": "Πρὸς Ὀνήτορα ἐξούλης Αʹ", "st": "30"}, {"sp": "N", "t": "περὶ πολλοῦ ποιούμενος, ὦ ἄνδρες δικασταί, μήτε πρὸς Ἄφοβόν μοι συμβῆναι τὴν γενομένην διαφορὰν μήτε τὴν νῦν οὖσαν πρὸς Ὀνήτορα τουτονί, κηδεστὴν ὄντ’ αὐτοῦ, πολλὰ καὶ δίκαια προκαλεσάμενος ἀμφοτέρους, οὐδενὸς ἐδυνήθην τυχεῖν τῶν μετρίων, ἀλλ’ ηὕρηκα πολὺ τοῦτον ἐκείνου δυσκολώτερον καὶ μᾶλλον ἄξιον ὄντα δοῦναι δίκην.", "st": "30.1"}, {"sp": "N", "t": "τὸν μὲν γὰρ οἰόμενος δεῖν ἐν τοῖς φίλοις διαδικάσασθαι τὰ πρὸς ἐμὲ καὶ μὴ λαβεῖν ὑμῶν πεῖραν οὐχ οἷός τ’ ἐγενόμην πεῖσαι· τοῦτον δ’ αὐτὸν αὑτῷ κελεύων γενέσθαι δικαστήν, ἵνα μὴ παρ’ ὑμῖν κινδυνεύσῃ, τοσοῦτον κατεφρονήθην, ὥστ’ οὐχὶ μόνον λόγου τυχεῖν οὐκ ἠξιώθην, ἀλλὰ καὶ ἐκ τῆς γῆς, ἣν Ἄφοβος ἐκέκτηθ’ ὅτ’ ὠφλίσκανέ μοι τὴν δίκην, ὑβριστικῶς ὑπ’ αὐτοῦ πάνυ ἐξεβλήθην.", "st": "30.2"}, {"sp": "N", "t": "ἐπειδὴ οὖν συναποστερεῖ τέ με τῶν ὄντων τῷ ἑαυτοῦ κηδεστῇ, πιστεύων τ’ εἰς ὑμᾶς εἰσελήλυθεν ταῖς αὑτοῦ παρασκευαῖς, ὑπόλοιπόν ἐστιν ἐν ὑμῖν πειρᾶσθαι παρ’ αὐτοῦ τῶν δικαίων τυγχάνειν. οἶδα μὲν οὖν, ὦ ἄνδρες δικασταί, ὅτι μοι πρὸς παρασκευὰς λόγων καὶ μάρτυρας οὐ τἀληθῆ μαρτυρήσοντας ὁ ἀγών ἐστιν· ὅμως μέντοι τοσοῦτον οἶμαι διοίσειν τῷ δικαιότερα τούτου λέγειν,", "st": "30.3"}, {"sp": "N", "t": "ὥστ’ εἰ καί τις ὑμῶν πρότερον τοῦτον ἡγεῖτ’ εἶναι μὴ πονηρόν, ἔκ γε τῶν πρὸς ἐμὲ πεπραγμένων γνώσεσθαι, ὅτι καὶ τὸν ἄλλον χρόνον ἐλάνθανεν αὐτὸν κάκιστος ὢν καὶ ἀδικώτατος ἁπάντων. ἀποδείξω γὰρ αὐτὸν οὐ μόνον τὴν προῖκ’ οὐ δεδωκότα, ἧς φησι νῦν ἀποτετιμῆσθαι τὸ χωρίον, ἀλλὰ καὶ ἐξ ἀρχῆς τοῖς ἐμοῖς ἐπιβουλεύσαντα, καὶ πρὸς τούτοις τὴν μὲν γυναῖκ’ οὐκ ἀπολελοιπυῖαν, ὑπὲρ ἧς ἐξήγαγέ μ’ ἐκ ταύτης τῆς γῆς,", "st": "30.4"}, {"sp": "N", "t": "προϊστάμενον δ’ ἐπ’ ἀποστερήσει τῶν ἐμῶν Ἀφόβου καὶ τούτους ὑπομένοντα τοὺς ἀγῶνας, οὕτω μεγάλοις τεκμηρίοις καὶ φανεροῖς ἐλέγχοις ὥσθ’ ὑμᾶς ἅπαντας εἴσεσθαι σαφῶς ὅτι δικαίως καὶ προσηκόντως οὗτος φεύγει ταύτην ὑπ’ ἐμοῦ τὴν δίκην. ὅθεν δὲ ῥᾷστα μαθήσεσθε περὶ αὐτῶν, ἐντεῦθεν ὑμᾶς καὶ ἐγὼ πρῶτον πειράσομαι διδάσκειν.", "st": "30.5"}, {"sp": "N", "t": "ἐγὼ γάρ, ὦ ἄνδρες δικασταί, πολλούς τ’ ἄλλους Ἀθηναίων καὶ τοῦτον οὐκ ἐλάνθανον κακῶς ἐπιτροπευόμενος, ἀλλ’ ἦν καταφανὴς εὐθὺς ἀδικούμενος· τοσαῦται πραγματεῖαι καὶ λόγοι καὶ παρὰ τῷ ἄρχοντι καὶ παρὰ τοῖς ἄλλοις ἐγίγνονθ’ ὑπὲρ τῶν ἐμῶν. τό τε γὰρ πλῆθος τῶν καταλειφθέντων ἦν φανερόν, ὅτι τ’ ἀμίσθωτον τὸν οἶκον ἐποίουν οἱ διαχειρίζοντες, ἵν’ αὐτοὶ τὰ χρήματα καρποῖντο, οὐκ ἄδηλον ἦν. ὥστ’ ἐκ τῶν γιγνομένων οὐκ ἔσθ’ ὅστις οὐχ ἡγεῖτο τῶν εἰδότων δίκην με λήψεσθαι παρ’ αὐτῶν, ἐπειδὴ τάχιστ’ ἀνὴρ εἶναι δοκιμασθείην.", "st": "30.6"}, {"sp": "N", "t": "ἐν οἷς καὶ Τιμοκράτης καὶ Ὀνήτωρ ταύτην ἔχοντες διετέλεσαν τὴν διάνοιαν. τεκμήριον δὲ πάντων μέγιστον· οὗτος γὰρ ἐβουλήθη μὲν Ἀφόβῳ δοῦναι τὴν ἀδελφήν, ὁρῶν τῆς θ’ αὑτοῦ πατρῴας οὐσίας καὶ τῆς ἐμῆς οὐκ ὀλίγης αὐτὸν κύριον γεγενημένον, προέσθαι δὲ τὴν προῖκ’ οὐκ ἐπίστευσεν, ὥσπερ εἰ τὰ τῶν ἐπιτροπευόντων χρήματ’ ἀποτίμημα τοῖς ἐπιτροπευομένοις καθεστάναι νομίζων. ἀλλὰ τὴν μὲν ἀδελφὴν ἔδωκεν, τὴν δὲ προῖκ’ αὐτῷ Τιμοκράτης ἐπὶ πέντ’ ὀβολοῖς ὀφειλήσειν ὡμολόγησεν, ᾧ πρότερον ἡ γυνὴ συνοικοῦσ’ ἐτύγχανεν.", "st": "30.7"}, {"sp": "N", "t": "ὀφλόντος δέ μοι τὴν δίκην Ἀφόβου τῆς ἐπιτροπῆς καὶ οὐδὲν δίκαιον ποιεῖν ἐθέλοντος, διαλύειν μὲν ἡμᾶς Ὀνήτωρ οὐδ’ ἐπεχείρησεν, οὐκ ἀποδεδωκὼς δὲ τὴν προῖκα, ἀλλ’ αὐτὸς κύριος ὤν, ὡς ἀπολελοιπυίας τῆς ἀδελφῆς καὶ δοὺς κομίσασθαι δ’ οὐ δυνάμενος, ἀποτιμήσασθαι φάσκων τὴν γῆν ἐξάγειν μ’ ἐξ αὐτῆς ἐτόλμησεν· τοσοῦτον καὶ ἐμοῦ καὶ ὑμῶν καὶ τῶν κειμένων νόμων κατεφρόνησεν.", "st": "30.8"}, {"sp": "N", "t": "καὶ τὰ μὲν γενόμενα, καὶ δι’ ἃ φεύγει τὴν δίκην καὶ περὶ ὧν οἴσετε τὴν ψῆφον, ταῦτ’ ἐστίν, ὦ ἄνδρες δικασταί· παρέξομαι δὲ μάρτυρας πρῶτον μὲν αὐτὸν Τιμοκράτην, ὡς ὡμολόγησεν ὀφειλήσειν τὴν προῖκα καὶ τὸν τόκον ἀπεδίδου τῆς προικὸς Ἀφόβῳ κατὰ τὰς ὁμολογίας, ἔπειθ’ ὡς αὐτὸς Ἄφοβος ὡμολόγει κομίζεσθαι τὸν τόκον παρὰ Τιμοκράτους. καί μοι λαβὲ τὰς μαρτυρίας.", "st": "30.9"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "30.9"}, {"sp": "N", "t": "ἐξ ἀρχῆς μὲν τοίνυν ὁμολογεῖται μὴ δοθῆναι τὴν προῖκα μηδὲ γενέσθαι κύριον αὐτῆς Ἄφοβον. δῆλον δὲ καὶ ἐκ τῶν εἰκότων ὅτι τούτων ἕνεχ’ ὧν εἴρηκα ὀφείλειν εἵλοντο μᾶλλον ἢ καταμεῖξαι τὴν προῖκ’ εἰς τὴν οὐσίαν τὴν Ἀφόβου τὴν οὕτω κινδυνευθήσεσθαι μέλλουσαν. οὔτε γὰρ δι’ ἀπορίαν οἷόν τ’ εἰπεῖν ὡς οὐκ εὐθὺς ἀπέδοσαν (Τιμοκράτει τε γάρ ἐστιν οὐσία πλέον ἢ δέκα ταλάντων, Ὀνήτορί τε πλέον ἢ τριάκοντα, ὥστ’ οὐκ ἂν διὰ τοῦτό γ’ εἶεν οὐκ εὐθὺς δεδωκότες) οὔτε κτήματα μὲν ἦν αὐτοῖς,", "st": "30.10"}, {"sp": "N", "t": "ἀργύριον δ’ οὐκ ἔτυχεν παρόν, ἡ γυνὴ δ’ ἐχήρευεν, διὸ πρᾶξαι ταῦτ’ ἠπείχθησαν οὐχ ἅμα τὴν προῖκα διδόντες· ἀργύριόν τε γὰρ οὗτοι δανείζουσιν ἄλλοις οὐκ ὀλίγον, συνοικοῦσάν τε ταύτην, ἀλλ’ οὐ χηρεύουσαν παρὰ Τιμοκράτους ἐξέδοσαν, ὥστ’ οὐδ’ ἂν ταύτην τὴν σκῆψιν εἰκότως αὐτῶν τις ἀποδέξαιτο.", "st": "30.11"}, {"sp": "N", "t": "καὶ μὲν δή, ὦ ἄνδρες δικασταί, κἀκεῖν’ ἂν πάντες ὁμολογήσαιτε, ὅτι τοιοῦτον πρᾶγμα συναλλάττων ὁστισοῦν ἕλοιτ’ ἂν ἑτέρῳ μᾶλλον ὀφείλειν ἢ κηδεστῇ τὴν προῖκα μὴ ἀποδοῦναι. μὴ διαλυσάμενος μὲν γὰρ γίγνεται χρήστης ἄδηλος εἴτ’ ἀποδώσει δικαίως εἴτε μή, μετὰ δὲ τῆς γυναικὸς τἀκείνης ἀποδοὺς οἰκεῖος καὶ κηδεστής·", "st": "30.12"}, {"sp": "N", "t": "ἐν οὐδεμιᾷ γάρ ἐστιν ὑποψίᾳ τὰ δίκαια πάντα ποιήσας. ὥσθ’ οὕτως τοῦ πράγματος ἔχοντος, καὶ τούτων οὐδὲ καθ’ ἓν ὧν εἶπον ὀφείλειν ἀναγκασθέντων, οὐδὲ βουληθέντων ἄν, οὐκ ἔστ’ εἰπεῖν ἄλλην πρόφασιν δι’ ἣν οὐκ ἀπέδοσαν, ἀλλ’ ἀνάγκη ταύτην εἶναι τὴν αἰτίαν, δι’ ἣν δοῦναι τὴν προῖκ’ οὐκ ἐπίστευσαν.", "st": "30.13"}, {"sp": "N", "t": "ἐγὼ τοίνυν ὁμολογουμένως οὕτω ταῦτ’ ἐξελέγχων, ὡς οὐδ’ ὕστερον ἀπέδοσαν, οἶμαι ῥᾳδίως ἐπιδείξειν ἐξ αὐτῶν τῶν πεπραγμένων, ὥσθ’ ὑμῖν γενέσθαι φανερόν, ὅτι κἂν εἰ μὴ ἐπὶ τούτοις, ἀλλ’ ἐπὶ τῷ διὰ ταχέων ἀποδοῦναι τἀργύριον εἶχον, οὐκ ἄν ποτ’ ἀπέδοσαν οὐδ’ ἂν προεῖντο· τοιαύτας ἀνάγκας εἶχεν αὐτοῖς τὸ πρᾶγμα.", "st": "30.14"}, {"sp": "N", "t": "δύο μὲν γάρ ἐστιν ἔτη τὰ μεταξὺ τοῦ συνοικῆσαί τε τὴν γυναῖκα καὶ φῆσαι τούτους πεποιῆσθαι τὴν ἀπόλειψιν· ἐγήματο μὲν γὰρ ἐπὶ Πολυζήλου ἄρχοντος σκιροφοριῶνος μηνός, ἡ δ’ ἀπόλειψις ἐγράφη ποσιδεῶνος μηνὸς ἐπὶ Τιμοκράτους· ἐγὼ δ’ εὐθέως μετὰ τοὺς γάμους δοκιμασθεὶς ἐνεκάλουν καὶ λόγον ἀπῄτουν, καὶ πάντων ἀποστερούμενος τὰς δίκας ἐλάγχανον ἐπὶ τοῦ αὐτοῦ ἄρχοντος.", "st": "30.15"}, {"sp": "N", "t": "ὁ δὴ χρόνος οὗτος ὀφειλῆσαι μὲν ἐνδέχεται κατὰ τὰς ὁμολογίας, ἀποδοῦναι δ’ οὐκ ἔχει πίστιν. ὃς γὰρ διὰ ταῦτ’ ἐξ ἀρχῆς ὀφείλειν εἵλετο καὶ τόκον φέρειν, ἵνα μὴ κινδυνεύοι ἡ προὶξ μετὰ τῆς ἄλλης οὐσίας, πῶς οὗτος ἂν ἀπέδωκεν ἤδη τὴν δίκην φεύγοντος; ὃς εἰ καὶ τότ’ ἐπίστευσεν, τηνικαῦτ’ ἂν ἀπολαβεῖν ἐζήτησεν. οὐκ ἔνεστι δήπουθεν, ὦ ἄνδρες δικασταί.", "st": "30.16"}, {"sp": "N", "t": "ἀλλὰ μὴν ὡς ἐγήματο μὲν ἡ γυνὴ καθ’ ὃν ἐγὼ λέγω χρόνον, ἀντίδικοι δ’ ἡμεῖς ἤδη πρὸς ἀλλήλους ἐν τῷ μεταξὺ χρόνῳ κατέστημεν, ὕστερον δ’ ἢ ἐγὼ τὴν δίκην ἔλαχον τὴν ἀπόλειψιν οὗτοι πρὸς τὸν ἄρχοντ’ ἀπεγράψαντο, λαβέ μοι καθ’ ἕκαστον ταύτας τὰς μαρτυρίας.", "st": "30.17"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "30.17"}, {"sp": "N", "t": "μετὰ τοίνυν τοῦτον τὸν ἄρχοντα Κηφισόδωρος, Χίων. ἐπὶ τούτων ἐνεκάλουν δοκιμασθείς, ἔλαχον δὲ τὴν δίκην ἐπὶ Τιμοκράτους. λαβὲ ταύτην τὴν μαρτυρίαν.", "st": "30.17"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "30.17"}, {"sp": "N", "t": "ἀνάγνωθι δὲ καὶ ταύτην τὴν μαρτυρίαν.", "st": "30.18"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "30.18"}, {"sp": "N", "t": "δῆλον μὲν τοίνυν καὶ ἐκ τῶν μεμαρτυρημένων, ὅτι τὴν προῖκ’ οὐ δόντες, ἀλλ’ ἐπὶ τῷ διασῴζειν Ἀφόβῳ τὴν οὐσίαν ταῦτα τολμῶσι πράττειν. οἳ γὰρ ἐν τοσούτῳ χρόνῳ καὶ ὀφειλῆσαι καὶ ἀποδοῦναι καὶ τὴν γυναῖκ’ ἀπολιπεῖν καὶ οὐ κομίσασθαι καὶ τὸ χωρίον ἀποτιμήσασθαί φασιν, πῶς οὐ φανερὸν ὅτι προστάντες τοῦ πράγματος τὰ γνωσθένθ’ ὑφ’ ὑμῶν ἀποστερῆσαί με ζητοῦσιν;", "st": "30.18"}, {"sp": "N", "t": "ὡς δὲ καὶ ἐξ ὧν αὐτὸς οὗτος καὶ Τιμοκράτης καὶ Ἄφοβος ἀπεκρίναντο, οὐχ οἷόν τ’ ἀποδεδόσθαι τὴν προῖκα, ταῦτ’ ἤδη πειράσομαι διδάσκειν ὑμᾶς. ἐγὼ γάρ, ὦ ἄνδρες δικασταί, τούτων ἕκαστον ἠρόμην πολλῶν ἐναντίον μαρτύρων, Ὀνήτορα μὲν καὶ Τιμοκράτην, εἴ τινες εἶεν μάρτυρες ὧν ἐναντίον τὴν προῖκ’ ἀπέδοσαν, αὐτὸν δ’ Ἄφοβον, εἴ τινες παρῆσαν ὅτ’ ἀπελάμβανεν.", "st": "30.19"}, {"sp": "N", "t": "καί μοι πάντες ἀπεκρίναντο καθ’ ἕκαστον, ὅτι οὐδεὶς μάρτυς παρείη, κομίζοιτο δὲ λαμβάνων καθ’ ὁποσονοῦν δέοιτ’ Ἄφοβος παρ’ αὐτῶν. καίτοι τῷ τοῦθ’ ὑμῶν πιστόν, ὡς ταλάντου τῆς προικὸς οὔσης ἄνευ μαρτύρων Ὀνήτωρ καὶ Τιμοκράτης Ἀφόβῳ τοσοῦτον ἀργύριον ἐνεχείρισαν; ᾧ μὴ ὅτι τοῦτον τὸν τρόπον, ἀλλ’ οὐδὲ μετὰ πολλῶν μαρτύρων ἀποδιδοὺς εἰκῇ τις ἂν ἐπίστευσεν, ἵν’ εἴ τις γίγνοιτο διαφορά, κομίσασθαι ῥᾳδίως παρ’ ὑμῖν δύνηται.", "st": "30.20"}, {"sp": "N", "t": "μὴ γὰρ ὅτι πρὸς τοῦτον τοιοῦτον ὄντα, ἀλλ’ οὐδὲ πρὸς ἄλλον οὐδ’ ἂν εἷς οὐδένα τοιοῦτον συνάλλαγμα ποιούμενος ἀμαρτύρως ἂν ἔπραξεν· ἀλλὰ τῶν τοιούτων ἕνεκα καὶ γάμους ποιοῦμεν καὶ τοὺς ἀναγκαιοτάτους παρακαλοῦμεν, ὅτι οὐ πάρεργον, ἀλλ’ ἀδελφῶν καὶ θυγατέρων βίους ἐγχειρίζομεν, ὑπὲρ ὧν τὰς ἀσφαλείας μάλιστα σκοποῦμεν.", "st": "30.21"}, {"sp": "N", "t": "εἰκὸς τοίνυν καὶ τοῦτον, ὧνπερ ἐναντίον ὀφείλειν ὡμολόγησεν καὶ τὸν τόκον οἴσειν, τῶν αὐτῶν τούτων παρόντων διαλύσασθαι πρὸς Ἄφοβον, εἴπερ ὡς ἀληθῶς ἀπεδίδου τὴν προῖκ’ αὐτῷ. τοῦτον μὲν γὰρ τὸν τρόπον πράξας, ὅλου τοῦ πράγματος ἀπηλλάττετο, μόνος μόνῳ δ’ ἀποδιδούς, τοὺς ἐπὶ ταῖς ὁμολογίαις παραγενομένους ὡς κατ’ ὀφείλοντος ἂν αὑτοῦ μάρτυρας ὑπελείπετο.", "st": "30.22"}, {"sp": "N", "t": "νῦν τοίνυν τοὺς μὲν ὄντας οἰκείους καὶ βελτίους αὑτῶν οὐκ ἐδύναντο πεῖσαι τὴν προῖκ’ ἀποδεδωκέναι σφᾶς μαρτυρεῖν, ἑτέρους δ’ εἰ παρέχοιντο μάρτυρας μηδὲν γένει προσήκοντας, οὐκ ἂν ἡγοῦνθ’ ὑμᾶς αὐτοῖς πιστεύειν. ἔτι δ’ ἁθρόαν μὲν φάσκοντες δεδωκέναι τὴν προῖκα, ᾔδεσαν ὅτι τοὺς ἀπενεγκόντας οἰκέτας ἐξαιτήσομεν, οὓς μὴ γεγενημένης τῆς δόσεως παραδοῦναι μὴ ’θέλοντες ἠλέγχοντ’ ἄν· εἰ δ’ αὐτοὶ μόνοι μόνῳ τοῦτον τὸν τρόπον ἀποδεδωκέναι λέγοιεν, ἐνόμιζον οὐκ ἐλεγχθήσεσθαι.", "st": "30.23"}, {"sp": "N", "t": "διὰ τοῦτο τοῦτον εἵλοντ’ ἐξ ἀνάγκης ψεύδεσθαι τὸν τρόπον. τοιαύταις τέχναις καὶ πανουργίαις, ὡς ἁπλοῖ τινὲς εἶναι δόξοντες, ἡγοῦνται ῥᾳδίως ὑμᾶς ἐξαπατήσειν, ἁπλῶς οὐδ’ ἂν μικρὸν ὑπὲρ τῶν διαφερόντων, ἀλλ’ ὡς οἷόν τ’ ἀκριβέστατα πράξαντες. λαβὲ τὰς μαρτυρίας αὐτοῖς ὧν ἐναντίον ἀπεκρίναντο, καὶ ἀνάγνωθι.", "st": "30.24"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "30.24"}, {"sp": "N", "t": "φέρε δή, ὦ ἄνδρες δικασταί, καὶ τὴν γυναῖχ’ ὑμῖν ἀποδείξω λόγῳ μὲν ἀπολελοιπυῖαν, ἔργῳ δὲ συνοικοῦσαν Ἀφόβῳ· νομίζω γάρ, ἂν τοῦτ’ ἀκριβῶς μάθητε, μᾶλλον ὑμᾶς τούτοις μὲν ἀπιστήσειν, ἐμοὶ δ’ ἀδικουμένῳ τὰ δίκαια βοηθήσειν. μάρτυρας δὲ τῶν μὲν ὑμῖν παρέξομαι, τῶν δ’ ἐπιδείξω μεγάλα τεκμήρια καὶ πίστεις ἱκανάς.", "st": "30.25"}, {"sp": "N", "t": "ἐγὼ γάρ, ὦ ἄνδρες δικασταί, μετὰ τὸ γεγράφθαι παρὰ τῷ ἄρχοντι ταύτην τὴν γυναῖκ’ ἀπολελοιπυῖαν καὶ τὸ φάσκειν Ὀνήτορ’ ἀντὶ τῆς προικὸς ἀποτετιμῆσθαι τὸ χωρίον, ὁρῶν Ἄφοβον ὁμοίως ἔχοντα καὶ γεωργοῦντα τὴν γῆν καὶ τῇ γυναικὶ συνοικοῦντα, σαφῶς ᾔδειν ὅτι λόγος ταῦτα καὶ παραγωγὴ τοῦ πράγματός ἐστιν.", "st": "30.26"}, {"sp": "N", "t": "βουλόμενος δ’ ἐμφανῆ ποιῆσαι ταῦτα πᾶσιν ὑμῖν, ἐξελέγχειν αὐτὸν ἠξίουν ἐναντίον μαρτύρων, εἰ μὴ φάσκοι ταῦθ’ οὕτως ἔχειν, καὶ παρεδίδουν οἰκέτην εἰς βάσανον, ὃς συνῄδει πάντ’ ἀκριβῶς· ὃν ἔλαβον κατὰ τὴν ὑπερημερίαν ἐκ τῶν Ἀφόβου. οὗτος δ’ ἐμοῦ ταῦτ’ ἀξιώσαντος, περὶ μὲν τοῦ συνοικεῖν Ἀφόβῳ τὴν ἀδελφὴν ἔφυγε τὴν βάσανον· ὡς δ’ οὐκ ἐκεῖνος ἐγεώργει τὴν γῆν, οὐκ ἐδύνατ’ ἀρνηθῆναι διὰ τὴν περιφάνειαν, ἀλλὰ προσωμολόγησεν.", "st": "30.27"}, {"sp": "N", "t": "οὐ μόνον δ’ ἐκ τούτων ἦν ῥᾴδιον γνῶναι, ὅτι καὶ συνῴκει τῇ γυναικὶ καὶ τὸ χωρίον ἐκέκτητ’ ἔτι πρὶν γενέσθαι τὴν δίκην, ἀλλὰ καὶ ἐξ ὧν ὀφλὼν διεπράξατο περὶ αὐτῶν. ὡς γὰρ οὐκ ἀποτετιμηκώς, ἀλλ’ ἐμῶν ἐσομένων κατὰ τὴν δίκην, ἃ μὲν οἷόν τ’ ἦν ἐξενεγκεῖν, ᾤχετο λαβών, τοὺς καρποὺς καὶ τὰ σκεύη τὰ γεωργικὰ πάντα πλὴν τῶν πιθακνῶν· ὃ δ’ οὐχ οἷόν τ’ ἦν ἀνελεῖν, ἐξ ἀνάγκης ὑπέλιπεν, ὥστ’ ἐγγενέσθαι τούτῳ νῦν αὐτῆς τῆς γῆς ἀμφισβητεῖν.", "st": "30.28"}, {"sp": "N", "t": "καίτοι δεινὸν τὸν μὲν λέγειν ὡς ἀπετιμήσατο τὸ χωρίον, τὸν δ’ ἀποτετιμηκότα φαίνεσθαι γεωργοῦντα, καὶ φάσκειν μὲν ἀπολελοιπέναι τὴν ἀδελφήν, ὑπὲρ αὐτῶν δὲ τούτων φανερὸν εἶναι φεύγοντα τοὺς ἐλέγχους, καὶ τὸν μὲν οὐ συνοικοῦντα, ὡς οὗτός φησιν, καὶ τοὺς καρποὺς καὶ τὰ ἐκ τῆς γεωργίας ἅπαντ’ ἐξενεγκεῖν, τὸν δ’ ὑπὲρ τῆς ἀπολελοιπυίας πράττοντα, ὑπὲρ ἧς ἀποτετιμῆσθαί φησι τὸ χωρίον, φαίνεσθαι μηδ’ ὑπὲρ ἑνὸς τούτων ἀγανακτοῦντα, ἀλλ’ ἡσυχίαν ἔχοντα.", "st": "30.29"}, {"sp": "N", "t": "ταῦτ’ οὐ πολλὴ περιφάνει’ ἐστίν; ταῦτ’ οὐχ ὁμολογουμένη προστασία; φήσειέ γ’ ἄν τις, εἰ διαλογίζοιτ’ ὀρθῶς ἕκαστ’ αὐτῶν. ὡς τοίνυν ὡμολόγει μὲν ἐκεῖνον γεωργεῖν πρὶν γενέσθαι τὴν δίκην ἐμοὶ πρὸς αὐτόν, ὑπὲρ δὲ τοῦ μὴ συνοικεῖν τὴν ἀδελφὴν οὐκ ἠθέλησεν ποιήσασθαι τὴν βάσανον, ἡ δὲ γεωργία ἐξεσκευάσθη μετὰ τὴν δίκην πλὴν τῶν ἐγγείων, λαβὲ ταύτας τὰς μαρτυρίας καὶ ἀνάγνωθι.", "st": "30.30"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "30.30"}, {"sp": "N", "t": "ἐμοὶ τοίνυν τοσούτων ὑπαρχόντων τεκμηρίων, οὐχ ἥκιστ’ αὐτὸς ἔδειξεν Ὀνήτωρ, ὅτι οὐκ ἀληθινὴν ἐποιήσατο τὴν ἀπόλειψιν. ᾧ γὰρ προσῆκεν χαλεπῶς φέρειν, εἰ τὴν προῖκα δούς, ὥς φησιν, ἀντ’ ἀργυρίου χωρίον ἀμφισβητούμενον ἀπελάμβανεν, οὗτος οὐχ ὡς διάφορος οὐδ’ ὡς ἀδικούμενος, ἀλλ’ ὡς οἰκειότατος πάντων τὴν πρὸς ἐμὲ δίκην αὐτῷ συνηγωνίζετο. κἀμὲ μὲν συναποστερῆσαι μετ’ ἐκείνου τῶν πατρῴων ἐπεχείρησεν, καθ’ ὅσον αὐτὸς οἷός τ’ ἦν, ὑφ’ οὗ κακὸν οὐδ’ ὁτιοῦν ἦν πεπονθώς· Ἀφόβῳ δ’, ὃν ἀλλότριον εἶναι προσῆκε νομίζειν, εἴ τι τούτων ἀληθὲς ἦν ὧν νῦν λέγουσιν, καὶ τἀμὰ πρὸς τοῖς ἐκείνου περιποιεῖν ἐζήτησεν.", "st": "30.31"}, {"sp": "N", "t": "καὶ οὐ μόνον ἐνταῦθα τοῦτ’ ἐποίησεν, ἀλλὰ καὶ κατεγνωσμένης ἤδη τῆς δίκης, ἀναβὰς ἐπὶ τὸ δικαστήριον ἐδεῖθ’ ἱκετεύων ὑπὲρ αὐτοῦ καὶ ἀντιβολῶν καὶ δάκρυσι κλάων ταλάντου τιμῆσαι, καὶ τούτου αὐτὸς ἐγίγνετ’ ἐγγυητής. καὶ ταῦθ’ ὁμολογούμενα μέν ἐστιν πολλαχόθεν (οἵ τε γὰρ ἐν τῷ δικαστηρίῳ τότε δικάζοντες καὶ τῶν ἔξωθεν παρόντων πολλοὶ συνίσασιν), ὅμως δὲ καὶ μάρτυρας ὑμῖν παρέξομαι. καί μοι λαβὲ ταύτην τὴν μαρτυρίαν.", "st": "30.32"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "30.32"}, {"sp": "N", "t": "ἔτι τοίνυν, ὦ ἄνδρες δικασταί, καὶ τεκμηρίῳ μεγάλῳ γνῶναι ῥᾴδιον, ὅτι τῇ ἀληθείᾳ συνῴκει καὶ οὐδέπω καὶ τήμερον ἀπολέλοιπεν. αὕτη γὰρ ἡ γυνή, πρὶν μὲν ὡς Ἄφοβον ἐλθεῖν, μίαν ἡμέραν οὐκ ἐχήρευσεν, ἀλλὰ παρὰ ζῶντος Τιμοκράτους ἐκείνῳ συνῴκησεν, νῦν δ’ ἐν τρισὶν ἔτεσιν ἄλλῳ συνοικοῦσ’ οὐδενὶ φαίνεται. καίτοι τῷ πιστόν, ὡς τότε μέν, ἵνα μὴ χηρεύσειεν, παρ’ ἀνδρὸς ὡς ἄνδρ’ ἐβάδιζεν, νῦν δ’, εἴπερ ὡς ἀληθῶς ἀπολέλοιπεν, τοσοῦτον ἂν χρόνον χηρεύουσ’ ἠνείχετ’ ἐξὸν ἄλλῳ συνοικεῖν, τοῦ τ’ ἀδελφοῦ κεκτημένου τοσαύτην οὐσίαν, αὐτή τε ταύτην ἔχουσα τὴν ἡλικίαν;", "st": "30.33"}, {"sp": "N", "t": "οὐκ ἔχει ταῦτ’ ἀλήθειαν, ὦ ἄνδρες δικασταί, πιθανήν, ἀλλὰ λόγοι ταῦτ’ εἰσί, συνοικεῖ δ’ ἡ γυνὴ φανερῶς καὶ οὐκ ἐπικρύπτεται τὸ πρᾶγμα. παρέξομαι δ’ ὑμῖν Πασιφῶντος μαρτυρίαν, ὃς ἀρρωστοῦσαν αὐτὴν θεραπεύων ἑώρα παρακαθήμενον Ἄφοβον ἐπὶ τούτου τοῦ ἄρχοντος, ἤδη τούτῳ ταυτησὶ τῆς δίκης εἰληγμένης. καί μοι λαβὲ τὴν Πασιφῶντος μαρτυρίαν.", "st": "30.34"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "30.34"}, {"sp": "N", "t": "ἐγὼ τοίνυν εἰδώς, ὦ ἄνδρες δικασταί, καὶ μετὰ τὴν δίκην τοῦτον εὐθὺς ἀποδεδεγμένον τὰ ἐκ τῆς οἰκίας τῆς Ἀφόβου χρήματα, καὶ κύριον τῶν τ’ ἐκείνου καὶ τῶν ἐμῶν ἁπάντων γεγενημένον, καὶ συνοικοῦσαν [αὐτῷ] τὴν γυναῖκα σαφῶς ἐπιστάμενος, τρεῖς θεραπαίνας ἐξῄτησ’ αὐτόν, αἳ συνοικοῦσάν τε τὴν γυναῖκ’ ᾔδεσαν καὶ τὰ χρήμαθ’ ὅτι παρὰ τούτοις ἦν, ἵνα μὴ λόγοι μόνον, ἀλλὰ καὶ βάσανοι περὶ αὐτῶν γίγνοιντο.", "st": "30.35"}, {"sp": "N", "t": "οὗτος δ’ ἐμοῦ προκαλεσαμένου ταῦτα, καὶ πάντων τῶν παρόντων δίκαια λέγειν μ’ ἀποφηναμένων, οὐκ ἠθέλησεν εἰς τοῦτο τἀκριβὲς καταφυγεῖν, ἀλλ’ ὥσπερ ἑτέρων τινῶν ὄντων περὶ τῶν τοιούτων σαφεστέρων ἐλέγχων ἢ βασάνων καὶ μαρτυριῶν, οὔτε μάρτυρας παρεχόμενος τὴν προῖχ’ ὡς ἀπέδωκεν, οὔτ’ εἰς βάσανον ἐκδιδοὺς τὰς συνειδυίας περὶ τοῦ μὴ συνοικεῖν τὴν ἀδελφήν, ὅτι ταῦτ’ ἠξίουν, ὑβριστικῶς πάνυ καὶ προπηλακιστικῶς οὐκ εἴα μ’ αὑτῷ διαλέγεσθαι. τούτου γένοιτ’ ἄν τις σχετλιώτερος ἄνθρωπος, ἢ μᾶλλον ἑκὼν τὰ δίκαι’ ἀγνοεῖν προσποιούμενος; λαβὲ δ’ αὐτὴν τὴν πρόκλησιν καὶ ἀνάγνωθι.", "st": "30.36"}, {"sp": "N", "t": "ΠΡΟΚΛΗΣΙΣ.", "st": "30.36"}, {"sp": "N", "t": "ὑμεῖς τοίνυν καὶ ἰδίᾳ καὶ δημοσίᾳ βάσανον ἀκριβεστάτην πασῶν ⟨πίστεων⟩ νομίζετε, καὶ ὅπου ἂν δοῦλοι καὶ ἐλεύθεροι παραγένωνται, δέῃ δ’ εὑρεθῆναι τὸ ζητούμενον, οὐ χρῆσθε ταῖς τῶν ἐλευθέρων μαρτυρίαις, ἀλλὰ τοὺς δούλους βασανίζοντες, οὕτω ζητεῖτε τὴν ἀλήθειαν εὑρεῖν. εἰκότως, ὦ ἄνδρες δικασταί· τῶν μὲν γὰρ μαρτυρησάντων ἤδη τινὲς οὐ τἀληθῆ μαρτυρῆσαι ἔδοξαν· τῶν δὲ βασανισθέντων οὐδένες πώποτ’ ἐξηλέγχθησαν, ὡς οὐκ ἀληθῆ τὰ ἐκ τῆς βασάνου εἶπον.", "st": "30.37"}, {"sp": "N", "t": "οὗτος δὲ τηλικαῦτα δίκαια φυγὼν καὶ σαφεῖς οὕτω καὶ μεγάλους ἐλέγχους παραλιπών, Ἄφοβον παρεχόμενος μάρτυρα καὶ Τιμοκράτην, τὸν μὲν ὡς ἀπέδωκε τὴν προῖκα, τὸν δ’ ὡς ἀπείληφεν, ἀξιώσει πιστεύεσθαι παρ’ ὑμῖν, ἀμάρτυρον τὴν πρὸς τούτους πρᾶξιν γεγενῆσθαι προσποιούμενος· τοσαύτην ὑμῶν εὐήθειαν κατέγνωκεν.", "st": "30.38"}, {"sp": "N", "t": "ὅτι μὲν τοίνυν οὔτ’ ἀληθῆ οὔτ’ ἀληθείᾳ ἐοικότα λέξουσιν, καὶ ἐκ τοῦ ἐξ ἀρχῆς αὐτοὺς ὁμολογεῖν τὴν προῖκα μὴ δοῦναι, καὶ ἐκ τοῦ πάλιν ἄνευ μαρτύρων ἀποδεδωκέναι φάσκειν, καὶ ἐκ τοῦ τὸν χρόνον μὴ ἐγχωρεῖν ἀμφισβητουμένης ἤδη τῆς οὐσίας ἀποδοῦναι τἀργύριον, καὶ ἐκ τῶν ἄλλων ἁπάντων ἱκανῶς ἀποδεδεῖχθαι νομίζω.", "st": "30.39"}, {"sp": "HDR", "t": "Πρὸς Ὀνήτορα ἐξούλης Βʹ", "st": "31"}, {"sp": "N", "t": "ὃ παρέλιπον ἐν τῷ προτέρῳ λόγῳ τεκμήριον, οὐδενὸς τῶν εἰρημένων ἔλαττον, τοῦ μὴ δεδωκέναι τὴν προῖκα τούτους Ἀφόβῳ, τοῦτο πρῶτον εἰπών, μετὰ τοῦτο καὶ περὶ ὧν οὗτος ἔψευσται πρὸς ὑμᾶς ἐξελέγχειν αὐτὸν πειράσομαι. οὗτος γάρ, ὦ ἄνδρες δικασταί, τὸ πρῶτον ὅτε τῶν Ἀφόβου διενοεῖτ’ ἀμφισβητεῖν, οὐχὶ τάλαντον ἔφη τὴν προῖκα, ὥσπερ νυνί, ἀλλ’ ὀγδοήκοντα μνᾶς δεδωκέναι, καὶ τίθησιν ὅρους ἐπὶ μὲν τὴν οἰκίαν δισχιλίων, ἐπὶ δὲ τὸ χωρίον ταλάντου, βουλόμενος μὴ μόνον τοῦτο, ἀλλὰ κἀκείνην διασῴζειν αὐτῷ.", "st": "31.1"}, {"sp": "N", "t": "γενομένης δέ μοι τῆς δίκης πρὸς αὐτόν, ἰδὼν ὡς διάκεισθ’ ὑμεῖς πρὸς τοὺς λίαν ἀναιδῶς ἀδικοῦντας, ἔννους γίγνεται, καὶ δεινὰ πάσχειν ἡγήσατο δόξειν ἐμὲ τοσούτων χρημάτων ἀπεστερημένον, εἰ μηδ’ ὁτιοῦν ἕξοιμι τῶν Ἀφόβου λαβεῖν τοῦ τἄμ’ ἔχοντος, ἀλλ’ ὑπὸ τούτου κωλυόμενος φανερὸς γενήσομαι.", "st": "31.2"}, {"sp": "N", "t": "καὶ τί ποιεῖ; τοὺς ὅρους ἀπὸ τῆς οἰκίας ἀφαιρεῖ, καὶ τάλαντον μόνον εἶναι τὴν προῖκά φησιν, ἐν ᾧ τὸ χωρίον ἀποτετιμῆσθαι. καίτοι δῆλον ὅτι τοὺς ἐπὶ τῆς οἰκίας ὅρους εἰ δικαίως ἔθηκεν καὶ ὄντως ἀληθεῖς, δικαίως καὶ τοὺς ἐπὶ τοῦ χωρίου τέθηκεν· εἰ δ’ εὐθὺς ἀδικεῖν βουλόμενος ψευδεῖς ἔθηκεν ἐκείνους, εἰκὸς καὶ τούτους οὐκ ἀληθεῖς ὑπάρχειν.", "st": "31.3"}, {"sp": "N", "t": "τοῦτο τοίνυν οὐκ ἐξ ὧν ἐγὼ δεδήλωκα λόγων δεῖ σκοπεῖν, ἀλλ’ ἐξ ὧν αὐτὸς οὗτος διεπράξατο· οὐδ’ ὑφ’ ἑνὸς γὰρ ἀναγκασθεὶς ἀνθρώπων αὐτὸς ἀνεῖλεν τοὺς ὅρους, ἔργῳ φανερὸν ποιήσας ὅτι ψεύδεται. καὶ ταῦθ’ ὡς ἀληθῆ λέγω, τὸ μὲν χωρίον καὶ νῦν οὗτός φησιν ἀποτετιμῆσθαι ταλάντου, τὴν δ’ οἰκίαν ὡς προσωρίσατο δισχιλίων καὶ πάλιν τοὺς ὅρους ἀνεῖλεν γενομένης τῆς δίκης, τοὺς εἰδότας ὑμῖν μάρτυρας παρέξομαι. καί μοι λαβὲ τὴν μαρτυρίαν.", "st": "31.4"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "31.4"}, {"sp": "N", "t": "δῆλον τοίνυν ὅτι δισχιλίων μὲν ὡρισμένος τὴν οἰκίαν, ταλάντου δὲ τὸ χωρίον, ὡς ὀγδοήκοντα μνᾶς δεδωκὼς ἔμελλεν ἀμφισβητήσειν. μεῖζον οὖν ἄν τι γένοιτο τεκμήριον ὑμῖν τοῦ μηδὲν ἀληθὲς νῦν λέγειν τοῦτον ἢ εἰ φανείη μὴ ταὐτὰ λέγων τοῖς ἐξ ἀρχῆς περὶ τῶν αὐτῶν; ἐμοὶ μὲν γὰρ οὐδὲν ἂν δοκεῖ τούτου μεῖζον εὑρεθῆναι.", "st": "31.5"}, {"sp": "N", "t": "σκέψασθε τοίνυν τὴν ἀναίδειαν, ὃς ἐν ὑμῖν ἐτόλμησεν εἰπεῖν, ὡς οὐκ ἀποστερεῖ μ’ ὅσῳ πλείονος ἄξιόν ἐστι ταλάντου, καὶ ταῦτ’ αὐτὸς τιμήσας οὐκ ἄξιον εἶναι πλείονος. τί γὰρ βουλόμενος δισχιλίων προσωρίσω τὴν οἰκίαν, ὅτε τὰς ὀγδοήκοντα μνᾶς ἐνεκάλεις, εἴ γε τὸ χωρίον ἄξιον ἦν πλείονος, ἀλλ’ οὐκ ἐπὶ τούτῳ καὶ τὰς δισχιλίας ἐτίθεις;", "st": "31.6"}, {"sp": "N", "t": "ἢ ὅταν μέν σοι δοκῇ πάντα τὰ Ἀφόβου διασῴζειν, τό τε χωρίον ἔσται ταλάντου μόνον ἄξιον, καὶ τὴν οἰκίαν ἐν δισχιλίαις προσέξεις, ἥ τε προὶξ ὀγδοήκοντα μναῖ γενήσονται, καὶ ἀξιώσεις ἔχειν ἀμφότερα· ὅταν δέ σοι μὴ συμφέρῃ, τἀναντία πάλιν ἡ μὲν οἰκία ταλάντου, διότι νῦν ἐγὼ ταύτην ἔχω, τοῦ δὲ χωρίου τὸ περιὸν οὐκ ἐλάττονος ἢ δυοῖν ἄξιον, ἵν’ ἐγὼ δοκῶ βλάπτειν τοῦτον, οὐκ ἀποστερεῖσθαι;", "st": "31.7"}, {"sp": "N", "t": "ὁρᾷς ὡς ὑποκρίνει μὲν δεδωκέναι τὴν προῖκα, φαίνει δὲ κατ’ οὐδ’ ὁντινοῦν τρόπον δεδωκώς; τὰ γὰρ ἀληθῆ καὶ μὴ κακουργούμενα τῶν πραγμάτων ἁπλῶς, οἷ’ ἂν ἐξ ἀρχῆς πραχθῇ, τοιαῦτ’ ἐστίν· σὺ δὲ τοὐναντίον ἐξελέγχει πράξας εἰς τὴν καθ’ ἡμῶν ὑπηρεσίαν.", "st": "31.8"}, {"sp": "N", "t": "ἄξιον τοίνυν καὶ τὸν ὅρκον, ὁποῖόν τιν’ ἂν ὤμοσεν, εἴ τις ἔδωκεν, ἐκ τούτων ἰδεῖν. ὃς γὰρ ὀγδοήκοντα μνᾶς ἔφη τὴν προῖκ’ εἶναι, εἰ τότ’ αὐτῷ τις ἔδωκεν, ὀμόσαντι ταῦτ’ ἀληθῆ λέγειν, κομίσασθαι, τί ἐποίησεν ἄν; ἢ δῆλον ὅτι ὤμοσεν; τί γὰρ καὶ λέγων οὐ φήσει τότ’ ἂν ὀμόσαι, νῦν γε τοῦτ’ ἀξιῶν; οὐκοῦν ὅτι γ’ ἐπιώρκησεν ἄν, ἑαυτὸν ἐξελέγχει· νῦν γὰρ οὐκ ὀγδοήκοντα μνᾶς, ἀλλὰ τάλαντον δεδωκέναι φησίν. τί μᾶλλον ἂν οὖν εἰκότως τις αὐτὸν ἐκεῖν’ ἐπιορκεῖν ἢ τάδ’ ἡγοῖτο; ἢ τίνα τις δικαίως ἂν ἔχοι περὶ τούτου διάνοιαν, τοῦ ῥᾳδίως οὕτως αὑτὸν ἐξελέγχοντος ὄντ’ ἐπίορκον;", "st": "31.9"}, {"sp": "N", "t": "ἀλλὰ νὴ Δί’ ἴσως οὐχὶ πάντ’ αὐτῷ τοιαῦτα πέπρακται, οὐδὲ πανταχόθεν δῆλός ἐστι τεχνάζων. ἀλλὰ καὶ τιμώμενος φανερὸς γέγονεν ὑπὲρ Ἀφόβου ταλάντου, καὶ τοῦτ’ αὐτὸς ἡμῖν ἀποδώσειν ἐγγυώμενος. καίτοι σκέψασθ’ ὅτι τοῦτ’ ἔστι τεκμήριον οὐ μόνον τοῦ τὴν γυναῖκα συνοικεῖν Ἀφόβῳ καὶ τοῦτον οἰκείως ἔχειν, ἀλλὰ καὶ τοῦ μὴ δεδωκέναι τὴν προῖκα.", "st": "31.10"}, {"sp": "N", "t": "τίς γὰρ ἀνθρώπων ἠλίθιός ἐστιν οὕτως ὥστ’ ἀργύριον μὲν δοὺς τοσοῦτον, ἔπειθ’ ἓν λαβὼν χωρίον ἀμφισβητούμενον εἰς ἀποτίμησιν, σὺν οἷς πρότερον ἐζημίωτο, τὸν ἀδικήσανθ’ ὡς δίκαιόν τι ποιήσοντα καὶ τοῦ τῆς δίκης ὀφλήματος προσεγγυήσασθαι; ἐγὼ μὲν οὐδέν’ οἶμαι. καὶ γὰρ οὐδὲ λόγον τὸ πρᾶγμ’ ἔχον ἐστίν, τὸν αὐτὸν αὑτῷ μὴ δυνάμενον κομίσασθαι τάλαντον, τοῦτον ἄλλῳ τινὶ φάσκειν ἀποτείσειν καὶ ταῦτ’ ἐγγυᾶσθαι. ἀλλὰ καὶ ἀπ’ αὐτῶν τούτων ἐστὶ δῆλον ὅτι τὴν μὲν προῖκ’ οὐκ ἔδωκεν, ἀντὶ δὲ πολλῶν χρημάτων τῶν ἐμῶν οἰκεῖος ὢν Ἀφόβῳ ταῦτ’ ἀπετιμᾶτο, κληρονόμον τὴν ἀδελφὴν τῶν ἐμῶν μετ’ ἐκείνου καταστῆσαι βουλόμενος.", "st": "31.11"}, {"sp": "N", "t": "εἶτα νῦν παρακρούσασθαι ζητεῖ καὶ φενακίζει, λέγων ὡς πρότερον τοὺς ὅρους ἔστησεν ἢ ’κεῖνον τὴν δίκην ὀφλεῖν. οὐ πρότερόν γ’ ἢ παρὰ σοί, νῦν εἰ ἀληθῆ λέγεις. δῆλον γὰρ ὅτι καταγνοὺς ἀδικίαν αὐτοῦ ταῦτ’ ἐποίεις. εἶτα καὶ γελοῖον τοῦτο λέγειν, ὥσπερ οὐκ εἰδότων ὑμῶν ὅτι πάντες οἱ τὰ τοιαῦτ’ ἀδικοῦντες σκοποῦσι τί λέξουσιν, καὶ οὐδεὶς πώποτ’ ὦφλεν σιωπῶν οὐδ’ ἀδικεῖν ὁμολογῶν· ἀλλ’ ἐπειδὰν οἶμαι μηδὲν ἀληθὲς λέγων ἐξελεγχθῇ, τότε γιγνώσκεται ὁποῖός ἐστιν.", "st": "31.12"}, {"sp": "N", "t": "ὅπερ καὶ οὗτος ἔμοιγε δοκεῖ πάσχειν. ἐπεὶ φέρε, πῶς ἐστι δίκαιον, ἐὰν μὲν ὀγδοήκοντα μνῶν θῇς ὅρους, ὀγδοήκοντα μνᾶς εἶναι τὴν προῖκα, ἐὰν δὲ πλείονος πλέον, ἐὰν δ’ ἐλάττονος ἔλαττον; ἢ πῶς ἐστι δίκαιον, τῆς ἀδελφῆς τῆς σῆς μηδέπω καὶ τήμερον ἄλλῳ συνοικούσης μηδ’ ἀπηλλαγμένης Ἀφόβου, μηδὲ τὴν προῖκα δεδωκότος σοῦ, μηδ’ ὑπὲρ τούτων εἰς βάσανον μηδ’ εἰς ἄλλο δίκαιον μηδὲν καταφεύγειν ἐθέλοντος, ὅτι σὺ στῆσαι φὴς ὅρους, σὸν εἶναι τὸ χωρίον; ἐγὼ μὲν οὐδαμῶς οἶμαι· τὴν γὰρ ἀλήθειαν σκεπτέον, οὐχ ἅ τις αὑτῷ παρεσκεύασεν ἐξεπίτηδες εἰς τὸ λέγειν τι δοκεῖν, ὥσπερ ὑμεῖς.", "st": "31.13"}, {"sp": "N", "t": "ἔπειτα τὸ δεινότατον· εἰ καὶ δεδωκότες ἦθ’ ὡς μάλιστα τὴν προῖκα, ἣν οὐ δεδώκατε, τίς ὁ τούτων αἴτιος; οὐχ ὑμεῖς, ἐπεὶ ⟨ἐπὶ⟩ τἄμ’ ἔδοτε; οὐχ ὅλοις ἔτεσιν πρότερον δέκα τἀμὰ λαβὼν εἶχεν ἐκεῖνος ὧν ὦφλεν τὴν δίκην, ἢ κηδεστήν σοι γενέσθαι; ἢ σὲ μὲν δεῖ κομίσασθαι πάντα, τὸν δὲ καὶ καταδικασάμενον καὶ δι’ ὀρφανίαν ἠδικημένον καὶ προικὸς ἀληθινῆς ἀπεστερημένον, ὃν μόνον ἀνθρώπων οὐδὲ τῆς ἐπωβελίας ἄξιον ἦν κινδυνεύειν, ἠναγκάσθαι τοιαῦτα παθεῖν, κεκομισμένον μηδ’ ὁτιοῦν, καὶ ταῦτ’ ἐθέλοντα ποιεῖν ⟨ἐφ’⟩ ὑμῖν αὐτοῖς, εἴ τι τῶν δεόντων ἐβούλεσθε πράττειν;", "st": "31.14"}, {"sp": "HDR", "t": "Πρὸς Ζηνόθεμιν παραγραφή", "st": "32"}, {"sp": "N", "t": "ἄνδρες δικασταί, βούλομαι παραγεγραμμένος μὴ εἰσαγώγιμον εἶναι τὴν δίκην, περὶ τῶν νόμων πρῶτον εἰπεῖν, καθ’ οὓς παρεγραψάμην. οἱ νόμοι κελεύουσιν, ὦ ἄνδρες δικασταί, τὰς δίκας εἶναι τοῖς ναυκλήροις καὶ τοῖς ἐμπόροις τῶν Ἀθήναζε καὶ τῶν Ἀθήνηθεν συμβολαίων, καὶ περὶ ὧν ἂν ὦσι συγγραφαί· ἂν δέ τις παρὰ ταῦτα δικάζηται, μὴ εἰσαγώγιμον εἶναι τὴν δίκην.", "st": "32.1"}, {"sp": "N", "t": "τουτῳὶ τοίνυν Ζηνοθέμιδι πρὸς μὲν ἐμὲ ὅτι οὐδὲν ἦν συμβόλαιον οὐδὲ συγγραφή, καὐτὸς ὁμολογεῖ ἐν τῷ ἐγκλήματι· δανεῖσαι δέ φησιν Ἡγεστράτῳ ναυκλήρῳ, τούτου δ’ ἀπολομένου ἐν τῷ πελάγει, ἡμᾶς τὸ ναῦλον σφετερίσασθαι· τουτὶ τὸ ἔγκλημ’ ἐστίν. ἐκ δὴ τοῦ αὐτοῦ λόγου τήν τε δίκην οὐκ εἰσαγώγιμον οὖσαν μαθήσεσθε, καὶ τὴν ὅλην ἐπιβουλὴν καὶ πονηρίαν τουτουὶ τοῦ ἀνθρώπου ὄψεσθε.", "st": "32.2"}, {"sp": "N", "t": "δέομαι δ’ ὑμῶν πάντων, ὦ ἄνδρες δικασταί, εἴπερ ἄλλῳ τινὶ πώποτε πράγματι τὸν νοῦν προσέσχετε, καὶ τούτῳ προσέχειν· ἀκούσεσθε γὰρ ἀνθρώπου τόλμαν καὶ πονηρίαν οὐ τὴν τυχοῦσαν, ἄνπερ ἐγὼ τὰ πεπραγμέν’ αὐτῷ πρὸς ὑμᾶς πολλάκις εἰπεῖν δυνηθῶ. οἶμαι δέ.", "st": "32.3"}, {"sp": "N", "t": "Ζηνόθεμις γὰρ οὑτοσί, ὢν ὑπηρέτης Ἡγεστράτου τοῦ ναυκλήρου, ὃν καὶ αὐτὸς ἔγραψεν ἐν τῷ ἐγκλήματι ὡς ἐν τῷ πελάγει ἀπώλετο (πῶς δέ, οὐ προσέγραψεν, ἀλλ’ ἐγὼ φράσω), ἀδίκημα τοιουτονὶ μετ’ ἐκείνου συνεσκευάσατο. χρήματ’ ἐν ταῖς Συρακούσαις ἐδανείζεθ’ οὗτος κἀκεῖνος. ὡμολόγει δ’ ἐκεῖνος μὲν πρὸς τοὺς τούτῳ δανείζοντας, εἴ τις ἔροιτο, ἐνεῖναι σῖτον ἐν τῇ νηὶ τούτῳ πολύν, οὗτος δὲ πρὸς τοὺς ἐκείνῳ τὸν γόμον οἰκεῖον ἔχειν αὐτὸν τῆς νεώς· ὢν δ’ ὁ μὲν ναύκληρος, ὁ δ’ ἐπιβάτης, ἐπιστεύοντ’ εἰκότως ἃ περὶ ἀλλήλων ἔλεγον.", "st": "32.4"}, {"sp": "N", "t": "λαμβάνοντες δὲ τὰ χρήματα, οἴκαδ’ ἀπέστελλον εἰς τὴν Μασσαλίαν, καὶ οὐδὲν εἰς τὴν ναῦν εἰσέφερον. οὐσῶν δὲ τῶν συγγραφῶν, ὥσπερ εἰώθασιν ἅπασαι, σωθείσης τῆς νεὼς ἀποδοῦναι τὰ χρήματα, ἵν’ ἀποστερήσαιεν τοὺς δανείσαντας, τὴν ναῦν καταδῦσαι ἐβουλεύσαντο. ὁ μὲν οὖν Ἡγέστρατος, ὡς ἀπὸ τῆς γῆς ἀπῆραν δυοῖν ἢ τριῶν ἡμερῶν πλοῦν, καταβὰς τῆς νυκτὸς εἰς κοίλην ναῦν διέκοπτε τοῦ πλοίου τὸ ἔδαφος. οὑτοσὶ δ’, ὡς οὐδὲν εἰδώς, ἄνω μετὰ τῶν ἄλλων ἐπιβατῶν διέτριβεν. ψόφου δὲ γενομένου, αἰσθάνονται οἱ ἐν τῷ πλοίῳ ὅτι κατόν τι ἐν κοίλῃ νηὶ γίγνεται, καὶ βοηθοῦσι κάτω.", "st": "32.5"}, {"sp": "N", "t": "ὡς δ’ ἡλίσκεθ’ ὁ Ἡγέστρατος καὶ δίκην δώσειν ὑπέλαβεν, φεύγει καὶ διωκόμενος ῥίπτει αὑτὸν εἰς τὴν θάλατταν, διαμαρτὼν δὲ τοῦ λέμβου διὰ τὸ νύκτ’ εἶναι, ἀπεπνίγη. ἐκεῖνος μὲν οὕτως, ὥσπερ ἄξιος ἦν, κακὸς κακῶς ἀπώλετο, ἃ τοὺς ἄλλους ἐπεβούλευσε ποιῆσαι, ταῦτα παθὼν αὐτός.", "st": "32.6"}, {"sp": "N", "t": "οὑτοσὶ δ’ ὁ κοινωνὸς αὐτοῦ καὶ συνεργὸς τὸ μὲν πρῶτον εὐθὺς ἐν τῷ πλοίῳ παρὰ τἀδικήματα, ὡς οὐδὲν εἰδώς, ἀλλ’ ἐκπεπληγμένος καὶ αὐτός, ἔπειθεν τὸν πρῳρέα καὶ τοὺς ναύτας εἰς τὸν λέμβον ἐκβαίνειν καὶ ἐκλιπεῖν τὴν ναῦν τὴν ταχίστην, ὡς ἀνελπίστου τῆς σωτηρίας οὔσης καὶ καταδυσομένης τῆς νεὼς αὐτίκα μάλα, ἵν’, ὅπερ διενοήθησαν, τοῦτ’ ἐπιτελεσθείη καὶ ἡ ναῦς ἀπόλοιτο καὶ τὰ συμβόλαι’ ἀποστερήσαιεν.", "st": "32.7"}, {"sp": "N", "t": "ἀποτυχὼν δὲ τούτου, καὶ τοῦ παρ’ ἡμῶν συμπλέοντος ἐναντιωθέντος καὶ τοῖς ναύταις μισθούς, εἰ διασῴσειαν τὴν ναῦν, μεγάλους ἐπαγγειλαμένου, σωθείσης εἰς Κεφαλληνίαν τῆς νεὼς διὰ τοὺς θεοὺς μάλιστά γε, εἶτα καὶ διὰ τὴν τῶν ναυτῶν ἀρετήν, πάλιν μετὰ τῶν Μασσαλιωτῶν τῶν τοῦ Ἡγεστράτου πολιτῶν μὴ καταπλεῖν Ἀθήναζε τὸ πλοῖον ἔπραττε, λέγων ὡς αὐτός τε καὶ τὰ χρήματ’ ἐκεῖθέν ἐστι, καὶ ὁ ναύκληρος εἴη καὶ οἱ δεδανεικότες Μασσαλιῶται.", "st": "32.8"}, {"sp": "N", "t": "ἀποτυχὼν δὲ καὶ τούτου, καὶ τῶν ἀρχόντων τῶν ἐν τῇ Κεφαλληνίᾳ γνόντων Ἀθήναζε τὴν ναῦν καταπλεῖν, ὅθενπερ ἀνήχθη, ὃν οὐδ’ ἂν εἷς ἐλθεῖν ᾤετο δεῦρο τολμῆσαι τοιαῦτά γ’ ἐσκευωρημένον καὶ πεποιηκότα, οὗτος, ὦ ἄνδρες Ἀθηναῖοι, τοσοῦτον ὑπερβέβληκεν ἀναιδείᾳ καὶ τόλμῃ, ὥστ’ οὐκ ἐλήλυθεν μόνον, ἀλλὰ καὶ τοῦ σίτου τοῦ ἡμετέρου ἀμφισβητήσας ἡμῖν δίκην προσείληχεν.", "st": "32.9"}, {"sp": "N", "t": "τί οὖν ποτ’ ἐστὶν τὸ αἴτιον, καὶ τῷ ποτ’ ἐπηρμένος οὗτος καὶ ἐλήλυθεν καὶ τὴν δίκην εἴληχεν; ἐγὼ ὑμῖν ἐρῶ, ἄνδρες δικασταί, ἀχθόμενος μὲν νὴ τὸν Δία καὶ θεούς, ἀναγκαζόμενος δέ. ἔστιν ἐργαστήρια μοχθηρῶν ἀνθρώπων συνεστηκότων ἐν τῷ Πειραιεῖ· οὓς οὐδ’ ὑμεῖς ἀγνοήσετ’ ἰδόντες.", "st": "32.10"}, {"sp": "N", "t": "ἐκ τούτων ἕνα, ἡνίχ’ οὗτος ἔπραττεν ὅπως ἡ ναῦς μὴ καταπλεύσεται δεῦρο, πρεσβευτὴν ἐκ βουλῆς τινα λαμβάνομεν γνώριμον οὑτωσί, ὅ τι δ’ ἦν οὐκ εἰδότες, ἀτύχημ’ οὐδὲν ἔλαττον, εἰ οἷόν τ’ εἰπεῖν, ἀτυχήσαντες ἢ τὸ ἐξ ἀρχῆς πονηροῖς ἀνθρώποις συμμεῖξαι. οὗτος ὁ πεμφθεὶς ὑφ’ ἡμῶν (Ἀριστοφῶν ὄνομ’ αὐτῷ), ὃς καὶ τὰ τοῦ Μικκαλίωνος πράγματ’ ἐσκευώρηται (ταῦτα γὰρ νῦν ἀκούομεν), ἠργολάβηκεν αὐτὸς καὶ κατεπήγγελται τουτῳί, καὶ ὅλως ἐστὶν ὁ πάντα πράττων οὗτος· ὁδὶ δ’ ἅσμενος δέδεκται ταῦτα.", "st": "32.11"}, {"sp": "N", "t": "ὡς γὰρ διήμαρτεν τοῦ διαφθαρῆναι τὸ πλοῖον, οὐκ ἔχων ἀποδοῦναι τὰ χρήματα τοῖς δανείσασιν (πῶς γάρ; ἅ γ’ ἐξ ἀρχῆς μὴ ἐνέθετο) ἀντιποιεῖται τῶν ἡμετέρων, καί φησι τῷ Ἡγεστράτῳ ἐπὶ τούτῳ τῷ σίτῳ δεδανεικέναι ὃν ὁ παρ’ ἡμῶν ἐπιπλέων ἐπρίατο. οἱ δὲ δανεισταὶ τὸ ἐξ ἀρχῆς ἐξηπατημένοι, ὁρῶντες ἑαυτοῖς ἀντὶ τῶν χρημάτων ἄνθρωπον πονηρὸν χρήστην, ἄλλο δ’ οὐδέν, ἐλπίδ’ ἔχοντες ὑπὸ τούτου παρακρουσθέντων ὑμῶν ἐκ τῶν ἡμετέρων ἀπολήψεσθαι τὰ ἑαυτῶν, ὃν ἴσασιν ψευδόμενον ταῦτα καθ’ ἡμῶν, τούτῳ συνδικεῖν ἀναγκάζονται τοῦ συμφέροντος εἵνεκα τοῦ ἑαυτῶν.", "st": "32.12"}, {"sp": "N", "t": "τὸ μὲν οὖν πρᾶγμ’ ὑπὲρ οὗ τὴν ψῆφον οἴσετε, ὡς εἰπεῖν ἐν κεφαλαίῳ, τοιοῦτόν ἐστιν. βούλομαι δὲ τοὺς μάρτυρας ὧν λέγω πρῶτον ὑμῖν παρασχόμενος, μετὰ ταῦτ’ ἤδη καὶ τἄλλα διδάσκειν. καί μοι λέγε τὰς μαρτυρίας.", "st": "32.13"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "32.13"}, {"sp": "N", "t": "ἐπειδὴ τοίνυν ἀφίκετο δεῦρο τὸ πλοῖον, γνόντων τῶν Κεφαλλήνων ἀντιπράττοντος τούτου, ὅθεν ἐξέπλευσε τὸ πλοῖον, ἐνταῦθα καὶ καταπλεῖν αὐτό, τὴν μὲν ναῦν οἱ ἐπὶ τῇ νηὶ δεδανεικότες ἐνθένδ’ εὐθέως εἶχον, τὸν δὲ σῖτον ὁ ἠγορακὼς εἶχεν· ἦν δ’ οὗτος ὁ ἡμῖν τὰ χρήματ’ ὀφείλων. μετὰ ταῦθ’ ἧκεν οὗτος ἔχων τὸν παρ’ ἡμῶν πεμφθέντα πρεσβευτήν, τὸν Ἀριστοφῶντα, καὶ ἠμφεσβήτει τοῦ σίτου, φάσκων Ἡγεστράτῳ δεδανεικέναι.", "st": "32.14"}, {"sp": "N", "t": "“τί λέγεις, ἄνθρωπε;” εὐθέως ὁ Πρῶτος (τοῦτο γὰρ ἦν τοὔνομα τῷ τὸν σῖτον εἰσαγαγόντι, τῷ τὰ χρήμαθ’ ἡμῖν ὀφείλοντι) “σὺ χρήματα δέδωκας Ἡγεστράτῳ, μεθ’ οὗ τοὺς ἄλλους ἐξηπάτηκας, ὅπως δανείσηται, καὶ σοὶ πολλάκις λέγοντος ὅτι τοῖς προϊεμένοις ἀπολεῖται τὰ χρήματα; σὺ οὖν ταῦτ’ ἀκούων αὐτὸς ἂν προήκω;” ἔφη καὶ ἀναιδὴς ἦν. “οὐκοῦν εἰ τὰ μάλιστ’ ἀληθῆ λέγεις,” τῶν παρόντων τις ὑπέλαβεν, “ὁ σὸς κοινωνὸς καὶ πολίτης, ὁ Ἡγέστρατος, ὡς ἔοικεν, ἐξηπάτηκέν σε, καὶ ὑπὲρ τούτων αὐτὸς αὑτῷ θανάτου τιμήσας ἀπόλωλεν.”", "st": "32.15"}, {"sp": "N", "t": "“καὶ ὅτι γ’,” ἔφη τις τῶν παρόντων, “ἁπάντων ἐστὶ συνεργὸς οὗτος ἐκείνῳ, σημεῖον ὑμῖν ἐρῶ· πρὸ γὰρ τοῦ διακόπτειν ἐπιχειρῆσαι τὴν ναῦν, τίθενται πρός τινα τῶν συμπλεόντων οὗτος καὶ ὁ Ἡγέστρατος συγγραφήν. καίτοι εἰ μὲν εἰς πίστιν ἔδωκας, τί πρὸ τοῦ κακουργήματος ἂν τὰ βέβαι’ ἐποιοῦ; εἰ δ’ ἀπιστῶν ἐτύγχανες, τί οὐχ, ὥσπερ οἱ ἄλλοι, τὰ δίκαι’ ἐλάμβανες ἐν τῇ γῇ;”", "st": "32.16"}, {"sp": "N", "t": "τί ἂν τὰ πολλὰ λέγοι τις; ἦν γὰρ οὐδ’ ὁτιοῦν πλέον ἡμῖν ταῦτα λέγουσιν, ἀλλ’ εἴχετο τοῦ σίτου. ἐξῆγεν αὐτὸν Πρῶτος καὶ ὁ κοινωνὸς τοῦ Πρώτου, Φέρτατος· οὑτοσὶ δ’ οὐκ ἐξήγετο, οὐδ’ ἂν ἔφη διαρρήδην ὑπ’ οὐδενὸς ἐξαχθῆναι, εἰ μὴ αὐτὸν ἐγὼ ἐξάξω.", "st": "32.17"}, {"sp": "N", "t": "μετὰ ταῦτα προὐκαλεῖθ’ ὁ Πρῶτος αὐτὸν καὶ ἡμεῖς ἐπὶ τὴν ἀρχὴν τὴν τῶν Συρακοσίων, κἂν μὲν ἐωνημένος τὸν σῖτον ἐκεῖνος φαίνηται καὶ τὰ τέλη κείμεν’ ἐκείνῳ καὶ τὰς τιμὰς ὁ διαλύων ἐκεῖνος, τοῦτον πονηρὸν ὄντ’ ἀξιοῦμεν ζημιοῦσθαι, εἰ δὲ μή, καὶ τὰ διάφορ’ ἀπολαβεῖν καὶ τάλαντον προσλαβεῖν, καὶ τοῦ σίτου ἀφιστάμεθα. ταῦτ’ ἐκείνου προκαλουμένου καὶ λέγοντος καὶ ἡμῶν οὐδὲν ἦν πλέον, ἀλλ’ ἦν αἵρεσις ἢ τοῦτον ἐξάγειν ἢ ἀπολωλεκέναι σωθέντα καὶ παρόντα τὰ ἡμέτερ’ αὐτῶν.", "st": "32.18"}, {"sp": "N", "t": "ὁ γὰρ αὖ Πρῶτος διεμαρτύρετ’ ἐξάγειν, βεβαιῶν ἀναπλεῖν ἐθέλειν εἰς τὴν Σικελίαν· εἰ δὲ ταῦτ’ ἐθέλοντος αὑτοῦ προησόμεθ’ ἡμεῖς τούτῳ τὸν σῖτον, οὐδὲν αὑτῷ μέλειν. καὶ ὅτι ταῦτ’ ἀληθῆ λέγω, καὶ οὔτ’ ἂν ἐξαχθῆναι ἔφη, εἰ μὴ ὑπ’ ἐμοῦ, οὔθ’ ἃ προὐκαλεῖτο περὶ τοῦ ἀναπλεῖν ἐδέχετο, ἔν τε τῷ πλῷ τὴν συγγραφὴν ἔθετο, λέγε τὰς μαρτυρίας.", "st": "32.19"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "32.19"}, {"sp": "N", "t": "ἐπειδὴ τοίνυν οὔτ’ ἐξάγεσθαι ἤθελεν ὑπὸ τοῦ Πρώτου οὔτ’ εἰς τὴν Σικελίαν ἀναπλεῖν ἐπὶ τὰ δίκαια, προειδώς θ’ ἅπαντ’ ἐφαίνετο, ἃ ὁ Ἡγέστρατος ἐκακούργει, λοιπὸν ἦν ἡμῖν τοῖς ἐνθένδε μὲν πεποιημένοις τὸ συμβόλαιον, παρειληφόσι δὲ τὸν σῖτον παρὰ τοῦ δικαίως ἐκεῖ πριαμένου, ἐξάγειν τοῦτον.", "st": "32.20"}, {"sp": "N", "t": "τί γὰρ ἂν καὶ ἄλλ’ ἐποιοῦμεν; οὔπω γὰρ τοῦτό γ’ οὐδεὶς ἡμῶν τῶν κοινωνῶν ὑπέλαβεν, ὡς ὑμεῖς γνώσεσθέ ποτ’ εἶναι τούτου τὸν σῖτον, ὃν καταλιπεῖν οὗτος ἔπειθεν τοὺς ναύτας, ὅπως ἀπόλοιτο τοῦ πλοίου καταδύντος. ὃ καὶ μέγιστόν ἐστι σημεῖον τοῦ μηδὲν προσήκειν αὐτῷ. τίς γὰρ ἂν τὸν ἑαυτοῦ σῖτον ἔπειθε προέσθαι τοὺς σῴζειν βουλομένους; ἢ τίς οὐκ ἂν ἔπλει δεξάμενος τὴν πρόκλησιν εἰς τὴν Σικελίαν, οὗ ταῦτ’ ἦν ἐλέγξαι καθαρῶς.", "st": "32.21"}, {"sp": "N", "t": "καὶ μὴν οὐδὲ τοῦτ’ ἐμέλλομεν ὑμῶν καταγνώσεσθαι, ὡς εἰσαγώγιμον ψηφιεῖσθε τούτῳ τὴν δίκην περὶ τούτων τῶν χρημάτων, ἃ κατὰ πολλοὺς τρόπους οὗτος ἔπραττεν ὅπως μὴ εἰσαγώγιμα δεῦρ’ ἔσται, πρῶτον μὲν ὅτ’ αὐτὰ καταλιπεῖν τοὺς ναύτας ἔπειθεν, εἶθ’ ὅτ’ ἐν Κεφαλληνίᾳ μὴ δεῦρο πλεῖν τὴν ναῦν ἔπραττεν.", "st": "32.22"}, {"sp": "N", "t": "πῶς γὰρ οὐκ αἰσχρὸν καὶ δεινὸν ἂν γένοιτο, εἰ Κεφαλλῆνες μέν, ὅπως τοῖς Ἀθηναίοις σωθῇ τὰ χρήματα, δεῦρο πλεῖν τὴν ναῦν ἔκριναν, ὑμεῖς δ’ ὄντες Ἀθηναῖοι τὰ τῶν πολιτῶν τοῖς καταποντίσαι βουληθεῖσιν δοῦναι γνοίητε, καὶ ἃ μὴ καταπλεῖν ὅλως οὗτος δεῦρ’ ἔπραττεν, ταῦτ’ εἰσαγώγιμα τούτῳ ψηφίσαισθε; μὴ δῆτ’, ὦ Ζεῦ καὶ θεοί. λέγε δή μοι τί παραγέγραμμαι.", "st": "32.23"}, {"sp": "N", "t": "ΠΑΡΑΓΡΑΦΗ.", "st": "32.23"}, {"sp": "N", "t": "λέγε δή μοι τὸν νόμον.", "st": "32.23"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "32.23"}, {"sp": "N", "t": "ὅτι μὲν τοίνυν ἐκ τῶν νόμων παρεγραψάμην μὴ εἰσαγώγιμον εἶναι τὴν δίκην, ἱκανῶς οἴομαι δεδεῖχθαι· τέχνην δ’ ἀκούσεσθε τοῦ σοφοῦ τοῦ ταῦτα πάντα συντεθηκότος, τοῦ Ἀριστοφῶντος. ὡς γὰρ ἐκ τῶν πραγμάτων ἁπλῶς οὐδὲν ἑώρων δίκαιον ἑαυτοῖς ἐνόν, ἐπικηρυκεύονται τῷ Πρώτῳ καὶ πείθουσι τὸν ἄνθρωπον ἐνδοῦναι τὰ πράγμαθ’ ἑαυτοῖς, πράττοντες μὲν ὡς ἔοικεν καὶ ἐξ ἀρχῆς τοῦτο, ὡς ἡμῖν νῦν φανερὸν γέγονεν, οὐ δυνάμενοι δὲ πεῖσαι.", "st": "32.24"}, {"sp": "N", "t": "ὁ γὰρ Πρῶτος, ἕως μὲν ᾤετο τὸν σῖτον κέρδος ἐλθόντα ποιήσειν, ἀντείχετο τούτου, καὶ μᾶλλον ᾑρεῖτ’ αὐτός τε κερδᾶναι καὶ ἡμῖν τὰ δίκαι’ ἀποδοῦναι, ἢ κατακοινωνήσας τούτοις τῆς μὲν ὠφελίας τούτους ποιῆσαι μερίτας, ἡμᾶς δ’ ἀδικῆσαι· ὡς δὲ δεῦρ’ ἥκοντος αὐτοῦ καὶ περὶ ταῦτα πραγματευομένου, ἐπανῆκεν ὁ σῖτος, ἄλλην εὐθέως ἔλαβεν γνώμην.", "st": "32.25"}, {"sp": "N", "t": "καὶ ἅμα (εἰρήσεται γάρ, ἄνδρες Ἀθηαῖοι, πᾶσα πρὸς ὑμᾶς ἡ ἀλήθεια) καὶ ἡμεῖς οἱ δεδανεικότες προσεκρούομεν αὐτῷ καὶ πικρῶς εἴχομεν, τῆς τε ζημίας ἐφ’ ἡμᾶς ἰούσης τῆς περὶ τὸν σῖτον καὶ συκοφάντην ἀντὶ χρημάτων αἰτιώμενοι τοῦτον ἡμῖν κεκομικέναι. ἐκ τούτων, οὐδὲ φύσει χρηστὸς ὢν ἅνθρωπος δῆλον ὅτι, ἐπὶ τούτους ἀποκλίνει, καὶ συγχωρεῖ τὴν δίκην ἔρημον ὀφλεῖν, ἣν οὗτος αὐτῷ λαγχάνει τότε, ὅτ’ οὔπω ταὔτ’ ἐφρόνουν.", "st": "32.26"}, {"sp": "N", "t": "εἰ μὲν γὰρ ἀφῆκε τὸν Πρῶτον, ἐξελήλεγκτ’ ἂν εὐθέως ἡμᾶς συκοφαντῶν· ὀφλεῖν δὲ παρὼν ἐκεῖνος οὐ συνεχώρει, ἵν’ ἐὰν μὲν αὐτῷ ποιῶσιν ἃ ὡμολογήκασιν—, εἰ δὲ μή, τὴν ἔρημον ἀντιλάχῃ. ἀλλὰ τί ταῦτα; εἰ μὲν γὰρ ἃ γέγραφεν οὗτος εἰς τὸ ἔγκλημ’ ἐποίει, οὐκ ὀφλεῖν ἂν δίκην δικαίως, ἀλλ’ ἀποθανεῖν Πρῶτος ἔμοιγε δοκεῖ. εἰ γὰρ ἐν κακοῖς καὶ χειμῶνι τοσοῦτον οἶνον ἔπινεν ὥσθ’ ὅμοιον εἶναι μανίᾳ, τί οὐκ ἄξιός ἐστι παθεῖν.", "st": "32.27"}, {"sp": "N", "t": "ἢ εἰ γράμματ’ ἔκλεπτεν; εἰ ὑπανέῳγεν; ἀλλὰ ταῦτα μὲν αὐτοὶ πρὸς ἑαυτοὺς ὑμεῖς ὅπως ποτ’ ἔχει διακρινεῖσθε· τῇ δ’ ἐμῇ δίκῃ μηδὲν ἐκείνης πρόσαγε. εἴ τί σ’ ἠδίκηκεν ὁ Πρῶτος ἢ λέγων ἢ ποιῶν, ἔχεις ὡς ἔοικε δίκην· οὐδεὶς ἡμῶν ἐκώλυεν, οὐδὲ νῦν παραιτεῖται. εἰ σεσυκοφάντηκας, οὐ περιεργαζόμεθα.", "st": "32.28"}, {"sp": "N", "t": "νὴ Δί’, ἀλλ’ ἐκποδών ἐστιν ἅνθρωπος. διά γ’ ὑμᾶς, ἵνα τάς τε μαρτυρίας τὰς ἡμετέρας λίπῃ, καὶ νῦν ὑμεῖς ὅ τι ἂν βούλησθε λέγητε κατ’ αὐτοῦ. εἰ γὰρ μὴ δι’ ὑμῶν ἔρημος ἐγίγνεθ’ ἡ δίκη, ἅμ’ ἂν αὐτὸν προσεκαλοῦ καὶ κατηγγύας πρὸς τὸν πολέμαρχον, καὶ εἰ μὲν κατέστησέ σοι τοὺς ἐγγυητάς, μένειν ἠναγκάζετ’ ἄν, ἢ σὺ παρ’ ὧν λήψει δίκην ἑτοίμους εἶχες, εἰ δὲ μὴ κατέστησεν, εἰς τὸ οἴκημ’ ἂν ᾔει.", "st": "32.29"}, {"sp": "N", "t": "νῦν δὲ κοινωσάμενοι τὸ πρᾶγμα, ὁ μὲν διὰ σοῦ τὴν γεγονυῖαν ἔκδειαν οὐκ ἀποδώσειν ἡμῖν οἴεται, σὺ δ’ ἐκείνου κατηγορῶν τῶν ἡμετέρων κύριος γενήσεσθαι. τεκμήριον δέ· ἐγὼ μὲν γὰρ αὐτὸν κλητεύσω, σὺ δ’ οὔτε κατηγγύησας οὔτε νῦν κλητεύσεις.", "st": "32.30"}, {"sp": "N", "t": "ἔτι τοίνυν ἑτέρα τις ἐστὶν ἐλπὶς αὐτοῖς τοῦ παρακρούσεσθαι καὶ φενακιεῖν ὑμᾶς. αἰτιάσονται Δημοσθένην, καὶ ἐκείνῳ ἐμὲ πιστεύοντα φήσουσιν ἐξάγειν τουτονί, ὑπολαμβάνοντες τῷ ῥήτορα καὶ γνώριμον εἶναι ἐκεῖνον πιθανὴν ἔχειν τὴν αἰτίαν. ἐμοὶ δ’ ἐστὶ μέν, ὦ ἄνδρες Ἀθηναῖοι, Δημοσθένης οἰκεῖος γένει (καὶ πάντας ὑμῖν ὄμνυμι τοὺς θεοὺς ἦ μὴν ἐρεῖν τἀληθῆ).", "st": "32.31"}, {"sp": "N", "t": "προσελθόντος δ’ αὐτῷ μου καὶ παρεῖναι καὶ βοηθεῖν ἀξιοῦντος εἴ τι ἔχοι, “δήμων,” ἔφη, “ἐγὼ ποιήσω μὲν ὡς ἂν σὺ κελεύῃς (καὶ γὰρ ἂν δεινὸν εἴη). δεῖ μέντοι καὶ τὸ σαυτοῦ καὶ τοὐμὸν λογίσασθαι. ἐμοὶ συμβέβηκεν, ἀφ’ οὗ περὶ τῶν κοινῶν λέγειν ἠρξάμην, μηδὲ πρὸς ἓν πρᾶγμ’ ἴδιον προσεληλυθέναι· ἀλλὰ καὶ τῆς πολιτείας αὐτῆς τὰ τοιαῦτ’ ἐξέστηκα …”", "st": "32.32"}, {"sp": "HDR", "t": "Πρὸς Ἀπατούριον παραγραφή", "st": "33"}, {"sp": "N", "t": "τοῖς μὲν ἐμπόροις, ὦ ἄνδρες δικασταί, καὶ τοῖς ναυκλήροις κελεύει ὁ νόμος εἶναι τὰς δίκας πρὸς τοὺς θεσμοθέτας, ἐάν τι ἀδικῶνται ἐν τῷ ἐμπορίῳ ἢ ἐνθένδε ποι πλέοντες ἢ ἑτέρωθεν δεῦρο, καὶ τοῖς ἀδικοῦσιν δεσμὸν ἔταξεν τοὐπιτίμιον, ἕως ἂν ἐκτείσωσιν ὅ τι ἂν αὐτῶν καταγνωσθῇ, ἵνα μηδεὶς ἀδικῇ μηδένα τῶν ἐμπόρων εἰκῇ.", "st": "33.1"}, {"sp": "N", "t": "τοῖς δὲ περὶ τῶν μὴ γενομένων συμβολαίων εἰς κρίσιν καθισταμένοις ἐπὶ τὴν παραγραφὴν καταφεύγειν ἔδωκεν ὁ νόμος, ἵνα μηδεὶς συκοφαντῆται, ἀλλ’ αὐτοῖς τοῖς τῇ ἀληθείᾳ ἀδικουμένοις τῶν ἐμπόρων καὶ τῶν ναυκλήρων αἱ δίκαι ὦσιν. καὶ πολλοὶ ἤδη τῶν φευγόντων ἐν ταῖς ἐμπορικαῖς παραγραψάμενοι κατὰ τὸν νόμον τουτονὶ καὶ εἰσελθόντες εἰς ὑμᾶς ἐξήλεγξαν τοὺς δικαζομένους ἀδίκως ἐγκαλοῦντας καὶ ἐπὶ τῇ προφάσει τοῦ ἐμπορεύεσθαι συκοφαντοῦντας.", "st": "33.2"}, {"sp": "N", "t": "ὁ μὲν οὖν μετὰ τούτου μοι ἐπιβεβουλευκὼς καὶ τὸν ἀγῶνα τουτονὶ κατεσκευακὼς προϊόντος τοῦ λόγου καταφανὴς ὑμῖν ἔσται· ἐγκαλοῦντος δέ μοι Ἀπατουρίου τὰ ψευδῆ καὶ παρὰ τοὺς νόμους δικαζομένου, καὶ ὅσα μὲν ἐμοὶ καὶ τούτῳ ἐγένετο συμβόλαια, πάντων ἀπαλλαγῆς καὶ ἀφέσεως γενομένης, ἄλλου δὲ συμβολαίου οὐκ ὄντος ἐμοὶ πρὸς τοῦτον, οὔτε ναυτικοῦ οὔτ’ ἐγγείου, παρεγραψάμην τὴν δίκην μὴ εἰσαγώγιμον εἶναι κατὰ τοὺς νόμους τουτουσί.", "st": "33.3"}, {"sp": "N", "t": "ΝΟΜΟΙ.", "st": "33.3"}, {"sp": "N", "t": "ὡς τοίνυν παρὰ τοὺς νόμους τούτους εἴληχέ μοι τὴν δίκην Ἀπατούριος καὶ τὰ ψευδῆ ἐγκέκληκεν, ἐκ πολλῶν ὑμῖν τοῦτ’ ἐπιδείξω. ἐγὼ γάρ, ὦ ἄνδρες δικασταί, πολὺν ἤδη χρόνον ἐπὶ τῆς ἐργασίας ὢν τῆς κατὰ θάλατταν, μέχρι μέν τινος αὐτὸς ἐκινδύνευον, οὔπω δὲ ἔτη ἐστὶν ἑπτὰ ἀφ’ οὗ τὸ μὲν πλεῖν καταλέλυκα, μέτρια δ’ ἔχων τούτοις πειρῶμαι ναυτικοῖς ἐργάζεσθαι.", "st": "33.4"}, {"sp": "N", "t": "διὰ δὲ τὸ ἀφῖχθαι πολλαχόσε καὶ διὰ τὸ εἶναί μοι τὰς διατριβὰς περὶ τὸ ἐμπόριον γνωρίμως ἔχω τοῖς πλείστοις τῶν πλεόντων τὴν θάλατταν· τούτοις δὲ τοῖς ἐκ Βυζαντίου καὶ πάνυ οἰκείως χρῶμαι διὰ τὸ ἐνδιατρῖψαι αὐτόθι. ἔχοντος δέ μου οὕτως ὡς λέγω, κατέπλευσαν δεῦρο τρίτον ἔτος οὗτός τε καὶ πολίτης αὐτοῦ Παρμένων, Βυζάντιος μὲν τὸ γένος, φυγὰς δ’ ἐκεῖθεν.", "st": "33.5"}, {"sp": "N", "t": "προσιόντες δέ μοι ἐν τῷ ἐμπορίῳ οὗτος καὶ ὁ Παρμένων ἐμνήσθησαν περὶ ἀργυρίου. ἔτυχεν δὲ οὑτοσὶ ὀφείλων ἐπὶ τῇ νηὶ τῇ ἑαυτοῦ τετταράκοντα μνᾶς, καὶ οἱ χρῆσται κατήπειγον αὐτὸν ἀπαιτοῦντες καὶ ἐνεβάτευον εἰς τὴν ναῦν, εἰληφότες τῇ ὑπερημερίᾳ. ἀπορουμένῳ δ’ αὐτῷ μνᾶς μὲν δέκα ὁ Παρμένων ὡμολόγησεν δώσειν, τριάκοντα δὲ μνᾶς ἐδεῖτό μου οὗτος συνευπορῆσαι, αἰτιώμενος τοὺς χρήστας ἐπιθυμοῦντας τῆς νεὼς διαβεβληκέναι αὑτὸν ἐν τῷ ἐμπορίῳ, ἵνα κατάσχωσι τὴν ναῦν εἰς ἀπορίαν καταστήσαντες τοῦ ἀποδοῦναι τὰ χρήματα.", "st": "33.6"}, {"sp": "N", "t": "ἐμοὶ μὲν οὖν οὐκ ἔτυχεν παρὸν ἀργύριον, χρώμενος δὲ Ἡρακλείδῃ τῷ τραπεζίτῃ ἔπεισα αὐτὸν δανεῖσαι τὰ χρήματα λαβόντα ἐμὲ ἐγγυητήν. ἤδη δὲ τῶν τριάκοντα μνῶν πεπορισμένων, ἔτυχεν προσκεκρουκώς τι τούτῳ ὁ Παρμένων· ὡμολογηκὼς δ’ εὐπορήσειν αὐτῷ δέκα μνᾶς, καὶ τούτων δεδωκὼς τὰς τρεῖς, διὰ τὸ προειμένον ἀργύριον ἠναγκάζετο καὶ τὸ λοιπὸν διδόναι.", "st": "33.7"}, {"sp": "N", "t": "αὐτὸς μὲν οὖν διὰ τοῦτο οὐκ ἐβούλετο ποιήσασθαι τὸ συμβόλαιον, ἐμὲ δ’ ἐκέλευεν πρᾶξαι ὅπως αὐτῷ ὡς ἀσφαλέστατα ἕξει. λαβὼν δὲ [ἐγὼ] τὰς ἑπτὰ μνᾶς παρὰ τοῦ Παρμένοντος, καὶ τὰς τρεῖς ἃς προειλήφει οὗτος παρ’ ἐκείνου, ἀνθομολογησάμενος πρὸς τοῦτον, ὠνὴν ποιοῦμαι τῆς νεὼς καὶ τῶν παίδων, ἕως ἀποδοίη τάς τε δέκα μνᾶς ἃς δι’ ἐμοῦ ἔλαβεν, καὶ τὰς τριάκοντα ὧν κατέστησεν ἐμὲ ἐγγυητὴν τῷ τραπεζίτῃ. καὶ ὡς ἀληθῆ λέγω, ἀκούσατε τῶν μαρτυριῶν.", "st": "33.8"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "33.8"}, {"sp": "N", "t": "τὸν μὲν τρόπον τοῦτον ἀπήλλαξεν τοὺς χρήστας Ἀπατούριος οὑτοσί. οὐ πολλῷ δὲ χρόνῳ μετὰ ταῦτα τῆς τραπέζης ἀνασκευασθείσης, καὶ τοῦ Ἡρακλείδου κατ’ ἀρχὰς κεκρυμμένου, ἐπιβουλεύει οὑτοσὶ τούς τε παῖδας ἐκπέμψαι Ἀθήνηθεν καὶ τὴν ναῦν ἐξορμίσαι ἐκ τοῦ λιμένος. ὅθεν ἐμοὶ πρὸς τοῦτον ἡ πρώτη διαφορὰ ἐγένετο. αἰσθόμενος γὰρ ὁ Παρμένων ἐξαγομένων τῶν παίδων ἐπιλαμβάνεται καὶ τὴν ναῦν κατεκώλυσεν αὐτὸν ἐξορμίζειν, καὶ μεταπεμψάμενος ἐμὲ λέγει τὸ πρᾶγμα.", "st": "33.9"}, {"sp": "N", "t": "ὡς δ’ ἤκουσα, τοῦτον μὲν ἀνοσιώτατον ἡγησάμην εἶναι τῷ ἐπιχειρήματι, ἐσκοπούμην δὲ ὅπως αὐτός τε ἀπολυθήσομαι τῆς ἐγγύης τῆς ἐπὶ τὴν τράπεζαν, καὶ ὁ ξένος μὴ ἀπολεῖ ἃ δι’ ἐμοῦ τούτῳ ἐδάνεισεν. καταστήσας δὲ φύλακας τῆς νεὼς διηγησάμην τοῖς ἐγγυηταῖς τῆς τραπέζης τὴν πρᾶξιν, καὶ παρέδωκα τὸ ἐνέχυρον, εἰπὼν αὐτοῖς ὅτι δέκα μναῖ ἐνείησαν τῷ ξένῳ ἐν τῇ νηί. ταῦτα δὲ πράξας κατηγγύησα τοὺς παῖδας, ἵν’ εἴ τις ἔνδεια γίγνοιτο, τὰ ἐλλείποντα ἐκ τῶν παίδων εἴη.", "st": "33.10"}, {"sp": "N", "t": "καὶ ἐγὼ μὲν ἐπειδὴ ἔλαβον τοῦτον ἀδικοῦντα, διωρθωσάμην ὑπὲρ ἐμαυτοῦ καὶ τοῦ ξένου· ὁ δ’ ὥσπερ ἀδικούμενος, ἀλλ’ οὐκ ἀδικῶν ἐμέμφετό μοι, καὶ ἠρώτα εἰ οὐχ ἱκανόν μοι εἴη αὐτῷ ἀπολυθῆναι τῆς ἐγγύης τῆς πρὸς τὴν τράπεζαν, ἀλλὰ καὶ ὑπὲρ τοῦ ἀργυρίου τοῦ Παρμένοντος τὴν ναῦν κατεγγυῶ καὶ τοὺς παῖδας, καὶ ὑπὲρ ἀνθρώπου φυγάδος ἀπεχθανοίμην αὑτῷ.", "st": "33.11"}, {"sp": "N", "t": "ἐγὼ δὲ τὸν πιστεύοντα ἐμαυτῷ τοσούτῳ ἔφην ἧττον ἂν περιιδεῖν, ὅσῳ φυγὰς ὢν καὶ ἀτυχῶν ἠδικεῖτο ὑπὸ τούτου. πάντα δὲ ποιήσας καὶ εἰς πᾶσαν ἀπέχθειαν τούτῳ ἐλθών, μόλις εἰσέπραξα τὸ ἀργύριον, πραθείσης τῆς νεὼς τετταράκοντα μνῶν, ὅσουπερ ἡ θέσις ἦν. ἀποδοθεισῶν δὲ τῶν τριάκοντα μνῶν ἐπὶ τὴν τράπεζαν καὶ τῶν δέκα μνῶν τῷ Παρμένοντι, ἐναντίον πολλῶν μαρτύρων τάς τε συγγραφὰς ἀνειλόμεθα, καθ’ ἃς ἐδανείσθη τὰ χρήματα, καὶ τῶν συναλλαγμάτων ἀφεῖμεν καὶ ἀπηλλάξαμεν ἀλλήλους, ὥστε μήτε τούτῳ πρὸς ἐμὲ μήτ’ ἐμοὶ πρὸς τοῦτον πρᾶγμα εἶναι μηδέν. καὶ ὡς ἀληθῆ λέγω, ἀκούσατε τῶν μαρτυριῶν.", "st": "33.12"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "33.12"}, {"sp": "N", "t": "μετὰ ταῦτα τοίνυν ἐμοὶ μὲν οὔτε μεῖζον οὔτε ἔλαττον πρὸς αὐτὸν συμβόλαιον γέγονεν· ὁ δὲ Παρμένων ἐδικάζετο τούτῳ τῶν τε πληγῶν ὧν ἔλαβεν ὑπὸ τούτου, ὅτε τῶν παίδων ἐξαγομένων ἐπελάβετο, καὶ ὅτι τοῦ εἰς Σικελίαν πλοῦ διὰ τοῦτον κατεκωλύθη. ἐνεστηκυίας δὲ τῆς δίκης δίδωσιν ὁ Παρμένων ὅρκον τούτῳ περί τινων ἐγκλημάτων, καὶ οὗτος ἐδέξατο, ἐπιδιαθέμενος ἀργύριον, ἐὰν μὴ ὀμόσῃ τὸν ὅρκον. καὶ ὅτι ἀληθῆ λέγω, λαβέ μοι τὴν μαρτυρίαν.", "st": "33.13"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "33.13"}, {"sp": "N", "t": "δεξάμενος τοίνυν τὸν ὅρκον, εἰδὼς ὅτι πολλοὶ αὑτῷ συνείσονται ἐπιορκήσαντι, ἐπὶ μὲν τὸ ὀμόσαι οὐκ ἀπήντα, ὡς δὲ δίκῃ λύσων τὸν ὅρκον προσκαλεῖται τὸν Παρμένοντα. ἐνεστηκυιῶν δ’ αὐτοῖς τῶν δικῶν πεισθέντες ὑπὸ τῶν παρόντων εἰς ἐπιτροπὴν ἔρχονται, καὶ γράψαντες συνθήκας ἐπιτρέπουσιν ἑνὶ μὲν διαιτητῇ κοινῷ Φωκρίτῳ πολίτῃ αὑτῶν, ἕνα δ’ ἑκάτερος παρεκαθίσατο, οὗτος μὲν Ἀριστοκλέα Ὀῆθεν, ὁ δὲ Παρμένων ἐμέ.", "st": "33.14"}, {"sp": "N", "t": "καὶ συνέθεντο ἐν ταῖς συνθήκαις, εἰ μὲν τρεῖς ὄντες ὁμογνώμονες γενοίμεθα, ταῦτα κύρια εἶναι αὑτοῖς, εἰ δὲ μή, οἷς οἱ δύο γνοίησαν, τούτοις ἐπάναγκες εἶναι ἐμμένειν. συνθέμενοι δὲ ταῦτα, ἐγγυητὰς τούτων ἀλλήλοις κατέστησαν, οὗτος μὲν ἐκείνῳ τὸν Ἀριστοκλέα, ὁ δὲ Παρμένων τούτῳ Ἄρχιππον Μυρρινούσιον. καὶ τὸ μὲν πρῶτον ἐτίθεντο τὰς συνθήκας παρὰ τῷ Φωκρίτῳ, εἶτα κελεύσαντος τοῦ Φωκρίτου παρ’ ἄλλῳ τινὶ θέσθαι, τίθενται παρὰ τῷ Ἀριστοκλεῖ. καὶ ὡς ἀληθῆ λέγω, ἀκούσατε τῶν μαρτυριῶν.", "st": "33.15"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "33.15"}, {"sp": "N", "t": "ὅτι μὲν ἐτέθησαν αἱ συνθῆκαι παρὰ Ἀριστοκλεῖ καὶ ἡ ἐπιτροπὴ ἐγένετο Φωκρίτῳ καὶ Ἀριστοκλεῖ καὶ ἐμοί, οἱ εἰδότες ταῦτα μεμαρτυρήκασιν ὑμῖν. δέομαι δέ, ὦ ἄνδρες δικασταί, τὰ μετὰ ταῦτα πραχθέντα ἀκοῦσαί μου· ἐντεῦθεν γὰρ ἔσται φανερὸν ὑμῖν, ὅτι συκοφαντοῦμαι ὑπὸ τουτουὶ Ἀπατουρίου. ἐπειδὴ γὰρ ᾔσθετο ὁμογνώμονας ὄντας ἐμὲ καὶ τὸν Φώκριτον καὶ ἔγνω καταδιαιτήσοντας ἡμᾶς ἑαυτοῦ, λῦσαι βουλόμενος τὴν ἐπιτροπήν, διαφθεῖραι τὰς συνθήκας ἐπεχείρησε μετὰ τοῦ ἔχοντος αὐτάς.", "st": "33.16"}, {"sp": "N", "t": "καὶ ἦλθεν ἐπὶ τὸ ἀμφισβητεῖν ὡς αὑτῷ διαιτητὴς εἴη ὁ Ἀριστοκλῆς, τὸν δὲ Φώκριτον καὶ ἐμὲ οὐδενὸς κυρίους ἔφησεν εἶναι ἀλλ’ ἢ τοῦ διαλῦσαι. ἀγανακτήσας δὴ τῷ λόγῳ ὁ Παρμένων ἠξίου τὸν Ἀριστοκλέα ἐκφέρειν τὰς συνθήκας, οὐ πόρρω φάσκων εἶναι τὸν ἔλεγχον, εἴ τι κακουργοῖτο περὶ τὰ γράμματα· γεγραφέναι γὰρ αὐτὰ οἰκέτην ἑαυτοῦ.", "st": "33.17"}, {"sp": "N", "t": "ὁμολογήσας δὲ ἐξοίσειν τὰς συνθήκας ὁ Ἀριστοκλῆς ἐμφανεῖς μὲν οὔπω καὶ τήμερον ἐνήνοχεν, εἰς δὲ τὴν ἡμέραν τὴν συγκειμένην ἀπαντήσας εἰς τὸ Ἡφαιστεῖον, προὐφασίζετο ὡς ὁ παῖς περιμένων αὑτὸν ἀπολωλεκὼς εἴη τὸ γραμματεῖον καθεύδων. ὁ δὲ ταῦτα κατασκευάζων ἦν Ἐρυξίας ὁ ἰατρὸς ὁ ἐκ Πειραιῶς, οἰκείως ἔχων τῷ Ἀριστοκλεῖ· ὅσπερ καὶ ἐμοὶ τοῦ ἀγῶνος αἴτιός ἐστιν, διαφόρως ἔχων. καὶ ὡς ἐσκήψατο ἀπολωλέναι ὁ Ἀριστοκλῆς, ἀκούσατε τῶν μαρτυριῶν.", "st": "33.18"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "33.18"}, {"sp": "N", "t": "ἐντεῦθεν τοίνυν τὸ μὲν τῆς ἐπιτροπῆς ἐλέλυτο, ἠφανισμένων τῶν συνθηκῶν καὶ τῶν διαιτητῶν ἀντιλεγομένων· ἐπιχειροῦντες δὲ γράφειν ἑτέρας συνθήκας περὶ τούτων διηνέχθησαν, οὗτος μὲν ἀξιῶν τὸν Ἀριστοκλέα, ὁ δὲ Παρμένων τοὺς τρεῖς, οἷσπερ καὶ ἐξ ἀρχῆς ἡ ἐπιτροπὴ ἐγένετο. οὐ γραφεισῶν δ’ ἑτέρων συνθηκῶν, τῶν δὲ ἐξ ἀρχῆς ἀφανισθεισῶν, εἰς τοῦτ’ ἦλθεν ἀναιδείας ὁ ἠφανικὼς τὰς συνθήκας, ὥστε εἷς ὢν ἀποφανεῖσθαι ἔφη τὴν δίαιταν. παρακαλέσας δὲ ὁ Παρμένων μάρτυρας ἀπεῖπεν τῷ Ἀριστοκλεῖ μὴ ἀποφαίνεσθαι παρὰ τὰς συνθήκας καθ’ αὑτοῦ ἄνευ τῶν συνδιαιτητῶν. καὶ ὧν ἐναντίον ἀπεῖπεν, ἀκούσατε τῆς μαρτυρίας.", "st": "33.19"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "33.19"}, {"sp": "N", "t": "μετὰ ταῦτα τοίνυν τῷ Παρμένοντι συνέβη συμφορὰ δεινή, ὦ ἄνδρες δικασταί. οἰκοῦντος γὰρ αὐτοῦ ἐν Ὀφρυνείῳ διὰ τὴν οἴκοθεν φυγήν, ὅτε ὁ σεισμὸς ἐγένετο ὁ περὶ Χερρόνησον, συμπεσούσης αὐτῷ τῆς οἰκίας ἀπώλοντο ἡ γυνὴ καὶ οἱ παῖδες. καὶ ὁ μὲν πυθόμενος τὴν συμφορὰν ᾤχετο ἐνθένδε ἀποπλέων· ὁ δὲ Ἀριστοκλῆς, διαμαρτυραμένου τοῦ ἀνθρώπου ἐναντίον μαρτύρων μὴ ἀποφαίνεσθαι καθ’ αὑτοῦ ἄνευ τῶν συνδιαιτητῶν, ἀποδημήσαντος τοῦ ἀνθρώπου διὰ τὴν συμφορὰν ἐρήμην κατ’ αὐτοῦ ἀπεφήνατο τὴν δίαιταν.", "st": "33.20"}, {"sp": "N", "t": "καὶ ἐγὼ μὲν καὶ ὁ Φώκριτος ἐν ταῖς αὐταῖς συνθήκαις γεγραμμένοι, ὅτι ἠμφεσβήτησεν οὗτος μὴ εἶναι ἡμᾶς διαιτητὰς αὑτῷ, ἐφύγομεν τὸ διαιτῆσαι· ὁ δὲ οὐ μόνον ἀμφισβητηθείς, ἀλλὰ καὶ ἀπορρηθὲν αὐτῷ, οὐδὲν ἧττον τὴν ἀπόφασιν ἐποιήσατο. ὃ οὔτε ὑμῶν οὔτε τῶν ἄλλων Ἀθηναίων ὑπομείναι ἂν ποιῆσαι οὐδείς.", "st": "33.21"}, {"sp": "N", "t": "ἃ μὲν οὖν περὶ τὴν ἀφάνισιν τῶν συνθηκῶν καὶ περὶ τὴν γνῶσιν τῆς διαίτης Ἀπατουρίῳ καὶ τῷ διαιτητῇ πέπρακται, ἐάν ποτε σωθῇ ὁ ἠδικημένος, δίκην παρ’ αὐτῶν λήψεται· ἐπειδὴ δ’ εἰς τοῦτο ἐλήλυθεν Ἀπατούριος ἀναιδείας, ὥστε κἀμοὶ δικάζεται, ἐπιφέρων αἰτίαν ὡς ἀνεδεξάμην ἐκτείσειν, εἴ τι καταγνωσθείη τοῦ Παρμένοντος, καί φησιν ἐγγραφῆναι εἰς τὰς συνθήκας ἐμὲ ἐγγυητήν, ὥσπερ προσήκει τοιαύτην αἰτίαν ἀπολύσασθαι, πρῶτον μὲν ὑμῖν μάρτυρας παρασχήσομαι ὡς οὐκ ἠγγυησάμην ἐγὼ τὸν Παρμένοντα, ἀλλ’ Ἄρχιππος Μυρρινούσιος, ἔπειτα πειράσομαι καὶ ἐκ τεκμηρίων τὴν ἀπολογίαν ποιήσασθαι, ὦ ἄνδρες δικασταί.", "st": "33.22"}, {"sp": "N", "t": "πρῶτον μὲν οὖν τὸν χρόνον ἐμαυτῷ ἡγοῦμαι μάρτυρα εἶναι τοῦ μὴ ἀληθὲς τὸ ἔγκλημα εἶναι. ἡ μὲν γὰρ ἐπιτροπὴ τούτῳ πρὸς τὸν Παρμένοντα τρίτον ἔτος γέγονεν καὶ ἡ γνῶσις τοῦ Ἀριστοκλέους· αἱ δὲ λήξεις τοῖς ἐμπόροις τῶν δικῶν ἔμμηνοί εἰσιν ἀπὸ τοῦ βοηδρομιῶνος μέχρι τοῦ μουνιχιῶνος, ἵνα παραχρῆμα τῶν δικαίων τυχόντες ἀνάγωνται. εἰ δὴ τῇ ἀληθείᾳ ἐγγυητὴς ἦν τοῦ Παρμένοντος, διὰ τί πρῶτον μὲν οὐκ εὐθὺς τῆς γνώσεως γενομένης ἐπράττετο τὴν ἐγγύην;", "st": "33.23"}, {"sp": "N", "t": "οὐ γὰρ δὴ τοῦτό γ’ αὐτῷ ἔνι εἰπεῖν, ὡς διὰ τὴν πρὸς ἐμὲ φιλίαν ὤκνει μοι ἀπεχθέσθαι. αὐτὸς γὰρ εἰσεπέπρακτο ὑπ’ ἐμοῦ πρὸς ἔχθραν τὰς χιλίας δραχμὰς τὰς τοῦ Παρμένοντος, καὶ ὅτ’ ἐξώρμιζε τὴν ναῦν ἐπιβουλεύων ἀποδρᾶναι καὶ ἀποστερῆσαι τὸ ἐπὶ τὴν τράπεζαν χρέως, ἐκωλύθη ὑπ’ ἐμοῦ. ὥστε εἰ ἦν ἠγγυημένος ἐγὼ τὸν Παρμένοντα, οὐκ ἂν τρίτῳ ἔτει ὕστερον, ἀλλ’ εὐθὺς τότε εἰσέπραττεν ἄν με τὴν ἐγγύην.", "st": "33.24"}, {"sp": "N", "t": "ἀλλὰ νὴ Δία εὐπόρως διέκειτο, ὥστ’ ἐνεδέχετο αὐτῷ καὶ ὕστερον ἐπ’ ἐμὲ ἐλθεῖν, τότε δ’ ἀσχόλως εἶχεν περὶ ἀναγωγὴν ὤν. ἀλλὰ δι’ ἀπορίαν ἐξειστήκει τῶν ἑαυτοῦ καὶ τὴν ναῦν ἐπεπράκει. εἰ δ’ ἄρα ἐμποδών τι αὐτῷ ἐγένετο τοῦ μὴ εὐθὺς τότε δικάσασθαι, διὰ τί πέρυσιν ἐπιδημῶν, μὴ ὅτι δικάσασθαι, ἀλλ’ οὐδ’ ἐγκαλέσαι μοι ἐτόλμησεν; καίτοι προσῆκεν, εἰ ὁ μὲν Παρμένων ὠφλήκει αὐτῷ τὴν δίκην, ἐγὼ δὲ ἐγγυητὴς ἦν, προσελθεῖν αὐτόν μοι ἔχοντα μάρτυρας καὶ ἀπαιτῆσαι τὴν ἐγγύην, εἰ μὴ προπέρυσιν, ἐν τῷ ἐξελθόντι ἐνιαυτῷ· καὶ εἰ μὲν αὐτῷ ἀπεδίδουν, κομίσασθαι, εἰ δὲ μή, δικάζεσθαι.", "st": "33.25"}, {"sp": "N", "t": "τῶν γὰρ τοιούτων ἐγκλημάτων πρότερον τὰς ἀπαιτήσεις ποιοῦνται ἅπαντες ἢ δικάζονται. οὐκ ἔστιν τοίνυν ὅστις μαρτυρήσει παραγενέσθαι, ὅπου οὗτος ἢ πέρυσιν ἢ προπέρυσιν ἐδικάσατό μοι ἢ λόγον ὁντινοῦν ἐποιήσατο πρὸς ἐμὲ περὶ ὧν νυνί μοι δικάζεται. ὅτι δ’ ἐπεδήμει πέρυσιν, ὅτε αἱ δίκαι ἦσαν, λαβέ μοι τὴν μαρτυρίαν.", "st": "33.26"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "33.26"}, {"sp": "N", "t": "λαβὲ δή μοι καὶ τὸν νόμον, ὃς κελεύει τὰς ἐγγύας ἐπετείους εἶναι. καὶ οὐκ ἰσχυρίζομαι τῷ νόμῳ, ὡς οὐ δεῖ με δίκην δοῦναι εἰ ἠγγυησάμην, ἀλλὰ μάρτυρά μοί φημι τὸν νόμον εἶναι τοῦ μὴ ἐγγυήσασθαι καὶ αὐτὸν τοῦτον· ἐδεδίκαστο γὰρ ἄν μοι τῆς ἐγγύης ἐν τῷ χρόνῳ τῷ ἐν τῷ νόμῳ γεγραμμένῳ.", "st": "33.27"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "33.27"}, {"sp": "N", "t": "γενέσθω τοίνυν καὶ τοῦτο ὑμῖν τεκμήριον τοῦ ψεύδεσθαι Ἀπατούριον· εἰ γὰρ ἠγγυησάμην ἐγὼ τούτῳ τὸν Παρμένοντα, οὐκ ἔστιν ὅπως τούτῳ μὲν ὑπὲρ ἐκείνου ἀπηχθόμην, πρόνοιαν ποιούμενος ὅπως μὴ ἀπολεῖ ἃ δι’ ἐμοῦ τούτῳ συνέβαλεν, αὐτὸς δ’ ἐμαυτὸν περιεῖδον ἂν ὑπ’ ἐκείνου πρὸς τοῦτον ἐν ἐγγύῃ καταλειπόμενον. τίνα γὰρ ἐλπίδα ἔσχον τοῦτον ἀποσχήσεσθαί μου, ὃν αὐτὸς ἠναγκάκειν ἐκείνῳ τὰ δίκαια ποιῆσαι; καὶ τὴν ἐγγύην αὐτὸν εἰσπράξας τὴν πρὸς τὴν τράπεζαν πρὸς ἀπέχθειαν, τί προσεδόκων ὑπὸ τούτου αὐτὸς πείσεσθαι;", "st": "33.28"}, {"sp": "N", "t": "ἄξιον τοίνυν καὶ τοῦτ’ ἐνθυμηθῆναι, ὦ ἄνδρες δικασταί, ὅτι οὐκ ἄν ποτε ἔξαρνος ἐγενόμην, εἰ ἠγγυήμην· πολὺ γὰρ ὁ λόγος ἦν μοι ἰσχυρότερος ὁμολογοῦντι τὴν ἐγγύην ἐπὶ τὰς συνθήκας ἰέναι, καθ’ ἃς ἡ ἐπιτροπὴ ἐγένετο. ὅτι μὲν γὰρ τρισὶν ἐπετράπη διαιτηταῖς, μεμαρτύρηται ὑμῖν· ὁπότε δὲ μὴ ἔγνωσται ὑπὸ τῶν τριῶν, τί βουλόμενος ἠρνούμην ἂν τὴν ἐγγύην; μὴ γὰρ γενομένης τῆς γνώσεως κατὰ τὰς συνθήκας, οὐδ’ ἂν ἐγὼ τῆς ἐγγύης ὑπόδικος ἦν. ὥστε οὐκ ἄν ποτε, ὦ ἄνδρες δικασταί, παραλιπὼν τὴν οὖσάν μοι ἀπολογίαν, εἰ ἠγγυησάμην, ἐπὶ τὸ ἀρνεῖσθαι ἦλθον.", "st": "33.29"}, {"sp": "N", "t": "ἀλλὰ μὴν καὶ τοῦτο μεμαρτύρηται ὑμῖν, ὅτι ἐπειδὴ ἠφανίσθησαν αἱ συνθῆκαι ὑπὸ τούτων, ἐζήτουν ἑτέρας γράφεσθαι οὗτος καὶ ὁ Παρμένων, ὡς ἀκύρων ὄντων αὐτοῖς τῶν πρότερον ὡμολογημένων. καίτοι ὁπότε περὶ τῆς μελλούσης γνώσεως γενήσεσθαι ἑτέρας ἐνεχείρουν συνθήκας γράφεσθαι, ἐπειδὴ αἱ ὑπάρχουσαι ἀπώλοντο, πῶς ἐνῆν μὴ γραφεισῶν συνθηκῶν ἑτέρων ἢ δίαιταν γενέσθαι ἢ ἐγγύην; περὶ αὐτοῦ γὰρ τούτου διενεχθέντες οὐκ ἔγραψαν ἕτερα γράμματα, ὁ μὲν ἀξιῶν ἕνα διαιτητὴν αὑτῷ εἶναι, ὁ δὲ τρεῖς. ὁπότε δὲ αἱ μὲν ἐξ ἀρχῆς συνθῆκαι ἠφανίσθησαν, καθ’ ἃς ἐμέ φησιν γενέσθαι ἐγγυητήν, ἕτεραι δὲ μὴ ἐγράφησαν, πῶς ὀρθῶς ἂν ἐμοὶ δικάζοιτο, καθ’ οὗ μὴ ἔχει παρασχέσθαι συνθήκας;", "st": "33.30"}, {"sp": "N", "t": "ἀλλὰ μὴν καὶ ὡς ἀπηγόρευεν ὁ Παρμένων τῷ Ἀριστοκλεῖ καθ’ αὑτοῦ μὴ γιγνώσκειν ἄνευ τῶν συνδιαιτητῶν, μεμαρτύρηται ὑμῖν. ὅταν δὴ ὁ αὐτὸς ἠφανικὼς φαίνηται τὰ γράμματα καθ’ ἃ ἔδει τὴν δίαιταν γενέσθαι, καὶ ἄνευ τῶν συνδιαιτητῶν παρὰ τὴν ἀπόρρησιν φῇ δεδιῃτηκέναι, πῶς ἂν τούτῳ τῷ ἀνθρώπῳ πιστεύσαντες δικαίως ἐμὲ ἀπολέσαιτε;", "st": "33.31"}, {"sp": "N", "t": "σκέψασθε γὰρ τοῦτο, ὦ ἄνδρες δικασταί· εἰ μὴ ἐμὲ νυνί, ἀλλὰ τὸν Παρμένοντα ἐδίωκεν Ἀπατούριος οὑτοσί, εἰσπράττων τὰς εἴκοσι μνᾶς, ἰσχυριζόμενος τῇ Ἀριστοκλέους γνώσει, ὁ δὲ Παρμένων παρὼν ἀπελογεῖτο ὑμῖν καὶ μάρτυρας παρείχετο, τοῦτο μὲν ὅτι οὐ μόνῳ τῷ Ἀριστοκλεῖ, ἀλλὰ τρίτῳ ἐπέτρεψεν,", "st": "33.32"}, {"sp": "N", "t": "εἶθ’ ὅτι ἀπεῖπεν αὐτῷ ἄνευ τῶν συνδιαιτητῶν καθ’ αὑτοῦ μὴ ἀποφαίνεσθαι, καὶ ὅτι ἀπολομένης αὑτῷ τῆς γυναικὸς καὶ τῶν παίδων ὑπὸ τοῦ σεισμοῦ καὶ ἐπὶ τηλικαύτην συμφορὰν ἀπάραντος οἴκαδε, ὁ τὰς συνθήκας ἠφανικὼς ἐρήμην αὑτοῦ ἐν τῇ ἀποδημίᾳ κατέγνω τὴν δίαιταν, ἔστιν ὅστις ἂν ὑμῶν ταῦτα τοῦ Παρμένοντος ἀπολογουμένου τὴν οὕτω παρανόμως γνωσθεῖσαν δίαιταν κυρίαν ἔγνω εἶναι;", "st": "33.33"}, {"sp": "N", "t": "μὴ γὰρ ὅτι ἀμφισβητουμένων ἁπάντων, ἀλλ’ εἰ ἦσαν μὲν αἱ συνθῆκαι, ὡμολογεῖτο δὲ εἷς εἶναι ὁ διαιτητὴς Ἀριστοκλῆς, μὴ ἀπεῖπεν δὲ ὁ Παρμένων αὐτῷ καθ’ αὑτοῦ μὴ διαιτᾶν, ἀλλὰ συνέβη πρὶν τὴν ἀπόφασιν γενέσθαι τῆς διαίτης ἡ συμφορὰ τῷ ἀνθρώπῳ, τίς οὕτως ὠμός ἐστιν ἀντίδικος ἢ διαιτητὴς ὃς οὐκ ἂν ἀνεβάλετο εἰς τὸ ἐπιδημῆσαι τὸν ἄνθρωπον; εἰ δὲ ὁ Παρμένων εἰς λόγον καταστὰς πανταχοῦ δικαιότερ’ ἂν φαίνοιτο λέγων τούτου, πῶς ἂν ὀρθῶς ἐμοῦ καταγιγνώσκοιτε, ᾧ τὸ παράπαν πρὸς τὸν ἄνθρωπον τουτονὶ μηδὲν συμβόλαιόν ἐστιν;", "st": "33.34"}, {"sp": "N", "t": "ὅτι μὲν οὖν ἐγὼ μὲν ὀρθῶς τὴν παραγραφὴν πεποίημαι, Ἀπατούριος δὲ τὰ ψευδῆ ἐγκέκληκε καὶ παρὰ τοὺς νόμους τὴν λῆξιν πεποίηται, ἐκ πολλῶν οἶμαι ἐπιδεδεῖχθαι τοῦτο ὑμῖν, ὦ ἄνδρες δικασταί· τὸ δὲ κεφάλαιον, πρὸς ἐμὲ οὐδ’ ἐπιχειρήσει λέγειν Ἀπατούριος ὡς συνθῆκαί τινες αὐτῷ εἰσίν. ὅταν δὲ λέγῃ ψευδόμενος, ὡς ἐν ταῖς πρὸς τὸν Παρμένοντα συνθήκαις ἐνεγράφην ἐγγυητής, ἀπαιτεῖτε αὐτὸν τὰς συνθήκας,", "st": "33.35"}, {"sp": "N", "t": "καὶ ἐνταῦθα αὐτῷ ἀπαντᾶτε, ὅτι πάντες ἄνθρωποι, ὅταν πρὸς ἀλλήλους ποιῶνται συγγραφάς, τούτου ἕνεκα σημηνάμενοι τίθενται παρ’ οἷς ἂν πιστεύσωσιν, ἵνα, ἐάν τι ἀντιλέγωσιν, ᾖ αὐτοῖς ἐπανελθοῦσιν ἐπὶ τὰ γράμματα, ἐντεῦθεν τὸν ἔλεγχον ποιήσασθαι περὶ τοῦ ἀμφισβητουμένου. ὅταν δ’ ἀφανίσας τις τἀκριβὲς λόγῳ ἐξαπατᾶν πειρᾶται, πῶς ἂν δικαίως πιστεύοιτε;", "st": "33.36"}, {"sp": "N", "t": "ἀλλὰ νὴ Δία (τὸ ῥᾷστον τοῖς ἀδικεῖν καὶ συκοφαντεῖν προῃρημένοις) μαρτυρήσει τις αὐτῷ κατ’ ἐμοῦ. ἐὰν οὖν ἐπισκήψωμαι αὐτῷ, πόθεν τὴν ἀπόδειξιν ποιήσεται τοῦ ἀληθῆ μαρτυρεῖν; ἐκ τῶν συνθηκῶν; τοῦτο τοίνυν μὴ ἀναβαλλέσθω, ἀλλ’ ἤδη φερέτω ὁ ἔχων τὰς συνθήκας. εἰ δ’ ἀπολωλέναι φησίν, πόθεν λάβω ἐγὼ τὸν ἔλεγχον καταψευδομαρτυρηθείς; εἰ μὲν γὰρ παρ’ ἐμοὶ ἐτέθη τὸ γραμματεῖον, ἐνῆν αἰτιάσασθαι Ἀπατουρίῳ, ὡς ἐγὼ διὰ τὴν ἐγγύην ἠφάνικα τὰς συνθήκας·", "st": "33.37"}, {"sp": "N", "t": "εἰ δὲ παρὰ τῷ Ἀριστοκλεῖ, διὰ τί, εἴπερ ἄνευ τῆς τούτου γνώμης ἀπολώλασιν αἱ συνθῆκαι, τῷ μὲν λαβόντι αὐτὰς καὶ οὐ παρέχοντι οὐ δικάζεται, ἐμοὶ δ’ ἐγκαλεῖ, μάρτυρα παρεχόμενος κατ’ ἐμοῦ τὸν ἠφανικότα τὰς συνθήκας, ᾧ προσῆκεν αὐτὸν ὀργίζεσθαι, εἴπερ μὴ κοινῇ μετὰ τούτου ἐκακοτέχνει;", "st": "33.38"}, {"sp": "N", "t": "εἴρηταί μοι τὰ δίκαια, ὅσα ἐδυνάμην. ὑμεῖς οὖν κατὰ τοὺς νόμους γιγνώσκετε τὰ δίκαια.", "st": "33.38"}, {"sp": "HDR", "t": "Πρὸς Φορμίωνα ὑπὲρ δανείου", "st": "34"}, {"sp": "N", "t": "δίκαια ὑμῶν δεησόμεθα, ὦ ἄνδρες δικασταί, ἀκοῦσαι ἡμῶν μετ’ εὐνοίας ἐν τῷ μέρει λεγόντων, γνόντας ὅτι ἰδιῶται παντελῶς ἐσμέν, καὶ πολὺν χρόνον εἰς τὸ ὑμέτερον ἐμπόριον εἰσαφικνούμενοι καὶ συμβόλαια πολλοῖς συμβάλλοντες οὐδεμίαν πώποτε δίκην πρὸς ὑμᾶς εἰσήλθομεν, οὔτ’ ἐγκαλοῦντες οὔτ’ ἐγκαλούμενοι ὑφ’ ἑτέρων.", "st": "34.1"}, {"sp": "N", "t": "οὐδ’ ἂν νῦν, ἀκριβῶς ἴστε, ὦ ἄνδρες Ἀθηναῖοι, εἰ ὑπελαμβάνομεν ἀπολωλέναι τὰ χρήματα ἐπὶ τῆς νεὼς τῆς διαφθαρείσης, ἃ ἐδανείσαμεν Φορμίωνι, οὐκ ἄν ποτ’ ἐλάχομεν τὴν δίκην αὐτῷ· οὐχ οὕτως ἡμεῖς ἀναίσχυντοί ἐσμεν οὐδ’ ἄπειροι τοῦ ζημιοῦσθαι. πολλῶν δ’ ἡμᾶς κακιζόντων, καὶ μάλιστα τῶν ἐν Βοσπόρῳ ἐπιδημησάντων ἅμα Φορμίωνι, οἵπερ τοῦτον ᾔδεσαν οὐ συναπολέσαντα τὰ χρήματα ἐν τῇ νηί, δεινὸν ἡγούμεθα εἶναι τὸ μὴ βοηθῆσαι ἡμῖν αὐτοῖς ἀδικουμένοις ὑπὸ τούτου.", "st": "34.2"}, {"sp": "N", "t": "περὶ μὲν οὖν τῆς παραγραφῆς βραχύς ἐστιν ὁ λόγος· καὶ γὰρ οὗτοι οὐ τὸ παράπαν συμβόλαιον ἐξαρνοῦνται μὴ γενέσθαι ἐν τῷ ἐμπορίῳ τῷ ὑμετέρῳ, ἀλλ’ οὐκέτι εἶναί φασι πρὸς αὑτοὺς οὐδὲν συμβόλαιον· πεποιηκέναι γὰρ οὐδὲν ἔξω τῶν ἐν τῇ συγγραφῇ γεγραμμένων.", "st": "34.3"}, {"sp": "N", "t": "οἱ μὲν οὖν νόμοι, καθ’ οὓς ὑμεῖς δικασταὶ κάθησθε, οὐχ οὕτως λέγουσιν, ἀλλ’ ὑπὲρ μὲν τῶν μὴ γενομένων ὅλως συμβολαίων Ἀθήνησι μηδ’ εἰς τὸ Ἀθηναίων ἐμπόριον παραγράφεσθαι δεδώκασιν, ἐὰν δέ τις γενέσθαι μὲν ὁμολογῇ, ἀμφισβητῇ δὲ ὡς πάντα πεποίηκεν τὰ συγκείμενα, ἀπολογεῖσθαι κελεύουσιν εὐθυδικίαν εἰσιόντα, οὐ κατηγορεῖν τοῦ διώκοντος. οὐ μὴν ἀλλ’ ἔγωγε ἐλπίζω καὶ ἐξ αὐτοῦ τοῦ πράγματος δείξειν εἰσαγώγιμον τὴν δίκην οὖσαν.", "st": "34.4"}, {"sp": "N", "t": "σκέψασθε δέ, ὦ ἄνδρες Ἀθηναῖοι, ὅ τι ὁμολογεῖται παρ’ αὐτῶν τούτων καὶ τί ἀντιλέγεται· οὕτω γὰρ ἂν ἄριστα ἐξετάσαιτε. οὐκοῦν δανείσασθαι μὲν τὰ χρήματα ὁμολογοῦσι καὶ συνθήκας ποιήσασθαι τοῦ δανείσματος, φασὶν δ’ ἀποδεδωκέναι τὸ χρυσίον Λάμπιδι τῷ Δίωνος οἰκέτῃ ἐν Βοσπόρῳ. ἡμεῖς τοίνυν οὐ μόνον τοῦτο δείξομεν, ὡς οὐκ ἀπέδωκεν, ἀλλ’ ὡς οὐδ’ ἐνῆν αὐτῷ ἀποδοῦναι. ἀναγκαῖον δ’ ἐστὶν βραχέα τῶν ἐξ ἀρχῆς διηγήσασθαι ὑμῖν.", "st": "34.5"}, {"sp": "N", "t": "ἐγὼ γάρ, ὦ ἄνδρες Ἀθηναῖοι, ἐδάνεισα Φορμίωνι τουτῳὶ εἴκοσι μνᾶς ἀμφοτερόπλουν εἰς τὸν Πόντον ἐπὶ ἑτέρᾳ ὑποθήκῃ, καὶ συγγραφὴν ἐθέμην παρὰ Κίττῳ τῷ τραπεζίτῃ. κελευούσης δὲ τῆς συγγραφῆς ἐνθέσθαι εἰς τὴν ναῦν τετρακισχιλίων φορτία ἄξια, πρᾶγμα ποιεῖ πάντων δεινότατον· εὐθὺς γὰρ ἐν τῷ Πειραιεῖ ἐπιδανείζεται λάθρᾳ ἡμῶν παρὰ μὲν Θεοδώρου τοῦ Φοίνικος τετρακισχιλίας πεντακοσίας δραχμάς, παρὰ δὲ τοῦ ναυκλήρου Λάμπιδος χιλίας δραχμάς.", "st": "34.6"}, {"sp": "N", "t": "δέον δ’ αὐτὸν καταγοράσαι φορτία Ἀθήνηθεν μνῶν ἑκατὸν δέκα πέντε, εἰ ἔμελλεν τοῖς δανεισταῖς πᾶσι ποιήσειν τὰ ἐν ταῖς συγγραφαῖς γεγραμμένα, οὐ κατηγόρασεν ἀλλ’ ἢ πεντακισχιλίων καὶ πεντακοσίων δραχμῶν, σὺν τῷ ἐπισιτισμῷ· ὀφείλει δὲ ἑβδομήκοντα μνᾶς καὶ πέντε. ἀρχὴ μὲν οὖν αὕτη ἐγένετο τοῦ ἀδικήματος, ὦ ἄνδρες Ἀθηναῖοι· οὔτε γὰρ τὴν ὑποθήκην παρέσχεν οὔτε τὰ χρήματ’ ἐνέθετ’ εἰς τὴν ναῦν, κελευούσης τῆς συγγραφῆς ἐπάναγκες ἐντίθεσθαι. καί μοι λαβὲ τὴν συγγραφήν.", "st": "34.7"}, {"sp": "N", "t": "ΣΥΓΓΡΑΦΗ.", "st": "34.7"}, {"sp": "N", "t": "λαβὲ δὴ καὶ τὴν τῶν πεντηκοστολόγων ἀπογραφὴν καὶ τὰς μαρτυρίας.", "st": "34.7"}, {"sp": "N", "t": "ΑΠΟΓΡΑΦΗ. ΜΑΡΤΥΡΙΑΙ.", "st": "34.7"}, {"sp": "N", "t": "ἐλθὼν τοίνυν εἰς τὸν Βόσπορον, ἔχων ἐπιστολὰς παρ’ ἐμοῦ, ἃς ἔδωκ’ αὐτῷ ἀπενεγκεῖν τῷ παιδὶ τῷ ἐμῷ παραχειμάζοντι ἐκεῖ καὶ κοινωνῷ τινί, γράψας ἐν τῇ ἐπιστολῇ τό τε ἀργύριον ὃ ἐδεδανείκειν καὶ τὴν ὑποθήκην, καὶ προστάξας, ἐπειδὰν τάχιστα ἐξαιρεθῇ τὰ χρήματα, ἐξετάζειν καὶ παρακολουθεῖν, τὰς μὲν ἐπιστολὰς οὐκ ἀποδίδωσιν οὗτος ἃς ἔλαβεν παρ’ ἐμοῦ, ἵνα μηδὲν εἰδείησαν ὧν ἔπραττεν οὗτος, καταλαβὼν δ’ ἐν τῷ Βοσπόρῳ μοχθηρὰ τὰ πράγματα διὰ τὸν συμβάντα πόλεμον τῷ Παιρισάδῃ πρὸς τὸν Σκύθην καὶ τῶν φορτίων ὧν ἦγεν πολλὴν ἀπρασίαν, ἐν πάσῃ ἀπορίᾳ ἦν· καὶ γὰρ οἱ δανεισταὶ εἴχοντο αὐτοῦ οἱ τὰ ἑτερόπλοα δανείσαντες.", "st": "34.8"}, {"sp": "N", "t": "ὥστε τοῦ ναυκλήρου κελεύοντος αὐτὸν κατὰ τὴν συγγραφὴν ἐντίθεσθαι τὰ ἀγοράσματα τῶν ἐμῶν χρημάτων, εἶπεν οὗτος ὁ νῦν φάσκων ἀποδεδωκέναι τὸ χρυσίον, ὅτι οὐκ ἂν δύναιτο ἐνθέσθαι εἰς τὴν ναῦν τὰ χρήματα· ἄπρατον γὰρ εἶναι τὸν ῥῶπον. καὶ ἐκεῖνον μὲν ἐκέλευεν ἀνάγεσθαι, αὐτὸς δ’, ἐπειδὰν διαθῆται τὰ φορτία, ἐφ’ ἑτέρας νεὼς ἔφη ἐκπλεύσεσθαι. καί μοι λέγε ταύτην τὴν μαρτυρίαν.", "st": "34.9"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "34.9"}, {"sp": "N", "t": "μετὰ ταῦτα τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, οὗτος μὲν ἐν τῷ Βοσπόρῳ κατελέλειπτο, ὁ δὲ Λάμπις ἀναχθεὶς ἐναυάγησεν οὐ μακρὰν ἀπὸ τοῦ ἐμπορίου· γεγεμισμένης γὰρ ἤδη τῆς νεώς, ὡς ἀκούομεν, μᾶλλον τοῦ δέοντος, προσανέλαβεν ἐπὶ τὸ κατάστρωμα χιλίας βύρσας, ὅθεν καὶ ἡ διαφθορὰ τῇ νηὶ συνέβη. καὶ αὐτὸς μὲν ἀπεσώθη ἐν τῷ λέμβῳ μετὰ τῶν ἄλλων παίδων τῶν Δίωνος, ἀπώλεσεν δὲ πλέον ἢ τριάκοντα σώματα ἐλεύθερα χωρὶς τῶν ἄλλων. πολλοῦ δὲ πένθους ἐν τῷ Βοσπόρῳ ὄντος ὡς ἐπύθοντο τὴν διαφθορὰν τῆς νεώς, ηὐδαιμόνιζον Φορμίωνα πάντες τουτονί, ὅτι οὔτε συνανήχθη οὔτε ἐνέθετο εἰς τὴν ναῦν οὐδέν. συνέβαινεν δὲ παρά τε τῶν ἄλλων καὶ παρὰ τούτου ὁ αὐτὸς λόγος. καί μοι ἀνάγνωθι ταύτας τὰς μαρτυρίας.", "st": "34.10"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "34.10"}, {"sp": "N", "t": "αὐτὸς μὲν τοίνυν ὁ Λάμπις, ᾧ φησιν ἀποδεδωκέναι τὸ χρυσίον (τούτῳ γὰρ προσέχετε τὸν νοῦν), προσελθόντος αὐτῷ ἐμοῦ, ἐπειδὴ τάχιστα κατέπλευσεν ἐκ τῆς ναυαγίας Ἀθήναζε, καὶ ἐρωτῶντος ὑπὲρ τούτων, ἔλεγεν ὅτι οὔτε τὰ χρήματα ἔνθοιτο εἰς τὴν ναῦν οὗτος κατὰ τὴν συγγραφήν, οὔτε τὸ χρυσίον εἰληφὼς εἴη παρ’ αὐτοῦ ἐν Βοσπόρῳ τότε. καί μοι ἀνάγνωθι τὴν μαρτυρίαν τῶν παραγενομένων.", "st": "34.11"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "34.11"}, {"sp": "N", "t": "ἐπειδὴ τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, ἐπεδήμησεν Φορμίων οὑτοσὶ σεσῳσμένος ἐφ’ ἑτέρας νεώς, προσῄειν αὐτῷ ἀπαιτῶν τὸ δάνειον. καὶ οὗτος κατὰ μὲν ἀρχὰς οὐδεπώποτ’, ὦ ἄνδρες Ἀθηναῖοι, εἶπε τὸν λόγον τοῦτον ὃν νυνὶ λέγει, ἀλλ’ ἀεὶ ὡμολόγει ἀποδώσειν· ἐπειδὴ δὲ ἀνεκοινώσατο τοῖς νῦν παροῦσιν αὐτῷ καὶ συνδικοῦσιν, ἕτερος ἤδη ἦν καὶ οὐχ ὁ αὐτός.", "st": "34.12"}, {"sp": "N", "t": "ὡς δ’ ᾐσθόμην αὐτὸν διακρουόμενόν με, προσέρχομαι τῷ Λάμπιδι, λέγων ὅτι οὐδὲν ποιεῖ τῶν δικαίων Φορμίων οὐδ’ ἀποδίδωσι τὸ δάνειον, καὶ ἅμα ἠρόμην αὐτὸν εἰ εἰδείη ὅπου ἐστίν, ἵνα προσκαλεσαίμην αὐτόν. ὁ δ’ ἀκολουθεῖν μ’ ἐκέλευεν ἑαυτῷ, καὶ καταλαμβάνομεν πρὸς τοῖς μυροπωλίοις τουτονί· κἀγὼ κλητῆρας ἔχων προσεκαλεσάμην αὐτόν.", "st": "34.13"}, {"sp": "N", "t": "καὶ ὁ Λάμπις, ὦ ἄνδρες Ἀθηναῖοι, παρὼν προσκαλουμένῳ μοι οὐδαμοῦ ἐτόλμησεν εἰπεῖν ὡς ἀπείληφε παρὰ τούτου τὸ χρυσίον, οὐδ’ ὃ εἰκὸς ἦν εἶπε “Χρύσιππε, μαίνει· τί τοῦτον προσκαλεῖ; ἐμοὶ γὰρ ἀποδέδωκε τὸ χρυσίον”. ἀλλὰ μὴ ὅτι Λάμπις ἐφθέγξατο, ἀλλ’ οὐδὲ αὐτὸς οὗτος οὐδὲν ἠξίωσεν εἰπεῖν, παρεστηκότος τοῦ Λάμπιδος, ᾧ νῦν φησὶν ἀποδεδωκέναι τὸ χρυσίον.", "st": "34.14"}, {"sp": "N", "t": "καίτοι εἰκός γ’ ἦν αὐτὸν εἰπεῖν, ὦ ἄνδρες Ἀθηναῖοι, “τί με προσκαλεῖ, ἄνθρωπε; ἀποδέδωκα γὰρ τούτῳ τῷ παρεστηκότι τὸ χρυσίον”, καὶ ἅμα ὁμολογοῦντα παρέχειν τὸν Λάμπιν· νυνὶ δ’ οὐδέτερος αὐτῶν οὐδ’ ὁτιοῦν εἶπεν ἐν τοιούτῳ καιρῷ. καὶ ὅτι ἀληθῆ λέγω, λαβέ μοι τὴν μαρτυρίαν τῶν κλητήρων.", "st": "34.15"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "34.15"}, {"sp": "N", "t": "λαβὲ δή μοι καὶ τὸ ἔγκλημα ὃ ἔλαχον αὐτῷ πέρυσιν· ὅ ἐστιν οὐδενὸς ἔλαττον τεκμήριον, ὅτι οὐδέπω τότ’ ἔφησεν Φορμίων ἀποδεδωκέναι τὸ χρυσίον Λάμπιδι.", "st": "34.16"}, {"sp": "N", "t": "ΕΓΚΛΗΜΑ.", "st": "34.16"}, {"sp": "N", "t": "τοῦτο τὸ ἔγκλημα ἔγραφον ἐγώ, ὦ ἄνδρες Ἀθηναῖοι, οὐδαμόθεν ἄλλοθεν σκοπῶν ἀλλ’ ἢ ἐκ τῆς ἀπαγγελίας τῆς Λάμπιδος, ὃς οὐκ ἔφασκεν οὔτε τὰ χρήματα ἐντεθεῖσθαι τοῦτον οὔτε τὸ χρυσίον ἀπειληφέναι· μὴ γὰρ οἴεσθέ με οὕτως ἀπόπληκτον εἶναι καὶ παντελῶς μαινόμενον, ὥστε τοιοῦτο γράφειν ἔγκλημα ὁμολογοῦντος τοῦ Λάμπιδος ἀπειληφέναι τὸ χρυσίον, ὑφ’ οὗ ἔμελλον ἐξελεγχθήσεσθαι.", "st": "34.16"}, {"sp": "N", "t": "ἔτι δέ, ὦ ἄνδρες Ἀθηναῖοι, κἀκεῖνο σκέψασθε· αὐτοὶ γὰρ οὗτοι παραγραφὴν διδόντες πέρυσιν, οὐκ ἐτόλμησαν ἐν τῇ παραγραφῇ γράψαι ὡς ἀποδεδώκασιν Λάμπιδι τὸ χρυσίον. καί μοι λαβὲ αὐτὴν τὴν παραγραφήν.", "st": "34.17"}, {"sp": "N", "t": "ΠΑΡΑΓΡΑΦΗ.", "st": "34.17"}, {"sp": "N", "t": "ἀκούετε, ὦ ἄνδρες Ἀθηναῖοι, ὅτι οὐδαμοῦ γέγραπται ἐν τῇ παραγραφῇ ὡς ἀποδέδωκεν τὸ χρυσίον Φορμίων Λάμπιδι, καὶ ταῦτ’ ἐμοῦ διαρρήδην γράψαντος εἰς τὸ ἔγκλημα ὃ ἠκούσατε ἀρτίως, ὅτι οὔτε τὰ χρήματα ἔνθοιτο εἰς τὴν ναῦν οὔτ’ ἀπέδωκεν τὸ χρυσίον. τίνα οὖν ἄλλον χρὴ περιμένειν ὑμᾶς μάρτυρα, ὅταν τηλικαύτην μαρτυρίαν παρ’ αὐτῶν τούτων ἔχητε;", "st": "34.17"}, {"sp": "N", "t": "μελλούσης δὲ τῆς δίκης εἰσιέναι εἰς τὸ δικαστήριον ἐδέοντο ἡμῶν ἐπιτρέψαι τινί· καὶ ἡμεῖς ἐπετρέψαμεν Θεοδότῳ ἰσοτελεῖ κατὰ συνθήκας. καὶ ὁ Λάμπις μετὰ ταῦτα νομίσας αὑτῷ ἀσφαλὲς ἤδη εἶναι [πρὸς διαιτητῇ] μαρτυρεῖν ὅ τι βούλοιτο, μερισάμενος τὸ ἐμὸν χρυσίον μετὰ Φορμίωνος τουτουί, ἐμαρτύρει τἀναντία οἷς πρότερον εἰρήκει.", "st": "34.18"}, {"sp": "N", "t": "οὐ γὰρ ὅμοιόν ἐστιν, ὦ ἄνδρες Ἀθηναῖοι, εἰς τὰ ὑμέτερα πρόσωπα ἐμβλέποντα τὰ ψευδῆ μαρτυρεῖν καὶ πρὸς διαιτητῇ· παρ’ ὑμῖν μὲν γὰρ ὀργὴ μεγάλη καὶ τιμωρία ὑπόκειται τοῖς τὰ ψευδῆ μαρτυροῦσιν, πρὸς δὲ τῷ διαιτητῇ ἀκινδύνως καὶ ἀναισχύντως μαρτυροῦσιν ὅ τι ἂν βούλωνται. ἀγανακτοῦντος δέ μου καὶ σχετλιάζοντος, ὦ ἄνδρες Ἀθηναῖοι, ἐπὶ τῇ τόλμῃ τοῦ Λάμπιδος,", "st": "34.19"}, {"sp": "N", "t": "καὶ παρεχομένου πρὸς τὸν διαιτητὴν τὴν αὐτὴν μαρτυρίαν ἥνπερ καὶ νῦν πρὸς ὑμᾶς παρέχομαι, τῶν ἐξ ἀρχῆς προσελθόντων αὐτῷ μεθ’ ἡμῶν, ὅτε οὔτε τὸ χρυσίον ἔφη ἀπειληφέναι παρὰ τούτου οὔτε τὰ χρήματα αὐτὸν ἐνθέσθαι εἰς τὴν ναῦν, οὕτως ὁ Λάμπις κατὰ κράτος ἐξελεγχόμενος τὰ ψευδῆ μαρτυρῶν καὶ πονηρὸς ὤν, ὡμολόγει μὲν εἰρηκέναι ταῦτα πρὸς τοῦτον, οὐ μέντοι γε ἐντὸς ὢν εἰπεῖν αὑτοῦ. καί μοι ἀνάγνωθι ταύτην τὴν μαρτυρίαν.", "st": "34.20"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "34.20"}, {"sp": "N", "t": "ἀκούσας τοίνυν ἡμῶν, ὦ ἄνδρες Ἀθηναῖοι, ὁ Θεόδοτος πολλάκις, καὶ νομίσας τὸν Λάμπιν ψευδῆ μαρτυρεῖν, οὐκ ἀπέγνω τῆς δίκης, ἀλλ’ ἀφῆκεν ἡμᾶς εἰς τὸ δικαστήριον· καταγνῶναι μὲν γὰρ οὐκ ἐβουλήθη διὰ τὸ οἰκείως ἔχειν Φορμίωνι τουτῳί, ὡς ἡμεῖς ὕστερον ἐπυθόμεθα, ἀπογνῶναι δὲ τῆς δίκης ὤκνει, ἵν’ αὐτὸς μὴ ἐπιορκήσειεν.", "st": "34.21"}, {"sp": "N", "t": "ἐξ αὐτοῦ δὴ τοῦ πράγματος λογίσασθε, ὦ ἄνδρες δικασταί, παρ’ ὑμῖν αὐτοῖς, ὁπόθεν ἔμελλεν οὗτος ἀποδώσειν τὸ χρυσίον. ἐνθένδε μὲν γὰρ ἐξέπλει οὐκ ἐνθέμενος εἰς τὴν ναῦν τὰ χρήματα καὶ ὑποθήκην οὐκ ἔχων, ἀλλ’ ἐπὶ τοῖς ἐμοῖς χρήμασιν ἐπιδανεισάμενος· ἐν Βοσπόρῳ δ’ ἀπρασίαν τῶν φορτίων κατέλαβεν, καὶ τοὺς τὰ ἑτερόπλοα δανείσαντας μόλις ἀπήλλαξεν.", "st": "34.22"}, {"sp": "N", "t": "καὶ οὗτος μὲν ἐδάνεισεν αὐτῷ δισχιλίας δραχμὰς ἀμφοτερόπλουν, ὥστ’ ἀπολαβεῖν Ἀθήνησιν δισχιλίας ἑξακοσίας δραχμάς· Φορμίων δέ φησιν ἀποδοῦναι Λάμπιδι ἐν Βοσπόρῳ ἑκατὸν καὶ εἴκοσι στατῆρας Κυζικηνούς (τούτῳ γὰρ προσέχετε τὸν νοῦν) δανεισάμενος ἐγγείων τόκων. ἦσαν δὲ ἔφεκτοι οἱ ἔγγειοι τόκοι, ὁ δὲ Κυζικηνὸς ἐδύνατο ἐκεῖ εἴκοσι καὶ ὀκτὼ δραχμὰς Ἀττικάς.", "st": "34.23"}, {"sp": "N", "t": "δεῖ δὴ μαθεῖν ὑμᾶς ὅσα φησὶν χρήματα ἀποδεδωκέναι. τῶν μὲν γὰρ ἑκατὸν εἴκοσι στατήρων γίγνονται τρισχίλιαι τριακόσιαι ἑξήκοντα, ὁ δὲ τόκος ὁ ἔγγειος ὁ ἔφεκτος [τῶν τριάκοντα μνῶν καὶ τριῶν καὶ ἑξήκοντα] πεντακόσιαι δραχμαὶ καὶ ἑξήκοντα· τὸ δὲ σύμπαν κεφάλαιον γίγνεται τόσον καὶ τόσον.", "st": "34.24"}, {"sp": "N", "t": "ἔστιν οὖν, ὦ ἄνδρες δικασταί, οὗτος ὁ ἄνθρωπος ἢ γενήσεταί ποτε, ὃς ἀντὶ δισχιλίων ἑξακοσίων δραχμῶν τριάκοντα μνᾶς καὶ τριακοσίας καὶ ἑξήκοντα ἀποτίνειν προείλετ’ ἄν, καὶ τόκον πεντακοσίας δραχμὰς καὶ ἑξήκοντα δανεισάμενος, ἅς φησιν ἀποδεδωκέναι Φορμίων Λάμπιδι, τρισχιλίας ἐνακοσίας εἴκοσι; ἐξὸν δ’ αὐτῷ ἀμφοτερόπλουν Ἀθήνησιν ἀποδοῦναι τὸ ἀργύριον, ἐν Βοσπόρῳ ἀπέδωκε, τρισὶ καὶ δέκα μναῖς πλέον;", "st": "34.25"}, {"sp": "N", "t": "καὶ τοῖς μὲν τὰ ἑτερόπλοα δανείσασι μόλις τἀρχαῖον ἀποδέδωκας, οἳ συνέπλευσάν σοι καὶ προσήδρευον· τούτῳ δὲ τῷ μὴ παρόντι οὐ μόνον τἀρχαῖα καὶ τοὺς τόκους ἀπεδίδους, ἀλλὰ καὶ τὰ ἐπιτίμια τὰ ἐκ τῆς συγγραφῆς ἀπέτινες, οὐδεμιᾶς σοι ἀνάγκης οὔσης;", "st": "34.26"}, {"sp": "N", "t": "κἀκείνους μὲν οὐκ ἐδεδίεις, οἷς αἱ συγγραφαὶ ἐν Βοσπόρῳ τὴν πρᾶξιν ἐδίδοσαν τοῦ δανείου· τούτου δὲ φὴς φροντίζειν, ὃν ἐξ ἀρχῆς εὐθὺς ἠδίκεις οὐκ ἐνθέμενος τὰ χρήματα εἰς τὴν ναῦν κατὰ τὴν συγγραφὴν Ἀθήνηθεν; καὶ νῦν μὲν εἰς τὸ ἐμπόριον ἥκων, οὗ τὸ συμβόλαιον ἐγένετο, οὐκ ὀκνεῖς ἀποστερεῖν τὸν δανείσαντα· ἐν Βοσπόρῳ δὲ πλείω τῶν δικαίων φὴς ποιεῖν, οὗ δίκην οὐκ ἔμελλες δώσειν;", "st": "34.27"}, {"sp": "N", "t": "καὶ οἱ μὲν ἄλλοι πάντες οἱ τὰ ἀμφοτερόπλοα δανειζόμενοι, ὅταν ἀποστέλλωνται ἐκ τῶν ἐμπορίων, πολλοὺς παρίστανται, ἐπιμαρτυρόμενοι ὅτι τὰ χρήματα ἤδη κινδυνεύεται τῷ δανείσαντι· σὺ δ’ ἑνὶ σκήπτει μάρτυρι αὐτῷ τῷ συναδικοῦντι, καὶ οὔτε τὸν παῖδα τὸν ἡμέτερον παρέλαβες ἐν Βοσπόρῳ ὄντα οὔτε τὸν κοινωνόν, οὐδὲ τὰς ἐπιστολὰς ἀπέδωκας αὐτοῖς, ἃς ἡμεῖς ἐπεθήκαμεν, ἐν αἷς ἐγέγραπτο παρακολουθεῖν σοι οἷς ἂν πράττῃς;", "st": "34.28"}, {"sp": "N", "t": "καίτοι, ὦ ἄνδρες δικασταί, τί οὐκ ἂν πράξειεν ὁ τοιοῦτος, ὅστις γράμματα λαβὼν μὴ ἀποδέδωκεν ὀρθῶς καὶ δικαίως; ἢ πῶς οὐ φανερόν ἐστιν ὑμῖν τὸ τούτου κακούργημα ἐξ αὐτῶν ὧν ἔπραττεν; καίτοι, ὦ γῆ καὶ θεοί, προσῆκέν γε τοσοῦτο χρυσίον ἀποδιδόντα, καὶ πλέον τοῦ δανείσματος, περιβόητον ποιεῖν ἐν τῷ ἐμπορίῳ, καὶ παρακαλεῖν πάντας ἀνθρώπους, πρῶτον δὲ τὸν παῖδα τὸν τούτου καὶ τὸν κοινωνόν·", "st": "34.29"}, {"sp": "N", "t": "ἴστε γὰρ δήπου πάντες ὅτι δανείζονται μὲν μετ’ ὀλίγων μαρτύρων, ὅταν δ’ ἀποδιδῶσιν, πολλοὺς παρίστανται μάρτυρας, ἵνα ἐπιεικεῖς δοκῶσιν εἶναι περὶ τὰ συμβόλαια. σοὶ δ’ ἀποδιδόντι τό τε δάνειον καὶ τοὺς τόκους ἀμφοτέρους, ἑτερόπλῳ τῷ ἀργυρίῳ κεχρημένῳ, καὶ προστιθέντι ἑτέρας τρεῖς καὶ δέκα μνᾶς, πῶς οὐχὶ πολλοὺς ἦν παραληπτέον μάρτυρας; καὶ εἰ τοῦτο ἔπραξας, οὐδ’ ἂν εἷς σοῦ μᾶλλον τῶν πλεόντων ἐθαυμάζετο.", "st": "34.30"}, {"sp": "N", "t": "σὺ δ’ ἀντὶ τοῦ πολλοὺς μάρτυρας τούτων ποιεῖσθαι πάντας ἀνθρώπους λανθάνειν ἐπειρῶ, ὥσπερ ἀδικῶν τι. καὶ εἰ μὲν ἐμοὶ τῷ δανείσαντι ἀπεδίδους, οὐδὲν ⟨ἂν⟩ ἔδει μαρτύρων· τὴν γὰρ συγγραφὴν ἀνελόμενος ἀπήλλαξο ἂν τοῦ συμβολαίου· νῦν δ’ οὐκ ἐμοί, ἀλλ’ ἑτέρῳ ὑπὲρ ἐμοῦ ἀποδιδούς, καὶ οὐκ Ἀθήνησιν, ἀλλ’ ἐν Βοσπόρῳ, καὶ τῆς συγγραφῆς σοι κειμένης Ἀθήνησι καὶ πρὸς ἐμέ, καὶ ᾧ τὸ χρυσίον ἀπεδίδους ὄντος θνητοῦ καὶ πέλαγος τοσοῦτον μέλλοντος πλεῖν, μάρτυρα οὐδένα ἐποιήσω, οὔτε δοῦλον οὔτ’ ἐλεύθερον.", "st": "34.31"}, {"sp": "N", "t": "ἡ γὰρ συγγραφή με, φησί, τῷ ναυκλήρῳ ἐκέλευεν ἀποδοῦναι τὸ χρυσίον. μάρτυρας δέ γ’ οὐκ ἐκώλυεν παρακαλεῖν, οὐδὲ τὰς ἐπιστολὰς ἀποδοῦναι. καὶ οἵδε μὲν πρὸς σὲ δύο συγγραφὰς ἐποιήσαντο ὑπὲρ τοῦ συμβολαίου, ὡς ἂν οἱ μάλιστ’ ἀπιστοῦντες· σὺ δὲ μόνος μόνῳ φὴς δοῦναι τῷ ναυκλήρῳ τὸ χρυσίον, εἰδὼς κατὰ σοῦ κειμένην Ἀθήνησι συγγραφὴν πρὸς τοῦτον.", "st": "34.32"}, {"sp": "N", "t": "λέγει δὲ ὡς ἡ συγγραφὴ σωθείσης τῆς νεὼς αὐτὸν ἀποδοῦναι κελεύει τὰ χρήματα. καὶ γὰρ ἐνθέσθαι τἀγοράσματα εἰς τὴν ναῦν κελεύει σε, εἰ δὲ μή, πεντακισχιλίας δραχμὰς ἀποτίνειν. σὺ δὲ τοῦτο μὲν τῆς συγγραφῆς οὐ λαμβάνεις, παραβεβηκὼς δ’ εὐθὺς ἐξ ἀρχῆς καὶ τὰ χρήματα οὐκ ἐνθέμενος ἀμφισβητεῖς πρὸς ἓν ῥῆμα τῶν ἐν τῇ συγγραφῇ, καὶ τοῦτ’ ἀνῃρηκὼς αὐτός. ὁπότε γὰρ ἐν τῷ Βοσπόρῳ φὴς μὴ τὰ χρήματα ἐνθέσθαι εἰς τὴν ναῦν, ἀλλὰ τὸ χρυσίον τῷ ναυκλήρῳ ἀποδοῦναι, τί ἔτι περὶ τῆς νεὼς διαλέγει; οὐ γὰρ μετέσχηκας τοῦ κινδύνου διὰ τὸ μηδὲν ἐνθέσθαι.", "st": "34.33"}, {"sp": "N", "t": "καὶ τὸ μὲν πρῶτον, ὦ ἄνδρες δικασταί, ὥρμησεν ἐπὶ ταύτην τὴν σκῆψιν, ὡς ἐντεθειμένος τὰ χρήματα εἰς τὴν ναῦν· ἐπειδὴ δὲ τοῦτο ἐκ πολλῶν ἔμελλεν ἐλεγχθήσεσθαι ψευδόμενος, ἔκ τε τῆς ἀπογραφῆς τῆς ἐν Βοσπόρῳ παρὰ τοῖς ἐλλιμενισταῖς καὶ ὑπὸ τῶν ἐν τῷ ἐμπορίῳ ἐπιδημούντων κατὰ τὸν αὐτὸν χρόνον, τηνικαῦτα μεταβαλόμενος συνίσταται μετὰ τοῦ Λάμπιδος καί φησιν ἐκείνῳ τὸ χρυσίον ἀποδεδωκέναι,", "st": "34.34"}, {"sp": "N", "t": "ἐφόδιον μὲν λαβὼν τὸ τὴν συγγραφὴν κελεύειν, οὐκ ἂν ἡγούμενος δ’ ἡμᾶς εὐπόρως ἐξελέγξαι ὅσα μόνοι πρὸς αὑτοὺς αὐτοὶ πράξειαν. καὶ ὁ Λάμπις, ὅσα μὲν εἶπεν πρὸς ἐμὲ πρὶν ὑπὸ τούτου διαφθαρῆναι, οὐκ ἐντὸς ὢν αὑτοῦ φησιν εἰπεῖν· ἐπειδὴ δὲ τὸ χρυσίον τοὐμὸν ἐμερίσατο, τότ’ ἐντὸς εἶναί φησιν αὑτοῦ καὶ πάντ’ ἀκριβῶς μνημονεύειν.", "st": "34.35"}, {"sp": "N", "t": "εἰ μὲν οὖν, ὦ ἄνδρες δικασταί, ἐμοῦ μόνου κατεφρόνει Λάμπις, οὐδὲν ἂν ἦν θαυμαστόν· νῦν δὲ πολλῷ δεινότερα τούτου πέπρακται αὐτῷ πρὸς πάντας ὑμᾶς. κήρυγμα γὰρ ποιησαμένου Παιρισάδου ἐν Βοσπόρῳ, ἐάν τις βούληται Ἀθήναζε εἰς τὸ Ἀττικὸν ἐμπόριον σιτηγεῖν, ἀτελῆ τὸν σῖτον ἐξάγειν, ἐπιδημῶν ἐν τῷ Βοσπόρῳ ὁ Λάμπις ἔλαβε τὴν ἐξαγωγὴν τοῦ σίτου καὶ τὴν ἀτέλειαν ἐπὶ τῷ τῆς πόλεως ὀνόματι, γεμίσας δὲ ναῦν μεγάλην σίτου ἐκόμισεν εἰς Ἄκανθον κἀκεῖ διέθετο ⟨ὁ⟩ προσκοινωνήσας τούτῳ ἀπὸ τῶν ὑμετέρων χρημάτων.", "st": "34.36"}, {"sp": "N", "t": "καὶ ταῦτ’ ἔπραξεν, ὦ ἄνδρες δικασταί, οἰκῶν μὲν Ἀθήνησιν, οὔσης δ’ αὐτῷ γυναικὸς ἐνθάδε καὶ παίδων, τῶν δὲ νόμων τὰ ἔσχατα ἐπιτίμια προτεθηκότων, εἴ τις οἰκῶν Ἀθήνησιν ἄλλοσέ ποι σιτηγήσειεν ἢ εἰς τὸ Ἀττικὸν ἐμπόριον, ἔτι δ’ ἐν τοιούτῳ καιρῷ, ἐν ᾧ ὑμῶν οἱ μὲν ἐν τῷ ἄστει οἰκοῦντες διεμετροῦντο τὰ ἄλφιτα ἐν τῷ ᾠδείῳ, οἱ δ’ ἐν τῷ Πειραιεῖ ἐν τῷ νεωρίῳ ἐλάμβανον κατ’ ὀβολὸν τοὺς ἄρτους καὶ ἐπὶ τῆς μακρᾶς στοᾶς τὰ ἄλφιτα, καθ’ ἡμίεκτον μετρούμενοι καὶ καταπατούμενοι. καὶ ὅτι ἀληθῆ λέγω, λαβέ μοι τήν τε μαρτυρίαν καὶ τὸν νόμον.", "st": "34.37"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ. ΝΟΜΟΣ.", "st": "34.37"}, {"sp": "N", "t": "Φορμίων τοίνυν τούτῳ χρώμενος κοινωνῷ καὶ μάρτυρι οἴεται δεῖν ἀποστερῆσαι τὰ χρήματα ἡμᾶς, οἵ γε σιτηγοῦντες διατετελέκαμεν εἰς τὸ ὑμέτερον ἐμπόριον, καὶ τριῶν ἤδη καιρῶν κατειληφότων τὴν πόλιν, ἐν οἷς ὑμεῖς τοὺς χρησίμους τῷ δήμῳ ἐξητάζετε, οὐδενὸς τούτων ἀπολελείμμεθα, ἀλλ’ ὅτε μὲν εἰς Θήβας Ἀλέξανδρος παρῄει, ἐπεδώκαμεν ὑμῖν τάλαντον ἀργυρίου·", "st": "34.38"}, {"sp": "N", "t": "ὅτε δ’ ὁ σῖτος ἐπετιμήθη ⟨τὸ⟩ πρότερον καὶ ἐγένετο ἑκκαίδεκα δραχμῶν, εἰσαγαγόντες πλείους ἢ μυρίους μεδίμνους πυρῶν διεμετρήσαμεν ὑμῖν τῆς καθεστηκυίας τιμῆς, πέντε δραχμῶν τὸν μέδιμνον, καὶ ταῦτα πάντες ἴστε ἐν τῷ πομπείῳ διαμετρούμενοι· πέρυσι δὲ εἰς τὴν σιτωνίαν τὴν ὑπὲρ τοῦ δήμου τάλαντον ὑμῖν ἐπεδώκαμεν ἐγώ τε καὶ ὁ ἀδελφός. καί μοι ἀνάγνωθι τούτων τὰς μαρτυρίας.", "st": "34.39"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "34.39"}, {"sp": "N", "t": "ἀλλὰ μὴν εἴ γε δεῖ καὶ τούτοις τεκμαίρεσθαι, οὐκ εἰκὸς ἦν ἐπιδιδόναι μὲν ἡμᾶς τοσαῦτα χρήματα, ἵνα παρ’ ὑμῖν εὐδοξῶμεν, συκοφαντεῖν δὲ Φορμίωνα, ἵνα καὶ τὴν ὑπάρχουσαν ἐπιείκειαν ἀποβάλωμεν. δικαίως ἂν οὖν βοηθήσαιτε ἡμῖν, ὦ ἄνδρες δικασταί. ἐπέδειξα γὰρ ὑμῖν οὔτ’ ἐξ ἀρχῆς τὰ φορτία ἐνθέμενον τοῦτον εἰς τὴν ναῦν ἁπάντων ὧν ἐδανείσατο Ἀθήνηθεν, τῶν τ’ ἐν τῷ Βοσπόρῳ πραθέντων τοὺς τὰ ἑτερόπλοα δανείσαντας μόλις διαλύσαντα,", "st": "34.40"}, {"sp": "N", "t": "ἔτι δ’ οὔτ’ εὐποροῦντα οὔθ’ οὕτως ὄντ’ ἀβέλτερον ὥστ’ ἀντὶ δισχιλίων καὶ ἑξακοσίων δραχμῶν τριάκοντα μνᾶς καὶ ἐννέα ἀποδοῦναι, πρός τε τούτοις, ὅτε ἀποδοῦναί φησιν τὸ χρυσίον τῷ Λάμπιδι, οὔτε τὸν παῖδα παραλαβόντα τὸν ἐμὸν οὔτε τὸν κοινωνὸν ἐπιδημοῦντα ἐν Βοσπόρῳ. ἐμοὶ δὲ Λάμπις αὐτὸς μαρτυρῶν φαίνεται ὡς οὐκ ἀπείληφεν τὸ χρυσίον, πρὶν ὑπὸ τούτου διαφθαρῆναι.", "st": "34.41"}, {"sp": "N", "t": "καίτοι εἰ καθ’ ἓν ἕκαστον οὕτως ἐδείκνυεν Φορμίων, οὐκ οἶδ’ ὅπως ἂν ἄλλως ἄμεινον ἀπελογήσατο. ὑπὲρ δὲ τοῦ τὴν δίκην εἰσαγώγιμον εἶναι ὁ νόμος αὐτὸς διαμαρτύρεται, κελεύων τὰς δίκας εἶναι τὰς ἐμπορικὰς τῶν συμβολαίων τῶν Ἀθήνησιν καὶ εἰς τὸ Ἀθηναίων ἐμπόριον, καὶ οὐ μόνον τῶν Ἀθήνησιν, ἀλλὰ καὶ ὅσα ἂν γένηται ἕνεκα τοῦ πλοῦ τοῦ Ἀθήναζε. λαβὲ δή μοι τοὺς νόμους.", "st": "34.42"}, {"sp": "N", "t": "ΝΟΜΟΙ.", "st": "34.42"}, {"sp": "N", "t": "ὡς μὲν τοίνυν γέγονέ μοι τὸ συμβόλαιον πρὸς Φορμίων’ Ἀθήνησιν, οὐδ’ αὐτοὶ ἔξαρνοί εἰσιν, παραγράφονται δὲ ὡς οὐκ εἰσαγώγιμον τὴν δίκην οὖσαν. ἀλλ’ εἰς ποῖον δικαστήριον εἰσέλθωμεν, ἄνδρες δικασταί, εἰ μὴ πρὸς ὑμᾶς, οὗπερ τὸ συμβόλαιον ἐποιησάμεθα; δεινὸν γὰρ ἂν εἴη, εἰ μὲν ἕνεκα τοῦ πλοῦ τοῦ Ἀθήναζε ἠδικούμην, εἶναι ⟨ἄν⟩ μοι παρ’ ὑμῖν τὸ δίκαιον λαβεῖν παρὰ Φορμίωνος, ἐπειδὴ δὲ τὸ συμβόλαιον ἐν τῷ ὑμετέρῳ ἐμπορίῳ γέγονεν, μὴ φάσκειν παρ’ ὑμῖν τούτους ὑφέξειν τὴν δίκην.", "st": "34.43"}, {"sp": "N", "t": "καὶ ὅτε μὲν Θεοδότῳ τὴν δίαιταν ἐπετρέψαμεν, ὡμολόγησαν εἶναι καθ’ αὑτῶν ἐμοὶ τὴν δίκην εἰσαγώγιμον· νυνὶ δὲ τοὐναντίον λέγουσιν ὧν πρότερον αὐτοὶ συγκεχωρήκασιν, ὡς δέον παρὰ μὲν τῷ Θεοδότῳ τῷ ἰσοτελεῖ ὑποσχεῖν αὐτοὺς δίκην ἄνευ παραγραφῆς, ἐπειδὴ δὲ εἰς τὸ Ἀθηναίων δικαστήριον εἰσερχόμεθα, μηκέτ’ εἰσαγώγιμον τὴν δίκην εἶναι.", "st": "34.44"}, {"sp": "N", "t": "ἐνθυμοῦμαι δ’ ἔγωγε, τί ἄν ποτε εἰς τὴν παραγραφὴν ἔγραψεν, εἰ ὁ Θεόδοτος ἀπέγνω τῆς δίκης, ὅπου νῦν γνόντος τοῦ Θεοδότου ἀπιέναι ἡμᾶς εἰς τὸ δικαστήριον οὔ φησι τὴν δίκην εἶναι εἰσαγώγιμον παρ’ ὑμῖν, πρὸς οὓς ἐκεῖνος ἔγνω ἀπιέναι. πάθοιμι μέντἂν δεινότατα, εἰ οἱ μὲν νόμοι τῶν Ἀθήνησι συμβολαίων κελεύουσι τὰς δίκας εἶναι πρὸς τοὺς θεσμοθέτας, ὑμεῖς δὲ ἀπογνοίητε τῆς δίκης ὀμωμοκότες κατὰ τοὺς νόμους ψηφιεῖσθαι.", "st": "34.45"}, {"sp": "N", "t": "τοῦ μὲν οὖν δανεῖσαι ἡμᾶς τὰ χρήματα αἵ τε συνθῆκαι καὶ αὐτὸς οὗτός ἐστι μάρτυς· τοῦ δ’ ἀποδεδωκέναι οὐδείς ἐστι μάρτυς ἔξω τοῦ Λάμπιδος τοῦ συναδικοῦντος. καὶ οὗτος μὲν εἰς ἐκεῖνον μόνον ἀναφέρει τὴν ἀπόδοσιν, ἐγὼ δ’ εἴς τε τὸν Λάμπιν αὐτὸν καὶ τοὺς ἀκούσαντας αὐτοῦ ὅτε οὐκ ἔφη ἀπειληφέναι τὸ χρυσίον. τούτῳ μὲν οὖν τοὺς ἐμοὺς μάρτυρας ἔξεστι κρίνειν, εἰ μή φησι τἀληθῆ μαρτυρεῖν αὐτούς· ἐγὼ δ’ οὐκ ἔχω τί χρήσωμαι τοῖς τούτου μάρτυσιν, οἵ φασιν εἰδέναι τὸν Λάμπιν μαρτυροῦντα ἀπειληφέναι τὸ χρυσίον. εἰ μὲν γὰρ ἡ μαρτυρία ἡ τοῦ Λάμπιδος κατεβάλλετο ἐνταῦθα, ἴσως ἂν ἔφασαν οὗτοι δίκαιον εἶναι ἐπισκήπτεσθαί μ’ ἐκείνῳ· νῦν δ’ οὔτε τὴν μαρτυρίαν ταύτην ἔχω, οὑτοσί τε οἴεται δεῖν ἀθῷος εἶναι οὐδὲν βέβαιον ἐνέχυρον καταλιπὼν ὧν πείθει ὑμᾶς ψηφίζεσθαι.", "st": "34.46"}, {"sp": "N", "t": "πῶς δ’ οὐκ ἂν εἴη ἄτοπον, εἰ αὐτοῦ Φορμίωνος ὁμολογοῦντος δανείσασθαι, φάσκοντος δὲ ἀποδεδωκέναι, τὸ μὲν ὁμολογούμενον ὑπ’ αὐτοῦ τούτου ἄκυρον ποιήσαιτε, τὸ δὲ ἀμφισβητούμενον κύριον ψηφίσαισθε; καὶ ὁ μὲν Λάμπις, ᾧ οὗτος σκήπτεται μάρτυρι, μαρτυρεῖ ἔξαρνος γενόμενος τὸ ἐξ ἀρχῆς ὡς οὐκ ἀπείληφεν τὸ χρυσίον· ὑμεῖς δὲ γνοίητε ὡς ἀπείληφεν ἐκεῖνος, ᾧ οὐκ εἰσὶ μάρτυρες τοῦ πράγματος;", "st": "34.47"}, {"sp": "N", "t": "καὶ ὅσα μὲν εἶπε μετὰ τῆς ἀληθείας, μὴ χρήσαισθε τεκμηρίῳ, ἃ δ’ ἐψεύσατο ὕστερον, ἐπειδὴ διεφθάρη, πιστότερα ταῦθ’ ὑπολάβοιτε εἶναι; καὶ μήν, ὦ ἄνδρες Ἀθηναῖοι, πολὺ δικαιότερόν ἐστιν τοῖς ἐξ ἀρχῆς ῥηθεῖσι τεκμαίρεσθαι μᾶλλον ἢ τοῖς ὕστερον τεκταινομένοις. τὰ μὲν γὰρ οὐκ ἐκ παρασκευῆς, ἀλλ’ ἐκ τῆς ἀληθείας ἔλεγεν, τὰ δ’ ὕστερον ψευδόμενος καὶ πρὸς τὸ συμφέρον αὑτῷ.", "st": "34.48"}, {"sp": "N", "t": "ἀναμνήσθητε δέ, ὦ ἄνδρες Ἀθηναῖοι, ὅτι οὐδ’ αὐτὸς ὁ Λάμπις ἔξαρνος ἐγένετο ὡς οὐκ εἴη εἰρηκὼς ὅτι οὐκ ἀπείληφεν τὸ χρυσίον, ἀλλ’ εἰπεῖν μὲν ὡμολόγει, οὐ μέντοι γε ἐντὸς ὢν αὑτοῦ εἰπεῖν. οὔκουν ἄτοπον, εἰ τῆς ἐκείνου μαρτυρίας τὸ μὲν πρὸς τοῦ ἀποστεροῦντος πιστῶς ἀκούσεσθε, τὸ δ’ ὑπὲρ τῶν ἀποστερουμένων ἄπιστον ἔσται παρ’ ὑμῖν;", "st": "34.49"}, {"sp": "N", "t": "μηδαμῶς, ὦ ἄνδρες δικασταί. ὑμεῖς γάρ ἐστε [οἱ] αὐτοὶ οἱ τὸν ἐπιδεδανεισμένον ἐκ τοῦ ἐμπορίου πολλὰ χρήματα καὶ τοῖς δανεισταῖς οὐ παρασχόντα τὰς ὑποθήκας θανάτῳ ζημιώσαντες εἰσαγγελθέντα ἐν τῷ δήμῳ, καὶ ταῦτα πολίτην ὑμέτερον ὄντα καὶ πατρὸς ἐστρατηγηκότος.", "st": "34.50"}, {"sp": "N", "t": "ἡγεῖσθε γὰρ τοὺς τοιούτους οὐ μόνον τοὺς ἐντυγχάνοντας ἀδικεῖν, ἀλλὰ καὶ κοινῇ βλάπτειν τὸ ἐμπόριον ὑμῶν, εἰκότως. αἱ γὰρ εὐπορίαι τοῖς ἐργαζομένοις οὐκ ἀπὸ τῶν δανειζομένων, ἀλλ’ ἀπὸ τῶν δανειζόντων εἰσίν, καὶ οὔτε ναῦν οὔτε ναύκληρον οὔτ’ ἐπιβάτην ἔστ’ ἀναχθῆναι, τὸ τῶν δανειζόντων μέρος ἂν ἀφαιρεθῇ.", "st": "34.51"}, {"sp": "N", "t": "ἐν μὲν οὖν τοῖς νόμοις πολλαὶ καὶ καλαὶ βοήθειαί εἰσιν αὐτοῖς· ὑμᾶς δὲ δεῖ συνεπανορθοῦντας φαίνεσθαι καὶ μὴ συγχωροῦντας τοῖς πονηροῖς, ἵν’ ὑμῖν ὡς πλείστη ὠφέλεια παρὰ τὸ ἐμπόριον ᾖ. ἔσται δέ, ἐὰν διαφυλάττητε τοὺς τὰ ἑαυτῶν προϊεμένους, καὶ μὴ ἐπιτρέπητε ἀδικεῖσθαι ὑπὸ τῶν τοιούτων θηρίων.", "st": "34.52"}, {"sp": "N", "t": "ἐγὼ μὲν οὖν ὅσαπερ οἷός τ’ ἦν εἴρηκα· καλῶ δὲ καὶ ἄλλον τινὰ τῶν φίλων, ἐὰν κελεύητε.", "st": "34.52"}, {"sp": "HDR", "t": "Πρὸς τὴν Λάκριτον παραγραφὴν", "st": "35"}, {"sp": "N", "t": "οὐδὲν καινὸν διαπράττονται οἱ Φασηλῖται, ὦ ἄνδρες δικασταί, ἀλλ’ ἅπερ εἰώθασιν. οὗτοι γὰρ δεινότατοι μέν εἰσιν δανείσασθαι χρήματα ἐν τῷ ἐμπορίῳ, ἐπειδὰν δὲ λάβωσιν καὶ συγγραφὴν συγγράψωνται ναυτικήν, εὐθὺς ἐπελάθοντο καὶ τῶν συγγραφῶν καὶ τῶν νόμων καὶ ὅτι δεῖ ἀποδοῦναι αὐτοὺς ἃ ἔλαβον,", "st": "35.1"}, {"sp": "N", "t": "καὶ οἴονται, ἐὰν ἀποδῶσιν, ὥσπερ τῶν ἰδίων τι τῶν ἑαυτῶν ἀπολωλεκέναι, ἀλλ’ ἀντὶ τοῦ ἀποδοῦναι σοφίσματα εὑρίσκουσιν καὶ παραγραφὰς καὶ προφάσεις, καὶ εἰσὶν πονηρότατοι ἀνθρώπων καὶ ἀδικώτατοι. τεκμήριον δὲ τούτου· πολλῶν γὰρ ἀφικνουμένων εἰς τὸ ὑμέτερον ἐμπόριον καὶ Ἑλλήνων καὶ βαρβάρων, πλείους δίκαι εἰσὶν ἑκάστοτε αὐτῶν τῶν Φασηλιτῶν ἢ τῶν ἄλλων ἁπάντων.", "st": "35.2"}, {"sp": "N", "t": "οὗτοι μὲν οὖν τοιοῦτοί εἰσιν· ἐγὼ δέ, ὦ ἄνδρες δικασταί, χρήματα δανείσας Ἀρτέμωνι τῷ τούτου ἀδελφῷ κατὰ τοὺς ἐμπορικοὺς νόμους, εἰς τὸν Πόντον καὶ πάλιν Ἀθήναζε, τελευτήσαντος ἐκείνου πρὶν ἀποδοῦναί μοι τὰ χρήματα, Λακρίτῳ τουτῳὶ εἴληχα τὴν δίκην ταύτην κατὰ τοὺς αὐτοὺς νόμους τούτους καθ’ οὕσπερ τὸ συμβόλαιον ἐποιησάμην,", "st": "35.3"}, {"sp": "N", "t": "ἀδελφῷ ὄντι τούτῳ ἐκείνου καὶ ἔχοντι ἅπαντα τὰ Ἀρτέμωνος, καὶ ὅσα ἐνθάδε κατέλιπεν καὶ ὅσα ἦν αὐτῷ ἐν τῇ Φασήλιδι, καὶ κληρονόμῳ ὄντι τῶν ἐκείνου ἁπάντων, καὶ οὐκ ἂν ἔχοντος τούτου δεῖξαι νόμον ὅστις αὐτῷ δίδωσιν ἐξουσίαν ἔχειν μὲν τὰ τοῦ ἀδελφοῦ καὶ διῳκηκέναι ὅπως ἐδόκει αὐτῷ, μὴ ἀποδοῦναι δὲ τὰ ἀλλότρια χρήματα, ἀλλὰ λέγειν νῦν ὅτι οὐκ ἔστιν κληρονόμος, ἀλλ’ ἀφίσταται τῶν ἐκείνου.", "st": "35.4"}, {"sp": "N", "t": "ἡ μὲν τουτουὶ Λακρίτου πονηρία τοιαύτη ἐστίν· ἐγὼ δ’ ὑμῶν δέομαι, ὦ ἄνδρες δικασταί, εὐνοϊκῶς ἀκοῦσαί μου περὶ τοῦ πράγματος τουτουί· κἂν ἐξελέγξω αὐτὸν ἀδικοῦντα ἡμᾶς τε τοὺς δανείσαντας καὶ ὑμᾶς οὐδὲν ἧττον, βοηθεῖτε ἡμῖν τὰ δίκαια.", "st": "35.5"}, {"sp": "N", "t": "ἐγὼ γάρ, ὦ ἄνδρες δικασταί, αὐτὸς μὲν οὐδ’ ὁπωστιοῦν ἐγνώριζον τοὺς ἀνθρώπους τούτους· Θρασυμήδης δ’ ὁ Διοφάντου υἱός, ἐκείνου τοῦ Σφηττίου, καὶ Μελάνωπος ὁ ἀδελφὸς αὐτοῦ ἐπιτήδειοί μοί εἰσιν, καὶ χρώμεθα ἀλλήλοις ὡς οἷόν τε μάλιστα. οὗτοι προσῆλθόν μοι μετὰ Λακρίτου τουτουί, ὁπόθεν δήποτε ἐγνωρισμένοι τούτῳ (οὐ γὰρ οἶδα),", "st": "35.6"}, {"sp": "N", "t": "καὶ ἐδέοντό μου δανεῖσαι χρήματα εἰς τὸν Πόντον Ἀρτέμωνι τῷ τούτου ἀδελφῷ καὶ Ἀπολλοδώρῳ, ὅπως ἂν ἐνεργοὶ ὦσιν, οὐδὲν εἰδώς, ὦ ἄνδρες δικασταί, οὐδ’ ὁ Θρασυμήδης τὴν τούτων πονηρίαν, ἀλλ’ οἰόμενος εἶναι ἐπιεικεῖς ἀνθρώπους καὶ οἷοίπερ προσεποιοῦντο καὶ ἔφασαν εἶναι, καὶ ἡγούμενος ποιήσειν αὐτοὺς πάντα ὅσαπερ ὑπισχνεῖτο καὶ ἀνεδέχετο Λάκριτος οὑτοσί.", "st": "35.7"}, {"sp": "N", "t": "πλεῖστον δ’ ἄρα ἦν ἐψευσμένος, καὶ οὐδὲν ᾔδει οἵοις θηρίοις ἐπλησίαζε τοῖς ἀνθρώποις τούτοις. κἀγὼ πεισθεὶς ὑπὸ τοῦ Θρασυμήδους καὶ τοῦ ἀδελφοῦ αὐτοῦ, καὶ Λακρίτου τουτουὶ ἀναδεχομένου μοι πάντ’ ἔσεσθαι τὰ δίκαια παρὰ τῶν ἀδελφῶν τῶν αὑτοῦ, ἐδάνεισα μετὰ ξένου τινὸς ἡμετέρου Καρυστίου τριάκοντα μνᾶς ἀργυρίου.", "st": "35.8"}, {"sp": "N", "t": "βούλομαι οὖν, ὦ ἄνδρες δικασταί, τῆς συγγραφῆς ἀκοῦσαι ὑμᾶς πρῶτον, καθ’ ἣν ἐδανείσαμεν τὰ χρήματα, καὶ τῶν μαρτύρων τῶν παραγενομένων τῷ δανείσματι· ἔπειτα περὶ τῶν ἄλλων ἐπιδείξομεν, οἷα ἐτοιχωρύχησαν οὗτοι περὶ τὸ δάνειον. λέγε τὴν συγγραφήν, εἶτα τὰς μαρτυρίας.", "st": "35.9"}, {"sp": "N", "t": "ΣΥΓΓΡΑΦΗ.", "st": "35.9"}, {"sp": "N", "t": "ἐδάνεισαν Ἀνδροκλῆς Σφήττιος καὶ Ναυσικράτης Καρύστιος Ἀρτέμωνι καὶ Ἀπολλοδώρῳ Φασηλίταις ἀργυρίου δραχμὰς τρισχιλίας Ἀθήνηθεν εἰς Μένδην ἢ Σκιώνην, καὶ ἐντεῦθεν εἰς Βόσπορον, ἐὰν δὲ βούλωνται, τῆς ἐπ’ ἀριστερὰ μέχρι Βορυσθένους, καὶ πάλιν Ἀθήναζε, ἐπὶ διακοσίαις εἴκοσι πέντε τὰς χιλίας, ἐὰν δὲ μετ’ Ἀρκτοῦρον ἐκπλεύσωσιν ἐκ τοῦ Πόντου ἐφ’ Ἱερόν, ἐπὶ τριακοσίαις τὰς χιλίας, ἐπὶ οἴνου κεραμίοις Μενδαίοις τρισχιλίοις, ὃς πλεύσεται ἐκ Μένδης ἢ Σκιώνης ἐν τῇ εἰκοσόρῳ ἣν Ὑβλήσιος ναυκληρεῖ.", "st": "35.10"}, {"sp": "N", "t": "ὑποτιθέασι δὲ ταῦτα, οὐκ ὀφείλοντες ἐπὶ τούτοις ἄλλῳ οὐδενὶ οὐδὲν ἀργύριον, οὐδ’ ἐπιδανείσονται. καὶ ἀπάξουσι τὰ χρήματα τὰ ἐκ τοῦ Πόντου ἀντιφορτισθέντα Ἀθήναζε πάλιν ἐν τῷ αὐτῷ πλοίῳ ἅπαντα. σωθέντων δὲ τῶν χρημάτων Ἀθήναζε, ἀποδώσουσιν οἱ δανεισάμενοι τοῖς δανείσασι τὸ γιγνόμενον ἀργύριον κατὰ τὴν συγγραφὴν ἡμερῶν εἴκοσιν, ἀφ’ ἧς ἂν ἔλθωσιν Ἀθήναζε, ἐντελὲς πλὴν ἐκβολῆς, ἣν ἂν οἱ σύμπλοι ψηφισάμενοι κοινῇ ἐκβάλωνται, καὶ ἄν τι πολεμίοις ἀποτείσωσιν· τῶν δ’ ἄλλων ἁπάντων ἐντελές. καὶ παρέξουσι τοῖς δανείσασι τὴν ὑποθήκην ἀνέπαφον κρατεῖν, ἕως ἂν ἀποδῶσι τὸ γιγνόμενον ἀργύριον κατὰ τὴν συγγραφήν.", "st": "35.11"}, {"sp": "N", "t": "ἐὰν δὲ μὴ ἀποδῶσιν ἐν τῷ συγκειμένῳ χρόνῳ, τὰ ὑποκείμενα τοῖς δανείσασιν ἐξέστω ὑποθεῖναι καὶ ἀποδόσθαι τῆς ὑπαρχούσης τιμῆς· καὶ ἐάν τι ἐλλείπῃ τοῦ ἀργυρίου, ὃ δεῖ γενέσθαι τοῖς δανείσασι κατὰ τὴν συγγραφήν, παρὰ Ἀρτέμωνος καὶ Ἀπολλοδώρου ἔστω ἡ πρᾶξις τοῖς δανείσασι καὶ ἐκ τῶν τούτων ἁπάντων, καὶ ἐγγείων καὶ ναυτικῶν, πανταχοῦ ὅπου ἂν ὦσι, καθάπερ δίκην ὠφληκότων καὶ ὑπερημέρων ὄντων, καὶ ἑνὶ ἑκατέρῳ τῶν δανεισάντων καὶ ἀμφοτέροις.", "st": "35.12"}, {"sp": "N", "t": "ἐὰν δὲ μὴ εἰσβάλωσι, μείναντες ἐπὶ κυνὶ ἡμέρας δέκα ἐν Ἑλλησπόντῳ, ἐξελόμενοι ὅπου ἂν μὴ σῦλαι ὦσιν Ἀθηναίοις, καὶ ἐντεῦθεν καταπλεύσαντες Ἀθήναζε τοὺς τόκους ἀποδόντων τοὺς πέρυσι γραφέντας εἰς τὴν συγγραφήν. ἐὰν δέ τι ἡ ναῦς πάθῃ ἀνήκεστον ἐν ᾗ ἂν πλέῃ τὰ χρήματα, σωτηρία δ’ ἔσται τῶν ὑποκειμένων, τὰ περιγενόμενα κοινὰ ἔστω τοῖς δανείσασιν. κυριώτερον δὲ περὶ τούτων ἄλλο μηδὲν εἶναι τῆς συγγραφῆς.", "st": "35.13"}, {"sp": "N", "t": "Μάρτυρες· Φορμίων Πειραιεύς, Κηφισόδοτος Βοιώτιος, Ἡλιόδωρος Πιθεύς.", "st": "35.13"}, {"sp": "N", "t": "λέγε δὴ καὶ τὰς μαρτυρίας.", "st": "35.14"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ", "st": "35.14"}, {"sp": "N", "t": "Ἀρχενομίδης Ἀρχεδάμαντος Ἀναγυράσιος μαρτυρεῖ συνθήκας παρ’ ἑαυτῷ καταθέσθαι Ἀνδροκλέα Σφήττιον, Ναυσικράτην Καρύστιον, Ἀρτέμωνα, Ἀπολλόδωρον Φασηλίτας, καὶ εἶναι παρ’ ἑαυτῷ ἔτι κειμένην τὴν συγγραφήν.", "st": "35.14"}, {"sp": "N", "t": "λέγε δὴ καὶ τὴν τῶν παραγενομένων μαρτυρίαν.", "st": "35.14"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "35.14"}, {"sp": "N", "t": "Θεόδοτος ἰσοτελής, Χαρῖνος Ἐπιχάρους Λευκονοεύς, Φορμίων Κτησιφῶντος Πειραιεύς, Κηφισόδοτος Βοιώτιος, Ἡλιόδωρος Πιθεὺς μαρτυροῦσι παρεῖναι, ὅτ’ ἐδάνεισεν Ἀνδροκλῆς Ἀπολλοδώρῳ καὶ Ἀρτέμωνι ἀργυρίου τρισχιλίας δραχμάς, καὶ εἰδέναι τὴν συγγραφὴν καταθεμένους παρὰ Ἀρχενομίδῃ Ἀναγυρασίῳ.", "st": "35.14"}, {"sp": "N", "t": "κατὰ τὴν συγγραφὴν ταύτην, ὦ ἄνδρες δικασταί, ἐδάνεισα τὰ χρήματα Ἀρτέμωνι τῷ τούτου ἀδελφῷ, κελεύοντος τούτου καὶ ἀναδεχομένου ἅπαντα ἔσεσθαί μοι τὰ δίκαια κατὰ τὴν συγγραφήν, καθ’ ἣν ἐδάνεισα τούτου αὐτοῦ γράφοντος καὶ συσσημηναμένου, ἐπειδὴ ἐγράφη. οἱ μὲν γὰρ ἀδελφοὶ οἱ τούτου ἔτι νεώτεροι ἦσαν, μειράκια κομιδῇ, οὑτοσὶ δὲ Λάκριτος Φασηλίτης, μέγα πρᾶγμα, Ἰσοκράτους μαθητής·", "st": "35.15"}, {"sp": "N", "t": "οὗτος ἦν ὁ πάντα διοικῶν, καὶ ἑαυτῷ με τὸν νοῦν προσέχειν ἐκέλευεν· αὐτὸς γὰρ ἔφη ποιήσειν μοι τὰ δίκαια ἅπαντα καὶ ἐπιδημήσειν Ἀθήνησιν, τὸν δὲ ἀδελφὸν τὸν ἑαυτοῦ Ἀρτέμωνα πλεύσεσθαι ἐπὶ τοῖς χρήμασιν. καὶ τότε μέν, ὦ ἄνδρες δικασταί, ὅτ’ ἐβούλετο τὰ χρήματα λαβεῖν παρ’ ἡμῶν, καὶ ἀδελφὸς ἔφη εἶναι καὶ κοινωνὸς τοῦ Ἀρτέμωνος, καὶ λόγους θαυμασίως ὡς πιθανοὺς ἔλεγεν·", "st": "35.16"}, {"sp": "N", "t": "ἐπειδὴ δὲ τάχιστα ἐγκρατεῖς ἐγένοντο τοῦ ἀργυρίου, τοῦτο μὲν διενείμαντο καὶ ἐχρῶντο ὅ τι ἐδόκει τούτοις, κατὰ δὲ τὴν συγγραφὴν τὴν ναυτικήν, καθ’ ἣν ἔλαβον τὰ χρήματα, οὔτε μέγα οὔτε μικρὸν ἔπραττον, ὡς αὐτὸ τὸ ἔργον ἐδήλωσεν. οὑτοσὶ δὲ Λάκριτος ἁπάντων ἦν τούτων ὁ ἐξηγητής. καθ’ ἕκαστον δὲ τῶν γεγραμμένων ἐν τῇ συγγραφῇ ἐπιδείξω τούτους οὐδ’ ὁτιοῦν πεποιηκότας ὑγιές.", "st": "35.17"}, {"sp": "N", "t": "πρῶτον μὲν γὰρ γέγραπται ὅτι ἐπ’ οἴνου κεραμίοις τρισχιλίοις ἐδανείζοντο παρ’ ἡμῶν τὰς τριάκοντα μνᾶς, ὡς ὑπαρχούσης αὐτοῖς ὑποθήκης ἑτέρων τριάκοντα μνῶν, ὥστε εἰς τάλαντον ἀργυρίου τὴν τιμὴν εἶναι τοῦ οἴνου καθισταμένην, σὺν τοῖς ἀναλώμασιν, ὅσα ἔδει ἀναλίσκεσθαι εἰς τὴν κατασκευὴν τὴν περὶ τὸν οἶνον· τὰ δὲ τρισχίλια κεράμια ἄγεσθαι ταῦτα εἰς τὸν Πόντον ἐν τῇ εἰκοσόρῳ ἣν Ὑβλήσιος ἐναυκλήρει.", "st": "35.18"}, {"sp": "N", "t": "γέγραπται μὲν ταῦτα ἐν τῇ συγγραφῇ, ὦ ἄνδρες δικασταί, ἧς ὑμεῖς ἀκηκόατε· οὗτοι δὲ ἀντὶ τῶν τρισχιλίων κεραμίων οὐδὲ πεντακόσια κεράμια εἰς τὸ πλοῖον ἐνέθεντο, ἀλλ’ ἀντὶ τοῦ ἠγοράσθαι αὐτοῖς τὸν οἶνον, ὅσον προσῆκεν, τοῖς χρήμασιν ἐχρῶντο ὅ τι ἐδόκει τούτοις, τὰ δὲ κεράμια τὰ τρισχίλια οὐδ’ ἐμέλλησαν οὐδὲ διενοήθησαν ἐνθέσθαι εἰς τὸ πλοῖον κατὰ τὴν συγγραφήν. ὅτι δ’ ἀληθῆ ταῦτα λέγω, λαβὲ τὴν μαρτυρίαν τῶν συμπλεόντων ἐν τῷ αὐτῷ πλοίῳ τούτοις.", "st": "35.19"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "35.19"}, {"sp": "N", "t": "Ἐρασικλῆς μαρτυρεῖ κυβερνᾶν τὴν ναῦν ἣν Ὑβλήσιος ἐναυκλήρει, καὶ εἰδέναι Ἀπολλόδωρον ἀγόμενον ἐν τῷ πλοίῳ οἴνου Μενδαίου κεράμια τετρακόσια πεντήκοντα, καὶ οὐ πλείω· ἄλλο δὲ μηδὲν ἀγώγιμον ἄγεσθαι ἐν τῷ πλοίῳ Ἀπολλόδωρον εἰς τὸν Πόντον.", "st": "35.20"}, {"sp": "N", "t": "Ἱππίας Ἀθηνίππου Ἁλικαρνασσεὺς μαρτυρεῖ συμπλεῖν ἐν τῇ Ὑβλησίου νηὶ διοπεύων τὴν ναῦν, καὶ εἰδέναι Ἀπολλόδωρον τὸν Φασηλίτην ἀγόμενον ἐν τῷ πλοίῳ ἐκ Μένδης εἰς τὸν Πόντον οἴνου Μενδαίου κεράμια τετρακόσια πεντήκοντα, ἄλλο δὲ μηδὲν φορτίον.", "st": "35.20"}, {"sp": "N", "t": "πρὸς τούσδ’ ἐξεμαρτύρησεν· Ἀρχιάδης Μνησωνίδου Ἀχαρνεύς, Σώστρατος Φιλίππου Ἑστιαιόθεν, Εὐμάριχος Εὐβοίου Ἑστιαιόθεν, Φιλτάδης Κτησίου Ξυπεταιών, Διονύσιος Δημοκρατίδου Χολλῄδης.", "st": "35.20"}, {"sp": "N", "t": "περὶ μὲν οὖν τοῦ πλήθους τοῦ οἴνου, ὅσον ἔδει αὐτοὺς ἐνθέσθαι εἰς τὸ πλοῖον, ταῦτα διεπράξαντο, καὶ ἤρξαντο εὐθὺς ἐντεῦθεν ἀπὸ τοῦ πρώτου γεγραμμένου παραβαίνειν καὶ μὴ ποιεῖν τὰ γεγραμμένα. μετὰ δὲ ταῦτ’ ἔστιν ἐν τῇ συγγραφῇ ὅτι ὑποτιθέασιν ταῦτα ἐλεύθερα καὶ οὐδενὶ οὐδὲν ὀφείλοντες, καὶ ὅτι οὐδ’ ἐπιδανείσονται ἐπὶ τούτοις παρ’ οὐδενός. ταῦτα διαρρήδην γέγραπται, ὦ ἄνδρες δικασταί.", "st": "35.21"}, {"sp": "N", "t": "οὗτοι δὲ τί ἐποίησαν; ἀμελήσαντες τῶν γεγραμμένων ἐν τῇ συγγραφῇ δανείζονται παρά τινος νεανίσκου, ἐξαπατήσαντες ὡς οὐδενὶ οὐδὲν ὀφείλοντες· καὶ ἡμᾶς τε παρεκρούσαντο καὶ ἔλαθον δανεισάμενοι ἐπὶ τοῖς ἡμετέροις, ἐκεῖνόν τε τὸν νεανίσκον τὸν δανείσαντα ἐξηπάτησαν ὡς ἐπ’ ἐλευθέροις τοῖς χρήμασιν δανειζόμενοι· τοιαῦτα τούτων ἐστὶν τὰ κακουργήματα. ταῦτα δὲ πάντ’ ἐστὶν τὰ σοφίσματα Λακρίτου τουτουί. ὅτι δὲ ἀληθῆ λέγω καὶ ἐπεδανείσαντο χρήματα παρὰ τὴν συγγραφήν, μαρτυρίαν ἀναγνώσεται ὑμῖν αὐτοῦ τοῦ ἐπιδανείσαντος.", "st": "35.22"}, {"sp": "N", "t": "λέγε τὴν μαρτυρίαν.", "st": "35.23"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "35.23"}, {"sp": "N", "t": "Ἄρατος Ἁλικαρνασσεὺς μαρτυρεῖ δανεῖσαι Ἀπολλοδώρῳ ἕνδεκα μνᾶς ἀργυρίου ἐπὶ τῇ ἐμπορίᾳ, ἣν ἦγεν ἐν τῇ Ὑβλησίου νηὶ εἰς τὸν Πόντον, καὶ τοῖς ἐκεῖθεν ἀνταγορασθεῖσι, καὶ μὴ εἰδέναι αὐτὸν δεδανεισμένον παρὰ Ἀνδροκλέους ἀργύριον· οὐ γὰρ ἂν δανεῖσαι αὐτὸς Ἀπολλοδώρῳ τὸ ἀργύριον.", "st": "35.23"}, {"sp": "N", "t": "αἱ μὲν πανουργίαι τοιαῦται τῶν ἀνθρώπων τούτων εἰσίν. γέγραπται δὲ μετὰ ταῦτα ἐν τῇ συγγραφῇ, ὦ ἄνδρες δικασταί, ἐπειδὰν ἀποδῶνται ἐν τῷ Πόντῳ ἃ ἦγον, πάλιν ἀνταγοράζειν χρήματα καὶ ἀντιφορτίζεσθαι καὶ ἀπάγειν Ἀθήναζε τὰ ἀντιφορτισθέντα, καὶ ἐπειδὰν ἀφίκωνται Ἀθήναζε, ἀποδοῦναι εἴκοσιν ἡμερῶν τὸ ἀργύριον ἡμῖν δόκιμον· ἕως δ’ ἂν ἀποδῶσιν, κρατεῖν τῶν χρημάτων ἡμᾶς, καὶ ἀνέπαφα ταῦτα παρέχειν τούτους, ἕως ἂν ἀπολάβωμεν.", "st": "35.24"}, {"sp": "N", "t": "γέγραπται μὲν ταῦτα οὑτωσὶ ἀκριβῶς ἐν τῇ συγγραφῇ· οὗτοι δέ, ὦ ἄνδρες δικασταί, ἐνταῦθα καὶ ἐπεδείξαντο μάλιστα τὴν ὕβριν καὶ τὴν ἀναίδειαν τὴν ἑαυτῶν, καὶ ὅτι οὐδὲ μικρὸν προσεῖχον τοῖς γράμμασι τοῖς γεγραμμένοις ἐν τῇ συγγραφῇ, ἀλλ’ ἡγοῦντο εἶναι τὴν συγγραφὴν ἄλλως ὕθλον καὶ φλυαρίαν. οὔτε γὰρ ἀντηγόρασαν οὐδὲν ἐν τῷ Πόντῳ οὔτε ἀντεφορτίσαντο ὥστε ἄγειν Ἀθήναζε· ἡμεῖς τε οἱ δανείσαντες τὰ χρήματα ἡκόντων αὐτῶν τούτων ἐκ τοῦ Πόντου οὐκ εἴχομεν ὅτου ἐπιλαβοίμεθα οὐδ’ ὅτου κρατοῖμεν, ἕως κομισαίμεθα τὰ ἡμέτερ’ αὐτῶν· οὐδ’ ὁτιοῦν γὰρ εἰσήγαγον εἰς τὸν λιμένα τὸν ὑμέτερον οὗτοι.", "st": "35.25"}, {"sp": "N", "t": "ἀλλὰ πεπόνθαμεν καινότατον, ὦ ἄνδρες δικασταί· ἐν γὰρ τῇ πόλει τῇ ἡμετέρᾳ αὐτῶν, οὐδὲν ἀδικοῦντες οὐδὲ δίκην οὐδεμίαν ὠφληκότες τούτοις, σεσυλήμεθα τὰ ἡμέτερ’ αὐτῶν ὑπὸ τούτων Φασηλιτῶν ὄντων, ὥσπερ δεδομένων συλῶν Φασηλίταις κατ’ Ἀθηναίων. ἐπειδὰν γὰρ μὴ ἐθέλωσιν ἀποδοῦναι ἃ ἔλαβον, τί ἄν τις ἄλλο ὄνομα ἔχοι θέσθαι τοῖς τοιούτοις ἢ ὅτι ἀφαιροῦνται βίᾳ τὰ ἀλλότρια; ἐγὼ μὲν οὐδὲ ἀκήκοα πώποτε πρᾶγμα μιαρώτερον ἢ ὃ οὗτοι διαπεπραγμένοι εἰσὶ περὶ ἡμᾶς, καὶ ταῦτα ὁμολογοῦντες λαβεῖν παρ’ ἡμῶν τὰ χρήματα.", "st": "35.26"}, {"sp": "N", "t": "ὅσα μὲν γὰρ ἀμφισβητήσιμά ἐστι τῶν συμβολαίων, κρίσεως δεῖται, ὦ ἄνδρες δικασταί· τὰ δὲ παρ’ ἀμφοτέρων ὁμολογηθέντα τῶν συντιθεμένων, καὶ περὶ ὧν συγγραφαὶ κεῖνται ναυτικαί, τέλος ἔχειν ἅπαντες νομίζουσιν, καὶ χρῆσθαι προσήκει τοῖς γεγραμμένοις. ὅτι δὲ κατὰ τὴν συγγραφὴν οὐδ’ ὁτιοῦν πεποιήκασιν, ἀλλ’ εὐθὺς ἀπ’ ἀρχῆς ἀρξάμενοι ἐκακοτέχνουν καὶ ἐπεβούλευον μηδὲν ὑγιὲς ποιεῖν, ὑπό τε τῶν μαρτυριῶν καὶ αὐτοὶ ὑφ’ ἑαυτῶν ἐλέγχονται οὑτωσὶ καταφανῶς.", "st": "35.27"}, {"sp": "N", "t": "ὃ δὲ πάντων δεινότατον διεπράξατο Λάκριτος οὑτοσί, δεῖ ὑμᾶς ἀκοῦσαι· οὗτος γὰρ ἦν ὁ πάντα ταῦτα διοικῶν. ἐπειδὴ γὰρ ἀφίκοντο δεῦρο, εἰς μὲν τὸ ὑμέτερον ἐμπόριον οὐ καταπλέουσιν, εἰς φωρῶν δὲ λιμένα ὁρμίζονται, ὅς ἐστιν ἔξω τῶν σημείων τοῦ ὑμετέρου ἐμπορίου, καὶ ἔστιν ὅμοιον εἰς φωρῶν λιμένα ὁρμίσασθαι, ὥσπερ ἂν εἴ τις εἰς Αἴγιναν ἢ εἰς Μέγαρα ὁρμίσαιτο· ἔξεστι γὰρ ἀποπλεῖν ἐκ τοῦ λιμένος τούτου ὅποι ἄν τις βούληται καὶ ὁπηνίκ’ ἂν δοκῇ αὐτῷ.", "st": "35.28"}, {"sp": "N", "t": "καὶ τὸ μὲν πλοῖον ὥρμει ἐνταῦθα πλείους ἢ πέντε καὶ εἴκοσιν ἡμέρας, οὗτοι δὲ περιεπάτουν ἐν τῷ δείγματι τῷ ἡμετέρῳ, καὶ ἡμεῖς προσιόντες διελεγόμεθα, καὶ ἐκελεύομεν τούτους ἐπιμελεῖσθαι ὅπως ἂν ὡς τάχιστα ἀπολάβωμεν τὰ χρήματα. οὗτοι δὲ ὡμολόγουν τε καὶ ἔλεγον ὅτι αὐτὰ ταῦτα περαίνοιεν. καὶ ἡμεῖς τούτοις προσῇμεν, καὶ ἅμα ἐπεσκοποῦμεν εἴ τι ἐξαιροῦνταί ποθεν ἐκ πλοίου ἢ πεντηκοστεύονται.", "st": "35.29"}, {"sp": "N", "t": "ἐπειδὴ δὲ ἡμέραι τε ἦσαν συχναὶ ἐπιδημοῦσι τούτοις, ἡμεῖς τε οὐδ’ ὁτιοῦν εὑρίσκομεν οὔτ’ ἐξῃρημένον οὔτε πεπεντηκοστευμένον ἐπὶ τῷ ὀνόματι τῷ τούτων, ἐνταῦθα ἤδη μᾶλλον προσεκείμεθα ἀπαιτοῦντες. καὶ ἐπειδὴ ἠνωχλοῦμεν αὐτοῖς, ἀποκρίνεται Λάκριτος οὑτοσί, ἁδελφὸς ὁ Ἀρτέμωνος, ὅτι οὐκ ἂν οἷοί τ’ εἴησαν ἀποδοῦναι, ἀλλ’ ἀπόλωλεν ἅπαντα τὰ χρήματα· καὶ ἔφη Λάκριτος δίκαιόν τι ἔχειν λέγειν περὶ τούτων.", "st": "35.30"}, {"sp": "N", "t": "καὶ ἡμεῖς, ὦ ἄνδρες δικασταί, ἠγανακτοῦμεν ἐπὶ τοῖς λεγομένοις, πλέον δὲ οὐδὲν ἦν ἀγανακτοῦσιν ἡμῖν· τούτοις γὰρ οὐδ’ ὁτιοῦν ἔμελεν. οὐδὲν δ’ ἧττον ἠρωτῶμεν αὐτούς, ὅντινα τρόπον ἀπολωλότα εἴη τὰ χρήματα. Λάκριτος δὲ οὑτοσὶ ναυαγῆσαι ἔφη τὸ πλοῖον παραπλέον ἐκ Παντικαπαίου εἰς Θεοδοσίαν, ναυαγήσαντος δὲ τοῦ πλοίου ἀπολωλέναι τὰ χρήματα τοῖς ἀδελφοῖς τοῖς ἑαυτοῦ, ἃ ἔτυχεν ἐν τῷ πλοίῳ ἐνόντα· ἐνεῖναι δὲ τάριχός τε καὶ οἶνον Κῷον καὶ ἄλλ’ ἄττα, καὶ ταῦτα ἔφασαν πάντα ἀντιφορτισθέντα μέλλειν ἀπάγειν Ἀθήναζε, εἰ μὴ ἀπώλετο ἐν τῷ πλοίῳ.", "st": "35.31"}, {"sp": "N", "t": "καὶ ἃ μὲν ἔλεγεν, ταῦτ’ ἦν· ἄξιον δὲ ἀκοῦσαι τὴν βδελυρίαν τῶν ἀνθρώπων τούτων καὶ τὴν ψευδολογίαν. πρός τε γὰρ τὸ πλοῖον τὸ ναυαγῆσαν οὐδὲν ἦν αὐτοῖς συμβόλαιον, ἀλλ’ ἦν ἕτερος ὁ δεδανεικὼς Ἀθήνηθεν ἐπὶ τῷ ναύλῳ τῷ εἰς τὸν Πόντον καὶ ἐπ’ αὐτῷ τῷ πλοίῳ (Ἀντίπατρος ὄνομα ἦν τῷ δεδανεικότι, Κιτιεὺς τὸ γένος)· τό τε οἰνάριον τὸ Κῷον ὀγδοήκοντα στάμνοι ἐξεστηκότος οἴνου, καὶ τὸ τάριχος ἀνθρώπῳ τινὶ γεωργῷ παρεκομίζετο ἐν τῷ πλοίῳ ἐκ Παντικαπαίου εἰς Θεοδοσίαν τοῖς ἐργάταις τοῖς περὶ τὴν γεωργίαν χρῆσθαι. τί οὖν ταύτας τὰς προφάσεις λέγουσιν; οὐδὲν γὰρ προσήκει.", "st": "35.32"}, {"sp": "N", "t": "καί μοι λαβὲ τὴν μαρτυρίαν, πρῶτον μὲν τὴν Ἀπολλωνίδου, ὅτι Ἀντίπατρος ἦν ὁ δανείσας ἐπὶ τῷ πλοίῳ, τούτοις δ’ οὐδ’ ὁτιοῦν προσήκει τῆς ναυαγίας, ἔπειτα τὴν Ἐρασικλέους καὶ τὴν Ἱππίου, ὅτι ὀγδοήκοντα μόνον κεράμια παρήγετο ἐν τῷ πλοίῳ.", "st": "35.33"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "35.33"}, {"sp": "N", "t": "Ἀπολλωνίδης Ἁλικαρνασσεὺς μαρτυρεῖ εἰδέναι δανείσαντα Ἀντίπατρον, Κιτιέα τὸ γένος, χρήματα Ὑβλησίῳ εἰς τὸν Πόντον ἐπὶ τῇ νηὶ ἣν Ὑβλήσιος ἐναυκλήρει, καὶ τῷ ναύλῳ τῷ εἰς τὸν Πόντον· κοινωνεῖν δὲ καὶ αὑτὸν τῆς νεὼς Ὑβλησίῳ, καὶ συμπλεῖν ἑαυτοῦ οἰκέτας ἐν τῇ νηί, καὶ ὅτε διεφθάρη ἡ ναῦς, παρεῖναι τοὺς οἰκέτας τοὺς ἑαυτοῦ καὶ ἀπαγγέλλειν ἑαυτῷ, καὶ ὅτι ἡ ναῦς κενὴ διεφθάρη παραπλέουσα εἰς Θευδοσίαν ἐκ Παντικαπαίου.", "st": "35.33"}, {"sp": "N", "t": "Ἐρασικλῆς μαρτυρεῖ συμπλεῖν Ὑβλησίῳ κυβερνῶν τὴν ναῦν εἰς τὸν Πόντον, καὶ ὅτε παρέπλει ἡ ναῦς εἰς Θευδοσίαν ἐκ Παντικαπαίου, εἰδέναι κενὴν τὴν ναῦν παραπλέουσαν, καὶ Ἀπολλοδώρου αὐτοῦ τοῦ φεύγοντος νυνὶ τὴν δίκην μὴ εἶναι οἶνον ἐν τῷ πλοίῳ, ἀλλὰ παράγεσθαι τῶν ἐκ Θευδοσίας τινὶ οἴνου Κῷα κεράμια περὶ ὀγδοήκοντα.", "st": "35.34"}, {"sp": "N", "t": "Ἱππίας Ἀθηνίππου Ἁλικαρνασσεὺς μαρτυρεῖ συμπλεῖν Ὑβλησίῳ διοπεύων τὴν ναῦν, καὶ ὅτε παρέπλει ἡ ναῦς εἰς Θευδοσίαν ἐκ Παντικαπαίου, ἐνθέσθαι Ἀπολλόδωρον εἰς τὴν ναῦν ἐρίων ἀγγεῖον ἓν ἢ δύο καὶ ταρίχους κεράμια ἕνδεκα ἢ δώδεκα καὶ δέρματ’ αἴγεια, δύο δέσμας ἢ τρεῖς, ἄλλο δ’ οὐδέν.", "st": "35.34"}, {"sp": "N", "t": "πρὸς τούσδ’ ἐξεμαρτύρησεν· Εὐφίλητος Δαμοτίμου Ἀφιδναῖος, Ἱππίας Τιμοξένου Θυμαιτάδης, Σώστρατος Φιλίππου Ἑστιαιόθεν, Ἀρχενομίδης Στράτωνος Θριάσιος, Φιλτάδης Κτησικλέους Ξυπεταιών.", "st": "35.34"}, {"sp": "N", "t": "ἡ μὲν ἀναίδεια τοιαύτη τῶν ἀνθρώπων τούτων ἐστίν. ὑμεῖς δέ, ὦ ἄνδρες δικασταί, ἐνθυμεῖσθε πρὸς ὑμᾶς αὐτούς, εἴ τινας πώποτ’ ἴστε ἢ ἠκούσατε οἶνον Ἀθήναζε ἐκ τοῦ Πόντου κατ’ ἐμπορίαν εἰσαγαγόντας, ἄλλως τε καὶ Κῷον. πᾶν γὰρ δήπου τοὐναντίον εἰς τὸν Πόντον ὁ οἶνος εἰσάγεται ἐκ τῶν τόπων τῶν περὶ ἡμᾶς, ἐκ Πεπαρήθου καὶ Κῶ καὶ Θάσιος καὶ Μενδαῖος καὶ ἐξ ἄλλων τινῶν πόλεων παντοδαπός· ἐκ δὲ τοῦ Πόντου ἕτερά ἐστιν ἃ εἰσάγεται δεῦρο.", "st": "35.35"}, {"sp": "N", "t": "κατεχόμενοι δὲ ὑφ’ ἡμῶν καὶ ἐλεγχόμενοι εἴ τι περιγένοιτο τῶν χρημάτων ἐν τῷ Πόντῳ, ἀπεκρίνατο Λάκριτος οὑτοσί, ὅτι ἑκατὸν στατῆρες Κυζικηνοὶ περιγένοιντο, καὶ τοῦτο τὸ χρυσίον δεδανεικὼς εἴη ἁδελφὸς αὐτοῦ ἐν τῷ Πόντῳ ναυκλήρῳ τινὶ Φασηλίτῃ, πολίτῃ καὶ ἐπιτηδείῳ ἑαυτοῦ, καὶ οὐ δύναιτο κομίσασθαι, ἀλλὰ σχεδόν τι ἀπολωλὸς εἴη καὶ τοῦτο.", "st": "35.36"}, {"sp": "N", "t": "ταῦτ’ ἐστὶν ἃ ἔλεγεν Λάκριτος οὑτοσί. ἡ δὲ συγγραφὴ οὐ ταῦτα λέγει, ὦ ἄνδρες δικασταί, ἀλλ’ ἀντιφορτισαμένους ἀπάγειν κελεύει Ἀθήναζε, οὐ δανείζειν τούτους ὅτῳ ἂν βούλωνται ἐν τῷ Πόντῳ τὰ ἡμέτερα ἄνευ ἡμῶν, ἀλλ’ Ἀθήναζε παρέχειν ἀνέπαφα ἡμῖν, ἕως ἂν ἡμεῖς ἀπολάβωμεν τὰ χρήματα ὅσα ἐδανείσαμεν. καί μοι ἀναγίγνωσκε τὴν συγγραφὴν πάλιν.", "st": "35.37"}, {"sp": "N", "t": "ΣΥΓΓΡΑΦΗ.", "st": "35.37"}, {"sp": "N", "t": "πότερον, ὦ ἄνδρες δικασταί, δανείζειν κελεύει τούτους ἡ συγγραφὴ τὰ ἡμέτερα, καὶ ταῦτα ἀνθρώπῳ ὃν ἡμεῖς οὔτε γιγνώσκομεν οὔθ’ ἑοράκαμεν πώποτε, ἢ ἀντιφορτισαμένους κομίσαι Ἀθήναζε καὶ φανερὰ ποιῆσαι ἡμῖν καὶ ἀνέπαφα παρέχειν;", "st": "35.38"}, {"sp": "N", "t": "ἡ μὲν γὰρ συγγραφὴ οὐδὲν κυριώτερον ἐᾷ εἶναι τῶν ἐγγεγραμμένων, οὐδὲ προσφέρειν οὔτε νόμον οὔτε ψήφισμα οὔτ’ ἄλλ’ οὐδ’ ὁτιοῦν πρὸς τὴν συγγραφήν· τούτοις δ’ εὐθὺς ἐξ ἀρχῆς οὐδὲν ἐμέλησε τῆς συγγραφῆς ταύτης, ἀλλὰ τοῖς χρήμασιν ἐχρῶντο τοῖς ἡμετέροις ὥσπερ ἰδίοις οὖσιν αὑτῶν· οὕτως εἰσὶν οὗτοι κακοῦργοι σοφισταὶ καὶ ἄδικοι ἄνθρωποι.", "st": "35.39"}, {"sp": "N", "t": "ἐγὼ δέ, μὰ τὸν Δία τὸν ἄνακτα καὶ τοὺς θεοὺς ἅπαντας, οὐδενὶ πώποτε ἐφθόνησα οὐδ’ ἐπετίμησα, ὦ ἄνδρες δικασταί, εἴ τις βούλεται σοφιστὴς εἶναι καὶ Ἰσοκράτει ἀργύριον ἀναλίσκειν· μαινοίμην γὰρ ἄν, εἴ τί μοι τούτων ἐπιμελὲς εἴη. οὐ μέντοι μὰ Δία οἶμαί γε δεῖν ἀνθρώπους καταφρονοῦντας καὶ οἰομένους δεινοὺς εἶναι ἐφίεσθαι τῶν ἀλλοτρίων, οὐδὲ ἀφαιρεῖσθαι, τῷ λόγῳ πιστεύοντας· πονηροῦ γὰρ ταῦτ’ ἐστὶν σοφιστοῦ καὶ οἰμωξομένου.", "st": "35.40"}, {"sp": "N", "t": "Λάκριτος δ’ οὑτοσί, ὦ ἄνδρες δικασταί, οὐ τῷ δικαίῳ πιστεύων εἰσελήλυθε ταύτην τὴν δίκην, ἀλλ’ ἀκριβῶς εἰδὼς τὰ πεπραγμέν’ αὑτοῖς περὶ τὸ δάνεισμα τοῦτο, καὶ ἡγούμενος δεινὸς εἶναι καὶ ῥᾳδίως λόγους ποριεῖσθαι περὶ ἀδίκων πραγμάτων, οἴεται παράξειν ὑμᾶς ὅποι ἂν βούληται. ταῦτα γὰρ ἐπαγγέλλεται δεινὸς εἶναι, καὶ ἀργύριον αἰτεῖ καὶ μαθητὰς συλλέγει περὶ αὐτῶν τούτων ἐπαγγελλόμενος παιδεύειν.", "st": "35.41"}, {"sp": "N", "t": "καὶ πρῶτον μὲν τοὺς ἀδελφοὺς τοὺς αὑτοῦ ἐπαίδευσεν τὴν παιδείαν ταύτην, ἣν ὑμεῖς αἰσθάνεσθε πονηρὰν καὶ ἄδικον, ὦ ἄνδρες δικασταί, δανείζεσθαι ἐν τῷ ἐμπορίῳ ναυτικὰ χρήματα καὶ ταῦτ’ ἀποστερεῖν καὶ μὴ ἀποδιδόναι. πῶς ἂν γένοιντο πονηρότεροι ἄνθρωποι ἢ τοῦ παιδεύοντος τὰ τοιαῦτα ἢ αὐτῶν τῶν παιδευομένων; ἐπεὶ δ’ οὖν δεινός ἐστιν καὶ πιστεύει τῷ λέγειν καὶ ταῖς χιλίαις δραχμαῖς ἃς δέδωκεν τῷ διδασκάλῳ,", "st": "35.42"}, {"sp": "N", "t": "κελεύσατε αὐτὸν διδάξαι ὑμᾶς, ἢ ὡς τὰ χρήματα οὐκ ἔλαβον παρ’ ἡμῶν, ἢ ὡς λαβόντες ἀποδεδώκασιν, ἢ ὅτι τὰς ναυτικὰς συγγραφὰς οὐ δεῖ κυρίας εἶναι, ἢ ὡς δεῖ ἄλλο τι χρήσασθαι τοῖς χρήμασιν ἢ ἐφ’ οἷς ἔλαβον κατὰ τὴν συγγραφήν. τούτων ὅ τι βούλεται πεισάτω ὑμᾶς. καὶ ἔγωγε καὶ αὐτὸς συγχωρῶ σοφώτατον εἶναι τοῦτον, ἐὰν ὑμᾶς πείσῃ τοὺς περὶ τῶν συμβολαίων τῶν ἐμπορικῶν δικάζοντας. ἀλλ’ εὖ οἶδ’ ὅτι οὐδὲν ἂν τούτων οἷός τ’ εἴη οὗτος οὔτε διδάξαι οὔτε πεῖσαι.", "st": "35.43"}, {"sp": "N", "t": "χωρὶς δὲ τούτων, φέρε πρὸς τῶν θεῶν, ὦ ἄνδρες δικασταί, εἰ τοὐναντίον συνεβεβήκει, μὴ ὁ τούτου ἀδελφὸς ὁ τετελευτηκὼς ἐμοὶ ὤφειλε χρήματα, ἀλλ’ ἐγὼ τῷ τούτου, τάλαντον ἢ ὀγδοήκοντα μνᾶς ἢ πλέον ἢ ἔλαττον, ἆρ’ ἂν οἴεσθε Λάκριτον τουτονί, ὦ ἄνδρες δικασταί, τοὺς αὐτοὺς λόγους λέγειν οἷσπερ νυνὶ κατακέχρηται, ἢ φάσκειν αὑτὸν οὐκ εἶναι κληρονόμον ἢ ἀφίστασθαι τῶν τοῦ ἀδελφοῦ, καὶ οὐκ ἂν πάνυ πικρῶς εἰσπράττειν με, ὥσπερ καὶ παρὰ τῶν ἄλλων εἰσπέπρακται, εἴ τίς τι ἐκείνῳ τῷ τετελευτηκότι ὤφειλεν ἢ ἐν Φασήλιδι ἢ ἄλλοθί που;", "st": "35.44"}, {"sp": "N", "t": "καὶ εἴ γέ τις ἡμῶν φεύγων δίκην ὑπὸ τούτου παραγραφὴν ἐτόλμησε παραγράφεσθαι, μὴ εἰσαγώγιμον εἶναι τὴν δίκην, εὖ οἶδ’ ὅτι ἠγανάκτει ἂν αὐτὸς καὶ ἐσχετλίαζε πρὸς ὑμᾶς, δεινὰ φάσκων πάσχειν καὶ παρανομεῖσθαι, εἰ μή τις αὐτῷ τὴν δίκην ψηφιεῖται εἰσαγώγιμον εἶναι, ἐμπορικὴν οὖσαν. ἔπειτα, ὦ Λάκριτε, σοὶ μὲν τοῦτο δίκαιον δοκεῖ εἶναι, ἐμοὶ δὲ διὰ τί οὐκ ἔσται; οὐχ ἅπασιν ἡμῖν οἱ αὐτοὶ νόμοι γεγραμμένοι εἰσὶν καὶ τὸ αὐτὸ δίκαιον περὶ τῶν ἐμπορικῶν δικῶν;", "st": "35.45"}, {"sp": "N", "t": "ἀλλ’ οὕτως βδελυρός τίς ἐστι καὶ ὑπερβάλλων ἅπαντας ἀνθρώπους τῷ πονηρὸς εἶναι, ὥστ’ ἐπιχειρεῖ πείθειν ὑμᾶς ψηφίσασθαι μὴ εἰσαγώγιμον εἶναι τὴν ἐμπορικὴν δίκην ταύτην, δικαζόντων ὑμῶν νυνὶ τὰς ἐμπορικὰς δίκας. ἀλλὰ τί κελεύεις, ὦ Λάκριτε; μὴ ἱκανὸν εἶναι ἡμᾶς ἀποστερεῖσθαι ἃ ἐδανείσαμεν χρήματα ὑμῖν, ἀλλὰ καὶ εἰς τὸ δεσμωτήριον παραδοθῆναι ὑφ’ ὑμῶν προσοφλόντας τὰ ἐπιτίμια, ἐὰν μὴ ἐκτίνωμεν.", "st": "35.46"}, {"sp": "N", "t": "καὶ πῶς οὐκ ἂν δεινὸν εἴη καὶ σχέτλιον καὶ αἰσχρὸν ὑμῖν, ὦ ἄνδρες δικασταί, εἰ οἱ δανείσαντες ἐν τῷ ἐμπορίῳ τῷ ὑμετέρῳ χρήματα ναυτικὰ καὶ ἀποστερούμενοι ὑπὸ τῶν δανεισαμένων καὶ ἀποστερούντων ἀπάγοιντο εἰς τὸ δεσμωτήριον; ταῦτ’ ἐστίν, ὦ Λάκριτε, ἃ τουτουσὶ πείθεις. ἀλλὰ ποῦ χρὴ λαβεῖν δίκην, ὦ ἄνδρες δικασταί, περὶ τῶν ἐμπορικῶν συμβολαίων; παρὰ ποίᾳ ἀρχῇ ἢ ἐν τίνι χρόνῳ; παρὰ τοῖς ἕνδεκα; ἀλλὰ τοιχωρύχους καὶ κλέπτας καὶ τοὺς ἄλλους κακούργους τοὺς ἐπὶ θανάτῳ οὗτοι εἰσάγουσιν.", "st": "35.47"}, {"sp": "N", "t": "ἀλλὰ παρὰ τῷ ἄρχοντι; οὐκοῦν ἐπικλήρων καὶ ὀρφανῶν καὶ τῶν τοκέων τῷ ἄρχοντι προστέτακται ἐπιμελεῖσθαι. ἀλλὰ νὴ Δία παρὰ τῷ βασιλεῖ. ἀλλ’ οὐκ ἐσμὲν γυμνασίαρχοι, οὐδὲ ἀσεβείας οὐδένα γραφόμεθα. ἀλλ’ ὁ πολέμαρχος εἰσάξει. ἀποστασίου γε καὶ ἀπροστασίου. οὐκοῦν ὑπόλοιπόν ἐστιν οἱ στρατηγοί. ἀλλὰ τοὺς τριηράρχους καθιστᾶσιν, ἐμπορικὴν δὲ δίκην οὐδεμίαν εἰσάγουσιν.", "st": "35.48"}, {"sp": "N", "t": "ἐγὼ δ’ εἰμὶ ἔμπορος, καὶ σὺ ἀδελφὸς καὶ κληρονόμος ἑνὸς τῶν ἐμπόρων, τοῦ λαβόντος παρ’ ἡμῶν τὰ ἐμπορικὰ χρήματα. ποῖ οὖν δεῖ ταύτην εἰσελθεῖν τὴν δίκην; δίδαξον, ὦ Λάκριτε, μόνον δίκαιόν τι λέγων καὶ κατὰ τοὺς νόμους. ἀλλ’ οὐκ ἔστιν οὕτω δεινὸς ἄνθρωπος οὐδεὶς ὅστις ἂν περὶ τοιούτων πραγμάτων ἔχοι τι δίκαιον εἰπεῖν.", "st": "35.49"}, {"sp": "N", "t": "οὐ τοίνυν ταῦτα μόνον, ὦ ἄνδρες δικασταί, δεινὰ ἐγὼ πάσχω ὑπὸ Λακρίτου τουτουί, ἀλλὰ καὶ χωρὶς τοῦ ἀποστερεῖσθαι τὰ χρήματα καὶ εἰς τοὺς ἐσχάτους ἂν κινδύνους ἀφικόμην τὸ τούτου μέρος, εἰ μή μοι ἡ συγγραφὴ ἐβοήθει ἡ πρὸς τούτους, καὶ ἐμαρτύρει ὅτι εἰς τὸν Πόντον ἔδωκα τὰ χρήματα καὶ πάλιν Ἀθήναζε. ἴστε γάρ, ὦ ἄνδρες δικασταί, τὸν νόμον ὡς χαλεπός ἐστιν, ἐάν τις Ἀθηναίων ἄλλοσέ ποι σιτηγήσῃ ἢ Ἀθήναζε, ἢ χρήματα δανείσῃ εἰς ἄλλο τι ἐμπόριον ἢ τὸ Ἀθηναίων, οἷαι ζημίαι περὶ τούτων εἰσίν, ὡς μεγάλαι καὶ δειναί.", "st": "35.50"}, {"sp": "N", "t": "μᾶλλον δὲ αὐτὸν ἀνάγνωθι αὐτοῖς τὸν νόμον, ἵν’ ἀκριβέστερον μάθωσιν.", "st": "35.51"}, {"sp": "N", "t": "ΝΟΜΟΣ", "st": "35.51"}, {"sp": "N", "t": "ἀργύριον δὲ μὴ ἐξεῖναι ἐκδοῦναι Ἀθηναίων καὶ τῶν μετοίκων τῶν Ἀθήνησι μετοικούντων μηδενί, μηδὲ ὧν οὗτοι κύριοί εἰσιν, εἰς ναῦν ἥτις ἂν μὴ μέλλῃ ἄξειν σῖτον Ἀθήναζε, καὶ τἄλλα τὰ γεγραμμένα περὶ ἑκάστου αὐτῶν. ἐὰν δέ τις ἐκδῷ παρὰ ταῦτα, εἶναι τὴν φάσιν καὶ τὴν ἀπογραφὴν τοῦ ἀργυρίου πρὸς τοὺς ἐπιμελητάς, καθάπερ τῆς νεὼς καὶ τοῦ σίτου εἴρηται, κατὰ ταὐτά. καὶ δίκη αὐτῷ μὴ ἔστω περὶ τοῦ ἀργυρίου, ὃ ἂν ἐκδῷ ἄλλοσέ ποι ἢ Ἀθήναζε, μηδὲ ἀρχὴ εἰσαγέτω περὶ τούτου μηδεμία.", "st": "35.51"}, {"sp": "N", "t": "ὁ μὲν νόμος, ὦ ἄνδρες δικασταί, οὕτω χαλεπός ἐστιν· οὗτοι δὲ οἱ μιαρώτατοι ἀνθρώπων ἁπάντων, γεγραμμένον διαρρήδην ἐν τῇ συγγραφῇ Ἀθήναζε πάλιν ἥκειν τὰ χρήματα, εἰς Χίον ἐπέτρεψαν καταχθῆναι ἃ ἐδανείσαντο Ἀθήνηθεν παρ’ ἡμῶν. δανειζομένου γὰρ ἐν τῷ Πόντῳ τοῦ ναυκλήρου τοῦ Φασηλίτου ἕτερα χρήματα παρά τινος Χίου ἀνθρώπου, οὐ φάσκοντος δὲ τοῦ Χίου δανείσειν, ἐὰν μὴ ὑποθήκην λάβῃ ἅπαντα ὅσα ἦν περὶ τὸν ναύκληρον, καὶ ἐπιτρέπωσι ταῦτα οἱ πρότερον δεδανεικότες, ἐπέτρεψαν ταῦτα ὑποθήκην γενέσθαι τῷ Χίῳ τὰ ἡμέτερα καὶ κύριον ἐκεῖνον γενέσθαι ἁπάντων,", "st": "35.52"}, {"sp": "N", "t": "καὶ οὕτως ἀπέπλεον ἐκ τοῦ Πόντου μετὰ τοῦ Φασηλίτου ναυκλήρου καὶ μετὰ τοῦ Χίου τοῦ δεδανεικότος, καὶ ὁρμίζονται ἐν φωρῶν λιμένι, εἰς δὲ τὸ ὑμέτερον ἐμπόριον οὐχ ὡρμίσαντο. καὶ νυνί, ὦ ἄνδρες δικασταί, τὰ Ἀθήνηθεν δανεισθέντα χρήματα εἰς τὸν Πόντον καὶ πάλιν ἐκ τοῦ Πόντου Ἀθήναζε εἰς Χίον κατηγμένα ἐστὶν ὑπὸ τούτων.", "st": "35.53"}, {"sp": "N", "t": "ὅπερ οὖν ἐν ἀρχῇ ὑπεθέμην τοῦ λόγου, ὅτι καὶ ὑμεῖς ἀδικεῖσθε οὐδὲν ἧττον τῶν δόντων ἡμῶν τὰ χρήματα. σκοπεῖτε δέ, ὦ ἄνδρες δικασταί, πῶς οὐκ ἀδικεῖσθε, ἐπειδάν τις τῶν νόμων τῶν ὑμετέρων κρείττων ἐγχειρῇ εἶναι, καὶ τὰς συγγραφὰς τὰς ναυτικὰς ἀκύρους ποιῇ καὶ καταλύῃ, καὶ τὰ χρήματα τὰ παρ’ ἡμῶν εἰς Χίον ᾖ διαπεσταλκώς, πῶς οὐκ ἀδικεῖ ὁ τοιοῦτος ἄνθρωπος καὶ ὑμᾶς;", "st": "35.54"}, {"sp": "N", "t": "ἐμοὶ μὲν οὖν ἐστιν, ὦ ἄνδρες δικασταί, πρὸς τούτους ὁ λόγος (τούτοις γὰρ ἔδωκα τὰ χρήματα)· τούτοις δ’ ἔσται πρὸς τὸν ναύκληρον ἐκεῖνον τὸν Φασηλίτην, τὸν πολίτην τὸν αὑτῶν, ᾧ φασὶν δανεῖσαι τὰ χρήματα ἄνευ ἡμῶν παρὰ τὴν συγγραφήν· οὐδὲ γὰρ ἡμεῖς ἴσμεν τίνα ἐστὶν τὰ πεπραγμένα τούτοις πρὸς τὸν ἑαυτῶν πολίτην, ἀλλ’ αὐτοὶ οὗτοι ἴσασιν.", "st": "35.55"}, {"sp": "N", "t": "ταῦτα ἡγούμεθα δίκαια εἶναι, καὶ ὑμῶν δεόμεθα, ὦ ἄνδρες δικασταί, βοηθεῖν ἡμῖν τοῖς ἀδικουμένοις, καὶ κολάζειν τοὺς κακοτεχνοῦντας καὶ σοφιζομένους, ὥσπερ οὗτοι σοφίζονται. καὶ ἐὰν ταῦτα ποιῆτε, ὑμῖν τε αὐτοῖς τὰ συμφέροντα ἔσεσθε ἐψηφισμένοι, καὶ περιαιρήσεσθε τῶν πονηρῶν ἀνθρώπων τὰς πανουργίας ἁπάσας, ἃς ἔνιοι πανουργοῦσι περὶ τὰ συμβόλαια τὰ ναυτικά.", "st": "35.56"}, {"sp": "HDR", "t": "Παραγραφὴ ὑπὲρ Φορμίωνος", "st": "36"}, {"sp": "N", "t": "τὴν μὲν ἀπειρίαν τοῦ λέγειν, καὶ ὡς ἀδυνάτως ἔχει Φορμίων, αὐτοὶ πάντες ὁρᾶτ’, ὦ ἄνδρες Ἀθηναῖοι· ἀνάγκη δ’ ἐστὶν τοῖς ἐπιτηδείοις ἡμῖν, ἃ σύνισμεν πολλάκις τούτου διεξιόντος ἀκηκοότες, λέγειν καὶ διδάσκειν ὑμᾶς, ἵν’ εἰδότες καὶ μεμαθηκότες ὀρθῶς τὰ δίκαια παρ’ ἡμῶν, ἃν ᾖ δίκαια καὶ εὔορκα, ταῦτα ψηφίσησθε.", "st": "36.1"}, {"sp": "N", "t": "τὴν μὲν οὖν παραγραφὴν ἐποιησάμεθα τῆς δίκης, οὐχ ἵν’ ἐκκρούοντες χρόνους ἐμποιῶμεν, ἀλλ’ ἵνα τῶν πραγμάτων, ἐὰν ἐπιδείξῃ μηδ’ ὁτιοῦν ἀδικοῦνθ’ ἑαυτὸν οὑτοσί, ἀπαλλαγή τις αὐτῷ γένηται παρ’ ὑμῖν κυρία. ὅσα γὰρ παρὰ τοῖς ἄλλοις ἐστὶν ἀνθρώποις ἰσχυρὰ καὶ βέβαια ἄνευ τοῦ παρ’ ὑμῖν ἀγωνίσασθαι, ταῦτα πάντα πεποιηκὼς Φορμίων οὑτοσί, καὶ πολλὰ μὲν εὖ πεποιηκὼς Ἀπολλόδωρον τουτονί.", "st": "36.2"}, {"sp": "N", "t": "πάντα δ’, ὅσων κύριος τῶν τούτου κατελείφθη, διαλύσας καὶ παραδοὺς δικαίως, καὶ πάντων ἀφεθεὶς μετὰ ταῦτα τῶν ἐγκλημάτων, ὅμως, ὡς ὁρᾶτε, ἐπειδὴ φέρειν τοῦτον οὐχ οἷός τ’ ἐστίν, δίκην ταλάντων εἴκοσι λαχὼν αὐτῷ ταύτην συκοφαντεῖ. ἐξ ἀρχῆς οὖν ἅπαντα τὰ πραχθέντα τούτῳ πρὸς Πασίωνα καὶ Ἀπολλόδωρον ὡς ἂν δύνωμαι διὰ βραχυτάτων εἰπεῖν πειράσομαι, ἐξ ὧν εὖ οἶδ’ ὅτι ἥ τε τούτου συκοφαντία φανερὰ γενήσεται, καὶ ὡς οὐκ εἰσαγώγιμος ἡ δίκη γνώσεσθ’ ἅμα ταῦτ’ ἀκούσαντες.", "st": "36.3"}, {"sp": "N", "t": "πρῶτον μὲν οὖν ὑμῖν ἀναγνώσεται τὰς συνθήκας, καθ’ ἃς ἐμίσθωσε Πασίων τὴν τράπεζαν τούτῳ καὶ τὸ ἀσπιδοπηγεῖον. καί μοι λαβὲ τὰς συνθήκας καὶ τὴν πρόκλησιν καὶ τὰς μαρτυρίας ταυτασί.", "st": "36.4"}, {"sp": "N", "t": "ΣΥΝΘΗΚΑΙ. ΠΡΟΚΛΗΣΙΣ. ΜΑΡΤΥΡΙΑΙ.", "st": "36.4"}, {"sp": "N", "t": "αἱ μὲν οὖν συνθῆκαι, καθ’ ἃς ἐμίσθωσεν ὁ Πασίων τούτῳ τὴν τράπεζαν καὶ τὸ ἀσπιδοπηγεῖον ἤδη καθ’ ἑαυτὸν ὄντι, αὗταί εἰσιν, ὦ ἄνδρες Ἀθηναῖοι· δεῖ δ’ ὑμᾶς ἀκοῦσαι καὶ μαθεῖν ἐκ τίνος τρόπου προσώφειλεν τὰ ἕνδεκα τάλανθ’ ὁ Πασίων ἐπὶ τὴν τράπεζαν.", "st": "36.4"}, {"sp": "N", "t": "οὐ γὰρ δι’ ἀπορίαν ταῦτ’ ὤφειλεν, ἀλλὰ διὰ φιλεργίαν. ἡ μὲν γὰρ ἔγγειος ἦν οὐσία Πασίωνι μάλιστα ταλάντων εἴκοσιν, ἀργύριον δὲ πρὸς ταύτῃ δεδανεισμένον [ἴδιον] πλέον ἢ πεντήκοντα τάλαντα. ἐν [οὖν] τοῖς πεντήκοντα ταλάντοις τούτοις ἀπὸ τῶν παρακαταθηκῶν τῶν τῆς τραπέζης ἕνδεκα τάλαντ’ ἐνεργὰ ἦν.", "st": "36.5"}, {"sp": "N", "t": "μισθούμενος οὖν ὅδε τὴν ἐργασίαν αὐτὴν τῆς τραπέζης καὶ τὰς παρακαταθήκας [λαμβάνων], ὁρῶν ὅτι, μήπω τῆς πολιτείας αὐτῷ παρ’ ὑμῖν οὔσης, οὐχ οἷός τ’ ἔσοι’ εἰσπράττειν ὅσα Πασίων ἐπὶ γῇ καὶ συνοικίαις δεδανεικὼς ἦν, εἵλετο μᾶλλον αὐτὸν τὸν Πασίωνα χρήστην ἔχειν τούτων τῶν χρημάτων ἢ τοὺς ἄλλους χρήστας, οἷς προειμένος ἦν. καὶ οὕτω διὰ ταῦτ’ ἐγράφη εἰς τὴν μίσθωσιν προσοφείλων ὁ Πασίων ἕνδεκα τάλαντα, ὥσπερ καὶ μεμαρτύρηται ὑμῖν.", "st": "36.6"}, {"sp": "N", "t": "ὃν μὲν τοίνυν τρόπον ἡ μίσθωσις ἐγένετο, μεμαρτύρηται ὑμῖν ὑπ’ αὐτοῦ τοῦ ἐπικαθημένου· ἐπιγενομένης δ’ ἀρρωστίας τῷ Πασίωνι μετὰ ταῦτα, σκέψασθ’ ἃ διέθετο. λαβὲ τῆς διαθήκης τὸ ἀντίγραφον καὶ τὴν πρόκλησιν ταυτηνὶ καὶ τὰς μαρτυρίας ταυτασί[, παρ’ οἷς αἱ διαθῆκαι κεῖνται].", "st": "36.7"}, {"sp": "N", "t": "ΔΙΑΘΗΚΗ. ΠΡΟΚΛΗΣΙΣ. ΜΑΡΤΥΡΙΑΙ.", "st": "36.7"}, {"sp": "N", "t": "ἐπειδὴ τοίνυν ὁ Πασίων ἐτετελευτήκει ταῦτα διαθέμενος, Φορμίων οὑτοσὶ τὴν μὲν γυναῖκα λαμβάνει κατὰ τὴν διαθήκην, τὸν δὲ παῖδ’ ἐπετρόπευεν. ἁρπάζοντος δὲ τούτου καὶ πόλλ’ ἀπὸ κοινῶν ὄντων τῶν χρημάτων ἀναλίσκειν οἰομένου δεῖν, λογιζόμενοι πρὸς ἑαυτοὺς οἱ ἐπίτροποι, ὅτι, εἰ δεήσει κατὰ τὰς διαθήκας, ὅσ’ ἂν οὗτος ἐκ κοινῶν τῶν χρημάτων ἀναλώσῃ, τούτοις ἐξελόντας ἀντιμοιρεὶ τὰ λοιπὰ νέμειν, οὐδ’ ὁτιοῦν ἔσται περιόν, νείμασθαι τὰ ὄνθ’ ὑπὲρ τοῦ παιδὸς ἔγνωσαν.", "st": "36.8"}, {"sp": "N", "t": "καὶ νέμονται τὴν ἄλλην οὐσίαν πλὴν ὧν ἐμεμίσθωθ’ οὑτοσί· τούτων δὲ τῆς προσόδου τὴν ἡμίσειαν τούτῳ ἀπεδίδοσαν. ἄχρι μὲν οὖν τούτου τοῦ χρόνου πῶς ἔνεστ’ ἐγκαλεῖν αὐτῷ μισθώσεως; οὐ γὰρ νῦν, ἀλλὰ τότ’ εὐθὺς ἔδει χαλεπαίνοντα φαίνεσθαι. καὶ μὴν οὐδὲ τὰς ἐπιγιγνομένας μισθώσεις ὡς οὐκ ἀπείληφεν ἔστ’ εἰπεῖν αὐτῷ.", "st": "36.9"}, {"sp": "N", "t": "οὐ γὰρ ἄν ποτ’, ἐπειδὴ δοκιμασθέντος Πασικλέους ἀπηλλάττετο τῆς μισθώσεως ὅδε, ἀφήκατ’ ἂν αὐτὸν ἁπάντων τῶν ἐγκλημάτων, ἀλλὰ τότ’ ἂν παραχρῆμ’ ἀπῃτεῖτ’, εἴ τι προσώφειλεν ὑμῖν. ὡς τοίνυν ταῦτ’ ἀληθῆ λέγω, καὶ ἐνείμαθ’ οὗτος πρὸς τὸν ἀδελφὸν παῖδ’ ὄντα, καὶ ἀφῆκαν τῆς μισθώσεως καὶ τῶν ἄλλων ἁπάντων ἐγκλημάτων, λαβὲ ταυτηνὶ τὴν μαρτυρίαν.", "st": "36.10"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "36.10"}, {"sp": "N", "t": "εὐθὺς τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, ὡς ἀφεῖσαν τουτονὶ τῆς μισθώσεως, νέμονται τὴν τράπεζαν καὶ τὸ ἀσπιδοπηγεῖον, καὶ λαβὼν αἵρεσιν Ἀπολλόδωρος αἱρεῖται τὸ ἀσπιδοπηγεῖον ἀντὶ τῆς τραπέζης. καίτοι εἰ ἦν ἰδία τις ἀφορμὴ τούτῳ πρὸς τῇ τραπέζῃ, τί δή ποτ’ ἂν εἵλετο τοῦτο μᾶλλον ἢ ’κείνην; οὔτε γὰρ ἡ πρόσοδος ἦν πλείων, ἀλλ’ ἐλάττων (τὸ μὲν γὰρ τάλαντον, ἡ δ’ ἑκατὸν μνᾶς ἔφερεν), οὔτε τὸ κτῆμ’ ἥδιον, εἰ προσῆν χρήματα τῇ τραπέζῃ ἴδια. ἀλλ’ οὐ προσῆν. διόπερ σωφρονῶν εἵλετο τὸ ἀσπιδοπηγεῖον οὗτος· τὸ μὲν γὰρ κτῆμ’ ἀκίνδυνόν ἐστιν, ἡ δ’ ἐργασία προσόδους ἔχουσ’ ἐπικινδύνους ἀπὸ χρημάτων ἀλλοτρίων.", "st": "36.11"}, {"sp": "N", "t": "πολλὰ δ’ ἄν τις ἔχοι λέγειν καὶ ἐπιδεικνύναι σημεῖα τοῦ τοῦτον συκοφαντεῖν ἐγκαλοῦντ’ ἀφορμήν. ἀλλ’ οἶμαι μέγιστον μέν ἐστιν ἁπάντων τεκμήριον τοῦ μηδεμίαν λαβεῖν ἀφορμὴν εἰς ταῦτα τουτονὶ τὸ ἐν τῇ μισθώσει γεγράφθαι προσοφείλοντα τὸν Πασίων’ ἐπὶ τὴν τράπεζαν, οὐ δεδωκότ’ ἀφορμὴν τούτῳ, δεύτερον δὲ τὸ τοῦτον ἐν τῇ νομῇ μηδὲν ἐγκαλοῦντα φαίνεσθαι, τρίτον δ’, ὅτι μισθῶν ἑτέροις ὕστερον ταὐτὰ ταῦτα τοῦ ἴσου ἀργυρίου οὐ φανήσεται προσμεμισθωκὼς ἰδίαν ἀφορμήν.", "st": "36.12"}, {"sp": "N", "t": "καίτοι εἰ, ἣν ὁ πατὴρ παρέσχεν, ὑπὸ τοῦδ’ ἀπεστερεῖτο, αὐτὸν νῦν προσῆκεν ἐκείνοις ἄλλοθεν πορίσαντα δεδωκέναι. ὡς τοίνυν ταῦτ’ ἀληθῆ λέγω, καὶ ἐμίσθωσεν ὕστερον Ξένωνι καὶ Εὐφραίῳ καὶ Εὔφρονι καὶ Καλλιστράτῳ, καὶ οὐδὲ τούτοις παρέδωκεν ἰδίαν ἀφορμήν, ἀλλὰ τὰς παρακαταθήκας καὶ τὴν ἀπὸ τούτων ἐργασίαν αὐτὴν ἐμισθώσαντο, λαβέ μοι τὴν τούτων μαρτυρίαν, καὶ ὡς τὸ ἀσπιδοπηγεῖον εἵλετο.", "st": "36.13"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "36.13"}, {"sp": "N", "t": "μεμαρτύρηται μὲν τοίνυν ὑμῖν, ὦ ἄνδρες Ἀθηναῖοι, ὅτι καὶ τούτοις ἐμίσθωσαν καὶ οὐ παρέδωκαν ἰδίαν ἀφορμὴν οὐδεμίαν, καὶ ἐλευθέρους ἀφεῖσαν ὡς μεγάλ’ εὖ πεπονθότες, καὶ οὐκ ἐδικάζοντ’ οὔτ’ ἐκείνοις τότ’ οὔτε τούτῳ. ὃν μὲν τοίνυν χρόνον ἡ μήτηρ ἔζη, ἡ πάντ’ ἀκριβῶς ταῦτ’ εἰδυῖα, οὐδὲν ἔγκλημα πώποτ’ ἐποιήσατο πρὸς τουτονὶ Φορμίων’ Ἀπολλόδωρος· ὡς δ’ ἐτελεύτησεν ἐκείνη, τρισχιλίας ἐγκαλέσας ἀργυρίου δραχμὰς πρὸς αἷς ἔδωκεν ἐκείνη δισχιλίαις τοῖς τούτου παιδίοις, καὶ χιτωνίσκον τινὰ καὶ θεράπαιναν, ἐσυκοφάντει.", "st": "36.14"}, {"sp": "N", "t": "καὶ οὐδ’ ἐνταῦθα τούτων οὐδὲν ὧν νῦν ἐγκαλεῖ λέγων φανήσεται. ἐπιτρέψας δὲ τῷ τε τῆς ἑαυτοῦ γυναικὸς πατρὶ καὶ τῷ συγκηδεστῇ τῷ αὑτοῦ καὶ Λυσίνῳ καὶ Ἀνδρομένει, πεισάντων τούτων Φορμίωνα τουτονὶ δοῦναι δωρεὰν τὰς τρισχιλίας καὶ τὸ προσόν, καὶ φίλον μᾶλλον ἔχειν τοῦτον ἢ διὰ ταῦτ’ ἐχθρὸν αὐτὸν εἶναι, λαβὼν τὸ σύμπαν πεντακισχιλίας, καὶ πάντων ἀφεὶς τῶν ἐγκλημάτων τὸ δεύτερον εἰς τὸ ἱερὸν τῆς Ἀθηνᾶς ἐλθών.", "st": "36.15"}, {"sp": "N", "t": "πάλιν, ὡς ὁρᾶτε, δικάζεται, πάσας αἰτίας συμπλάσας καὶ ἐγκλήματ’ ἐκ παντὸς τοῦ χρόνου τοῦ πρὸ τούτου (τοῦτο γάρ ἐστιν μέγιστον ἁπάντων), ἃ οὐδεπώποτ’ ᾐτιάσατο. ὡς τοίνυν ταῦτ’ ἀληθῆ λέγω, λαβέ μοι τὴν γνῶσιν τὴν γενομένην ἐν ἀκροπόλει, καὶ τὴν μαρτυρίαν τῶν παραγενομένων, ὅτ’ ἀφίει τῶν ἐγκλημάτων ἁπάντων Ἀπολλόδωρος, λαμβάνων τοῦτο τὸ ἀργύριον.", "st": "36.16"}, {"sp": "N", "t": "ΓΝΩΣΙΣ. ΜΑΡΤΥΡΙΑ.", "st": "36.16"}, {"sp": "N", "t": "ἀκούετε τῆς γνώσεως, ἄνδρες δικασταί, ἣν ἔγνω Δεινίας, οὗ τὴν θυγατέρ’ οὗτος ἔχει, καὶ Νικίας ὁ τὴν ἀδελφὴν τῆς τούτου γυναικὸς ἔχων. ταῦτα τοίνυν λαβὼν καὶ ἀφεὶς ἁπάντων τῶν ἐγκλημάτων, ὥσπερ ἢ πάντων τεθνεώτων τούτων ἢ τῆς ἀληθείας οὐ γενησομένης φανερᾶς, δίκην τοσούτων ταλάντων λαχὼν τολμᾷ δικάζεσθαι.", "st": "36.17"}, {"sp": "N", "t": "τὰ μὲν οὖν πεπραγμένα καὶ γεγενημένα Φορμίωνι πρὸς Ἀπολλόδωρον ἐξ ἀρχῆς ἅπαντ’ ἀκηκόατ’, ὦ ἄνδρες Ἀθηναῖοι. οἶμαι δ’ Ἀπολλόδωρον τουτονί, οὐδὲν ἔχοντα δίκαιον εἰπεῖν περὶ ὧν ἐγκαλεῖ, ἅπερ παρὰ τῷ διαιτητῇ λέγειν ἐτόλμα, ταῦτ’ ἐρεῖν, ὡς τὰ γράμμαθ’ ἡ μήτηρ ἠφάνικε πεισθεῖσ’ ὑπὸ τούτου, καὶ τούτων ἀπολωλότων οὐκ ἔχει τίνα χρὴ τρόπον ταῦτ’ ἐξελέγχειν ἀκριβῶς.", "st": "36.18"}, {"sp": "N", "t": "περὶ δὴ τούτων καὶ ταύτης τῆς αἰτίας σκέψασθ’ ἡλίκ’ ἄν τις ἔχοι τεκμήρι’ εἰπεῖν ὅτι ψεύδεται. πρῶτον μὲν γάρ, ὦ ἄνδρες Ἀθηναῖοι, τίς ἂν ἐνείματο τὰ πατρῷα μὴ λαβὼν γράμματα, ἐξ ὧν ἔμελλεν εἴσεσθαι τὴν καταλειφθεῖσαν οὐσίαν; οὐδὲ εἷς δήπου. καίτοι δυοῖν δέοντ’ εἴκοσιν ἔτη ἐστὶν ἐξ ὅτου ἐνείμω, καὶ οὐκ ἂν ἔχοις ἐπιδεῖξαι, ὡς ἐνεκάλεσας πώποθ’ ὑπὲρ τῶν γραμμάτων.", "st": "36.19"}, {"sp": "N", "t": "δεύτερον δέ, τίς οὐκ ἄν, ἡνίχ’ ὁ Πασικλῆς ἀνὴρ γεγονὼς ἐκομίζετο τὸν λόγον τῆς ἐπιτροπῆς, εἰ δι’ αὑτοῦ τὰ γράμματ’ ὤκνει τὴν μητέρ’ αἰτιᾶσθαι διεφθαρκέναι, τούτῳ ταῦτ’ ἐδήλωσεν, ὅπως διὰ τούτου ταῦτ’ ἠλέγχθη; τρίτον δ’, ἐκ ποίων γραμμάτων τὰς δίκας ἐλάγχανες; οὗτος γὰρ πολλοῖς τῶν πολιτῶν δίκας λαγχάνων πολλὰ χρήματ’ εἰσπέπρακται, γράφων εἰς τὰ ἐγκλήματα “ἔβλαψέ με ὁ δεῖνα οὐκ ἀποδιδοὺς ἐμοὶ τὸ ἀργύριον, ὃ κατέλιπεν ὁ πατὴρ ὀφείλοντα αὐτὸν ἐν τοῖς γράμμασιν”.", "st": "36.20"}, {"sp": "N", "t": "καίτοι εἰ ἠφάνιστο τὰ γράμματα, ἐκ ποίων γραμμάτων τὰς δίκας ἐλάγχανεν; ἀλλὰ μὴν ὅτι ταῦτ’ ἀληθῆ λέγω, τὴν μὲν νομὴν ἀκηκόαθ’ ἣν ἐνείματο, καὶ μεμαρτύρηται ὑμῖν· τῶν δὲ λήξεων τούτων ἀναγνώσεται ὑμῖν τὰς μαρτυρίας. λαβὲ τὰς μαρτυρίας μοι.", "st": "36.21"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "36.21"}, {"sp": "N", "t": "οὐκοῦν ἐν ταύταις ταῖς λήξεσιν ὡμολόγηκεν ἀπειληφέναι τὰ τοῦ πατρὸς γράμματα· οὐ γὰρ δὴ συκοφαντεῖν γε, οὐδ’ ὧν οὐκ ὤφειλον οὗτοι δικάζεσθαι φήσειεν ἄν.", "st": "36.21"}, {"sp": "N", "t": "νομίζω τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, μεγάλων καὶ πολλῶν ὄντων ἐξ ὧν ἔστιν ἰδεῖν οὐκ ἀδικοῦντα Φορμίωνα τουτονί, μέγιστον ἁπάντων εἶναι, ὅτι Πασικλῆς, ἀδελφὸς ὢν Ἀπολλοδώρου τουτουί, οὔτε δίκην εἴληχεν οὔτ’ ἄλλ’ οὐδὲν ὧν οὗτος ἐγκαλεῖ. καίτοι οὐ δήπου τὸν μὲν παῖδ’ ὑπὸ τοῦ πατρὸς καταλειφθέντα, καὶ οὗ τῶν ὄντων κύριος ἦν, ἐπίτροπος καταλελειμμένος, οὐκ ἂν ἠδίκει, σὲ δέ, ὃς ἀνὴρ κατελείφθης τέτταρα καὶ εἴκοσιν ἔτη γεγονώς, καὶ ὑπὲρ σαυτοῦ ῥᾳδίως ἂν τὰ δίκαι’ ἐλάμβανες εὐθύς, εἴ τι ἠδικοῦ. οὐκ ἔστι ταῦτα. ὡς τοίνυν ταῦτ’ ἀληθῆ λέγω καὶ ὁ Πασικλῆς οὐδὲν ἐγκαλεῖ, λαβέ μοι τὴν τούτου μαρτυρίαν.", "st": "36.22"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "36.22"}, {"sp": "N", "t": "ἃ τοίνυν ἤδη περὶ αὐτοῦ τοῦ μὴ εἰσαγώγιμον εἶναι τὴν δίκην δεῖ σκοπεῖν ὑμᾶς, ταῦτ’ ἀναμνήσθητ’ ἐκ τῶν εἰρημένων. ἡμεῖς γάρ, ὦ ἄνδρες Ἀθηναῖοι, γεγενημένου μὲν διαλογισμοῦ καὶ ἀφέσεως τῆς τραπέζης καὶ τοῦ ἀσπιδοπηγείου τῆς μισθώσεως, γεγενημένης δὲ διαίτης καὶ πάλιν πάντων ἀφέσεως, οὐκ ἐώντων τῶν νόμων δίκας ὧν ἂν ἀφῇ τις ἅπαξ λαγχάνειν,", "st": "36.23"}, {"sp": "N", "t": "συκοφαντοῦντος τούτου καὶ παρὰ τοὺς νόμους δικαζομένου παρεγραψάμεθ’ ἐκ τῶν νόμων μὴ εἶναι τὴν δίκην εἰσαγώγιμον. ἵν’ οὖν εἰδῆθ’ ὑπὲρ οὗ τὴν ψῆφον οἴσετε, τόν τε νόμον ὑμῖν τοῦτον ἀναγνώσεται καὶ τὰς μαρτυρίας ἐφεξῆς τῶν παρόντων, ὅτ’ ἀφίει τῆς μισθώσεως καὶ τῶν ἄλλων ἁπάντων ἐγκλημάτων Ἀπολλόδωρος. λαβέ μοι τὰς μαρτυρίας ταυτασὶ καὶ τὸν νόμον.", "st": "36.24"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ. ΝΟΜΟΣ.", "st": "36.24"}, {"sp": "N", "t": "ἀκούετε τοῦ νόμου λέγοντος, ὦ ἄνδρες Ἀθηναῖοι, τά τ’ ἄλλ’ ὧν μὴ εἶναι δίκας, καὶ ὅσα τις ἀφῆκεν ἢ ἀπήλλαξεν. εἰκότως· εἰ γάρ ἐστι δίκαιον, ὧν ἂν ἅπαξ γένηται δίκη, μηκέτ’ ἐξεῖναι δικάζεσθαι, πολὺ τῶν ἀφεθέντων δικαιότερον μὴ εἶναι δίκας. ὁ μὲν γὰρ ἐν ὑμῖν ἡττηθεὶς τάχ’ ἂν εἴποι τοῦθ’ ὡς ἐξηπατήθηθ’ ὑμεῖς· ὁ δ’ αὑτοῦ φανερῶς καταγνοὺς καὶ ἀφεὶς καὶ ἀπαλλάξας, τίν’ ἂν ἑαυτὸν αἰτίαν αἰτιασάμενος τῶν αὐτῶν πάλιν εἰκότως δικάζοιτο; οὐδεμίαν δήπου. διόπερ τοῦτο πρῶτον ἔγραψεν ὁ τὸν νόμον θεὶς ὧν μὴ εἶναι δίκας, ὅσα τις ἀφῆκεν ἢ ἀπήλλαξεν. ἃ τῷδε γέγονεν ἀμφότερα· καὶ γὰρ ἀφῆκεν καὶ ἀπήλλαξεν. ὡς δ’ ἀληθῆ λέγω, μεμαρτύρηται ὑμῖν, ὦ ἄνδρες Ἀθηναῖοι.", "st": "36.25"}, {"sp": "N", "t": "λαβὲ δή μοι καὶ τὸν τῆς προθεσμίας νόμον.", "st": "36.25"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "36.25"}, {"sp": "N", "t": "ὁ μὲν τοίνυν νόμος, ὦ ἄνδρες Ἀθηναῖοι, σαφῶς οὑτωσὶ τὸν χρόνον ὥρισεν· Ἀπολλόδωρος δ’ οὑτοσὶ παρεληλυθότων ἐτῶν πλέον ἢ εἴκοσιν τὴν ἑαυτοῦ συκοφαντίαν ἀξιοῖ περὶ πλείονος ὑμᾶς ποιήσασθαι τῶν νόμων, καθ’ οὓς ὀμωμοκότες δικάζετε. καίτοι πᾶσι μὲν τοῖς νόμοις προσέχειν εἰκός ἐσθ’ ὑμᾶς, οὐχ ἥκιστα δὲ τούτῳ, ὦ ἄνδρες Ἀθηναῖοι.", "st": "36.26"}, {"sp": "N", "t": "δοκεῖ γάρ μοι καὶ ὁ Σόλων οὐδενὸς ἄλλου ἕνεκα θεῖναι αὐτὸν ἢ τοῦ μὴ συκοφαντεῖσθαι ὑμᾶς. τοῖς μὲν γὰρ ἀδικουμένοις τὰ πέντ’ ἔτη ἱκανὸν ἡγήσατ’ εἶναι εἰσπράξασθαι· κατὰ δὲ τῶν ψευδομένων τὸν χρόνον ἐνόμισεν σαφέστατον ἔλεγχον ἔσεσθαι. καὶ ἅμ’ ἐπειδὴ ἀδύνατον ἔγνω ὂν τούς τε συμβάλλοντας καὶ τοὺς μάρτυρας ἀεὶ ζῆν, τὸν νόμον ἀντὶ τούτων ἔθηκεν, ὅπως μάρτυς εἴη τοῦ δικαίου τοῖς ἐρήμοις.", "st": "36.27"}, {"sp": "N", "t": "θαυμάζω τοίνυν ἔγωγ’, ὦ ἄνδρες δικασταί, τί ποτ’ ἐστὶν ἃ πρὸς ταῦτ’ ἐπιχειρήσει λέγειν Ἀπολλόδωρος οὑτοσί. οὐ γὰρ ἐκεῖνό γ’ ὑπείληφεν, ὡς ὑμεῖς, μηδὲν ὁρῶντες εἰς χρήματα τοῦτον ἠδικημένον, ὀργιεῖσθ’ ὅτι τὴν μητέρ’ ἔγημεν αὐτοῦ Φορμίων. οὐ γὰρ ἀγνοεῖ τοῦτο, οὐδ’ αὐτὸν λέληθεν, οὐδ’ ὑμῶν πολλούς, ὅτι Σωκράτης ὁ τραπεζίτης ἐκεῖνος, παρὰ τῶν κυρίων ἀπαλλαγεὶς ὥσπερ ὁ τούτου πατήρ, ἔδωκε Σατύρῳ τὴν ἑαυτοῦ γυναῖκα, ἑαυτοῦ ποτὲ γενομένῳ.", "st": "36.28"}, {"sp": "N", "t": "ἕτερος Σωκλῆς τραπεζιτεύσας ἔδωκε τὴν ἑαυτοῦ γυναῖκα Τιμοδήμῳ τῷ νῦν ἔτ’ ὄντι καὶ ζῶντι, γενομένῳ ποθ’ αὑτοῦ. καὶ οὐ μόνον ἐνθάδε ταῦτα ποιοῦσιν οἱ περὶ τὰς ἐργασίας ὄντες ταύτας, ὦ ἄνδρες Ἀθηναῖοι, ἀλλ’ ἐν Αἰγίνῃ ἔδωκεν Στρυμόδωρος Ἑρμαίῳ τῷ ἑαυτοῦ οἰκέτῃ τὴν γυναῖκα, καὶ τελευτησάσης ἐκείνης ἔδωκε πάλιν τὴν θυγατέρα τὴν ἑαυτοῦ. καὶ πολλοὺς ἂν ἔχοι τις εἰπεῖν τοιούτους.", "st": "36.29"}, {"sp": "N", "t": "εἰκότως· ὑμῖν μὲν γάρ, ὦ ἄνδρες Ἀθηναῖοι, τοῖς γένει πολίταις, οὐδὲ ἓν πλῆθος χρημάτων ἀντὶ τοῦ γένους καλόν ἐστιν ἑλέσθαι· τοῖς δὲ τοῦτο μὲν δωρεὰν ἢ παρ’ ὑμῶν ἢ παρ’ ἄλλων τινῶν λαβοῦσιν, τῇ τύχῃ δ’ ἐξ ἀρχῆς ἀπὸ τοῦ χρηματίσασθαι καὶ ἑτέρων πλείω κτήσασθαι καὶ αὐτῶν τούτων ἀξιωθεῖσιν, ταῦτ’ ἐστὶν φυλακτέα. διόπερ Πασίων ὁ πατὴρ ὁ σὸς οὐ πρῶτος οὐδὲ μόνος, οὐδ’ αὑτὸν ὑβρίζων οὐδ’ ὑμᾶς τοὺς υἱεῖς, ἀλλὰ μόνην ὁρῶν σωτηρίαν τοῖς ἑαυτοῦ πράγμασιν, εἰ τοῦτον ἀνάγκῃ ποιήσειεν οἰκεῖον ὑμῖν, ἔδωκε τὴν ἑαυτοῦ γυναῖκα, μητέρα δ’ ὑμετέραν τούτῳ.", "st": "36.30"}, {"sp": "N", "t": "πρὸς μὲν οὖν τὰ συμφέροντ’ ἐὰν ἐξετάζῃς, καλῶς βεβουλευμένον αὐτὸν εὑρήσεις· εἰ δὲ πρὸς γένους δόξαν ἀναίνει Φορμίωνα κηδεστήν, ὅρα μὴ γελοῖον ᾖ σὲ ταῦτα λέγειν. εἰ γάρ τις ἔροιτό σε, ποῖόν τιν’ ἡγεῖ τὸν πατέρα τὸν σεαυτοῦ εἶναι, χρηστὸν εὖ οἶδ’ ὅτι φήσειας ἄν. πότερον οὖν οἴει μᾶλλον ἐοικέναι τὸν τρόπον καὶ πάντα τὸν βίον Πασίωνι σαυτὸν ἢ τουτονί; ἐγὼ μὲν εὖ οἶδ’ ὅτι τοῦτον. εἶθ’ ὅς ἐστιν ὁμοιότερος σοῦ τῷ σῷ πατρί, τοῦτον, εἰ τὴν μητέρα τὴν σὴν ἔγημεν, ἀναίνει.", "st": "36.31"}, {"sp": "N", "t": "ἀλλὰ μὴν ὅτι γε δόντος καὶ ἐπισκήψαντος τοῦ σοῦ πατρὸς ταῦτ’ ἐπράχθη, οὐ μόνον ἐκ τῆς διαθήκης ἔστιν ἰδεῖν, ὦ ἄνδρες Ἀθηναῖοι, ἀλλὰ καὶ σὺ μάρτυς αὐτὸς γέγονας. ὅτε γὰρ τὰ μητρῷα πρὸς μέρος ἠξίους νέμεσθαι, ὄντων παίδων ἐκ τῆς γυναικὸς Φορμίωνι τουτῳί, τόθ’ ὡμολόγεις κυρίως δόντος τοῦ πατρὸς τοῦ σοῦ κατὰ τοὺς νόμους αὐτὴν γεγαμῆσθαι. εἰ γὰρ αὐτὴν εἶχε λαβὼν ἀδίκως ὅδε μηδενὸς δόντος, οὐκ ἦσαν οἱ παῖδες κληρονόμοι, τοῖς δὲ μὴ κληρονόμοις οὐκ ἦν μετουσία τῶν ὄντων. ἀλλὰ μὴν ὅτι ταῦτ’ ἀληθῆ λέγω, μεμαρτύρηται τὸ τέταρτον μέρος λαβεῖν καὶ ἀφεῖναι τῶν ἐγκλημάτων ἁπάντων.", "st": "36.32"}, {"sp": "N", "t": "κατ’ οὐδὲν τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, δίκαιον οὐδὲν ἔχων εἰπεῖν, ἀναιδεστάτους λόγους ἐτόλμα λέγειν πρὸς τῷ διαιτητῇ, περὶ ὧν προακηκοέναι βέλτιόν ἐσθ’ ὑμᾶς, ἕνα μὲν τὸ παράπαν μὴ γενέσθαι διαθήκην, ἀλλ’ εἶναι τοῦτο πλάσμα καὶ σκευώρημ’ ὅλον, ἕτερον δ’ ἕνεκα τούτου πάντα ταῦτα συγχωρεῖν τὸν πρὸ τοῦ χρόνον καὶ οὐχὶ δικάζεσθαι, ὅτι μίσθωσιν ἤθελεν αὐτῷ φέρειν Φορμίων πολλὴν καὶ ὑπισχνεῖτ’ οἴσειν· ἐπειδὴ δ’ οὐ ποιεῖ ταῦτα, τηνικαῦτα, φησίν, δικάζομαι.", "st": "36.33"}, {"sp": "N", "t": "ὅτι δὲ ταῦτ’ ἀμφότερ’, ἐὰν λέγῃ, ψεύσεται καὶ τοῖς ὑφ’ ἑαυτοῦ πεπραγμένοις ἐναντί’ ἐρεῖ, σκοπεῖτ’ ἐκ τωνδί. ὅταν μὲν τοίνυν τὴν διαθήκην ἀρνῆται, ἐκ τίνος τρόπου πρεσβεῖα λαβὼν τὴν συνοικίαν κατὰ τὴν διαθήκην ἔχει, τοῦτ’ ἐρωτᾶτ’ αὐτόν. οὐ γὰρ ἐκεῖνό γ’ ἐρεῖ, ὡς ἃ μὲν πλεονεκτεῖν τόνδ’ ἔγραψεν ὁ πατήρ, κύρι’ ἐστὶν τῆς διαθήκης, τὰ δ’ ἄλλ’ ἄκυρα.", "st": "36.34"}, {"sp": "N", "t": "ὅταν δ’ ὑπὸ τῶν τοῦδ’ ὑποσχέσεων ὑπάγεσθαι φῇ, μέμνησθ’ ὅτι μάρτυρας ὑμῖν παρεσχήμεθα, οἳ χρόνον πολὺν τοῦδ’ ἀπηλλαγμένου μισθωταὶ τούτοις ἐγίγνοντο τῆς τραπέζης καὶ τοῦ ἀσπιδοπηγείου. καίτοι τόθ’, ὁπηνίκ’ ἐμίσθωσεν ἐκείνοις, τῷδ’ ἐγκαλεῖν παραχρῆμ’ ἐχρῆν, εἴπερ ἀληθῆ ἦν ὑπὲρ ὧν τότ’ ἀφεὶς νῦν τούτῳ δικάζεται. ὡς τοίνυν ἀληθῆ λέγω, καὶ πρεσβεῖά τε τὴν συνοικίαν ἔλαβεν κατὰ τὴν διαθήκην, καὶ τῷδ’ οὐχ ὅπως ἐγκαλεῖν ᾤετο δεῖν, ἀλλ’ ἐπῄνει, λαβὲ τὴν μαρτυρίαν.", "st": "36.35"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "36.35"}, {"sp": "N", "t": "ἵνα τοίνυν εἰδῆτ’, ὦ ἄνδρες Ἀθηναῖοι, ὅσα χρήματ’ ἔχων ἐκ τῶν μισθώσεων καὶ ἐκ τῶν χρεῶν ὡς ἀπορῶν καὶ πάντ’ ἀπολωλεκὼς ὀδυρεῖται, βραχέ’ ἡμῶν ἀκούσατε. οὗτος γὰρ ἐκ μὲν τῶν χρεῶν ὁμοῦ τάλαντ’ εἴκοσιν εἰσπέπρακται ἐκ τῶν γραμμάτων ὧν ὁ πατὴρ κατέλιπεν, καὶ τούτων ἔχει πλέον ἢ τὰ ἡμίσεα (πολλῶν γὰρ τὰ μέρη τὸν ἀδελφὸν ἀποστερεῖ).", "st": "36.36"}, {"sp": "N", "t": "ἐκ δὲ τῶν μισθώσεων, ὀκτὼ μὲν ἐτῶν ἃ Φορμίων εἶχε τὴν τράπεζαν, ὀγδοήκοντα μνᾶς τοῦ ἐνιαυτοῦ ἑκάστου, τὸ ἥμισυ τῆς ὅλης μισθώσεως· καὶ ταῦτ’ ἐστὶ δέκα τάλαντα καὶ τετταράκοντα μναῖ· δέκα δὲ τῶν μετὰ ταῦτα, ὧν ἐμίσθωσαν ὕστερον Ξένωνι καὶ Εὐφραίῳ καὶ Εὔφρονι καὶ Καλλιστράτῳ, τάλαντον τοῦ ἐνιαυτοῦ ἑκάστου.", "st": "36.37"}, {"sp": "N", "t": "χωρὶς δὲ τούτων, ἐτῶν ἴσως εἴκοσι τῆς ἐξ ἀρχῆς νεμηθείσης οὐσίας, ἧς αὐτὸς ἐπεμελεῖτο, τὰς προσόδους, πλέον ἢ μνᾶς τριάκοντα. ἐὰν δ’ ἅπαντα συνθῆτε, ὅσ’ ἐνείματο, ὅσ’ εἰσεπράξατο, ὅσ’ εἴληφε μίσθωσιν, πλέον ἢ τετταράκοντα τάλαντ’ εἰληφὼς φανήσεται, χωρὶς ὧν οὗτος εὖ πεποίηκεν, καὶ τῶν μητρῴων, καὶ ὧν ἀπὸ τῆς τραπέζης ἔχων οὐκ ἀποδίδωσι πένθ’ ἡμιταλάντων καὶ ἑξακοσίων δραχμῶν.", "st": "36.38"}, {"sp": "N", "t": "ἀλλὰ νὴ Δία ταῦθ’ ἡ πόλις εἴληφεν, καὶ δεινὰ πέπονθας πολλὰ καταλελῃτουργηκώς. ἀλλ’ ἃ μὲν ἐκ κοινῶν ἐλῃτούργεις τῶν χρημάτων, σὺ καὶ ἁδελφὸς ἀνηλώσατε· ἃ δ’ ὕστερον, οὐκ ἔστιν ἄξια μὴ ὅτι δυοῖν ταλάντοιν προσόδου, ἀλλ’ οὐδ’ εἴκοσι μνῶν. μηδὲν οὖν τὴν πόλιν αἰτιῶ, μηδ’ ἃ σὺ τῶν ὄντων αἰσχρῶς καὶ κακῶς ἀνήλωκας, ὡς ἡ πόλις εἴληφεν, λέγε.", "st": "36.39"}, {"sp": "N", "t": "ἵνα δ’ εἰδῆτ’, ὦ ἄνδρες Ἀθηναῖοι, τό τε πλῆθος τῶν χρημάτων ὧν εἴληφε, καὶ τὰς λῃτουργίας ἃς λελῃτούργηκεν, ἀναγνώσεται ὑμῖν καθ’ ἓν ἕκαστον. λαβέ μοι τὸ βιβλίον τουτὶ καὶ τὴν πρόκλησιν ταυτηνὶ καὶ τὰς μαρτυρίας ταυτασί.", "st": "36.40"}, {"sp": "N", "t": "⟨ΒΙΒΛΙΟΝ.⟩ ΠΡΟΚΛΗΣΙΣ. ΜΑΡΤΥΡΙΑΙ.", "st": "36.40"}, {"sp": "N", "t": "τοσαῦτα μὲν τοίνυν χρήματ’ εἰληφὼς καὶ χρέα πολλῶν ταλάντων ἔχων, ὧν τὰ μὲν παρ’ ἑκόντων, τὰ δ’ ἐκ τῶν δικῶν εἰσπράττει, ἃ τῆς μισθώσεως ἔξω τῆς τραπέζης καὶ τῆς ἄλλης οὐσίας, ἣν κατέλιπεν Πασίων, ὠφείλετ’ ἐκείνῳ καὶ νῦν παρειλήφασιν οὗτοι, καὶ τοσαῦτ’ ἀνηλωκὼς ὅσ’ ὑμεῖς ἠκούσατε, οὐδὲ πολλοστὸν μέρος τῶν προσόδων, μὴ ὅτι τῶν ἀρχαίων, εἰς τὰς λῃτουργίας, ὅμως ἀλαζονεύσεται καὶ τριηραρχίας ἐρεῖ καὶ χορηγίας.", "st": "36.41"}, {"sp": "N", "t": "ἐγὼ δ’, ὡς μὲν οὐκ ἀληθῆ ταῦτ’ ἐρεῖ, ἐπέδειξα, οἶμαι μέντοι, κἂν εἰ ταῦτα πάντ’ ἀληθῆ λέγοι, κάλλιον εἶναι καὶ δικαιότερον τόνδ’ ἀπὸ τῶν αὑτοῦ λῃτουργεῖν ὑμῖν ἢ τούτῳ δόντας τὰ τούτου, μικρὰ τῶν πάντων αὐτοὺς μετασχόντας, τόνδε μὲν ἐν ταῖς ἐσχάταις ἐνδείαις ὁρᾶν, τοῦτον δ’ ὑβρίζοντα καὶ εἰς ἅπερ εἴωθεν ἀναλίσκοντα.", "st": "36.42"}, {"sp": "N", "t": "ἀλλὰ μὴν περί γε τῆς εὐπορίας, ὡς ἐκ τῶν τοῦ πατρὸς τοῦ σοῦ κέκτηται, καὶ ὧν ἐρωτήσειν ἔφησθα, πόθεν τὰ ὄντα κέκτηται Φορμίων, μόνῳ τῶν ὄντων ἀνθρώπων σοὶ τοῦτον οὐκ ἔνεστ’ εἰπεῖν τὸν λόγον. οὐδὲ γὰρ Πασίων ὁ σὸς πατὴρ ἐκτήσαθ’ εὑρὼν οὐδὲ τοῦ πατρὸς αὐτῷ παραδόντος, ἀλλὰ παρὰ τοῖς αὑτοῦ κυρίοις Ἀντισθένει καὶ Ἀρχεστράτῳ τραπεζιτεύουσι πεῖραν δοὺς ὅτι χρηστός ἐστι καὶ δίκαιος, ἐπιστεύθη.", "st": "36.43"}, {"sp": "N", "t": "ἔστι δ’ ἐν ἐμπορίῳ καὶ χρήμασιν ἐργαζομένοις ἀνθρώποις φιλεργὸν δόξαι καὶ χρηστὸν εἶναι τὸν αὐτὸν θαυμαστὸν ἡλίκον. οὔτ’ οὖν ἐκείνῳ τοῦθ’ οἱ κύριοι παρέδωκαν, ἀλλ’ αὐτὸς ἔφυ χρηστός, οὔτε τῷδ’ ὁ σὸς πατήρ· σὲ γὰρ ἂν πρότερον τοῦδε χρηστὸν ἐποίησεν, εἰ ἦν ἐπ’ ἐκείνῳ. εἰ δὲ τοῦτ’ ἀγνοεῖς, ὅτι πίστις ἀφορμὴ πασῶν ἐστι μεγίστη πρὸς χρηματισμόν, πᾶν ἂν ἀγνοήσειας. χωρὶς δὲ τούτων πολλὰ καὶ τῷ σῷ πατρὶ καὶ σοὶ καὶ ὅλως τοῖς ὑμετέροις πράγμασι Φορμίων γέγονε χρήσιμος. ἀλλ’ οἶμαι τῆς σῆς ἀπληστίας καὶ τοῦ σοῦ τρόπου τίς ἂν δύναιτ’ ἐφικέσθαι.", "st": "36.44"}, {"sp": "N", "t": "καὶ δῆτα θαυμάζω πῶς οὐ λογίζει πρὸς σεαυτόν, ὅτι ἔστιν Ἀρχεστράτῳ τῷ ποτὲ τὸν σὸν πατέρα κτησαμένῳ υἱὸς ἐνθάδε, Ἀντίμαχος, πράττων οὐ κατ’ ἀξίαν, ὃς οὐ δικάζεταί σοι, οὐδὲ δεινά φησι πάσχειν, εἰ σὺ μὲν χλανίδα φορεῖς, καὶ τὴν μὲν λέλυσαι, τὴν δ’ ἐκδέδωκας ἑταίραν, καὶ ταῦτα γυναῖκ’ ἔχων ποιεῖς, καὶ τρεῖς παῖδας ἀκολούθους περιάγει, καὶ ζῇς ἀσελγῶς ὥστε καὶ τοὺς ἀπαντῶντας αἰσθάνεσθαι, αὐτὸς δ’ ἐκεῖνος πολλῶν ἐνδεής ἐστιν.", "st": "36.45"}, {"sp": "N", "t": "οὐδὲ τὸν Φορμίων’ ἐκεῖνος οὐχ ὁρᾷ. καίτοι εἰ κατὰ τοῦτ’ οἴει σοι προσήκειν τῶν τούτου, ὅτι τοῦ πατρός ποτ’ ἐγένετο τοῦ σοῦ, ἐκείνῳ προσήκει μᾶλλον ἢ σοί· ὁ γὰρ αὖ σὸς πατὴρ ἐκείνων ἐγένετο, ὥστε καὶ σὺ καὶ οὗτος ἐκείνου γίγνεσθ’ ἐκ τούτου τοῦ λόγου. σὺ δ’ εἰς τοῦθ’ ἥκεις ἀγνωμοσύνης ὥσθ’ ἃ προσήκει σοι τοὺς λέγοντας ἐχθροὺς νομίζειν, ταῦτ’ αὐτὸς ποιεῖς ἀνάγκην εἶναι λέγειν.", "st": "36.46"}, {"sp": "N", "t": "καὶ ὑβρίζεις μὲν σαυτὸν καὶ τοὺς γονέας τεθνεῶτας, προπηλακίζεις δὲ τὴν πόλιν, καὶ ἃ τῆς τουτωνὶ φιλανθρωπίας ἀπολαύσας ηὕρεθ’ ὁ σὸς πατὴρ καὶ μετὰ ταῦτα Φορμίων οὑτοσί, ταῦτ’ ἀντὶ τοῦ κοσμεῖν καὶ περιστέλλειν, ἵνα καὶ τοῖς δοῦσιν ὡς εὐσχημονέστατ’ ἐφαίνετο καὶ τοῖς λαβοῦσιν ὑμῖν, ἄγεις εἰς μέσον, δεικνύεις, ἐλέγχεις, μόνον οὐκ ὀνειδίζεις οἷον ὄντα σ’ ἐποιήσαντ’ Ἀθηναῖον.", "st": "36.47"}, {"sp": "N", "t": "εἶτ’ εἰς τοῦθ’ ἥκεις μανίας (τί γὰρ ἂν ἄλλο τις εἴποι;) ὥστ’ οὐκ αἰσθάνει ὅτι καὶ νῦν ἡμεῖς μὲν ἀξιοῦντες, ἐπειδήπερ ἀπηλλάγη Φορμίων, μηδὲν ὑπόλογον εἶναι εἴ ποτε τοῦ σοῦ πατρὸς ἐγένετο, ὑπὲρ σοῦ λέγομεν, σὺ δὲ μηδέποτ’ ἐξ ἴσου σοι γενέσθαι τοῦτον ἀξιῶν κατὰ σαυτοῦ λέγεις· ἃ γὰρ ἂν σὺ δίκαια σαυτῷ κατὰ τούτου τάξῃς, ταὐτὰ ταῦθ’ ἥξει κατὰ σοῦ παρὰ τῶν τὸν σὸν πατέρ’ ἐξ ἀρχῆς κτησαμένων. ἀλλὰ μὴν ὅτι κἀκεῖνος ἦν τινῶν, εἶτ’ ἀπηλλάγη τὸν αὐτὸν τρόπον ὅνπερ οὗτος ἀφ’ ὑμῶν, λαβέ μοι ταυτασὶ τὰς μαρτυρίας, ὡς ἐγένετο Πασίων Ἀρχεστράτου.", "st": "36.48"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "36.48"}, {"sp": "N", "t": "εἶτα τὸν σῴσαντα μὲν ἐξ ἀρχῆς τὰ πράγματα καὶ πολλὰ χρήσιμον αὑτὸν παρασχόντα τῷ πατρὶ τῷ τούτου, τοσαῦτα δ’ αὐτὸν τοῦτον ἀγάθ’ εἰργασμένον, ὅσ’ ὑμεῖς ἀκηκόατε, τοῦτον οἴεται δεῖν ἑλὼν τηλικαύτην δίκην ἀδίκως ἐκβαλεῖν. οὐ γὰρ ἄλλο γ’ ἔχοις οὐδὲν ἂν ποιῆσαι. εἰς μὲν γὰρ τὰ ὄντ’ εἰ βλέπεις ἀκριβῶς, ταῦθ’ εὑρήσεις ὧν ἔστιν, ἐάν, ὃ μὴ γένοιτο, ἐξαπατηθῶσιν οὗτοι.", "st": "36.49"}, {"sp": "N", "t": "ὁρᾷ τὸν Ἀριστόλοκον τὸν Καπιδήμου· ποτ’ εἶχεν ἀργόν, εἶτά γε νῦν πολλοῖς γὰρ ἐκεῖνος ὀφείλων αὐτὸν ἐκτήσατο. καὶ τὸν Σωσίνομον καὶ τὸν Τιμόδημον καὶ τοὺς ἄλλους τραπεζίτας, οἵ, ἐπειδὴ διαλύειν ἐδέησεν οἷς ὤφειλον, ἐξέστησαν ἅπαντες τῶν ὄντων. σὺ δ’ οὐδὲν οἴει δεῖν σκοπεῖν οὐδ’ ὧν ὁ πατὴρ σοῦ πολλῷ βελτίων ὢν καὶ ἄμεινον φρονῶν πρὸς ἅπαντ’ ἐβουλεύσατο.", "st": "36.50"}, {"sp": "N", "t": "ὅς, ὦ Ζεῦ καὶ θεοί, τοσούτῳ τοῦτον ἡγεῖτο σοῦ πλείονος ἄξιον εἶναι καὶ σοὶ καὶ ἑαυτῷ καὶ τοῖς ὑμετέροις πράγμασιν ὥστ’ ἀνδρὸς ὄντος σοῦ τοῦτον, οὐ σὲ τῶν ἡμίσεων κατέλιπεν ἐπίτροπον καὶ τὴν γυναῖκ’ ἔδωκεν καὶ ζῶν αὐτὸν ἐτίμα, δικαίως, ὦ ἄνδρες Ἀθηναῖοι· οἱ μὲν γὰρ ἄλλοι τραπεζῖται μίσθωσιν οὐ φέροντες, ἀλλ’ αὐτοὶ ἑαυτοῖς ἐργαζόμενοι, πάντες ἀπώλοντο, οὗτος δὲ μίσθωσιν φέρων δύο τάλαντα καὶ τετταράκοντα μνᾶς ὑμῖν ἔσῳσε τὴν τράπεζαν.", "st": "36.51"}, {"sp": "N", "t": "ὧν ἐκεῖνος μὲν χάριν εἶχεν, σὺ δ’ οὐδένα ποιεῖ λόγον, ἀλλ’ ἐναντία τῇ διαθήκῃ καὶ ταῖς ἀπ’ ἐκείνης ἀραῖς, γραφείσαις ὑπὸ τοῦ σοῦ πατρός, ἐλαύνεις συκοφαντεῖς διώκεις. ὦ βέλτιστ’, εἰ οἷόν τε σὲ τοῦτ’ εἰπεῖν, οὐ παύσει, καὶ γνώσει τοῦθ’, ὅτι πολλῶν χρημάτων τὸ χρηστὸν εἶναι λυσιτελέστερόν ἐστιν; σοὶ γοῦν, εἴπερ ἀληθῆ λέγεις, χρήματα μὲν τοσαῦτ’ εἰληφότι πάντ’ ἀπόλωλεν, ὡς φής· εἰ δ’ ἦσθ’ ἐπιεικής, οὐκ ἄν ποτ’ αὔτ’ ἀνήλωσας.", "st": "36.52"}, {"sp": "N", "t": "ἀλλ’ ἔγωγε μὰ τὸν Δία καὶ θεοὺς πανταχῇ σκοπῶν οὐδὲν ὁρῶ, δι’ ὅ τι ἂν σοὶ πεισθέντες τουδὶ καταψηφίσαιντο. τί γάρ; ὅτι πλησίον ὄντων τῶν ἀδικημάτων ἐγκαλεῖς; ἀλλ’ ἔτεσι καὶ χρόνοις ὕστερον αἰτιᾷ. ἀλλ’ ὅτι τοῦτον ἀπράγμων ἦσθα τὸν χρόνον; καὶ τίς οὐκ οἶδεν ὅσα πράγματα πράττων οὐ πέπαυσαι, οὐ μόνον δίκας ἰδίας διώκων οὐκ ἐλάττους ταυτησί, ἀλλὰ δημοσίᾳ συκοφαντῶν καὶ κρίνων τίνας οὔ; οὐχὶ Τιμομάχου κατηγόρεις; οὐχὶ Καλλίππου τοῦ νῦν ὄντος ἐν Σικελίᾳ; οὐ πάλιν Μένωνος; οὐκ Αὐτοκλέους; οὐ Τιμοθέου; οὐκ ἄλλων πολλῶν.", "st": "36.53"}, {"sp": "N", "t": "καίτοι πῶς ἔχει λόγον σέ, Ἀπολλόδωρον ὄντα, πρότερον τῶν κοινῶν, ὧν μέρος ἠδικοῦ, δίκην ἀξιοῦν λαμβάνειν, ἢ τῶν ἰδίων ὧν νῦν ἐγκαλεῖς, ἄλλως τε καὶ τηλικούτων ὄντων, ὡς σὺ φής; τί ποτ’ οὖν ἐκείνων κατηγορῶν τόνδ’ εἴας; οὐκ ἠδικοῦ, ἀλλ’ οἶμαι συκοφαντεῖς νῦν. ἡγοῦμαι τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, πάντων μάλιστ’ εἰς τὸ πρᾶγμ’ εἶναι τούτων μάρτυρας παρασχέσθαι· τὸν γὰρ συκοφαντοῦντ’ ἀεὶ τί χρὴ νομίζειν νῦν ποιεῖν.", "st": "36.54"}, {"sp": "N", "t": "καὶ νὴ Δί’ ἔγωγ’, ὦ ἄνδρες Ἀθηναῖοι, νομίζω πάνθ’ ὅσα τοῦ τρόπου τοῦ Φορμίωνός ἐστι σημεῖα καὶ τῆς τούτου δικαιοσύνης καὶ φιλανθρωπίας, καὶ ταῦτ’ εἰς τὸ πρᾶγμ’ εἶναι πρὸς ὑμᾶς εἰπεῖν. ὁ μὲν γὰρ περὶ πάντ’ ἄδικος τάχ’ ἄν, εἰ τύχοι, καὶ τοῦτον ἠδίκει· ὁ δὲ μηδένα μηδὲν ἠδικηκώς, πολλοὺς δ’ εὖ πεποιηκὼς ἑκών, ἐκ τίνος εἰκότως ἂν τρόπου τοῦτον μόνον ἠδίκει τῶν πάντων; τούτων τοίνυν τῶν μαρτυριῶν ἀκούσαντες γνώσεσθε τὸν ἑκατέρου τρόπον.", "st": "36.55"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "36.55"}, {"sp": "N", "t": "ἴθι δὴ καὶ τὰς κατ’ Ἀπολλοδώρου τῆς πονηρίας.", "st": "36.56"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "36.56"}, {"sp": "N", "t": "ἆρ’ οὖν ὅμοιος οὑτοσί; σκοπεῖτε. λέγε.", "st": "36.56"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "36.56"}, {"sp": "N", "t": "ἀνάγνωθι δὴ καὶ ὅσα δημοσίᾳ χρήσιμος τῇ πόλει γέγονεν οὑτοσί.", "st": "36.56"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "36.56"}, {"sp": "N", "t": "τοσαῦτα τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, Φορμίων χρήσιμος γεγονὼς καὶ τῇ πόλει καὶ πολλοῖς ὑμῶν, καὶ οὐδέν’ οὔτ’ ἰδίᾳ οὔτε δημοσίᾳ κακὸν οὐδὲν εἰργασμένος, οὐδ’ ἀδικῶν Ἀπολλόδωρον τουτονί, δεῖται καὶ ἱκετεύει καὶ ἀξιοῖ σωθῆναι, καὶ ἡμεῖς συνδεόμεθ’ οἱ ἐπιτήδειοι ταῦθ’ ὑμῶν. ἐκεῖνο δ’ ὑμᾶς ἀκοῦσαι δεῖ. τοσαῦτα γάρ, ὦ ἄνδρες Ἀθηναῖοι, χρήμαθ’ ὑμῖν ἀνεγνώσθη προσηυπορηκώς, ὅσ’ οὔθ’ οὗτος οὔτ’ ἄλλος οὐδεὶς κέκτηται. πίστις μέντοι Φορμίωνι παρὰ τοῖς εἰδόσι καὶ τοσούτων καὶ πολλῷ πλειόνων χρημάτων, δι’ ἧς καὶ αὐτὸς αὑτῷ καὶ ὑμῖν χρήσιμός ἐστιν.", "st": "36.57"}, {"sp": "N", "t": "ἃ μὴ προῆσθε, μηδ’ ἐπιτρέψητ’ ἀνατρέψαι τῷ μιαρῷ τούτῳ ἀνθρώπῳ, μηδὲ ποιήσητ’ αἰσχρὸν παράδειγμα, ὡς τὰ τῶν ἐργαζομένων καὶ μετρίως ἐθελόντων ζῆν τοῖς βδελυροῖς καὶ συκοφάνταις ὑπάρχει παρ’ ὑμῶν λαβεῖν· πολὺ γὰρ χρησιμώτερ’ ὑμῖν παρὰ τῷδ’ ὄνθ’ ὑπάρχει. ὁρᾶτε γὰρ αὐτοὶ καὶ ἀκούετε τῶν μαρτύρων, οἷον ἑαυτὸν τοῖς δεηθεῖσι παρέχει.", "st": "36.58"}, {"sp": "N", "t": "καὶ τούτων οὐδὲν εἵνεκα τοῦ λυσιτελοῦντος εἰς χρήματα πεποίηκεν, ἀλλὰ φιλανθρωπίᾳ καὶ τρόπου ἐπιεικείᾳ. οὔκουν ἄξιον, ὦ ἄνδρες Ἀθηναῖοι, τὸν τοιοῦτον ἄνδρα προέσθαι τούτῳ, οὐδὲ τηνικαῦτ’ ἐλεεῖν ὅτ’ οὐδὲν ἔσται τούτῳ πλέον, ἀλλὰ νῦν ὅτε κύριοι καθέστατε σῷσαι· οὐ γὰρ ἔγωγ’ ὁρῶ καιρὸν ἐν τίνι ἂν μᾶλλον βοηθήσειέ τις αὐτῷ.", "st": "36.59"}, {"sp": "N", "t": "τὰ μὲν οὖν πόλλ’ ὧν Ἀπολλόδωρος ἐρεῖ, νομίζετ’ εἶναι λόγον καὶ συκοφαντίας, κελεύετε δ’ αὐτὸν ἐπιδεῖξαι, ἢ ὡς οὐ διέθετο ταῦθ’ ὁ πατήρ, ἢ ὡς ἔστιν τις ἄλλη μίσθωσις πλὴν ἧς ἡμεῖς δείκνυμεν, ἢ ὡς οὐκ ἀφῆκεν αὐτὸν διαλογισάμενος τῶν ἐγκλημάτων ἁπάντων, ἃ ἔγνω ⟨θ’⟩ ὁ κηδεστὴς ὁ τούτου καὶ οὗτος αὐτὸς συνεχώρησεν, ἢ ὡς διδόασιν οἱ νόμοι δικάζεσθαι τῶν οὕτω πραχθέντων, ἢ τῶν τοιούτων τι δεικνύναι.", "st": "36.60"}, {"sp": "N", "t": "ἐὰν δ’ ἀπορῶν αἰτίας καὶ βλασφημίας λέγῃ καὶ κακολογῇ, μὴ προσέχετε τὸν νοῦν, μηδ’ ὑμᾶς ἡ τούτου κραυγὴ καὶ ἀναίδει’ ἐξαπατήσῃ, ἀλλὰ φυλάττετε καὶ μέμνησθ’ ὅσ’ ἡμῶν ἀκηκόατε. κἂν ταῦτα ποιῆτε, αὐτοί τ’ εὐορκήσετε καὶ τοῦτον δικαίως σώσετε, ἄξιον ὄντα νὴ τὸν Δία καὶ θεοὺς ἅπαντας.", "st": "36.61"}, {"sp": "N", "t": "ἀνάγνωθι λαβὼν αὐτοῖς τὸν νόμον καὶ τὰς μαρτυρίας τασδί.", "st": "36.62"}, {"sp": "N", "t": "ΝΟΜΟΣ. ΜΑΡΤΥΡΙΑΙ.", "st": "36.62"}, {"sp": "N", "t": "οὐκ οἶδ’ ὅ τι δεῖ πλείω λέγειν. οἶμαι γὰρ ὑμᾶς οὐδὲν ἀγνοεῖν τῶν εἰρημένων. ἐξέρα τὸ ὕδωρ.", "st": "36.62"}, {"sp": "HDR", "t": "Παραγραφὴ πρὸς Πανταίνετον", "st": "37"}, {"sp": "N", "t": "δεδωκότων, ὦ ἄνδρες δικασταί, τῶν νόμων παραγράψασθαι περὶ ὧν ἄν τις ἀφεὶς καὶ ἀπαλλάξας δικάζηται, γεγενημένων ἀμφοτέρων μοι τούτων πρὸς Πανταίνετον τουτονί, παρεγραψάμην, ὡς ἠκούσατ’ ἀρτίως, μὴ εἰσαγώγιμον εἶναι τὴν δίκην, οὐκ οἰόμενος δεῖν ἀφεῖσθαι τοῦ δικαίου τούτου, οὐδ’, ἐπειδὰν ἐξελέγξω πρὸς ἅπασι τοῖς ἄλλοις καὶ ἀφεικότα τοῦτον ἐμαυτὸν καὶ ἀπηλλαγμένον, ἐγγενέσθαι τούτῳ μὴ φάσκειν ἀληθῆ με λέγειν, καὶ ποιεῖσθαι τεκμήριον ὡς, εἴπερ ἐπράχθη τι τοιοῦτον, παρεγραψάμην ἂν αὐτόν, ἀλλ’ ἐπὶ ταύτης τῆς σκήψεως εἰσελθὼν ἀμφότερ’ ὑμῖν ἐπιδεῖξαι, καὶ ὡς οὐδὲν ἠδίκηκα τοῦτον καὶ ὡς παρὰ τὸν νόμον μοι δικάζεται.", "st": "37.1"}, {"sp": "N", "t": "εἰ μὲν οὖν ἐπεπόνθει τι τούτων Πανταίνετος ὧν νῦν ἐγκαλεῖ, κατ’ ἐκείνους ἂν τοὺς χρόνους εὐθὺς ἐφαίνετό μοι δικαζόμενος, ἐν οἷς τὸ συμβόλαιον ἡμῖν πρὸς ἀλλήλους ἐγένετο, οὐσῶν μὲν ἐμμήνων τούτων τῶν δικῶν, ἐπιδημούντων δ’ ἡμῶν ἀμφοτέρων, ἁπάντων δ’ ἀνθρώπων εἰωθότων παρ’ αὐτὰ τἀδικήματα μᾶλλον ἢ χρόνων ἐγγεγενημένων ἀγανακτεῖν. ἐπειδὴ δ’ οὐδὲν ἠδικημένος, ὡς καὶ ὑμεῖς οἶδ’ ὅτι φήσετε, ἐπειδὰν τὰ πεπραγμέν’ ἀκούσητε, τῷ κατορθῶσαι τὴν πρὸς Εὔεργον δίκην ἐπηρμένος συκοφαντεῖ, ὑπόλοιπόν ἐστι παρ’ ὑμῖν, ὦ ἄνδρες δικασταί, ἐπιδείξανθ’ ὡς οὐδ’ ὁτιοῦν ἀδικῶ, καὶ μάρτυρας ὧν ἂν λέγω παρασχόμενον, πειρᾶσθαι σῴζειν ἐμαυτόν.", "st": "37.2"}, {"sp": "N", "t": "δεήσομαι δὲ καὶ μέτρια καὶ δίκαι’ ὑμῶν ἁπάντων, ἀκοῦσαί τέ μου περὶ ὧν παρεγραψάμην εὐνοϊκῶς, καὶ προσέχειν ὅλῳ τῷ πράγματι τὸν νοῦν· πολλῶν γὰρ δικῶν ἐν τῇ πόλει γεγενημένων, οὐδένα πω δίκην οὔτ’ ἀναιδεστέραν οὔτε συκοφαντικωτέραν οἴομαι φανήσεσθαι δεδικασμένον ἧς νῦν οὑτοσὶ λαχὼν εἰσελθεῖν τετόλμηκεν. ἐξ ἀρχῆς δ’, ὡς ἂν οἷός τ’ ὦ διὰ βραχυτάτων, ἅπαντα τὰ πραχθέντα διηγήσομαι πρὸς ὑμᾶς.", "st": "37.3"}, {"sp": "N", "t": "ἐδανείσαμεν πέντε καὶ ἑκατὸν μνᾶς ἐγὼ καὶ Εὔεργος, ὦ ἄνδρες δικασταί, Πανταινέτῳ τουτῳί, ἐπ’ ἐργαστηρίῳ τ’ ἐν τοῖς ἔργοις ἐν Μαρωνείᾳ καὶ τριάκοντ’ ἀνδραπόδοις. ἦν δὲ τοῦ δανείσματος τετταράκοντα μὲν καὶ πέντε μναῖ ἐμαί, τάλαντον δ’ Εὐέργου. συνέβαινε δὲ τοῦτον ὀφείλειν Μνησικλεῖ μὲν Κολλυτεῖ τάλαντον, Φιλέᾳ δ’ Ἐλευσινίῳ καὶ Πλείστορι πέντε καὶ τετταράκοντα μνᾶς.", "st": "37.4"}, {"sp": "N", "t": "πρατὴρ μὲν δὴ τοῦ ἐργαστηρίου καὶ τῶν ἀνδραπόδων ὁ Μνησικλῆς ἡμῖν γίγνεται (καὶ γὰρ ἐώνητ’ ἐκεῖνος αὐτὰ τούτῳ παρὰ Τηλεμάχου τοῦ πρότερον κεκτημένου)· μισθοῦται δ’ οὗτος παρ’ ἡμῶν τοῦ γιγνομένου τόκου τῷ ἀργυρίῳ, πέντε καὶ ἑκατὸν δραχμῶν τοῦ μηνὸς ἑκάστου. καὶ τιθέμεθα συνθήκας, ἐν αἷς ἥ τε μίσθωσις ἦν γεγραμμένη καὶ λύσις τούτῳ παρ’ ἡμῶν ἔν τινι ῥητῷ χρόνῳ.", "st": "37.5"}, {"sp": "N", "t": "πραχθέντων δὲ τούτων ἐλαφηβολιῶνος μηνὸς ἐπὶ Θεοφίλου ἄρχοντος, ἐγὼ μὲν ἐκπλέων εἰς τὸν Πόντον εὐθὺς ᾠχόμην, οὗτος δ’ ἐνθάδ’ ἦν καὶ Εὔεργος. τὰ μὲν δὴ πραχθέντα τούτοις πρὸς αὑτούς, ἕως ἀπεδήμουν ἐγώ, οὐκ ἂν ἔχοιμ’ εἰπεῖν. οὔτε γὰρ ταὐτὰ λέγουσιν οὔτ’ ἀεὶ ταὔθ’ οὗτός γε, ἀλλὰ τοτὲ μὲν ἐκπεσεῖν ὑπ’ ἐκείνου βίᾳ παρὰ τὰς συνθήκας ἐκ τῆς μισθώσεως, τοτὲ δ’ αὐτὸν αἴτιον αὑτῷ πρὸς τὸ δημόσιον γενέσθαι τῆς ἐγγραφῆς, τοτὲ δ’ ἄλλ’ ὅ τι ἂν βούληται.", "st": "37.6"}, {"sp": "N", "t": "ἐκεῖνος δ’ ἁπλῶς οὔτε τοὺς τόκους ἀπολαμβάνων οὔτε τῶν ἄλλων τῶν ἐν ταῖς συνθήκαις ποιοῦντος οὐδὲν τούτου, ἐλθὼν παρ’ ἑκόντος τούτου λαβὼν ἔχειν τὰ ἑαυτοῦ· μετὰ δὲ ταῦτ’ ἀπελθόντα τοῦτον ἥκειν τοὺς ἀμφισβητήσοντας ἄγοντα, αὐτὸς δ’ οὐχ ὑπεξελθεῖν ἐκείνοις, τοῦτον δ’ οὐχὶ κωλύειν ἔχειν ὅσαπερ ἐμισθώσατο, εἰ ποιοίη τὰ συγκείμενα.", "st": "37.7"}, {"sp": "N", "t": "τούτων μὲν δὴ τοιούτους ἀκούω λόγους. ἐκεῖνο δ’ οἶδ’ ὅτι, εἰ μὲν οὗτος ἀληθῆ λέγει καὶ δεινὰ πέπονθεν, ὥσπερ φησίν, ὑπὸ τοῦ Εὐέργου, ἔχει δίκην ἧς ἐτιμήσατ’ αὐτός· εἷλεν γὰρ εἰσελθὼν αὐτὸν ὡς ὑμᾶς, καὶ οὐ δήπου τῶν αὐτῶν παρά τε τοῦ πεποιηκότος δίκαιός ἐστιν δίκην λαβεῖν καὶ παρ’ ἐμοῦ τοῦ μηδ’ ἐπιδημοῦντος· εἰ δ’ ὁ Εὔεργος ἀληθῆ λέγει, σεσυκοφάντηται μὲν ὡς ἔοικεν ἐκεῖνος, ἐγὼ δ’ οὐδ’ οὕτως τῶν αὐτῶν φεύγοιμ’ ἂν δίκην εἰκότως. ὡς οὖν ταῦτα πρῶτον ἀληθῆ λέγω, τούτων τοὺς μάρτυρας ὑμῖν παρέξομαι.", "st": "37.8"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "37.8"}, {"sp": "N", "t": "ὅτι μὲν τοίνυν καὶ πρατὴρ ἦν ἡμῖν τῶν κτημάτων ὅσπερ ἐξ ἀρχῆς αὐτὸς ἐώνητο, καὶ κατὰ τὰς συνθήκας οὗτος ἐμισθώσαθ’ ἡμέτερον ὂν τὸ ἐργαστήριον καὶ τἀνδράποδα, καὶ οὔτε παρῆν ἐγὼ τοῖς μετὰ ταῦτα πρὸς Εὔεργον τούτῳ πραχθεῖσιν οὔτ’ ἐπεδήμουν ὅλως, ἔλαχέν τε δίκην ἐκείνῳ καὶ οὐδὲν πώποθ’ ἡμῖν ἐνεκάλει, ἀκούετε τῶν μαρτύρων, ὦ ἄνδρες δικασταί.", "st": "37.9"}, {"sp": "N", "t": "ἐπειδὴ τοίνυν ἀφικόμην σχεδόν τι πάντ’ ἀπολωλεκὼς ὅσ’ ἔχων ἐξέπλευσα, ἀκούσας καὶ καταλαβὼν τοῦτον μὲν ἀφεστηκότα, τὸν δ’ Εὔεργον ἔχοντα καὶ κρατοῦνθ’ ὧν ἐωνήμεθα, θαυμαστῶς ὡς ἐλυπήθην, ὁρῶν τὸ πρᾶγμά μοι περιεστηκὸς εἰς ἄτοπον· ἢ γὰρ κοινωνεῖν ἔδει τῆς ἐργασίας καὶ τῶν ἐπιμελειῶν τῷ Εὐέργῳ, ἢ χρήστην ἀντὶ τούτου τὸν Εὔεργον ἔχειν, καὶ πρὸς ἐκεῖνον πάλιν μίσθωσιν γράφειν καὶ συμβόλαιον ποιεῖσθαι· τούτων δ’ οὐδέτερον προῃρούμην.", "st": "37.10"}, {"sp": "N", "t": "ἀηδῶς δ’ ἔχων οἷς λέγω τούτοις, ἰδὼν τὸν Μνησικλέα τὸν πρατῆρα τούτων ἡμῖν γεγενημένον, προσελθὼν ἐμεμφόμην αὐτῷ, λέγων οἷον ἄνθρωπον προὐξένησέ μοι, καὶ τοὺς ἀμφισβητοῦντας καὶ τί ταῦτ’ ἐστὶν ἠρώτων. ἀκούσας δ’ ἐκεῖνος τῶν μὲν ἀμφισβητούντων κατεγέλα, συνελθεῖν δ’ ἔφη τούτους βούλεσθαι πρὸς ἡμᾶς, καὶ συνάξειν αὐτὸς ἡμᾶς, καὶ παραινέσειν τούτῳ πάντα ποιεῖν τὰ δίκαι’ ἐμοί, καὶ οἴεσθαι πείσειν.", "st": "37.11"}, {"sp": "N", "t": "ὡς δὲ συνήλθομεν, τὰ μὲν πολλὰ τί δεῖ λέγειν; ἧκον δ’ οἱ δεδανεικέναι φάσκοντες τούτῳ ἐπὶ τῷ ἐργαστηρίῳ καὶ τοῖς ἀνδραπόδοις ἃ ἡμεῖς ἐπριάμεθα παρὰ Μνησικλέους, καὶ οὐδὲν ἦν ἁπλοῦν οὐδ’ ὑγιὲς τούτων. πάντα δ’ ἐξελεγχόμενοι ψευδῆ λέγοντες, καὶ τοῦ Μνησικλέους βεβαιοῦντος ἡμῖν, προκαλοῦνται πρόκλησιν ἡμᾶς ὡς οὐ δεξομένους, ἢ κομίσασθαι πάντα τὰ χρήματα παρ’ αὑτῶν καὶ ἀπελθεῖν, ἢ διαλῦσαι σφᾶς ὑπὲρ ὧν ἐνεκάλουν, αἰτιώμενοι πολλῷ πλείονος ἄξι’ ἔχειν ὧν ἐδεδώκεμεν χρημάτων.", "st": "37.12"}, {"sp": "N", "t": "ἀκούσας δ’ ἐγώ, παραχρῆμα, οὐδὲ βουλευσάμενος, κομίσασθαι συνεχώρησα, καὶ τὸν Εὔεργον ἔπεισα. ἐπειδὴ δ’ ἔδει τὰ χρήμαθ’ ἡμᾶς ἀπολαμβάνειν καὶ τὸ πρᾶγμ’ εἰς τοῦτο προῆκτο, οὐκ ἔφασαν μετὰ ταῦτα δώσειν οἱ τότ’ ἐκεῖν’ ἐπαγγειλάμενοι, εἰ μὴ πρατῆρες γιγνοίμεθ’ ἡμεῖς τῶν κτημάτων αὐτοῖς, νοῦν ἔχοντες, ὦ ἄνδρες Ἀθηναῖοι, κατ’ αὐτό γε τοῦτο· ἑώρων γὰρ ἡμᾶς οἷ’ ἐσυκοφαντούμεθ’ ὑπὸ τούτου. ὡς οὖν καὶ ταῦτ’ ἀληθῆ λέγω, λαβέ μοι καὶ ταύτας τὰς μαρτυρίας.", "st": "37.13"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "37.13"}, {"sp": "N", "t": "ἐπειδὴ τοίνυν τὸ πρᾶγμ’ ἐνταῦθ’ εἱστήκει, καὶ τὰ μὲν χρήματ’ οὐ προΐενθ’ οὓς ἐπήγαγεν οὗτος, ἡμεῖς δ’ εἰκότως ἐφαινόμεθ’ ὧν ἐωνήμεθα κρατεῖν, ἱκέτευεν, ἐδεῖτο, ἠντεβόλει πρατῆρας ἡμᾶς γενέσθαι. ἀξιοῦντος δὲ τούτου καὶ πολλὰ δεηθέντος ἐμοῦ καὶ τί οὐ ποιήσαντος; καὶ τοῦθ’ ὑπέμεινα.", "st": "37.14"}, {"sp": "N", "t": "ὁρῶν δ’ αὐτόν, ὦ ἄνδρες Ἀθηναῖοι, κακοήθη, καὶ τὸ μὲν ἐξ ἀρχῆς τοῦ Μνησικλέους κατηγοροῦντα πρὸς ἡμᾶς, πάλιν δ’ ᾧ φίλος ἦν τὰ μάλιστα, τῷ Εὐέργῳ, τούτῳ προσκεκρουκότα, καὶ τὸ μὲν πρῶτον ὡς ἐγὼ κατέπλευσα, ἅσμενον φάσκονθ’ ἑορακέναι με, ἐπειδὴ δ’ ἔδει τὰ δίκαια ποιεῖν, ἐμοὶ πάλιν δυσκολαίνοντα, καὶ ἅπασι μέχρι τοῦ προλαβεῖν καὶ τυχεῖν ὧν δέοιτο φίλον ὄντα, μετὰ ταῦτα δ’ ἐχθρὸν καὶ διάφορον γιγνόμενον,", "st": "37.15"}, {"sp": "N", "t": "ἠξίουν ἀπαλλαττόμενος καὶ πρατὴρ ὑπὲρ τούτου γιγνόμενος, πάντων ἀφεθεὶς τῶν ἐγκλημάτων καὶ ἀπαλλαγείς, οὕτω διαλύεσθαι. τούτων δὲ συγχωρηθέντων οὗτος μὲν ἀφῆκεν ἁπάντων ἐμέ, ἐγὼ δὲ πρατήρ, ὥσπερ ἐδεῖθ’ οὗτος, τῶν κτημάτων ἐγιγνόμην, καθάπερ αὐτὸς ἐπριάμην παρὰ Μνησικλέους. κομισάμενος δὲ τἀμαυτοῦ καὶ τοῦτον οὐδ’ ὁτιοῦν ἀδικῶν, μὰ τοὺς θεούς, οὐδ’ ἂν εἴ τι γένοιτο, ᾠήθην ἂν δίκην μοι λαχεῖν ποτὲ τουτονί.", "st": "37.16"}, {"sp": "N", "t": "τὰ μὲν δὴ γεγενημένα, καὶ περὶ ὧν οἴσετε τὴν ψῆφον, καὶ δι’ ἃ τὴν δίκην συκοφαντούμενος παρεγραψάμην μὴ εἰσαγώγιμον εἶναι, ταῦτ’ ἐστιν, ὦ ἄνδρες δικασταί. παρασχόμενος δὲ μάρτυρας οἳ παρῆσαν ἡνίκ’ ἀφιέμην ὑπὸ τούτου καὶ ἀπηλλαττόμην, ὡς οὐκ εἰσαγώγιμος ἐκ τῶν νόμων ἐστὶν ἡ δίκη, μετὰ ταῦτ’ ἐπιδείξω. καί μοι λέγε ταύτην τὴν μαρτυρίαν.", "st": "37.17"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "37.17"}, {"sp": "N", "t": "λέγε δή μοι καὶ τὴν τῶν ἐωνημένων μαρτυρίαν, ἵν’ εἰδῆθ’ ὅτι τούτου κελεύοντος αὔτ’ ἀπεδόμην οἷς οὗτος ἐκέλευσεν.", "st": "37.17"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "37.17"}, {"sp": "N", "t": "οὐ τοίνυν μόνον ἡμῖν εἰσιν οὗτοι μάρτυρες, ὡς ἀφείμεθα καὶ νῦν συκοφαντούμεθα, ἀλλὰ καὶ Πανταίνετος αὐτός. ὅτε γὰρ λαγχάνων Εὐέργῳ τὴν δίκην εἴασεν ἐμέ, τότ’ ἐμαρτύρει [οὗτος] πρὸς ἔμ’ αὑτῷ μηδὲν ἔγκλημ’ ὑπόλοιπον εἶναι· οὐ γὰρ ἂν δήπου, τῶν αὐτῶν ἀδικημάτων παρόντων, ἀμφοῖν δ’ ὁμοίως ἐγκαλῶν, τὸν μὲν εἴασεν τῷ δ’ ἐδικάζετο. ἀλλὰ μὴν ὅτι γ’ οὐκ ἐῶσιν οἱ νόμοι περὶ τῶν οὕτω πραχθέντων πάλιν λαγχάνειν, οἶμαι μὲν ὑμᾶς καὶ μηδὲν εἰπόντος ἐμοῦ γιγνώσκειν· ὅμως δὲ λέγ’ αὐτοῖς καὶ τὸν νόμον τουτονί.", "st": "37.18"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "37.18"}, {"sp": "N", "t": "ἀκούετ’, ὦ ἄνδρες δικασταί, τοῦ νόμου λέγοντος ἄντικρυς, ὧν ἂν ἀφῇ καὶ ἀπαλλάξῃ τις, μηκέτι τὰς δίκας εἶναι. καὶ μὴν ὅτι γ’ ἀμφότερ’ ἐστὶ πεπραγμένα ταῦτα τούτῳ πρὸς ἡμᾶς, ἠκούσατε τῶν μαρτυριῶν. ἁπάντων μὲν τοίνυν τῶν ἐν τοῖς νόμοις ἀπειρημένων οὐ προσήκει δικάζεσθαι, ἥκιστα δὲ τούτων. ἃ μὲν γὰρ τὸ δημόσιον πέπρακεν, ἔχοι τις ἂν εἰπεῖν ὡς ἀδίκως οὐ προσήκοντα πέπρακεν·", "st": "37.19"}, {"sp": "N", "t": "καὶ περὶ ὧν ἔγνω τὸ δικαστήριον, ἔστιν εἰπεῖν ὡς ἐξαπατηθὲν τοῦτ’ ἐποίησεν, καὶ περὶ τῶν ἄλλων τῶν ἐν τῷ νόμῳ καθ’ ἑκάστου γένοιτ’ ἄν τις εἰκότως λόγος. ἃ δ’ αὐτὸς ἐπείσθη καὶ ἀφῆκεν, οὐκ ἔνι δήπουθεν εἰπεῖν οὐδ’ αὑτὸν αἰτιάσασθαι, ὡς οὐ δικαίως ταῦτ’ ἐποίησεν. οἱ μὲν οὖν παρά τι τῶν ἄλλων τούτων δικαζόμενοι τοῖς ὑφ’ ἑτέρων δικαίοις ὡρισμένοις οὐκ ἐμμένουσιν, ὁ δ’ ὧν ἂν ἀφῇ πάλιν λαγχάνων τοῖς ὑφ’ ἑαυτοῦ. διὸ πάντων μάλιστ’ ἄξιον τούτοις χαλεπαίνειν.", "st": "37.20"}, {"sp": "N", "t": "οὐκοῦν ὡς μὲν ἀφῆκέ με πάντων, ὅτ’ ἐγιγνόμην τῶν ἀνδραπόδων πρατήρ, ἐπέδειξα· ὅτι δ’ οὐκ ἐῶσιν οἱ νόμοι τούτων εἶναι δίκας, ἀκηκόατ’ ἀρτίως ἀναγιγνωσκομένου τοῦ νόμου. ἵνα δ’, ὦ ἄνδρες Ἀθηναῖοι, μή τις οἴηται τοῖς περὶ τῶν πραγμάτων αὐτῶν δικαίοις ἁλισκόμενόν μ’ ἐπὶ τοῦτ’ ἀποχωρεῖν, καὶ καθ’ ἕκαστον ὧν ἐγκαλεῖ βούλομαι δεῖξαι αὐτὸν ψευδόμενον.", "st": "37.21"}, {"sp": "N", "t": "λέγε δ’ αὐτὸ τὸ ἔγκλημα, ὅ μοι δικάζεται.", "st": "37.22"}, {"sp": "N", "t": "ΕΓΚΛΗΜΑ.", "st": "37.22"}, {"sp": "N", "t": "ἔβλαψέ με Νικόβουλος ἐπιβουλεύσας ἐμοὶ καὶ τῇ οὐσίᾳ τῇ ἐμῇ, ἀφελέσθαι κελεύσας Ἀντιγένην τὸν ἑαυτοῦ οἰκέτην τὸ ἀργύριον τοῦ ἐμοῦ οἰκέτου, ὃ ἔφερεν καταβολὴν τῇ πόλει τοῦ μετάλλου, ὃ ἐγὼ ἐπριάμην ἐνενήκοντα μνῶν, καὶ αἴτιος ἐμοὶ γενόμενος ἐγγραφῆναι τὸ διπλοῦν τῷ δημοσίῳ.", "st": "37.22"}, {"sp": "N", "t": "ἐπίσχες. ταυτὶ πάντα, ἃ νῦν ἐγκέκληκεν ἐμοί, πρότερον τὸν Εὔεργον αἰτιασάμενος τὴν δίκην εἷλε. μεμαρτύρηται μὲν δὴ καὶ ἐν ἀρχῇ μοι τοῦ λόγου πρὸς ὑμᾶς ὡς ἀπεδήμουν, ὅτε τούτοις αἱ πρὸς ἀλλήλους ἐγίγνοντο διαφοραί· οὐ μὴν ἀλλὰ καὶ ἐκ τοῦ ἐγκλήματος τούτου δῆλόν ἐστιν. οὐδαμοῦ γὰρ ὡς ἐγώ τι πεποίηκα τούτων ἔγραψεν, ἀλλ’ ὑπογράψας ἐπιβουλεῦσαί με αὑτῷ καὶ τῇ οὐσίᾳ, προστάξαι φησὶ τῷ παιδὶ ταῦτα ποιεῖν, ψευδόμενος· πῶς γὰρ ἐγὼ προσέταξα, ὃς ὅτ’ ἐξέπλεον τῶν γενησομένων ἐνταῦθ’ οὐδ’ ὁτιοῦν δήπουθεν ᾔδειν;", "st": "37.23"}, {"sp": "N", "t": "εἶτα καὶ πόση μωρία, λέγονθ’ ὡς ἐπεβούλευον ἀτιμῶσαι καὶ τὰ ἔσχατα πρᾶξαι, οἰκέτῃ με ταῦτα προστάξαι γεγραφέναι, ἃ οὐδὲ πολίτης πολίτην δύναιτ’ ἂν ποιῆσαι; τί οὖν ἐστι τοῦτο; οὐκ ἔχων οἶμαι κατ’ οὐδὲν διὰ τὴν ἀποδημίαν εἰς ἐμὲ τούτων ἀνενεγκεῖν τι, συκοφαντεῖν δὲ βουλόμενος, ὡς προσέταξα, ἐνέγραψεν· οὐδὲ γὰρ λόγος ἦν, εἰ μὴ τοῦτ’ ἐποίησε.", "st": "37.24"}, {"sp": "N", "t": "λέγε τἀκόλουθον.", "st": "37.25"}, {"sp": "N", "t": "ΕΓΚΛΗΜΑ.", "st": "37.25"}, {"sp": "N", "t": "καὶ ἐπειδὴ ὦφλον ἐγὼ τῷ δημοσίῳ, καταστήσας Ἀντιγένην τὸν ἑαυτοῦ οἰκέτην εἰς τὸ ἐργαστήριον τὸ ἐμὸν τὸ ἐπὶ Θρασύλλῳ κύριον τῶν ἐμῶν, ἀπαγορεύοντος ἐμοῦ.", "st": "37.25"}, {"sp": "N", "t": "ἐπίσχες. πάλιν ταυτὶ πάνθ’ ὑπ’ αὐτοῦ τοῦ πράγματος ἐξελεγχθήσεται ψευδόμενος. γέγραφεν γὰρ καταστῆσαι μὲν ἐμέ, ἀπαγορεύειν δ’ αὑτόν. ταῦτα δ’ οὐχ οἷόν τε τὸν μὴ παρόντα. οὔτε γὰρ καθίστην ἐγώ, ὅ γ’ ὢν ἐν τῷ Πόντῳ, οὔτ’ ἀπηγόρευεν οὗτος τῷ μὴ παρόντι· πῶς γάρ;", "st": "37.25"}, {"sp": "N", "t": "πῶς οὖν εἰς ἀνάγκην ἦλθεν ταῦθ’ οὕτω γράψαι; ὁ Εὔεργος τότ’ οἶμαι πλημμελῶν ὧν δέδωκε δίκην, συνήθως ἔχων ἐμοὶ καὶ γνώριμος ὢν κατέστησεν τὸν οἰκέτην οἴκοθεν λαβὼν παρ’ ἐμοῦ φυλάττειν ὡς αὑτόν. εἰ μὲν οὖν ἔγραψε τἀληθές, γέλως ἂν ἦν· τί γάρ, εἰ κατέστησεν Εὔεργος, ἐγώ σ’ ἀδικῶ; φεύγων δὲ τοῦτο τοιαῦτ’ ἠνάγκασται γράφειν, ἵν’ ᾖ πρὸς ἔμ’ αὐτῷ τὸ ἔγκλημα. λέγε τὰ ἐφεξῆς.", "st": "37.26"}, {"sp": "N", "t": "ΕΓΚΛΗΜΑ.", "st": "37.26"}, {"sp": "N", "t": "κἄπειτα πείσας τοὺς οἰκέτας τοὺς ἐμοὺς καθέζεσθαι εἰς τὸν κεγχρεῶνα ἐπὶ βλάβῃ τῇ ἐμῇ.", "st": "37.26"}, {"sp": "N", "t": "τουτὶ παντελῶς ἤδη καὶ ἀναιδές ἐστιν· οὐ γὰρ μόνον ἐκ τοῦ προκαλεῖσθαι τούτους παραδοῦναι, τοῦτον δὲ μὴ ’θέλειν, ἀλλὰ καὶ ἐκ πάντων δῆλόν ἐστιν ψεῦδος ὄν. τίνος γὰρ εἵνεκ’ ἔπειθον; ἵνα νὴ Δί’ αὐτοὺς κτήσωμαι. ἀλλ’ αἱρέσεώς μοι δοθείσης ἢ ἔχειν ἢ κομίσασθαι τὰ ἐμαυτοῦ, εἱλόμην κομίσασθαι, καὶ ταῦτα μεμαρτύρηται. λέγε δὴ τὴν πρόκλησιν ὅμως.", "st": "37.27"}, {"sp": "N", "t": "ΠΡΟΚΛΗΣΙΣ.", "st": "37.27"}, {"sp": "N", "t": "ταύτην τοίνυν οὐχὶ δεξάμενος τὴν πρόκλησιν, ἀλλὰ φυγών, σκέψασθ’ οἷον εὐθέως μετὰ ταῦτ’ ἐγκαλεῖ. λέγε τοὐχόμενον.", "st": "37.28"}, {"sp": "N", "t": "ΕΓΚΛΗΜΑ.", "st": "37.28"}, {"sp": "N", "t": "καὶ κατεργασάμενος τὴν ἀργυρῖτιν, ἣν οἱ ἐμοὶ οἰκέται ἠργάσαντο, καὶ ἔχων τὸ ἀργύριον τὸ ἐκ ταύτης τῆς ἀργυρίτιδος.", "st": "37.28"}, {"sp": "N", "t": "πάλιν ταῦτα πῶς ἔνεστ’ ἐμοὶ πεπρᾶχθαι τῷ μὴ παρόντι, καὶ περὶ ὧν Εὐέργου κατεδικάσω;", "st": "37.28"}, {"sp": "N", "t": "λέγε δ’ αὐτοῖς τὸ ἐφεξῆς.", "st": "37.29"}, {"sp": "N", "t": "ΕΓΚΛΗΜΑ.", "st": "37.29"}, {"sp": "N", "t": "καὶ ἀποδόμενος τὸ ἐργαστήριον τὸ ἐμὸν καὶ τοὺς οἰκέτας παρὰ τὰς συνθήκας, ἃς ἔθετο πρός με.", "st": "37.29"}, {"sp": "N", "t": "ἐπίσχες. τουτὶ πολὺ πάνθ’ ὑπερβέβληκεν τἄλλα. πρῶτον μὲν γὰρ παρὰ τὰς συνθήκας φησίν, ἃς ἔθετο πρὸς ἐμέ. αὗται δ’ εἰσὶ τίνες; ἐμισθώσαμεν τῶν τόκων τῶν γιγνομένων τούτῳ τὰ ἡμέτερ’ ἡμεῖς, καὶ ἄλλ’ οὐδέν· πρατὴρ μὲν γὰρ ὁ Μνησικλῆς ἡμῖν ἐγεγόνει τούτου παρόντος καὶ κελεύοντος.", "st": "37.29"}, {"sp": "N", "t": "μετὰ ταῦτα δὲ τὸν αὐτὸν τρόπον ἡμεῖς ἑτέροις ἀπεδόμεθα, ἐφ’ οἷσπερ αὐτοὶ ἐπριάμεθα, οὐ μόνον κελεύοντος ἔτι τούτου, ἀλλὰ καὶ ἱκετεύοντος· οὐδεὶς γὰρ ἤθελεν δέχεσθαι τοῦτον πρατῆρα. τί οὖν αἱ τῆς μισθώσεως ἐνταῦθα συνθῆκαι; τί τοῦτ’, ὦ φαυλότατ’ ἀνθρώπων, ἐνέγραψας; ἀλλὰ μὴν ὅτι σοῦ κελεύοντος καὶ ἐφ’ οἷσπερ ἐωνήμεθ’ αὐτοὶ πάλιν ἀπεδόμεθα, λέγε τὴν μαρτυρίαν.", "st": "37.30"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "37.30"}, {"sp": "N", "t": "μαρτυρεῖς τοίνυν καὶ σύ· ἃ γὰρ ἡμεῖς πέντε καὶ ἑκατὸν μνῶν ἐωνήμεθα, ταῦθ’ ὕστερον τριῶν ταλάντων καὶ δισχιλίων καὶ ἑξακοσίων ἀπέδου σύ· καίτοι τίς ἂν καθάπαξ πρατῆρά σ’ ἔχων σοὶ δραχμὴν ἔδωκε μίαν; ἀλλὰ μὴν ὅτι ταῦτ’ ἀληθῆ λέγω, κάλει μοι τούτων τοὺς μάρτυρας.", "st": "37.31"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "37.31"}, {"sp": "N", "t": "ἔχων μὲν τοίνυν ἣν ἐπείσθη τῶν αὑτοῦ τιμήν, δεηθεὶς δ’ ἐμοῦ τὸ γενέσθαι πρατῆρα καθ’ ὃ συνέβαλον ἀργύριον, αὑτὸς δυοῖν ταλάντοιν προσδικάζεται. καὶ τὰ λοιπὰ τῶν ἐγκλημάτων ἔτ’ ἐστὶ δεινότερα. λέγε δή μοι τὸ λοιπὸν τοῦ ἐγκλήματος.", "st": "37.32"}, {"sp": "N", "t": "ΕΓΚΛΗΜΑ.", "st": "37.32"}, {"sp": "N", "t": "ἐνταυθὶ πόλλ’ ἄττα καὶ δεινά μοι ἅμ’ ἐγκαλεῖ· καὶ γὰρ αἴκειαν καὶ ὕβριν καὶ βιαίων καὶ πρὸς ἐπικλήρους ἀδικήματα. τούτων δ’ εἰσὶν ἑκάστου χωρὶς αἱ δίκαι καὶ οὔτε πρὸς ἀρχὴν τὴν αὐτὴν οὔθ’ ὑπὲρ τιμημάτων τῶν αὐτῶν, ἀλλ’ ἡ μὲν αἴκεια καὶ τὰ τῶν βιαίων πρὸς τοὺς τετταράκοντα, αἱ δὲ τῆς ὕβρεως πρὸς τοὺς θεσμοθέτας, ὅσα δ’ εἰς ἐπικλήρους, πρὸς τὸν ἄρχοντα. οἱ δὲ νόμοι καὶ τούτων διδόασι τὰς παραγραφὰς ἀντιλαγχάνειν, περὶ ὧν οὐκ εἰσὶν εἰσαγωγεῖς. λέγε δ’ αὐτοῖς τουτονὶ τὸν νόμον.", "st": "37.33"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "37.33"}, {"sp": "N", "t": "τοῦτο τοίνυν ἐμοῦ παραγεγραμμένου πρὸς τῇ ἄλλῃ παραγραφῇ, “καὶ οὐκ ὄντων εἰσαγωγέων τῶν θεσμοθετῶν ὑπὲρ ὧν λαγχάνει Πανταίνετος,” ἐξαλήλιπται καὶ οὐ πρόσεστι τῇ παραγραφῇ. τὸ δ’ ὅπως, ὑμεῖς σκοπεῖτε· ἐμοὶ μὲν γάρ, ἕως ἂν ἔχω τὸν νόμον αὐτὸν δεικνύναι, οὐδ’ ὁτιοῦν διαφέρει· οὐ γὰρ τὸ γιγνώσκειν καὶ συνιέναι τὰ δίκαι’ ὑμῶν ἐξαλεῖψαι δυνήσεται.", "st": "37.34"}, {"sp": "N", "t": "λαβὲ δὴ καὶ τὸν μεταλλικὸν νόμον· καὶ γὰρ ἐκ τούτου δείξειν οἴομαι, οὔτ’ οὖσαν εἰσαγώγιμον τὴν δίκην, χάριτός τ’ ὢν μᾶλλον ἄξιος ἢ τοῦ συκοφαντεῖσθαι. λέγε.", "st": "37.35"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "37.35"}, {"sp": "N", "t": "οὗτος σαφῶς ὁ νόμος διείρηκεν ὧν εἶναι δίκας προσήκει μεταλλικάς. οὐκοῦν ὁ μὲν νόμος, ἐάν τις ἐξίλλῃ τινὰ τῆς ἐργασίας, ὑπόδικον ποιεῖ· ἐγὼ δ’ οὐχ ὅπως αὐτὸς ἐξίλλω, ἀλλ’ ὧν τοῦτον ἄλλος ἀπεστέρει, τούτων ἐγκρατῆ κατέστησα καὶ παρέδωκα, καὶ πρατὴρ τούτου δεηθέντος ἐγενόμην.", "st": "37.35"}, {"sp": "N", "t": "ναί, φησίν· ἀλλὰ κἂν ἄλλο τι ἀδικῇ τις περὶ τὰ μέταλλα, καὶ τούτων εἰσὶν δίκαι. ὀρθῶς γ’, ὦ Πανταίνετε· ἀλλὰ ταῦτα τί ἐστιν; ἂν τύφῃ τις, ἂν ὅπλ’ ἐπιφέρῃ, ἂν ἐπικατατέμνῃ τῶν μέτρων ἐντός. ταῦτ’ ἐστὶν τἄλλα, ὧν οὐδὲν δήπου πέπρακται πρὸς ὑμᾶς ἐμοί, πλὴν εἰ τοὺς κομιζομένους ἃ προεῖντό σοι, μεθ’ ὅπλων ἥκειν νομίζεις. εἰ δὲ ταῦθ’ ἡγεῖ, πρὸς ἅπαντας τοὺς προϊεμένους τὰ ἑαυτῶν εἰσί σοι δίκαι μεταλλικαί.", "st": "37.36"}, {"sp": "N", "t": "ἀλλ’ οὐ δίκαιον. φέρε γάρ, ὅστις ἂν μέταλλον παρὰ τῆς πόλεως πρίηται, τοὺς κοινοὺς παρελθὼν νόμους, καθ’ οὓς καὶ διδόναι καὶ λαμβάνειν πᾶσι προσήκει δίκας, ἐν ταῖς μεταλλικαῖς δικάσεται, ἐὰν δανείσηται παρά του; τί δ’, ἂν κακῶς ἀκούσῃ; ἂν πληγὰς λάβῃ; ἂν κλοπὴν ἐγκαλῇ; ἂν προεισφορὰν μὴ κομίζηται; ἂν ὅλως ἄλλο τι;", "st": "37.37"}, {"sp": "N", "t": "ἐγὼ μὲν οὐκ οἴομαι, ἀλλὰ τὰς μεταλλικὰς εἶναι δίκας τοῖς κοινωνοῦσι μετάλλου καὶ τοῖς ἕτερον συντρήσασιν εἰς τὰ τῶν πλησίον καὶ ὅλως τοῖς ἐργαζομένοις τὰ μέταλλα καὶ τῶν ἐν τῷ νόμῳ τι ποιοῦσιν, τῷ δὲ δανείσαντι Πανταινέτῳ, καὶ ταῦτ’ ἀπειληφότι γλίσχρως καὶ μόλις παρὰ τούτου, οὐκ εἶναι δίκην μεταλλικὴν πρὸς φευκτέον, οὐδ’ ἐγγύς.", "st": "37.38"}, {"sp": "N", "t": "ὡς μὲν οὖν οὔτ’ ἠδίκηκα τοῦτον οὐδὲν οὔτ’ εἰσαγώγιμος ἐκ τῶν νόμων ἐστὶν ἡ δίκη, ταῦτ’ ἄν τις σκοπῶν ῥᾳδίως γνοίη. οὐδὲν τοίνυν δίκαιον ἔχων οὐδὲ καθ’ ἓν λέγειν ὑπὲρ ὧν ἐγκαλεῖ, ἀλλὰ καὶ ψευδῆ γεγραφὼς εἰς τὸ ἔγκλημα καὶ περὶ ὧν ἀφῆκε δικαζόμενος, τοῦ ἐξελθόντος μηνός, ὦ ἄνδρες Ἀθηναῖοι, ἐπειδὴ ἔμελλον εἰσιέναι τὴν δίκην, ἤδη τῶν δικαστηρίων ἐπικεκληρωμένων, προσελθὼν καὶ περιστήσας τοὺς μεθ’ ἑαυτοῦ, τὸ ἐργαστήριον τῶν συνεστώτων, πρᾶγμα ποιεῖ πάνδεινον·", "st": "37.39"}, {"sp": "N", "t": "ἀναγιγνώσκει μοι πρόκλησιν μακράν, ἀξιῶν, ὅν φησιν οἰκέτην ταῦτα συνειδέναι, βασανίζεσθαι, κἂν μὲν ᾖ ταῦτ’ ἀληθῆ, τὴν δίκην ἀτίμητον ὀφλεῖν αὑτῷ, ἐὰν δὲ ψευδῆ, τὸν βασανιστὴν Μνησικλέα ἐπιγνώμον’ εἶναι τῆς τιμῆς τῆς τοῦ παιδός. λαβὼν δ’ ἐγγυητὰς τούτων παρ’ ἐμοῦ, καὶ σημηναμένου τὴν πρόκλησιν ἐμοῦ, οὐχ ὡς δίκαιον ὄν (ποῦ γάρ ἐστι δίκαιον,", "st": "37.40"}, {"sp": "N", "t": "ἐν οἰκέτου σώματι καὶ ψυχῇ ἢ δύ’ ὠφληκέναι τάλαντα, ἢ μηδὲν τὸν συκοφαντοῦντα ζημιοῦσθαι;) ἀλλ’ ἐγὼ πολλῷ τῷ δικαίῳ περιεῖναι βουλόμενος συνεχώρουν. καὶ μετὰ ταῦτα προσκαλεῖται μέν με τὴν δίκην πάλιν, ἐπειδὴ θᾶττον ἀνείλετο τὰς παρακαταβολάς (οὕτως εὐθὺς ἦν δῆλος οὐδ’ οἷς αὐτὸς ὡρίσατ’ ἐμμένων δικαίοις)·", "st": "37.41"}, {"sp": "N", "t": "ἐπειδὴ δ’ ἥκομεν πρὸς τὸν βασανιστήν, ἀντὶ τοῦ τὴν πρόκλησιν ἀνοίξας δεῖξαι τὰ γεγραμμένα καὶ κατὰ ταῦτα πράττειν ὅ τι δόξαι (διὰ γὰρ τὸν θόρυβον τότε καὶ τὸ μέλλειν καλεῖσθαι τὴν δίκην τοιοῦτον ἦν· προκαλοῦμαί σε ταυτί· δέχομαι· φέρε δὴ τὸν δακτύλιον· λαβέ· τίς δ’ ἐγγυητής; οὑτοσί· οὐδὲν οὔτ’ ἀντίγραφον οὔτ’ ἄλλ’ οὐδὲν ἐποιησάμην τοιοῦτον) ἀντὶ δὲ τοῦ ταῦθ’ οὕτως ὥσπερ λέγω πράττειν ἑτέραν ἧκεν ἔχων πρόκλησιν, ἀξιῶν αὐτὸς βασανίζειν τὸν ἄνθρωπον, καὶ ἐπιλαβόμενος εἷλκεν, καὶ ἐνέλειπεν οὐδὲν ἀσελγείας.", "st": "37.42"}, {"sp": "N", "t": "καὶ ἔγωγ’ ἐνεθυμήθην, ὦ ἄνδρες δικασταί, ἡλίκον ἐστὶ πλεονέκτημα τὸ καταπεπλάσθαι τὸν βίον. ἐγὼ γὰρ ἐμαυτῷ ταῦτα πάσχειν ἐδόκουν καταφρονούμενος τῷ ἁπλῶς καὶ ὡς πέφυκα ζῆν, καὶ δίκην διδόναι παμμεγέθη ταῦτ’ ἀνεχόμενος. ὅτι δ’ οὖν ἠναγκαζόμην, παρ’ ἃ ἡγούμην δίκαι’ εἶναι, ἀντιπροκαλεῖσθαι, καὶ τὸν οἰκέτην παρεδίδουν, καὶ ὅτι ταῦτ’ ἀληθῆ λέγω, λέγε τὴν πρόκλησιν.", "st": "37.43"}, {"sp": "N", "t": "ΠΡΟΚΛΗΣΙΣ.", "st": "37.43"}, {"sp": "N", "t": "φυγὼν μὲν τοίνυν ταῦτα, φυγὼν δ’ ἃ τὸ πρῶτον αὐτὸς προὐκαλέσατο, ἔγωγ’, ὅ τι ποτ’ ἐρεῖ πρὸς ὑμᾶς, θαυμάζω. ἵνα δ’ εἰδῆθ’ ὑφ’ οὗ φησὶ καὶ τὰ δεινὰ πεπονθέναι, θεάσασθε. οὗτός ἐστιν ὁ Πανταίνετον ἐκβαλών, οὗτός ἐσθ’ ὁ κρείττων τῶν φίλων τῶν Πανταινέτου καὶ τῶν νόμων. οὐ γὰρ ἔγωγ’ ἐπεδήμουν, οὐδ’ αὐτὸς ἐγκαλεῖ.", "st": "37.44"}, {"sp": "N", "t": "βούλομαι δ’ ὑμῖν καὶ δι’ ὧν τοὺς πρότερον δικαστὰς ἐξαπατήσας εἷλε τὸν Εὔεργον εἰπεῖν, ἵν’ εἰδῆθ’ ὅτι καὶ νῦν οὐδὲν οὔτ’ ἀναιδείας οὔτε τοῦ ψεύδεσθαι παραλείψει. πρὸς δὲ τούτοις καὶ περὶ ὧν ἐμοὶ δικάζεται νυνί, τὰς αὐτὰς οὔσας ἀπολογίας εὑρήσετε· ὅσπερ ἔλεγχος ἀκριβέστατός ἐστιν ὑπὲρ τοῦ τότ’ ἐκεῖνον σεσυκοφαντῆσθαι. οὗτος γὰρ ᾐτιάσατ’ ἐκεῖνον πρὸς ἅπασι τοῖς ἄλλοις ἐλθόντ’ εἰς ἀγρὸν ὡς αὑτὸν ἐπὶ τὰς ἐπικλήρους εἰσελθεῖν καὶ τὴν μητέρα τὴν αὑτοῦ, καὶ τοὺς νόμους ἧκεν ἔχων τοὺς τῶν ἐπικλήρων πρὸς τὸ δικαστήριον.", "st": "37.45"}, {"sp": "N", "t": "καὶ πρὸς μὲν τὸν ἄρχοντα, ὃν τῶν τοιούτων οἱ νόμοι κελεύουσιν ἐπιμελεῖσθαι, καὶ παρ’ ᾧ τῷ μὲν ἠδικηκότι κίνδυνος περὶ τοῦ τί χρὴ παθεῖν ἢ ἀποτεῖσαι, τῷ δ’ ἐπεξιόντι μετ’ οὐδεμιᾶς ζημίας ἡ βοήθεια, οὐδέπω καὶ τήμερον ἐξήτασται, οὐδ’ εἰσήγγειλεν οὔτ’ ἔμ’ οὔτε τὸν Εὔεργον ὡς ἀδικοῦντας, ἐν δὲ τῷ δικαστηρίῳ ταῦτα κατηγόρει καὶ δυοῖν ταλάντοιν εἷλε δίκην.", "st": "37.46"}, {"sp": "N", "t": "ἦν γὰρ οἶμαι κατὰ μὲν τοὺς νόμους προειδότα τὴν αἰτίαν, ἐφ’ ᾗ κρίνεται, ῥᾴδιον τἀληθῆ καὶ τὰ δίκαι’ ἐπιδείξαντ’ ἀποφεύγειν, ἐν δὲ μεταλλικῇ δίκῃ, περὶ ὧν οὐδ’ ἂν ἤλπισεν αὑτοῦ κατηγορηθήσεσθαι, χαλεπὸν παραχρῆμ’ ἔχειν ἀπολύσασθαι τὴν διαβολήν· ἡ δ’ ὀργὴ ⟨ἡ⟩ παρὰ τῶν ἐξηπατημένων ὑπὸ τούτου δικαστῶν, ἐφ’ ᾧ τὴν ψῆφον εἶχον πράγματι, τούτου κατεψηφίσατο.", "st": "37.47"}, {"sp": "N", "t": "καίτοι τὸν ἐκείνους ἐξηπατηκότα τοὺς δικαστάς, ἆρ’ ὀκνήσειν ὑμᾶς ἐξαπατᾶν οἴεσθε; ἢ πεπιστευκότ’ εἰσιέναι τοῖς πράγμασιν, ἀλλ’ οὐ τοῖς λόγοις καὶ τοῖς συνεστῶσιν μεθ’ αὑτοῦ μάρτυσιν, τῷ τ’ ἀκαθάρτῳ καὶ μιαρῷ Προκλεῖ, τῷ μεγάλῳ τούτῳ, καὶ Στρατοκλεῖ τῷ πιθανωτάτῳ πάντων ἀνθρώπων καὶ πονηροτάτῳ, καὶ τῷ μηδὲν ὑποστελλόμενον μηδ’ αἰσχυνόμενον κλαήσειν καὶ ὀδυρεῖσθαι;", "st": "37.48"}, {"sp": "N", "t": "καίτοι τοσούτου δεῖς ἐλέου τινὸς ἄξιος εἶναι, ὥστε μισηθείης ἂν δικαιότατ’ ἀνθρώπων ἐξ ὧν πεπραγμάτευσαι· ὅς γ’ ὀφείλων μνᾶς ἑκατὸν καὶ πέντε καὶ οὐχ οἷός τ’ ὢν διαλῦσαι, τοὺς ταῦτα συνευπορήσαντας καὶ γενομένους αἰτίους σοι τοῦ τὰ δίκαια ποιῆσαι τοῖς συμβαλοῦσιν ἐξ ἀρχῆς, χωρὶς ὧν περὶ αὐτὰ τὰ συμβόλαι’ ἠδίκεις, καὶ πρὸς ἀτιμῶσαι ζητεῖς. καὶ τοὺς μὲν ἄλλους τοὺς δανειζομένους ἴδοι τις ἂν ἐξισταμένους τῶν ὄντων· σοὶ δ’ ὁ συμβεβληκὼς τοῦτο πέπονθεν, καὶ δανείσας τάλαντον δύ’ ὤφληκεν συκοφαντηθείς.", "st": "37.49"}, {"sp": "N", "t": "ἐγὼ δὲ τετταράκοντα μνᾶς δανείσας δυοῖν ταλάντοιν ταυτηνὶ φεύγω δίκην. καὶ ἐφ’ οἷς δανείσασθαι μὲν οὐδεπώποτ’ ἐδυνήθης ἑκατὸν μνῶν πλέον, πέπρακας δὲ καθάπαξ τριῶν ταλάντων καὶ δισχιλίων, εἰς ταῦτα τέτταρ’ ὡς ἔοικεν ἠδίκησαι τάλαντα. ὑπὸ τοῦ ταῦτα; ὑπὸ τοῦ οἰκέτου νὴ Δία τοῦ ἐμοῦ. τίς δ’ ἂν οἰκέτῃ παραχωρήσειε πολίτης τῶν αὑτοῦ; ἢ τίς ἂν φήσειεν, ὧν δίκην λαχὼν ᾕρηκεν οὗτος Εὔεργον, τούτων καὶ τὸν ἐμὸν παῖδ’ ὑπεύθυνον εἶναι προσήκειν;", "st": "37.50"}, {"sp": "N", "t": "χωρὶς δὲ τούτων αὐτὸς αὐτὸν οὗτος ἀφῆκε τῶν τοιούτων αἰτιῶν ἁπασῶν. οὐ γὰρ νῦν ἔδει λέγειν, οὐδ’ εἰς τὴν πρόκλησιν γράφειν ἐν ᾗ βασανίζειν ἐξῄτει, ἀλλὰ λαχόντ’ ἐκείνῳ τὴν δίκην τὸν κύριον διώκειν ἐμέ. νῦν δ’ εἴληχεν μὲν ἐμοί, κατηγορεῖ δ’ ἐκείνου. ταῦτα δ’ οὐκ ἐῶσιν οἱ νόμοι· τίς γὰρ πώποτε τῷ δεσπότῃ λαχών, τοῦ δούλου τὰ πράγματα, ὥσπερ κυρίου, κατηγόρησεν;", "st": "37.51"}, {"sp": "N", "t": "ἐπειδὰν τοίνυν τις αὐτὸν ἔρηται “καὶ τί δίκαιον ἕξεις λέγειν πρὸς Νικόβουλον;” μισοῦσι, φησίν, Ἀθηναῖοι τοὺς δανείζοντας· Νικόβουλος δ’ ἐπίφθονός ἐστι, καὶ ταχέως βαδίζει, καὶ μέγα φθέγγεται, καὶ βακτηρίαν φορεῖ· ταῦτα δ’ ἐστὶν ἅπαντα, φησίν, πρὸς ἐμοῦ. καὶ ταῦτ’ οὐκ αἰσχύνεται λέγων, οὐδὲ τοὺς ἀκούοντας οἴεται μανθάνειν ὅτι συκοφαντοῦντός ἐστι λογισμὸς οὗτος, οὐκ ἀδικουμένου.", "st": "37.52"}, {"sp": "N", "t": "ἐγὼ δ’ ἀδικεῖν μὲν οὐδένα τῶν δανειζόντων οἴομαι, μισεῖσθαι μέντοι τινὰς ἂν εἰκότως ὑφ’ ὑμῶν, οἳ τέχνην τὸ πρᾶγμα πεποιημένοι μήτε συγγνώμης μήτ’ ἄλλου μηδενός εἰσιν ἀλλ’ ἢ τοῦ πλείονος. διὰ γὰρ τὸ καὶ δεδανεῖσθαι πολλάκις, μὴ μόνον αὐτὸς τούτῳ δανεῖσαι, οὐδ’ ἐγὼ τούτους ἀγνοῶ, οὐδὲ φιλῶ, οὐ μέντοι γ’ ἀποστερῶ μὰ Δία, οὐδὲ συκοφαντῶ.", "st": "37.53"}, {"sp": "N", "t": "ὅστις δ’ εἴργασται μὲν ὥσπερ ἐγὼ πλέων καὶ κινδυνεύων, εὐπορήσας δὲ μικρῶν ἐδάνεισεν ταῦτα, καὶ χαρίσασθαι βουλόμενος καὶ μὴ λαθεῖν διαρρυὲν αὑτὸν τἀργύριον, τί τις ἂν τοῦτον εἰς ἐκείνους τιθείη; εἰ μὴ τοῦτο λέγεις, ὡς ὃς ἂν σοὶ δανείσῃ, τοῦτον δημοσίᾳ μισεῖσθαι προσήκει. λέγε δή μοι τὰς μαρτυρίας, τίς ἐγὼ πρὸς τοὺς συμβάλλοντας ἄνθρωπος καὶ πρὸς τοὺς δεομένους εἰμί.", "st": "37.54"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "37.54"}, {"sp": "N", "t": "τοιοῦτος, ὦ Πανταίνετε, ἐγώ, ὁ ταχὺ βαδίζων, καὶ τοιοῦτος σύ, ὁ ἀτρέμας. ἀλλὰ μὴν περὶ τοῦ ἐμοῦ γε βαδίσματος ἢ τῆς διαλέκτου, τἀληθῆ πάντ’ ἐρῶ πρὸς ὑμᾶς, ὦ ἄνδρες δικασταί, μετὰ παρρησίας. ἐγὼ γὰρ οὐχὶ λέγηθ’ ἐμαυτόν, οὐδ’ ἀγνοῶ, οὐ τῶν εὖ πεφυκότων κατὰ ταῦτ’ ὢν ἀνθρώπων, οὐδὲ τῶν λυσιτελούντως ἑαυτοῖς. εἰ γὰρ ἐν οἷς μηδὲν ὠφελοῦμαι ποιῶν, λυπῶ τινάς, πῶς οὐκ ἀτυχῶ κατὰ τοῦτο τὸ μέρος;", "st": "37.55"}, {"sp": "N", "t": "ἀλλὰ τί χρὴ παθεῖν; ἂν τῷ δεῖνι δανείσω, διὰ ταῦτα δίκην προσοφλεῖν; μηδαμῶς. κακίαν γὰρ ἐμοὶ καὶ πονηρίαν οὔθ’ οὗτος προσοῦσαν οὐδεμίαν δείξει, οὔθ’ ὑμῶν τοσούτων ὄντων οὐδὲ εἷς σύνοιδεν. τἄλλα δὲ ταῦθ’ ἕκαστος ἡμῶν, ὅπως ἔτυχεν, πέφυκεν οἶμαι. καὶ φύσει μάχεσθαι μὲν ἔχοντ’ οὐκ εὔπορόν ἐστιν (οὐ γὰρ ἂν ἀλλήλων διεφέρομεν οὐδέν), γνῶναι δ’ ἰδόνθ’ ἕτερον καὶ ἐπιπλῆξαι ῥᾴδιον.", "st": "37.56"}, {"sp": "N", "t": "ἀλλὰ τί τούτων ἐμοὶ πρὸς σέ, Πανταίνετε; πολλὰ καὶ δεινὰ πέπονθας; οὐκοῦν εἴληφας δίκην. οὐ παρ’ ἐμοῦ γε; οὐδὲ γὰρ ἠδικήθης οὐδὲν ὑπ’ ἐμοῦ. οὐ γὰρ ἄν ποτ’ ἀφῆκας, οὐδ’, ὅτ’ Εὐέργῳ προῃροῦ λαγχάνειν, εἴασας ἐμέ, οὐδὲ πρατῆρ’ ἠξίωσας ὑποστῆναι τόν γε δεινά σε καὶ πόλλ’ εἰργασμένον. εἶτα καὶ πῶς ἂν ὁ μὴ παρὼν μηδ’ ἐπιδημῶν ἐγώ τί σ’ ἠδίκησα;", "st": "37.57"}, {"sp": "N", "t": "εἰ τοίνυν ὡς οἷόν τε μέγιστ’ ἠδικῆσθαι δοίη τις αὐτῷ καὶ ἐρεῖν ἅπαντ’ ἀληθῆ περὶ τούτων νυνί, ἐκεῖνό γ’ οἶμαι πάντας ἂν ὑμᾶς ὁμολογῆσαι, ὅτι πολλὰ συμβέβηκεν ἠδικῆσθαί τισιν ἤδη μείζω τῶν εἰς χρήματα γιγνομένων ἀδικημάτων· καὶ γὰρ ἀκούσιοι φόνοι καὶ ὕβρεις εἰς ἃ μὴ δεῖ καὶ πόλλ’ ἄλλα τοιαῦτα γίγνεται. ἀλλ’ ὅμως ἁπάντων τούτων ὅρος καὶ λύσις τοῖς παθοῦσι τέτακται τὸ πεισθέντας ἀφεῖναι.", "st": "37.58"}, {"sp": "N", "t": "καὶ τοῦθ’ οὕτω τὸ δίκαιον ἐν πᾶσιν ἰσχύει, ὥστ’ ἐὰν ἑλών τις ἀκουσίου φόνου καὶ σαφῶς ἐπιδείξας μὴ καθαρόν, μετὰ ταῦτ’ αἰδέσηται καὶ ἀφῇ, οὐκέτ’ ἐκβαλεῖν κύριος τὸν αὐτόν ἐστιν. οὐδέ γ’, ἂν ὁ παθὼν αὐτὸς ἀφῇ τοῦ φόνου, πρὶν τελευτῆσαι, τὸν δράσαντα, οὐδενὶ τῶν λοιπῶν συγγενῶν ἔξεστ’ ἐπεξιέναι, ἀλλ’ οὓς ἐκπίπτειν καὶ φεύγειν, ἂν ἁλίσκωνται, καὶ τεθνάναι προστάττουσιν οἱ νόμοι, τούτους, ἐὰν ἀφεθῶσιν ἅπαξ, ἁπάντων ἐκλύει τῶν δεινῶν τοῦτο τὸ ῥῆμα.", "st": "37.59"}, {"sp": "N", "t": "εἶθ’ ὑπὲρ μὲν ψυχῆς καὶ τῶν μεγίστων οὕτως ἰσχύει καὶ μένει τὸ ἀφεῖναι, ὑπὲρ δὲ χρημάτων καὶ ἐλαττόνων ἐγκλημάτων ἄκυρον ἔσται; μηδαμῶς. οὐ γὰρ εἰ μὴ τῶν δικαίων ἐγὼ παρ’ ὑμῖν τεύξομαι, τοῦτ’ ἔστι δεινότατον, ἀλλ’ εἰ πρᾶγμα δίκαιον ὡρισμένον ἐκ παντὸς τοῦ χρόνου νῦν καταλύσετ’ ἐφ’ ἡμῶν.", "st": "37.60"}, {"sp": "HDR", "t": "Παραγραφὴ πρὸς Ναυσίμακον καὶ Ξενοπείθην", "st": "38"}, {"sp": "N", "t": "δεδωκότων, ὦ ἄνδρες δικασταί, τῶν νόμων παραγράψασθαι περὶ ὧν ἄν τις ἀφεὶς καὶ ἀπαλλάξας πάλιν δικάζηται, γεγενημένων ἀμφοτέρων τούτων τῷ πατρὶ πρὸς Ναυσίμαχον καὶ Ξενοπείθην τοὺς εἰληχότας ἡμῖν, παρεγραψάμεθα, ὥσπερ ἠκούσατ’ ἀρτίως, μὴ εἰσαγώγιμον εἶναι τὴν δίκην.", "st": "38.1"}, {"sp": "N", "t": "δεήσομαι δὲ καὶ δίκαια καὶ μέτρι’ ὑμῶν ἁπάντων, πρῶτον μὲν εὐνοϊκῶς ἀκοῦσαί μου λέγοντος, εἶτ’, ἐὰν ἀδικεῖσθαι δοκῶ καὶ μὴ προσήκοντος ἐγκλήματος φεύγειν δίκην, βοηθῆσαί μοι τὰ δίκαια. ὃ μὲν γὰρ ὑμεῖς ἐπὶ τῇ δίκῃ τίμημ’ ἀκηκόατε, τριάκοντα μναῖ εἰσιν, ὧν δὲ φεύγομεν χρημάτων, τέτταρα τάλαντα. ὄντες γὰρ δύο τέτταρας εἰλήχασι δίκας ἡμῖν, τῶν αὐτῶν χρημάτων πάσας, τρισχιλίων ἑκάστην, βλάβης· καὶ νυνὶ πρὸς τριάκοντα μνῶν ἐπίγραμμα, ὑπὲρ τοσούτων χρημάτων εἰς ἀγῶνα καθέσταμεν.", "st": "38.2"}, {"sp": "N", "t": "τὴν μὲν οὖν συκοφαντίαν τὴν τούτων, καὶ μεθ’ ὅσης ἐπιβουλῆς ἐληλύθασιν ἐφ’ ἡμᾶς, ἐξ αὐτῶν τῶν πεπραγμένων εἴσεσθε. ἀναγνώσεται δὲ πρῶτον ὑμῖν τὰς μαρτυρίας, ὡς ἀφεῖσαν τὸν πατέρ’ ἡμῶν ὧν ἐνεκάλεσαν εἰς τὴν ἐπιτροπήν· κατὰ γὰρ τοῦτο καὶ παρεγραψάμεθα μὴ εἰσαγώγιμον εἶναι τὴν δίκην. καί μοι λέγε ταυτασὶ τὰς μαρτυρίας.", "st": "38.3"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "38.3"}, {"sp": "N", "t": "ὅτι μὲν τοίνυν, ὦ ἄνδρες δικασταί, καὶ δίκας ἔλαχον τῆς ἐπιτροπῆς καὶ ἀφεῖσαν ταύτας καὶ τὰ συγχωρηθέντα χρήματ’ ἔχουσιν, ἀκούετε τῶν μαρτυριῶν. ὅτι δ’ οὐκ ἐῶσιν οἱ νόμοι περὶ τῶν οὕτω πραχθέντων αὖθις δικάζεσθαι, νομίζω μὲν ἅπαντας ὑμᾶς εἰδέναι, κἂν μηδὲν εἴπω περὶ αὐτῶν ἐγώ, βούλομαι δ’ ὅμως καὶ τὸν νόμον ὑμῖν αὐτὸν ἀναγνῶναι. λέγε τὸν νόμον.", "st": "38.4"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "38.4"}, {"sp": "N", "t": "ἀκούετ’, ὦ ἄνδρες δικασταί, τοῦ νόμου σαφῶς λέγοντος ἕκαστα, ὧν μὴ εἶναι δίκας· ὧν ἕν ἐστιν, ὁμοίως τοῖς ἄλλοις κύριον, περὶ ὧν ἄν τις ἀφῇ καὶ ἀπαλλάξῃ, μὴ δικάζεσθαι. οὕτω τοίνυν καὶ μετὰ πολλῶν μαρτύρων τῆς ἀφέσεως γεγονυίας, καὶ φανερῶς ἀπολύοντος ἡμᾶς τοῦ νόμου, εἰς τοῦτ’ ἐληλύθασιν ἀναισχυντίας οὗτοι καὶ τόλμης,", "st": "38.5"}, {"sp": "N", "t": "ὥστε τεττάρων μὲν καὶ δέκ’ ἐτῶν γεγενημένων ἀφ’ οὗ τὸν πατέρ’ ἡμῶν ἀφεῖσαν, εἴκοσι δὲ καὶ δυοῖν ἀφ’ οὗ τυγχάνουσιν ἐγγεγραμμένοι, τετελευτηκότος δὲ καὶ τοῦ πατρὸς τοῦ ἡμετέρου, πρὸς ὃν αὐτοῖς ἐγένονθ’ αἱ διαλλαγαί, καὶ τῶν ἐπιτρόπων, οἳ μετὰ τὸν ἐκείνου θάνατον τῶν ἡμετέρων ἐγένοντο κύριοι, καὶ τῆς ἑαυτῶν μητρός, ἥτις ἅπαντα ταῦτ’ ᾔδει, καὶ διαιτητῶν καὶ μαρτύρων καὶ πάντων [τῶν πλείστων] ὡς εἰπεῖν, τὴν ἡμετέραν ἀπειρίαν καὶ τὴν ἐξ ἀνάγκης ἄγνοιαν τῶν πεπραγμένων ἕρμαιον νομίσαντες ἑαυτῶν, τὰς δίκας ἡμῖν ἔλαχον ταυτασί, καὶ λόγον οὔτε δίκαιον οὔτ’ ἐπιεικῆ τολμῶσι λέγειν.", "st": "38.6"}, {"sp": "N", "t": "φασὶ γὰρ οὐκ ἀποδόσθαι τὰ πατρῷ’ ὧν ἐκομίζοντο χρημάτων, οὐδ’ ἀποστῆναι τῶν ὄντων, ἀλλ’ ὅσ’ αὐτοῖς κατελείφθη χρέα καὶ σκεύη καὶ ὅλως χρήματα, ταῦθ’ ἑαυτῶν γίγνεσθαι. ἐγὼ δ’ οἶδ’ ἀκούων ὅτι τὴν οὐσίαν Ξενοπείθης καὶ Ναυσικράτης ἅπασαν χρέα κατέλιπον, καὶ φανερὰν ἐκέκτηντο μικράν τινα· εἰσπραχθέντων δὲ τῶν χρεῶν καί τινων σκευῶν πραθέντων, ἔτι δ’ ἀνδραπόδων, καὶ τὰ χωρία καὶ τὰς συνοικίας ἐπρίανθ’ οἱ ἐπίτροποι, ἃ παρέλαβον οὗτοι.", "st": "38.7"}, {"sp": "N", "t": "εἰ μὲν οὖν μηδὲν ἠμφεσβητήθη περὶ τούτων πρότερον, μηδ’ ὡς οὐ καλῶς διῳκημένων εἰς δίκην ἦλθεν, ἄλλος ἂν ἦν λόγος· ἐπειδὴ δ’ ὅλην τὴν ἐπιτροπὴν ἐγκαλέσαντες οὗτοι καὶ δίκας λαχόντες χρήματ’ ἐπράξαντο, πάντα ταῦτ’ ἀφεῖται τότε. οὔτε γὰρ οὗτοι τοὐνόματος δήπου τοῦ τῆς ἐπιτροπῆς τὰς δίκας ἐδίωκον, ἀλλὰ τῶν χρημάτων, οὔτ’ ἐκεῖνοι τοὔνομα τοῦτ’ ἐωνοῦνθ’ ὧν ἀπέτεισαν χρημάτων, ἀλλὰ τὰ ἐγκλήματα.", "st": "38.8"}, {"sp": "N", "t": "ὅτι μὲν οὖν ὧν πρὸ τῶν ἀπαλλαγῶν εἰσέπραξεν χρεῶν ὁ πατὴρ ἢ ὅλως ἔλαβεν χρημάτων ἐκ τῆς ἐπιτροπῆς, οὐδενός εἰσιν δίκαι τούτοις καθ’ ἡμῶν ἀπηλλαγμένοις, ἐξ αὐτῶν τῶν νόμων καὶ τῆς ἀφέσεως ἱκανῶς πάντας ἡγοῦμαι ὑμᾶς μεμαθηκέναι. ὅτι δ’ ὕστερον οὐκ ἔνι τὴν κομιδὴν γεγενῆσθαι τούτων τῶν χρημάτων (τοῦτο γὰρ πλάττουσιν οὗτοι καὶ παράγουσιν), τοῦτο βούλομαι δεῖξαι.", "st": "38.9"}, {"sp": "N", "t": "τὸν μὲν γὰρ πατέρ’ οὐδ’ ἂν αἰτιάσαιντο λαβεῖν (τέτταρσι γὰρ ἢ τρισὶ μησὶν ὕστερον ἢ διελύσατο πρὸς τούτους ἐτελεύτησεν). ὡς δ’ οὐδὲ Δημάρετον τὸν καταλειφθένθ’ ἡμῶν ἐπίτροπον λαβεῖν οἷόν τε (καὶ γὰρ τοῦτον ἔγραψαν εἰς τὸ ἔγκλημα), καὶ τοῦτ’ ἐπιδείξω.", "st": "38.10"}, {"sp": "N", "t": "μέγιστοι μὲν οὖν ἡμῖν εἰσιν οὗτοι μάρτυρες (οὐδαμοῦ γὰρ φανήσονται δίκην εἰληχότες ζῶντι τῷ Δημαρέτῳ)· οὐ μὴν ἀλλὰ καὶ τὸ πρᾶγμ’ ἄν τις αὐτὸ σκοπῶν καὶ θεωρῶν ἴδοι οὐ μόνον οὐχὶ λαβόντα, ἀλλ’ οὐδ’ ἐνὸν αὐτῷ λαβεῖν. ἦν μὲν γὰρ τὸ χρέως ἐν Βοσπόρῳ, ἀφίκετο δ’ οὐδεπώποτ’ εἰς τὸν τόπον τοῦτον ὁ Δημάρετος· πῶς οὖν εἰσέπραξεν; ἔπεμψεν νὴ Δί’, εἴποι τις ἄν, τὸν κομιούμενον.", "st": "38.11"}, {"sp": "N", "t": "σκοπεῖτε δὴ τοῦθ’ οὑτωσί. ὤφειλεν Ἑρμῶναξ στατῆρας ἑκατὸν παρὰ Ναυσικράτους λαβὼν τούτοις. τούτων Ἀρίσταιχμος ἐπίτροπος καὶ κηδεμὼν ἐγένεθ’ ἑκκαίδεκ’ ἔτη. οὐκοῦν ἅ γε τούτων ἀνδρῶν γεγονότων δι’ ἑαυτοῦ διέλυε χρήμαθ’ ὁ Ἑρμῶναξ, οὐκ ἀπέδωκεν ὅτ’ ἦσαν παῖδες· οὐ γὰρ δίς γε ταὐτὰ κατετίθει. ἔστιν οὖν οὕτω τις ἀνθρώπων ἄτοπος, ὥσθ’ ἃ τοὺς κυρίους διεκρούσατο μὴ καταθεῖναι τοσοῦτον χρόνον, ταῦτα τῷ μὴ κυρίῳ πέμψαντι γράμμαθ’ ἑκὼν ἀποδοῦναι; ἐγὼ μὲν οὐκ οἶμαι.", "st": "38.12"}, {"sp": "N", "t": "ἀλλὰ μὴν ὡς ἀληθῆ λέγω, καὶ ὁ μὲν πατὴρ ἐτελεύτησεν εὐθέως μετὰ τὰς διαλύσεις, τῷ Δημαρέτῳ δ’ οὐδεπώποθ’ οὗτοι τούτων τῶν χρημάτων δίκην ἔλαχον, οὐδ’ ὅλως ἐξέπλευσεν ἐκεῖνος οὐδ’ ἀπεδήμησεν ἐκεῖσε, λαβὲ τὰς μαρτυρίας.", "st": "38.13"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "38.13"}, {"sp": "N", "t": "ὅτι μὲν τοίνυν οὔθ’ ὁ πατὴρ μετὰ τὴν ἄφεσιν τὰ χρήματ’ εἰσέπραξεν, οὔτ’ ἂν ἔδωκεν ἑκὼν οὐδείς, εἴ τιν’ ἔπεμψεν ὁ Δημάρετος, οὔτ’ ἀνέπλευσεν αὐτὸς οὐδ’ ἀφίκετ’ ἐκεῖσε, δῆλον ἐκ τῶν χρόνων καὶ τῶν μαρτυριῶν ὑμῖν γέγονεν. βούλομαι τοίνυν καὶ ὅλως ψευδομένους αὐτοὺς ὅλον τὸ πρᾶγμ’ ἐπιδεῖξαι. οὗτοι γὰρ γεγράφασιν εἰς ὃ νῦν ἔγκλημα διώκουσιν, ὀφείλειν ἡμᾶς τὸ ἀργύριον κομισαμένου τοῦ πατρὸς καὶ παραδόντος αὐτοῖς τοῦτο τὸ χρέως ἐν τῷ λόγῳ τῆς ἐπιτροπῆς ὀφειλόμενον. καί μοι λέγ’ αὐτὸ τὸ ἔγκλημα λαβών.", "st": "38.14"}, {"sp": "N", "t": "ΕΓΚΛΗΜΑ.", "st": "38.14"}, {"sp": "N", "t": "ἀκούετε γεγραμμένον ἐν τῷ ἐγκλήματι “παραδόντος ἐμοὶ τοῦ Ἀρισταίχμου τὸ χρέως ἐν τῷ λόγῳ τῆς ἐπιτροπῆς”. ὅτε τοίνυν ἐλάγχανον τῷ πατρὶ τῆς ἐπιτροπῆς, τἀναντί’ ἐγράψαντο τούτων· ὡς γὰρ οὐκ ἀποδόντι λόγον τότ’ ἐγκαλοῦντες φαίνονται. λέγ’ αὐτὸ τὸ ἔγκλημα, ὃ τότ’ ἔλαχον τῷ πατρί.", "st": "38.15"}, {"sp": "N", "t": "ΕΓΚΛΗΜΑ.", "st": "38.15"}, {"sp": "N", "t": "ἐν ποίῳ δὴ λόγῳ νῦν ἐγκαλεῖθ’ ὡς παρέδωκεν, ὦ Ξενοπείθη καὶ Ναυσίμαχε; τότε μὲν γὰρ ὡς οὐκ ἀποδόντι δίκας ἐλαγχάνετε καὶ χρήματ’ ἐπράττεσθε. εἰ δ’ ἐπ’ ἀμφότερ’ ἔσται συκοφαντεῖν ὑμῖν, καὶ τοτὲ μὲν τοῦ μὴ παραδοῦναι χρήματ’ ἐπράξασθε, τοτὲ δ’ ὡς παραδόντος διώκετε, οὐδὲν κωλύει καὶ τρίτον τι σκοπεῖν μετὰ ταῦτα, ὅτου πάλιν δικάσεσθε. οἱ νόμοι δ’ οὐ ταῦτα λέγουσιν, ἀλλ’ ἅπαξ περὶ τῶν αὐτῶν πρὸς τὸν αὐτὸν εἶναι τὰς δίκας.", "st": "38.16"}, {"sp": "N", "t": "ἵνα τοίνυν εἰδῆτ’, ὦ ἄνδρες δικασταί, ὅτι οὐ μόνον οὐκ ἀδικοῦνται νῦν, ἀλλὰ καὶ παρὰ πάντας ἡμῖν δικάζονται τοὺς νόμους, βούλομαι καὶ τοῦτον ὑμῖν τὸν νόμον εἰπεῖν, ὅστις διαρρήδην λέγει, ἐὰν πέντ’ ἔτη παρέλθῃ καὶ μὴ δικάσωνται, μηκέτ’ εἶναι τοῖς ὀρφανοῖς δίκην περὶ τῶν ἐκ τῆς ἐπιτροπῆς ἐγκλημάτων. καὶ ὑμῖν ἀναγνώσεται τὸν νόμον.", "st": "38.17"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "38.17"}, {"sp": "N", "t": "ἀκούετ’, ὦ ἄνδρες δικασταί, τοῦ νόμου λέγοντος ἄντικρυς, ἐὰν μὴ πέντ’ ἐτῶν δικάσωνται, μηκέτ’ εἶναι δίκην. οὐκοῦν ἐλάχομεν, φαῖεν ἄν. καὶ διελύσασθέ γε, ὥστ’ οὐκ εἰσὶν αὖθις ὑμῖν δίκαι. ἢ δεινόν γ’ ἂν εἴη, εἰ τῶν μὲν ἐξ ἀρχῆς ἀδικημάτων οὐ δίδωσιν ἔξω πέντ’ ἐτῶν τὰς δίκας τοῖς ὀρφανοῖς ὁ νόμος κατὰ τῶν οὐκ ἀφειμένων ἐπιτρόπων, πρὸς δὲ τοὺς ἐξ ἐκείνων ἡμᾶς, περὶ ὧν αὐτοὺς ἀφήκατε, εἰκοστῷ νῦν ἔτει δίκην τελέσαισθ’ ὑμεῖς.", "st": "38.18"}, {"sp": "N", "t": "ἀκούω τοίνυν αὐτοὺς τὰ μὲν περὶ τῶν πραγμάτων αὐτῶν καὶ τῶν νόμων δίκαια φεύξεσθαι, παρεσκευάσθαι δὲ λέγειν ὡς πολλὰ χρήματ’ αὐτοῖς κατελείφθη καὶ ταῦτ’ ἀπεστερήθησαν, καὶ τεκμηρίῳ χρήσεσθαι τούτου τῷ μεγέθει τῶν δικῶν ἃς ἐξ ἀρχῆς ἔλαχον, καὶ τὴν ὀρφανίαν ὀδυρεῖσθαι, καὶ τὸν τῆς ἐπιτροπῆς λόγον διεξιέναι· καὶ ταῦτ’ εἶναι καὶ τοιαῦθ’ οἷς πεπιστεύκασι καὶ δι’ ὧν ὑμᾶς ἐξαπατήσειν οἴονται.", "st": "38.19"}, {"sp": "N", "t": "ἐγὼ δὲ τὸ μὲν τῶν δικῶν μέγεθος τῶν τότε ληχθεισῶν μεῖζον ἡγοῦμαι τεκμήριον ἡμῖν [εἶναι] ὡς ἐσυκοφαντεῖθ’ ὁ πατήρ, ἢ τούτοις ὡς πόλλ’ ἀπεστεροῦντο. ὀγδοήκοντα μὲν γὰρ τάλαντ’ ἔχων ἐξελέγχειν, οὐδὲ εἷς ἂν τρία λαβὼν ἀπηλλάγη· τοσούτων δὲ χρημάτων ἐπιτροπῆς φεύγων, οὐδεὶς ἔστιν ὅστις οὐκ ἂν ἔδωκεν τρία τάλαντα, τὸν κίνδυνον ὠνούμενος καὶ τὰ φύσει τότε τούτοις πλεονεκτήμαθ’ ὑπάρχοντα. καὶ γὰρ ὀρφανοὶ καὶ νέοι καὶ ὁποῖοί τινές εἰσιν ἀγνῶτες ἦσαν· ταῦτα δὲ πάντες φασὶν μεγάλων δικαίων ἰσχύειν πλέον παρ’ ὑμῖν.", "st": "38.20"}, {"sp": "N", "t": "ὅτι τοίνυν οὐδ’ ἀνάσχοισθ’ ἂν αὐτῶν εἰκότως οὐδὲν περὶ τῆς ἐπιτροπῆς, καὶ τοῦτ’ οἴομαι δείξειν. εἰ γὰρ ὡς οἷόν τε μέγιστ’ ἠδικῆσθαι δοίη τις αὐτοῖς καὶ ἐρεῖν ἅπαντ’ ἀληθῆ περὶ τούτων νυνί, ἐκεῖνό γ’ οἶμαι πάντας ἂν ὑμᾶς ὁμολογῆσαι, ὅτι πολλὰ συμβέβηκεν ἠδικῆσθαί τισιν ἤδη μείζω τῶν εἰς χρήματα γιγνομένων ἀδικημάτων· καὶ γὰρ ἀκούσιοι φόνοι καὶ ὕβρεις εἰς ἃ μὴ δεῖ καὶ πολλὰ τοιαῦτ’ ἀδικήματα γίγνεται. ἀλλ’ ὅμως τούτων ἁπάντων ὅρος καὶ λύσις τοῖς παθοῦσιν τέτακται τὸ πεισθέντας ἀφεῖναι.", "st": "38.21"}, {"sp": "N", "t": "καὶ τοῦθ’ οὕτω τὸ δίκαιον ἐν πᾶσιν ἰσχύει, ὥστ’ ἐὰν ἑλών τις ἀκουσίου φόνου καὶ φανερῶς ἐπιδείξας μὴ καθαρόν, μετὰ ταῦτ’ αἰδέσηται καὶ ἀφῇ, οὐκέτ’ ἐκβαλεῖν κύριος τὸν αὐτόν ἐστιν. εἶθ’ ὑπὲρ μὲν ψυχῆς καὶ τῶν μεγίστων οὕτως ἰσχύει καὶ μένει τὸ ἀφεῖναι, ὑπὲρ δὲ χρημάτων καὶ ἐλαττόνων ἐγκλημάτων ἄκυρον ἔσται; μηδαμῶς. οὐ γὰρ εἰ μὴ τῶν δικαίων ἐγὼ παρ’ ὑμῖν τεύξομαι, τοῦτ’ ἔστι δεινότατον, ἀλλ’ εἰ πρᾶγμα δίκαιον ὡρισμένον ἐκ παντὸς τοῦ χρόνου νῦν καταλυθήσεται.", "st": "38.22"}, {"sp": "N", "t": "οὐκ ἐμίσθωσαν ἡμῶν τὸν οἶκον, ἴσως ἐροῦσιν. οὐ γὰρ ἐβούλεθ’ ὁ θεῖος ὑμῶν Ξενοπείθης, ἀλλὰ φήναντος Νικίδου τοὺς δικαστὰς ἔπεισεν ἐᾶσαι αὑτὸν διοικεῖν· καὶ ταῦτ’ ἴσασιν πάντες. πολλὰ διήρπασαν ἡμῶν ἐκεῖνοι. οὐκοῦν ἣν ἐπείσθητέ γε, τούτων δίκην παρ’ αὐτῶν ἔχετε, καὶ οὐ δήπουθεν πάλιν δεῖ λαβεῖν ὑμᾶς παρ’ ἐμοῦ.", "st": "38.23"}, {"sp": "N", "t": "ἵνα δὲ μηδ’ οἴησθ’ εἶναί τι ταῦτα, ἔστι μὲν οὐκ ἴσον (πῶς γάρ;) πρὸς τοὺς πράξαντας διαλυσαμένους τῶν οὐκ εἰδότων κατηγορεῖν, ὅμως μέντοι, ὦ Ξενοπείθη καὶ Ναυσίμαχε, εἰ μεγάλ’ ὑμῖν καὶ θαυμάστ’ εἶναι τὰ δίκαια ταῦθ’ ὑπολαμβάνετε, ἀποδόντες τὰ τρία τάλαντα περαίνετε. ὧν δὲ τοῦ μὴ κατηγορῆσαι τοσαῦτα χρήματ’ ἐπράξασθε, πρὶν ἂν ταῦτ’ ἀποδῶτε, σιωπᾶν ἐστὲ δίκαιοι, καὶ μὴ κατηγορεῖν καὶ ἔχειν· ἔσχατον γὰρ ἤδη πραγμάτων τοῦτό γε.", "st": "38.24"}, {"sp": "N", "t": "τάχα τοίνυν ἴσως καὶ τριηραρχίας ἐροῦσι, καὶ τὰ ὄνθ’ ὡς ἀνηλώκασιν εἰς ὑμᾶς. ἐγὼ δ’ ὅτι μὲν ψεύσονται, καὶ πόλλ’ ἀπολωλεκότες τῶν ὄντων αὑτοῖς, μικρὰ τῆς πόλεως μετειληφυίας, οὐ δικαίαν οὐδὲ γιγνομένην χάριν ἀξιώσουσι κομίζεσθαι παρ’ ὑμῶν, ἐάσω. ἀξιῶ δὲ καὶ αὐτός, ὦ ἄνδρες δικασταί, εἶναι τοῖς λῃτουργοῦσιν ὑμῖν ἅπασιν χάριν τιν’ ὑπάρχουσαν παρ’ ὑμῶν. τίσιν δὲ μεγίστην; τοῖς ὃ μὲν χρήσιμον τῇ πόλει τοῦ πράγματός ἐστι ποιοῦσιν, ὃ δ’ αἰσχρὸν ἅπαντες ἂν εἶναι φήσαιεν καὶ ὄνειδος, μὴ κατασκευάζουσιν.", "st": "38.25"}, {"sp": "N", "t": "οἱ μὲν τοίνυν μετὰ τοῦ λῃτουργεῖν τὰ σφέτερ’ αὐτῶν διεφθαρκότες τὴν βλασφημίαν ἀντὶ τῆς χρείας τῇ πόλει καταλείπουσιν (οὐδεὶς γὰρ αὐτὸς αὑτοῦ κατηγόρησεν πώποτε, ἀλλ’ ὡς ἡ πόλις τὰ ὄντ’ ἀφῄρηται λέγει)· οἱ δ’ ὅσα μὲν προστάττεθ’ ὑμεῖς ποιοῦντες προθύμως, τῇ περὶ τἄλλα δὲ σωφροσύνῃ τὰ ὄντα σῴζοντες, οὐ μόνον κατὰ τοῦτ’ ἐκείνων πλεονεκτοῖεν ἂν εἰκότως, ὅτι καὶ γεγόνασιν χρήσιμοι καὶ ἔσονται, ἀλλ’ ὅτι καὶ χωρὶς ὀνείδους ταῦτα παρ’ αὐτῶν ὑμῖν γίγνεται. ἡμεῖς μὲν τοίνυν τοιοῦτοι εἰς ὑμᾶς ἅπαντες φανούμεθ’ ὄντες· τούτους δ’ ἐάσω, μή με φῶσιν κακῶς αὑτοὺς λέγειν.", "st": "38.26"}, {"sp": "N", "t": "οὐ τοίνυν θαυμάσαιμ’ ἄν, εἰ καὶ δακρύειν καὶ ἐλεινοὺς ἑαυτοὺς πειρῷντο ποιεῖν. ἐγὼ δ’ ἀξιῶ πρὸς ταῦθ’ ὑπολαμβάνειν ἅπαντας ὑμᾶς, ὅτι τῶν αἰσχρῶν ἐστι, μᾶλλον δ’ οὐδὲ δικαίων, τὰ μὲν ὄντα κατεσθίοντας καὶ παροινοῦντας μετ’ Ἀριστοκράτους καὶ Διογνήτου καὶ τοιούτων ἑτέρων αἰσχρῶς καὶ κακῶς ἀνηλωκέναι, τὰ δ’ ἀλλότρι’ ὥστε λαβεῖν, δακρύειν νυνὶ καὶ κλάειν. ἐπ’ ἐκείνοις ἐκλάετ’ ἄν, οἷς ἐποιεῖτε, δικαίως. νῦν δ’ οὐ δεῖ δακρύειν, ἀλλ’ ὡς οὐκ ἀφήκατε δεικνύναι, ἢ ὡς εἰσὶν ὧν ἀφήκατ’ αὖθις ὑμῖν δίκαι, ἢ ὡς εἰκοστῷ λαγχάνειν ἔτει δίκαιόν ἐστι, τοῦ νόμου πέντ’ ἔτη τὴν προθεσμίαν δεδωκότος· ταῦτα γάρ ἐστιν ὑπὲρ ὧν οὗτοι δικάζουσιν.", "st": "38.27"}, {"sp": "N", "t": "ἐὰν δὲ μὴ δύνωνται ταῦτα δεικνύναι, ὡς οὐ δυνήσονται, ἡμεῖς ὑμῶν ἁπάντων, ὦ ἄνδρες δικασταί, δεόμεθα μὴ ἡμᾶς προέσθαι τούτοις, μηδὲ τετάρτην οὐσίαν ἔτι δοῦναι τρεῖς ἑτέρας κακῶς διῳκηκόσιν, ἣν παρ’ ἑκόντων ἔλαβον τῶν ἐπιτρόπων, ἣν ὑπὲρ τῶν δικῶν εἰσεπράξαντο, ἣν πρῴην ἀφείλοντ’ Αἰσίου δίκην ἑλόντες, ἀλλ’ ἡμᾶς τὰ ἡμέτερα, ὥσπερ ἐστὶν δίκαιον, ἐᾶν ἔχειν· ἃ καὶ ὑμῖν ἐστιν ἐν ὠφελείᾳ μείζονι παρ’ ἡμῖν ὄντ’ ἢ παρὰ τούτοις, καὶ δικαιότερον δήπου τὰ ἡμέτερα ἡμᾶς ἐστιν ἔχειν ἢ τούτους.", "st": "38.28"}, {"sp": "N", "t": "οὐκ οἶδ’ ὅ τι δεῖ πλείω λέγειν· οἶμαι γὰρ ὑμᾶς οὐδὲν ἀγνοεῖν τῶν εἰρημένων. ἐξέρα τὸ ὕδωρ.", "st": "38.28"}, {"sp": "HDR", "t": "Πρὸς Βοιωτὸν περὶ τοῦ Ὀνόματος", "st": "39"}, {"sp": "N", "t": "οὐδεμιᾷ φιλοπραγμοσύνῃ μὰ τοὺς θεούς, ὦ ἄνδρες δικασταί, τὴν δίκην ταύτην ἔλαχον Βοιωτῷ, οὐδ’ ἠγνόουν ὅτι πολλοῖς ἄτοπον δόξει τὸ δίκην ἐμὲ λαγχάνειν, εἴ τις ἐμοὶ ταὐτὸν ὄνομ’ οἴεται δεῖν ἔχειν· ἀλλ’ ἀναγκαῖον ἦν ἐκ τῶν συμβησομένων, εἰ μὴ τοῦτο διορθώσομαι, ἐν ὑμῖν κριθῆναι.", "st": "39.1"}, {"sp": "N", "t": "εἰ μὲν οὖν ἑτέρου τινὸς οὗτος ἔφη πατρὸς εἶναι καὶ μὴ τοῦ ἐμοῦ, περίεργος ἂν εἰκότως ἐδόκουν εἶναι φροντίζων ὅ τι βούλεται καλεῖν οὗτος ἑαυτόν. νῦν δὲ λαχὼν δίκην τῷ πατρὶ τῷ ἐμῷ καὶ μεθ’ ἑαυτοῦ κατασκευάσας ἐργαστήριον συκοφαντῶν, Μνησικλέα τε, ὃν ἴσως γιγνώσκετε πάντες, καὶ Μενεκλέα τὸν τὴν Νῖνον ἑλόντ’ ἐκεῖνον, καὶ τοιούτους τινάς, ἐδικάζεθ’ υἱὸς εἶναι φάσκων ἐκ τῆς Παμφίλου θυγατρὸς καὶ δεινὰ πάσχειν καὶ τῆς πατρίδος ἀποστερεῖσθαι.", "st": "39.2"}, {"sp": "N", "t": "ὁ πατὴρ δέ (πᾶσα γὰρ εἰρήσεται ἡ ἀλήθει’, ὦ ἄνδρες δικασταί) ἅμα μὲν φοβούμενος εἰς δικαστήριον εἰσιέναι, μή τις, οἷ’ ὑπὸ πολιτευομένου, ἑτέρωθί που λελυπημένος ἐνταυθοῖ ἀπαντήσειεν αὐτῷ, ἅμα δ’ ἐξαπατηθεὶς ὑπὸ τῆς τουτουὶ μητρός, ὀμοσάσης αὐτῆς ἦ μήν, ἐὰν ὅρκον αὐτῇ διδῷ περὶ τούτων, μὴ ὀμεῖσθαι, τούτων δὲ πραχθέντων οὐδὲν ἔτ’ ἔσεσθαι αὐτοῖς, καὶ μεσεγγυησαμένης ἀργύριον, ἐπὶ τούτοις δίδωσι τὸν ὅρκον.", "st": "39.3"}, {"sp": "N", "t": "ἡ δὲ δεξαμένη, οὐ μόνον τοῦτον, ἀλλὰ καὶ τὸν ἀδελφὸν τὸν ἕτερον πρὸς τούτῳ κατωμόσατ’ ἐκ τοῦ πατρὸς εἶναι τοῦ ἐμοῦ. ὡς δὲ τοῦτ’ ἐποίησεν, εἰσάγειν εἰς τοὺς φράτερας ἦν ἀνάγκη τούτους καὶ λόγος οὐδεὶς ὑπελείπετο. εἰσήγαγεν, ἐποιήσατο, ἵνα τἀν μέσῳ συντέμω, ἐγγράφει τοῖς Ἀπατουρίοις τουτονὶ μὲν Βοιωτὸν εἰς τοὺς φράτερας, τὸν δ’ ἕτερον Πάμφιλον· Μαντίθεος δ’ ἐνεγεγράμμην ἐγώ.", "st": "39.4"}, {"sp": "N", "t": "συμβάσης δὲ τῷ πατρὶ τῆς τελευτῆς πρὶν τὰς εἰς τοὺς δημότας ἐγγραφὰς γενέσθαι, ἐλθὼν εἰς τοὺς δημότας οὑτοσὶ ἀντὶ Βοιωτοῦ Μαντίθεον ἐνέγραψεν ἑαυτόν. τοῦτο δ’ ὅσα βλάπτει ποιῶν πρῶτον μὲν ἐμέ, εἶτα δὲ καὶ ὑμᾶς, ἐγὼ διδάξω, ἐπειδὰν ὧν λέγω παράσχωμαι μάρτυρας.", "st": "39.5"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "39.5"}, {"sp": "N", "t": "ὃν μὲν τοίνυν τρόπον ἡμᾶς ἐνέγραψεν ὁ πατήρ, ἀκηκόατε τῶν μαρτύρων· ὅτι δ’ οὐκ οἰομένου τούτου δεῖν ἐμμένειν, δικαίως καὶ ἀναγκαίως ἔλαχον τὴν δίκην, τοῦτ’ ἤδη δείξω. ἐγὼ γὰρ οὐχ οὕτω δήπου σκαιός εἰμ’ ἄνθρωπος οὐδ’ ἀλόγιστος, ὥστε τῶν μὲν πατρῴων, ἃ πάντ’ ἐμὰ ἐγίγνετο, ἐπειδήπερ ἐποιήσατο τούτους ὁ πατήρ, συγκεχωρηκέναι τὸ τρίτον νείμασθαι μέρος καὶ στέργειν ἐπὶ τούτῳ, περὶ δ’ ὀνόματος ζυγομαχεῖν, εἰ μὴ τὸ μὲν ἡμᾶς μεταθέσθαι μεγάλην ἀτιμίαν ἔφερε καὶ ἀνανδρίαν, τὸ δὲ ταὐτὸν ἔχειν τοῦτον ἡμῖν ὄνομα διὰ πόλλ’ ἀδύνατον ἦν.", "st": "39.6"}, {"sp": "N", "t": "πρῶτον μὲν γάρ, εἰ δεῖ τὰ κοινὰ τῶν ἰδίων εἰπεῖν πρότερον, τίν’ ἡμῖν ἡ πόλις ἐπιτάξει τρόπον, ἄν τι δέῃ ποιεῖν; οἴσουσι νὴ Δί’ οἱ φυλέται τὸν αὐτὸν τρόπον ὅνπερ καὶ τοὺς ἄλλους. οὐκοῦν Μαντίθεον Μαντίου Θορίκιον οἴσουσιν, ἐὰν χορηγὸν ἢ γυμνασίαρχον ἢ ἑστιάτορ’ ἢ ἐάν τι τῶν ἄλλων φέρωσιν. τῷ δῆλον οὖν ἔσται πότερον σὲ φέρουσιν ἢ ἐμέ; σὺ μὲν γὰρ φήσεις ἐμέ, ἐγὼ δὲ σέ.", "st": "39.7"}, {"sp": "N", "t": "καὶ δὴ καλεῖ μετὰ τοῦθ’ ὁ ἄρχων ἢ πρὸς ὅντιν’ ἂν ᾖ ἡ δίκη. οὐχ ὑπακούομεν, οὐ λῃτουργοῦμεν. πότερος ταῖς ἐκ τῶν νόμων ἔσται ζημίαις ἔνοχος; τίνα δ’ οἱ στρατηγοὶ τρόπον ἐγγράψουσιν, ἂν εἰς συμμορίαν ἐγγράφωσιν, ἢ ἂν τριήραρχον καθιστῶσιν; ἢ ἂν στρατεία τις ᾖ, τῷ δῆλον ἔσται πότερός ἐσθ’ ὁ κατειλεγμένος;", "st": "39.8"}, {"sp": "N", "t": "τί δ’, ἂν ἄλλη τις ἀρχὴ καθιστῇ λῃτουργεῖν, οἷον ἄρχων, βασιλεύς, ἀθλοθέται, τί σημεῖον ἔσται πότερον καθιστᾶσιν; προσπαραγράψουσι νὴ Δία τὸν ἐκ Πλαγγόνος, ἂν σὲ ἐγγράφωσιν, ἂν δ’ ἐμέ, τῆς ἐμῆς μητρὸς τοὔνομα. καὶ τίς ἤκουσε πώποτε, ἢ κατὰ ποῖον νόμον προσπαραγράφοιτ’ ἂν τοῦτο τὸ παράγραμμα ἢ ἄλλο τι πλὴν ὁ πατὴρ καὶ ὁ δῆμος; ὧν ὄντων ἀμφοῖν τῶν αὐτῶν πολλὴ ταραχὴ συμβαίνει.", "st": "39.9"}, {"sp": "N", "t": "φέρε, εἰ δὲ κριτὴς καλοῖτο Μαντίθεος Μαντίου Θορίκιος, τί ἂν ποιοῖμεν; ἢ βαδίζοιμεν ἂν ἄμφω; τῷ γὰρ ἔσται δῆλον πότερον σὲ κέκληκεν ἢ ἐμέ; πρὸς Διός, ἂν δ’ ἀρχὴν ἡντινοῦν ἡ πόλις κληροῖ, οἷον βουλῆς, θεσμοθέτου, τῶν ἄλλων, τῷ δῆλος ὁ λαχὼν ἡμῶν ἔσται; πλὴν εἰ σημεῖον, ὥσπερ ⟨ἂν⟩ ἄλλῳ τινί, τῷ χαλκίῳ προσέσται· καὶ οὐδὲ τοῦθ’ ὁποτέρου ἐστὶν οἱ πολλοὶ γνώσονται. οὐκοῦν ὁ μὲν ἑαυτόν, ἐγὼ δ’ ἐμαυτὸν φήσω τὸν εἰληχότ’ εἶναι.", "st": "39.10"}, {"sp": "N", "t": "λοιπὸν εἰς τὸ δικαστήριον [ἡμᾶς] εἰσιέναι. οὐκοῦν ἐφ’ ἑκάστῳ τούτων δικαστήριον ἡμῖν ἡ πόλις καθιεῖ, καὶ τοῦ μὲν κοινοῦ καὶ ἴσου, τοῦ τὸν λαχόντ’ ἄρχειν, ἀποστερησόμεθα, ἀλλήλους δὲ πλυνοῦμεν, καὶ ὁ τῷ λόγῳ κρατήσας ἄρξει. καὶ πότερ’ ἂν βελτίους εἴημεν τῶν ὑπαρχουσῶν δυσκολιῶν ἀπαλλαττόμενοι, ἢ καινὰς ἔχθρας καὶ βλασφημίας ποιούμενοι; ἃς πᾶσ’ ἀνάγκη συμβαίνειν, ὅταν ἀρχῆς ἤ τινος ἄλλου πρὸς ἡμᾶς αὐτοὺς ἀμφισβητῶμεν.", "st": "39.11"}, {"sp": "N", "t": "τί δ’, ἂν ἄρα (δεῖ γὰρ ἅπαντα [ἡμᾶς] ἐξετάσαι) ἅτερος ἡμῶν πείσας τὸν ἕτερον, ἐὰν λάχῃ, παραδοῦναι αὑτῷ τὴν ἀρχήν, οὕτω κληρῶται, τὸ δυοῖν πινακίοιν τὸν ἕνα κληροῦσθαι τί ἄλλ’ ἐστίν; εἶτ’ ἐφ’ ᾧ θάνατον ζημίαν ὁ νόμος λέγει, τοῦθ’ ἡμῖν ἀδεῶς ἐξέσται πράττειν; “πάνυ γε· οὐ γὰρ ἂν αὐτὸ ποιήσαιμεν.” οἶδα κἀγώ, τὸ γοῦν κατ’ ἐμέ· ἀλλ’ οὐδ’ αἰτίαν τοιαύτης ζημίας ἐνίους ἔχειν καλόν, ἐξὸν μή.", "st": "39.12"}, {"sp": "N", "t": "εἶεν. ἀλλὰ ταῦτα μὲν ἡ πόλις βλάπτεται· ἐγὼ δ’ ἰδίᾳ τί; θεάσασθ’ ἡλίκα, καὶ σκοπεῖτ’ ἄν τι δοκῶ λέγειν· πολὺ γὰρ χαλεπώτερα ταῦθ’ ὧν ἀκηκόατ’ ἐστίν. ὁρᾶτε μὲν γὰρ ἅπαντες αὐτὸν χρώμενον, ἕως μὲν ἔζη, Μενεκλεῖ καὶ τοῖς περὶ ἐκεῖνον ἀνθρώποις, νῦν δ’ ἑτέροις ἐκείνου βελτίοσιν οὐδέν, καὶ τὰ τοιαῦτ’ ἐζηλωκότα καὶ δεινὸν δοκεῖν εἶναι βουλόμενον· καὶ νὴ Δί’ ἴσως ἔστιν.", "st": "39.13"}, {"sp": "N", "t": "ἂν οὖν προϊόντος τοῦ χρόνου τῶν αὐτῶν τι ποιεῖν τούτοις ἐπιχειρῇ (ἔστι δὲ ταῦτα γραφαί, φάσεις, ἐνδείξεις, ἀπαγωγαί), εἶτ’ ἐπὶ τούτων τινί (πολλὰ γάρ ἐστι τἀνθρώπινα, καὶ τοὺς πάνυ δεινοὺς ἑκάστοτε, ὅταν πλεονάζωσιν, ἐπίστασθ’ ὑμεῖς κοσμίους ποιεῖν) ὄφλῃ τῷ δημοσίῳ, τί μᾶλλον οὗτος ἐγγεγραμμένος ἔσται ἐμοῦ;", "st": "39.14"}, {"sp": "N", "t": "ὅτι νὴ Δί’ εἴσονται πάντες πότερός ποτ’ ὦφλεν. καλῶς. ἂν δέ, ὃ τυχὸν γένοιτ’ ἄν, χρόνος διέλθῃ καὶ μὴ ἐκτεισθῇ τὸ ὄφλημα, τί μᾶλλον οἱ τούτου παῖδες ἔσονται τῶν ἐμῶν ἐγγεγραμμένοι, ὅταν τοὔνομα καὶ ὁ πατὴρ καὶ ἡ φυλὴ καὶ πάντ’ ᾖ ταὐτά; τί δ’, εἴ τις δίκην ἐξούλης αὐτῷ λαχὼν μηδὲν ἐμοὶ φαίη πρὸς αὑτὸν εἶναι, κυρίαν δὲ ποιησάμενος ἐγγράψαι, τί μᾶλλον ἂν εἴη τοῦτον ἢ ἔμ’ ἐγγεγραφώς; τί δ’, εἴ τινας εἰσφορὰς μὴ θείη;", "st": "39.15"}, {"sp": "N", "t": "τί δ’, εἴ τις ἄλλη περὶ τοὔνομα γίγνοιτ’ ἢ λῆξις δίκης ἢ δόξ’ ὅλως ἀηδής; τίς εἴσεται τῶν πολλῶν πότερός ποθ’ οὗτός ἐστιν, δυοῖν Μαντιθέοιν ταὐτοῦ πατρὸς ὄντοιν; φέρε, εἰ δὲ δίκην ἀστρατείας φεύγοι, χορεύοι δ’ ὅταν στρατεύεσθαι δέῃ; καὶ γὰρ νῦν, ὅτ’ εἰς Ταμύνας παρῆλθον οἱ ἄλλοι, ἐνθάδε τοὺς Χοᾶς ἄγων ἀπελείφθη καὶ τοῖς Διονυσίοις καταμείνας ἐχόρευεν, ὡς ἅπαντες ἑωρᾶθ’ οἱ ἐπιδημοῦντες.", "st": "39.16"}, {"sp": "N", "t": "ἀπελθόντων δ’ ἐξ Εὐβοίας τῶν στρατιωτῶν λιποταξίου προσεκλήθη, κἀγὼ ταξιαρχῶν τῆς φυλῆς ἠναγκαζόμην κατὰ τοὐνόματος τοῦ ἐμαυτοῦ πατρόθεν δέχεσθαι τὴν λῆξιν· καὶ εἰ μισθὸς ἐπορίσθη τοῖς δικαστηρίοις, εἰσῆγον ἂν δῆλον ὅτι. ταῦτα δ’ εἰ μὴ σεσημασμένων ἤδη συνέβη τῶν ἐχίνων, κἂν μάρτυρας ὑμῖν παρεσχόμην.", "st": "39.17"}, {"sp": "N", "t": "εἶεν. εἰ δὲ ξενίας προσκληθείη; πολλοῖς δὲ προσκρούει, καὶ ὃν ἠναγκάσθη τρόπον ὁ πατὴρ ποιήσασθαι αὐτόν, οὐ λέληθεν. ὑμεῖς δ’, ὅτε μὲν τοῦτον οὐκ ἐποιεῖθ’ ὁ πατήρ, τὴν μητέρ’ ἀληθῆ λέγειν ἡγεῖσθ’ αὐτοῦ· ἐπειδὰν δ’ οὕτως γεγονὼς οὗτος ὀχληρὸς ᾖ, πάλιν ὑμῖν ποτὲ δόξει ’κεῖνος ἀληθῆ λέγειν. τί δ’, εἰ ψευδομαρτυρίων ἁλώσεσθαι προσδοκῶν ἐφ’ οἷς ἐρανίζει τούτοις τοῖς περὶ αὑτόν, ἐρήμην ἐάσειεν τελεσθῆναι τὴν δίκην; ἆρά γε μικρὰν ἡγεῖσθε βλάβην, ὦ ἄνδρες Ἀθηναῖοι, ἐν κοινωνίᾳ τὸν ἅπαντα βίον τῆς τούτου δόξης καὶ τῶν ἔργων εἶναι;", "st": "39.18"}, {"sp": "N", "t": "ὅτι τοίνυν οὐδ’ ἃ διεξελήλυθ’ ὑμῖν μάτην φοβοῦμαι, θεωρήσατε. οὗτος γὰρ ἤδη καὶ γραφάς τινας, ὦ ἄνδρες Ἀθηναῖοι, πέφευγεν, ἐφ’ αἷς οὐδὲν αἴτιος ὢν ἐγὼ συνδιαβάλλομαι, καὶ τῆς ἀρχῆς ἠμφεσβήτει, ἣν ὑμεῖς ἔμ’ ἐχειροτονήσατε, καὶ πολλὰ καὶ δυσχερῆ διὰ τοὔνομα συμβέβηκεν ἡμῖν, ὧν, ἵν’ εἰδῆτε, ἑκάστων μάρτυρας ὑμῖν παρέξομαι.", "st": "39.19"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "39.19"}, {"sp": "N", "t": "ὁρᾶτ’, ὦ ἄνδρες Ἀθηναῖοι, τὰ συμβαίνοντα, καὶ τὴν ἀηδίαν τὴν ἐκ τοῦ πράγματος. εἰ τοίνυν μηδὲν ἀηδὲς ἦν ἐκ τούτων, μηδ’ ὅλως ἀδύνατον ταὐτὸν ἔχειν ὄνομ’ ἡμῖν συνέβαινεν, οὐ δήπου τοῦτον μὲν δίκαιον τὸ μέρος τῶν [ἐμῶν] χρημάτων ἔχειν κατὰ τὴν ποίησιν, ἣν ὁ πατὴρ αὐτὸν ἀναγκασθεὶς ἐποιήσατο, ἐμὲ δ’ ἀφαιρεθῆναι τοὔνομα, ὃ βουλόμενος καὶ οὐδ’ ὑφ’ ἑνὸς βιασθεὶς ἔθετο. οὐκ ἔγωγ’ ἡγοῦμαι. ἵνα τοίνυν εἰδῆτε, ὅτι οὐ μόνον εἰς τοὺς φράτερας οὕτως, ὡς μεμαρτύρηται, ὁ πατὴρ τὴν ἐγγραφὴν ἐποιήσατο, ἀλλὰ καὶ τὴν δεκάτην ἐμοὶ ποιῶν τοὔνομα τοῦτ’ ἔθετο, λαβέ μοι καὶ ταύτην τὴν μαρτυρίαν.", "st": "39.20"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "39.20"}, {"sp": "N", "t": "ἀκούετ’, ἄνδρες Ἀθηναῖοι, ὅτι ἐγὼ μέν εἰμ’ ἐπὶ τοὐνόματος τούτου πάντα τὸν χρόνον, τουτονὶ δὲ Βοιωτὸν εἰς τοὺς φράτερας, ἡνίκ’ ἠναγκάσθη, ἐνέγραψεν ὁ πατήρ. ἡδέως τοίνυν ἐροίμην ἂν αὐτὸν ἐναντίον ὑμῶν· εἰ μὴ ἐτελεύτησεν ὁ πατήρ, τί ἄν ποτ’ ἐποίεις πρὸς τοῖς δημόταις; οὐκ ἂν εἴας σεαυτὸν ἐγγράφειν Βοιωτόν; ἀλλ’ ἄτοπον δίκην μὲν λαγχάνειν τούτου, κωλύειν δὲ πάλιν. καὶ μὴν εἴ γ’ εἴας αὐτόν, ἐνέγραψεν ἄν σ’ εἰς τοὺς δημότας, ὅπερ εἰς τοὺς φράτερας. οὐκοῦν δεινόν, ὦ γῆ καὶ θεοί, φάσκειν μὲν ἐκεῖνον αὑτοῦ πατέρ’ εἶναι, τολμᾶν δ’ ἄκυρα ποιεῖν ἁκεῖνος ἔπραξεν ζῶν.", "st": "39.21"}, {"sp": "N", "t": "ἐτόλμα τοίνυν πρὸς τῷ διαιτητῇ πρᾶγμ’ ἀναιδέστατον λέγειν, ὡς ὁ πατὴρ αὑτοῦ δεκάτην ἐποίησεν ὥσπερ ἐμοῦ καὶ τοὔνομα τοῦτ’ ἔθετ’ αὐτῷ, καὶ μάρτυράς τινας παρείχετο, οἷς ἐκεῖνος οὐδεπώποτ’ ὤφθη χρώμενος. ἐγὼ δ’ οὐδέν’ ὑμῶν ἀγνοεῖν οἴομαι, ὅτι οὔτ’ ἂν ἐποίησε δεκάτην οὐδεὶς παιδίου μὴ νομίζων αὑτοῦ δικαίως εἶναι, οὔτε ποιήσας καὶ στέρξας, ὡς ἂν υἱόν τις στέρξαι, πάλιν ἔξαρνος ἐτόλμησε γενέσθαι.", "st": "39.22"}, {"sp": "N", "t": "οὐδὲ γὰρ εἴ τι τῇ μητρὶ πρὸς ὀργὴν ἦλθεν τῇ τούτων, τούτους ἂν ἐμίσει, νομίζων αὑτοῦ εἶναι· πολὺ γὰρ μᾶλλον εἰώθασιν, ὧν ἂν ἑαυτοῖς διενεχθῶσιν ἀνὴρ καὶ γυνή, διὰ τοὺς παῖδας καταλλάττεσθαι ἢ δι’ ἃν ἀδικηθῶσιν ὑφ’ αὑτῶν, τοὺς κοινοὺς παῖδας πρὸς μισεῖν. οὐ τοίνυν ἐκ τούτων ἔστιν ἰδεῖν μόνον ὅτι ψεύσεται, ταῦτ’ ἂν λέγῃ, ἀλλὰ πρὶν ἡμέτερος φάσκειν συγγενὴς εἶναι, εἰς Ἱπποθωντίδ’ ἐφοίτα φυλὴν εἰς παῖδας χορεύσων.", "st": "39.23"}, {"sp": "N", "t": "καίτοι τίς ἂν ὑμῶν οἴεται τὴν μητέρα πέμψαι τοῦτον εἰς ταύτην τὴν φυλήν, δεινὰ μέν, ὥς φησιν, ὑπὸ τοῦ πατρὸς πεπονθυῖαν, δεκάτην δ’ εἰδυῖαν πεποιηκότ’ ἐκεῖνον καὶ πάλιν ἔξαρνον ὄντα; ἐγὼ μὲν οὐδέν’ ἂν οἶμαι. εἰς γὰρ τὴν Ἀκαμαντίδ’ ὁμοίως ἐξῆν σοι φοιτᾶν, καὶ ἐφαίνετ’ ἂν οὖσ’ ἀκόλουθος ἡ φυλὴ τῇ θέσει τοὐνόματος. ὡς τοίνυν ταῦτ’ ἀληθῆ λέγω, τούτων μάρτυρας ὑμῖν τοὺς συμφοιτῶντας καὶ τοὺς εἰδότας παρέξομαι.", "st": "39.24"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "39.24"}, {"sp": "N", "t": "οὕτω τοίνυν φανερῶς παρὰ τὸν τῆς αὑτοῦ μητρὸς ὅρκον καὶ τὴν τοῦ δόντος ἐκείνῃ τὸν ὅρκον εὐήθειαν πατρὸς τετυχηκὼς καὶ ἀνθ’ Ἱπποθωντίδος ἐν Ἀκαμαντίδι φυλῇ γεγονώς, οὐκ ἀγαπᾷ Βοιωτὸς οὑτοσί, ἀλλὰ καὶ δίκας ἐμοὶ δύ’ ἢ τρεῖς εἴληχεν ἀργυρίου πρὸς αἷς καὶ πρότερόν μ’ ἐσυκοφάντει. καίτοι πάντας οἶμαι τοῦθ’ ὑμᾶς εἰδέναι, τίς ἦν χρηματιστὴς ὁ πατήρ.", "st": "39.25"}, {"sp": "N", "t": "ἐγὼ δ’ ἐάσω ταῦτα. ἀλλ’ εἰ δίκαι’ ὀμώμοκεν ἡ μήτηρ ἡ τούτων, ἐπ’ αὐτοφώρῳ συκοφάντην ἐπιδεικνύει τοῦτον ταῖς δίκαις ταύταις. εἰ γὰρ οὕτω δαπανηρὸς ἦν, ὥστε γάμῳ γεγαμηκὼς τὴν ἐμὴν μητέρα, ἑτέραν εἶχε γυναῖκα, ἧς ὑμεῖς ἐστέ, καὶ δύ’ οἰκίας ᾤκει, πῶς ἂν ἀργύριον τοιοῦτος ὢν κατέλιπεν;", "st": "39.26"}, {"sp": "N", "t": "οὐκ ἀγνοῶ τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, ὅτι Βοιωτὸς οὑτοσὶ δίκαιον μὲν οὐδὲν ἕξει λέγειν, ἥξει δ’ ἐπὶ ταῦθ’ ἅπερ ἀεὶ λέγει, ὡς ἐπηρέαζεν ὁ πατὴρ αὐτῷ πειθόμενος ὑπ’ ἐμοῦ, ἀξιοῖ δ’ αὐτὸς ὡς δὴ πρεσβύτερος ὢν τοὔνομ’ ἔχειν τὸ τοῦ πρὸς πατρὸς πάππου. πρὸς δὴ ταῦτ’ ἀκοῦσαι βέλτιον ὑμᾶς βραχέα. ἐγὼ γὰρ οἶδα τοῦτον, ὅτ’ οὔπω συγγενὴς ἦν ἐμοί, ὁρῶν ὥσπερ ἂν ἄλλον τιν’ οὑτωσί, νεώτερον ὄντ’ ἐμοῦ καὶ συχνῷ, ὅσ’ ἐξ ὄψεως, οὐ μὴν ἰσχυρίζομαι τούτῳ (καὶ γὰρ εὔηθες)·", "st": "39.27"}, {"sp": "N", "t": "ἀλλ’ εἴ τις ἔροιτο Βοιωτὸν τουτονί, ὅτ’ ἐν Ἱπποθωντίδι φυλῇ ἠξίους χορεύειν, οὔπω τοῦ πατρὸς εἶναι φάσκων τοῦ ἐμοῦ υἱός, τί σαυτὸν ἔχειν δικαίως ἂν θείης ὄνομα; εἰ γὰρ Μαντίθεον, οὐκ ἂν διὰ τοῦτό γε φαίης ὅτι πρεσβύτερος εἶ ἐμοῦ. ὃς γὰρ οὐδὲ τῆς φυλῆς τότε σοι προσήκειν ἡγοῦ τῆς ἐμῆς, πῶς ἂν τοῦ γε πάππου τοῦ ἐμοῦ ἠμφεσβήτεις;", "st": "39.28"}, {"sp": "N", "t": "ἔτι δ’, ὦ ἄνδρες Ἀθηναῖοι, τὸν μὲν τῶν ἐτῶν χρόνον οὐδεὶς οἶδεν ὑμῶν (ἐγὼ μὲν γὰρ ἐμοὶ πλείονα, οὗτος δ’ ἑαυτῷ φήσει), τὸν δὲ τοῦ δικαίου λόγον ἅπαντες ἐπίστασθε. ἔστι δ’ οὗτος τίς; ἀφ’ οὗ παῖδας ἐποιήσατο τούτους ὁ πατήρ, ἀπὸ τούτου καὶ νομίζεσθαι. πρότερον τοίνυν ἔμ’ εἰς τοὺς δημότας ἐνέγραψε Μαντίθεον, πρὶν εἰσαγαγεῖν τοῦτον εἰς τοὺς φράτερας. ὥστ’ οὐ τῷ χρόνῳ μόνον, ἀλλὰ καὶ τῷ δικαίῳ πρεσβεῖον ἔχοιμ’ ἂν ἐγὼ τοὔνομα τοῦτ’ εἰκότως.", "st": "39.29"}, {"sp": "N", "t": "εἶεν. εἰ δέ τίς σ’ ἔροιτο, “εἰπέ μοι, Βοιωτέ, πόθεν νῦν Ἀκαμαντίδος φυλῆς γέγονας καὶ τῶν δήμων Θορίκιος καὶ υἱὸς Μαντίου, καὶ τὸ μέρος τῶν ὑπ’ ἐκείνου καταλειφθέντων ἔχεις;” οὐδὲν ἂν ἄλλ’ ἔχοις εἰπεῖν, πλὴν ὅτι κἀμὲ ζῶν ἐποιήσατο Μαντίας. τί τεκμήριον, εἴ τίς σ’ ἔροιτο, ἢ μαρτύριόν ἐστί σοι τούτου; εἰς τοὺς φράτεράς μ’ εἰσήγαγε, φήσειας ἄν. τί οὖν σ’ ἐνέγραψεν ὄνομα, εἴ τις ἔροιτο, Βοιωτὸν ἂν εἴποις· τοῦτο γὰρ εἰσήχθης.", "st": "39.30"}, {"sp": "N", "t": "οὐκοῦν δεινὸν εἰ τῆς μὲν πόλεως καὶ τῶν ὑπ’ ἐκείνου καταλειφθέντων διὰ τοὔνομα τοῦτο μέτεστί σοι, τοῦτο δ’ ἀξιοῖς ἀφεὶς ἕτερον μεταθέσθαι σαυτῷ. φέρ’, εἴ σ’ ὁ πατὴρ ἀξιώσειεν ἀναστάς, ἢ μένειν ἐφ’ οὗ σ’ αὐτὸς ἐποιήσατ’ ὀνόματος, ἢ πατέρ’ ἄλλον σαυτοῦ φάσκειν εἶναι, ἆρ’ οὐκ ἂν μέτρι’ ἀξιοῦν δοκοίη; ταὐτὰ τοίνυν ταῦτ’ ἐγώ σ’ ἀξιῶ, ἢ πατρὸς ἄλλου σεαυτὸν παραγράφειν, ἢ τοὔνομ’ ἔχειν ὃ ’κεῖνος ἔδωκέ σοι.", "st": "39.31"}, {"sp": "N", "t": "νὴ Δί’, ἀλλ’ ὕβρει καὶ ἐπηρείᾳ τινὶ τοῦτ’ ἐτέθη σοι. ἀλλὰ πολλάκις μέν, ὅτ’ οὐκ ἐποιεῖθ’ ὁ πατὴρ τούτους, ἔλεγον οὗτοι ὡς οὐδὲν χείρους εἰσὶν οἱ τῆς μητρὸς τῆς τούτου συγγενεῖς τῶν τοῦ πατρὸς τοῦ ἐμοῦ. ἔστι δ’ ὁ Βοιωτὸς ἀδελφοῦ τῆς τούτου μητρὸς ὄνομα. ἐπειδὴ δ’ εἰσάγειν ὁ πατὴρ τούτους ἠναγκάζετο, ἐμοῦ προεισηγμένου Μαντιθέου, οὕτω τοῦτον εἰσάγει Βοιωτόν, τὸν ἀδελφὸν δ’ αὐτοῦ Πάμφιλον. ἐπεὶ σὺ δεῖξον, ὅστις Ἀθηναίων ταὐτὸν ὄνομα τοῖς αὑτοῦ παισὶν ἔθετο δυοῖν· κἂν δείξῃς, ἐγὼ συγχωρήσω δι’ ἐπήρειάν σοι τοῦτο τοὔνομα θέσθαι τὸν πατέρα.", "st": "39.32"}, {"sp": "N", "t": "καίτοι εἴ γε τοιοῦτος ἦσθα, ὥστε ποιήσασθαι μὲν σαυτὸν ἀναγκάσαι, ἐξ ὅτου δ’ ἀρέσεις ἐκείνῳ τρόπου μὴ σκοπεῖν, οὐκ ἦσθ’ οἷον δεῖ τὸν προσήκοντ’ εἶναι περὶ τοὺς γονέας, οὐκ ὢν δ’ οὐκ ἐπηρεάζου δικαίως ἄν, ἀλλ’ ἀπωλώλεις. ἢ δεινόν γ’ ἂν εἴη, εἰ κατὰ μὲν τῶν ὑπὸ τοῦ πατρὸς αὐτοῦ νομιζομένων παίδων οἱ περὶ τῶν γονέων ἰσχύσουσιν νόμοι, κατὰ δὲ τῶν αὑτοὺς εἰσβιαζομένων ἄκοντας ποιεῖσθαι ἄκυροι γενήσονται.", "st": "39.33"}, {"sp": "N", "t": "ἀλλ’, ὦ χαλεπώτατε Βοιωτέ, μάλιστα μὲν ὧν πράττεις πάντων παῦσαι, εἰ δ’ ἄρα μὴ βούλει, ἐκεῖνό γε πρὸς Διὸς πείθου· παῦσαι μὲν σαυτῷ παρέχων πράγματα, παῦσαι δ’ ἐμὲ συκοφαντῶν, ἀγάπα δ’ ὅτι σοι πόλις, οὐσία, πατὴρ γέγονεν. οὐδεὶς ἀπελαύνει σ’ ἀπὸ τούτων, οὔκουν ἔγωγε. ἀλλ’ ἂν μέν, ὥσπερ εἶναι φὴς ἀδελφός, καὶ τὰ ἔργ’ ἀδελφοῦ ποιῇς, δόξεις εἶναι συγγενής, ἂν δ’ ἐπιβουλεύῃς, δικάζῃ, φθονῇς, βλασφημῇς, δόξεις εἰς ἀλλότρι’ ἐμπεσὼν ὡς οὐ προσήκουσιν οὕτω χρῆσθαι.", "st": "39.34"}, {"sp": "N", "t": "ἐπεὶ ἔγωγ’ οὐδ’ εἰ τὰ μάλισθ’ ὁ πατὴρ ὄντα σ’ ἑαυτοῦ μὴ ἐποιεῖτ’ ἀδικῶ. οὐ γὰρ ἐμοὶ προσῆκεν εἰδέναι, τίνες εἰσὶν υἱεῖς ἐκείνου, ἀλλ’ ἐκείνῳ δεῖξαι, τίν’ ἐμοὶ νομιστέον ἔστ’ ἀδελφόν. ὃν μὲν τοίνυν οὐκ ἐποιεῖτό σε χρόνον, οὐδ’ ἐγὼ προσήκονθ’ ἡγούμην, ἐπειδὴ δ’ ἐποιήσατο, κἀγὼ νομίζω. τί τούτου σημεῖον; τῶν πατρῴων ἔχεις τὸ μέρος μετὰ τὴν τοῦ πατρὸς τελευτήν· ἱερῶν, ὁσίων μετέχεις· ἀπάγει σ’ οὐδεὶς ἀπὸ τούτων. τί βούλει; ἂν δὲ φῇ δεινὰ πάσχειν καὶ κλάῃ καὶ ὀδύρηται καὶ κατηγορῇ ἐμοῦ, ἃ μὲν ἂν λέγῃ, μὴ πιστεύετε (οὐ γὰρ δίκαιον μὴ περὶ τούτων ὄντος τοῦ λόγου νυνί), ἐκεῖνο δ’ ὑπολαμβάνετε, ὅτι οὐδὲν ἔστ’ αὐτῷ ἧττον δίκην λαμβάνειν Βοιωτῷ κληθέντι.", "st": "39.35"}, {"sp": "N", "t": "τί οὖν φιλονικεῖς; μηδαμῶς· μὴ ἔχ’ οὕτω πρὸς ἡμᾶς ἐθελέχθρως· οὐδὲ γὰρ ἐγὼ πρὸς σέ, ἐπεὶ καὶ νῦν, ἵνα μηδὲ τοῦτο λάθῃ σε, ὑπὲρ σοῦ λέγω μᾶλλον, ἀξιῶν μὴ ταὐτὸν ἔχειν ὄνομ’ ἡμᾶς. εἰ γὰρ μηδὲν ἄλλο, ἀνάγκη τὸν ἀκούσαντ’ ἐρέσθαι πότερος, δύ’ ἂν ὦσιν Μαντίθεοι Μαντίου. οὐκοῦν, ὃν ἠναγκάσθη ποιήσασθαι, σὲ ἂν λέγῃ, ἐρεῖ. τί οὖν ἐπιθυμεῖς τούτων; ἀνάγνωθι δέ μοι λαβὼν δύο ταυτασὶ μαρτυρίας, ὡς ἐμοὶ Μαντίθεον καὶ τούτῳ Βοιωτὸν ὁ πατὴρ ὄνομ’ ἔθετο.", "st": "39.36"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "39.36"}, {"sp": "N", "t": "λοιπὸν ἡγοῦμαι τοῦθ’ ὑμῖν ἐπιδεῖξαι, ὦ ἄνδρες Ἀθηναῖοι, ὡς οὐ μόνον εὐορκήσετε, ἂν ἁγὼ λέγω ψηφίσησθε, ἀλλὰ καὶ ὡς οὗτος [αὐτὸς] αὑτοῦ κατέγνω Βοιωτόν, ἀλλ’ οὐ Μαντίθεον ὄνομα δικαίως ἂν ἔχειν. λαχόντος γὰρ ἐμοῦ τὴν δίκην ταύτην Βοιωτῷ Μαντίου Θορικίῳ, ἐξ ἀρχῆς τ’ ἠντεδίκει καὶ ὑπώμνυθ’ ὡς ὢν Βοιωτός, καὶ τὸ τελευταῖον, ἐπεὶ οὐκέτ’ ἐνῆν αὐτῷ διακρούσασθαι, ἐρήμην ἐάσας καταδιαιτῆσαι, σκέψασθε πρὸς θεῶν τί ἐποίησεν·", "st": "39.37"}, {"sp": "N", "t": "ἀντιλαγχάνει μοι τὴν μὴ οὖσαν Βοιωτὸν αὑτὸν προσαγορεύσας. καίτοι ἐξ ἀρχῆς τ’ ἔδει ἐᾶν αὐτὸν τελέσασθαι τὴν δίκην κατὰ Βοιωτοῦ, εἴπερ μηδὲν προσῆκεν αὐτῷ τοὐνόματος, ὕστερόν τε μὴ αὐτὸν φαίνεσθαι ἐπὶ τῷ ὀνόματι τούτῳ ἀντιλαγχάνοντα τὴν μὴ οὖσαν. ὃς οὖν αὐτὸς αὑτοῦ κατέγνω δικαίως ⟨ἂν⟩ εἶναι Βοιωτός, τί ὑμᾶς ἀξιώσει τοὺς ὀμωμοκότας ψηφίζεσθαι; ὡς δὲ ταῦτ’ ἀληθῆ λέγω, λαβέ μοι τὴν ἀντίληξιν καὶ τὸ ἔγκλημα τουτί.", "st": "39.38"}, {"sp": "N", "t": "ΑΝΤΙΛΗΞΙΣ. ΕΓΚΛΗΜΑ.", "st": "39.38"}, {"sp": "N", "t": "εἰ μὲν τοίνυν οὗτος ἔχει δεῖξαι νόμον ὃς ποιεῖ κυρίους εἶναι τοὺς παῖδας τοῦ ἑαυτῶν ὀνόματος, ἃ λέγει νῦν οὗτος ὀρθῶς ἂν ψηφίζοισθε. εἰ δ’ ὁ μὲν νόμος, ὃν πάντες ἐπίστασθ’ ὁμοίως ἐμοί, τοὺς γονέας ποιεῖ κυρίους οὐ μόνον θέσθαι τοὔνομ’ ἐξ ἀρχῆς, ἀλλὰ κἂν πάλιν ἐξαλεῖψαι βούλωνται καὶ ἀποκηρῦξαι, ἐπέδειξα δ’ ἐγὼ τὸν πατέρα, ὃς κύριος ἦν ἐκ τοῦ νόμου, τούτῳ μὲν Βοιωτόν, ἐμοὶ δὲ Μαντίθεον θέμενον, πῶς ὑμῖν ἔστιν ἄλλο τι πλὴν ἁγὼ λέγω ψηφίσασθαι;", "st": "39.39"}, {"sp": "N", "t": "ἀλλὰ μὴν ὧν γ’ ἂν μὴ ὦσι νόμοι, γνώμῃ τῇ δικαιοτάτῃ δικάσειν ὀμωμόκατε, ὥστ’ εἰ μηδεὶς ἦν περὶ τούτων κείμενος νόμος, κἂν οὕτω δικαίως πρὸς ἐμοῦ τὴν ψῆφον ἔθεσθε. τίς γάρ ἐστιν ὑμῶν ὅστις ταὐτὸν ὄνομα τοῖς αὑτοῦ παισὶν τέθειται δυοῖν; τίς δ’, ᾧ μήπω παῖδες εἰσί, θήσεται;", "st": "39.40"}, {"sp": "N", "t": "οὐδεὶς δήπου. οὐκοῦν ὃ δίκαιον τῇ γνώμῃ τοῖς ὑμετέροις αὐτῶν παισὶν ὑπειλήφατε, τοῦτο καὶ περὶ ἡμῶν εὐσεβὲς γνῶναι. ὥστε καὶ κατὰ τὴν δικαιοτάτην γνώμην καὶ κατὰ τοὺς νόμους καὶ κατὰ τοὺς ὅρκους καὶ κατὰ τὴν τούτου προσομολογίαν ἐγὼ μὲν μέτρι’ ὑμῶν, ὦ ἄνδρες Ἀθηναῖοι, δέομαι καὶ δίκαι’ ἀξιῶ, οὗτος δ’ οὐ μόνον οὐ μέτρια, ἀλλ’ οὐδ’ εἰωθότα γίγνεσθαι.", "st": "39.41"}, {"sp": "HDR", "t": "Πρὸς Βοιωτὸν περὶ προικὸς μητρῴας", "st": "40"}, {"sp": "N", "t": "πάντων ἐστὶν ἀνιαρότατον, ὦ ἄνδρες δικασταί, ὅταν τις ὀνόματι μὲν ἀδελφὸς προσαγορευθῇ τινῶν, τῷ δ’ ἔργῳ ἐχθροὺς ἔχῃ τούτους, καὶ ἀναγκάζηται πολλὰ καὶ δεινὰ παθὼν ὑπ’ αὐτῶν εἰσιέναι εἰς δικαστήριον, ὃ νῦν ἐμοὶ συμβέβηκεν.", "st": "40.1"}, {"sp": "N", "t": "οὐ γὰρ μόνον ἀτύχημά μοι ἐξ ἀρχῆς ἐγένετο, διότι Πλαγγὼν ἡ τούτων μήτηρ ἐξαπατήσασα τὸν πατέρα μου καὶ ἐπιορκήσασα φανερῶς, ἠνάγκασεν αὐτὸν ὑπομεῖναι τούτους ποιήσασθαι, καὶ διὰ τοῦτο τὰ δύο μέρη τῶν πατρῴων ἀπεστερήθην· ἀλλὰ πρὸς τούτοις ἐξελήλαμαι μὲν ἐκ τῆς πατρῴας οἰκίας ὑπὸ τούτων, ἐν ᾗ καὶ ἐγενόμην καὶ ἐτράφην, καὶ εἰς ἣν οὐχ ὁ πατὴρ αὐτοὺς ἀλλ’ ἐγὼ τελευτήσαντος ἐκείνου παρεδεξάμην,", "st": "40.2"}, {"sp": "N", "t": "ἀποστεροῦμαι δὲ τὴν προῖκα τῆς ἐμαυτοῦ μητρός, περὶ ἧς νυνὶ δικάζομαι, αὐτὸς μὲν τούτοις δίκας ὑπὲρ ὧν ἐνεκάλουν μοι πάντων δεδωκώς, πλὴν εἴ τινα νῦν ἕνεκα τῆς δίκης ταύτης ἀντειλήχασίν μοι συκοφαντοῦντες, ὡς καὶ ὑμῖν ἔσται καταφανές, παρὰ δὲ τούτων ἐν ἕνδεκα ἔτεσιν οὐ δυνάμενος τυχεῖν τῶν μετρίων, ἀλλὰ νῦν εἰς ὑμᾶς [βοηθοὺς] καταπεφευγώς.", "st": "40.3"}, {"sp": "N", "t": "δέομαι οὖν ἁπάντων ὑμῶν, ὦ ἄνδρες δικασταί, μετ’ εὐνοίας τέ μου ἀκοῦσαι οὕτως ὅπως ἂν δύνωμαι λέγοντος, κἂν ὑμῖν δοκῶ δεινὰ πεπονθέναι, συγγνώμην ἔχειν μοι ζητοῦντι κομίσασθαι τἀμαυτοῦ, ἄλλως τε καὶ εἰς θυγατρὸς ἔκδοσιν· συνέβη γάρ μοι δεηθέντος τοῦ πατρὸς ὀκτωκαιδεκέτη γῆμαι, καὶ διὰ τοῦτο εἶναί μοι θυγατέρα ἤδη ἐπίγαμον.", "st": "40.4"}, {"sp": "N", "t": "ὥστ’ ἐμοὶ μὲν δικαίως ἂν ἀδικουμένῳ διὰ πολλὰ βοηθήσαιτε, τούτοις δὲ εἰκότως ἂν ὀργίζοισθε· οἵτινες, ὦ γῆ καὶ θεοί, ἐξὸν αὐτοῖς τὰ δίκαια ποιήσασι μὴ εἰσιέναι εἰς δικαστήριον, οὐκ αἰσχύνονται μὲν ἀναμιμνῄσκοντες ὑμᾶς εἴ τι ἢ ὁ πατὴρ ἡμῶν μὴ ὀρθῶς διεπράξατο ἢ οὗτοι εἰς ἐκεῖνον ἥμαρτον, ἀναγκάζουσι δ’ ἐμὲ δικάζεσθαι αὑτοῖς. ἵνα δὲ ἀκριβῶς εἰδῆτε, ὡς οὐκ ἐγὼ τούτου αἴτιός εἰμι ἀλλ’ οὗτοι, ἐξ ἀρχῆς ὑμῖν, ὡς ἂν ἐν βραχυτάτοις δύνωμαι, διηγήσομαι τὰ πραχθέντα.", "st": "40.5"}, {"sp": "N", "t": "ἡ γὰρ μήτηρ ἡ ἐμή, ὦ ἄνδρες δικασταί, θυγάτηρ μὲν ἦν Πολυαράτου Χολαργέως, ἀδελφὴ δὲ Μενεξένου καὶ Βαθύλλου καὶ Περιάνδρου. ἐκδόντος δὲ αὐτὴν τοῦ πατρὸς Κλεομέδοντι τῷ Κλέωνος υἱεῖ, καὶ προῖκα τάλαντον ἐπιδόντος, τὸ μὲν πρῶτον τούτῳ συνῴκει· γενομένων δ’ αὐτῇ τριῶν μὲν θυγατέρων, υἱοῦ δ’ ἑνὸς Κλέωνος, καὶ μετὰ ταῦτα τοῦ ἀνδρὸς αὐτῇ τελευτήσαντος, ἀπολιποῦσα τὸν οἶκον καὶ κομισαμένη τὴν προῖκα,", "st": "40.6"}, {"sp": "N", "t": "πάλιν ἐκδόντων αὐτὴν τῶν ἀδελφῶν Μενεξένου καὶ Βαθύλλου (ὁ γὰρ Περίανδρος ἔτι παῖς ἦν) καὶ τὸ τάλαντον ἐπιδόντων, συνῴκησε τῷ ἐμῷ πατρί. καὶ γίγνομαι αὐτοῖς ἐγώ τε καὶ ἄλλος ἀδελφὸς νεώτερος ἐμοῦ, ὃς ἔτι παῖς ὢν ἐτελεύτησεν. ὡς δ’ ἀληθῆ λέγω, περὶ τούτων ὑμῖν πρῶτον τοὺς μάρτυρας παρέξομαι.", "st": "40.7"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "40.7"}, {"sp": "N", "t": "τὴν μὲν τοίνυν μητέρα τὴν ἐμὴν οὕτως ὁ πατήρ μου γήμας εἶχε γυναῖκα ἐν τῇ οἰκίᾳ τῇ ἑαυτοῦ, ἐμέ τε ἐπαίδευεν καὶ ἠγάπα, ὥσπερ καὶ ὑμεῖς ἅπαντες τοὺς ὑμετέρους παῖδας ἀγαπᾶτε. τῇ δὲ τούτων μητρὶ Πλαγγόνι ἐπλησίασεν ὅντινα δή ποτ’ οὖν τρόπον· οὐ γὰρ ἐμὸν τοῦτο λέγειν ἐστίν.", "st": "40.8"}, {"sp": "N", "t": "καὶ οὕτως οὐ πάντα γε ἦν ὑπὸ τῆς ἐπιθυμίας κεκρατημένος, ὥστε οὐδὲ τῆς μητρὸς τῆς ἐμῆς ἀποθανούσης ἠξίωσεν αὐτὴν εἰς τὴν οἰκίαν παρ’ ἑαυτὸν εἰσδέξασθαι, οὐδὲ τούτους, ὡς υἱεῖς εἰσιν αὑτοῦ, πεισθῆναι· ἀλλὰ τὸν μὲν ἄλλον χρόνον οὗτοι διῆγον οὐκ ὄντες τοῦ ἐμοῦ πατρός, ὡς καὶ ὑμῶν οἱ πολλοὶ ἴσασιν, ἐπειδὴ δὲ οὗτος αὐξηθεὶς καὶ μεθ’ αὑτοῦ παρασκευασάμενος ἐργαστήριον συκοφαντῶν, ὧν ἡγεμὼν ἦν Μνησικλῆς καὶ Μενεκλῆς ἐκεῖνος ὁ τὴν Νῖνον ἑλών, μεθ’ ὧν οὗτος ἐδικάζετό", "st": "40.9"}, {"sp": "N", "t": "μου τῷ πατρὶ φάσκων υἱὸς εἶναι ἐκείνου—συνόδων δὲ γιγνομένων πολλῶν ὑπὲρ τούτων, καὶ τοῦ πατρὸς οὐκ ἂν φάσκοντος πεισθῆναι, ὡς οὗτοι γεγόνασιν ἐξ αὑτοῦ, τελευτῶσα ἡ Πλαγγών, ὦ ἄνδρες δικασταί (πάντα γὰρ εἰρήσεται τἀληθῆ πρὸς ὑμᾶς), μετὰ τοῦ Μενεκλέους ἐνεδρεύσασα τὸν πατέρα μου καὶ ἐξαπατήσασα ὅρκῳ, ὃς μέγιστος δοκεῖ καὶ δεινότατος παρὰ πᾶσιν ἀνθρώποις εἶναι, ὡμολόγησεν τριάκοντα μνᾶς λαβοῦσα τούτους μὲν τοῖς αὑτῆς ἀδελφοῖς εἰσποιήσειν υἱεῖς, αὐτὴ δέ, ἂν πρὸς τῷ διαιτητῇ προκαλῆται αὐτὴν ὁ πατήρ μου ὀμόσαι ἦ μὴν τοὺς παῖδας ἐξ αὑτοῦ γεγονέναι, οὐ δέξεσθαι τὴν πρόκλησιν· τούτων γὰρ γενομένων οὔτε τούτους ἀποστερήσεσθαι τῆς πολιτείας, τῷ τε πατρί μου οὐκέτι δυνήσεσθαι αὐτοὺς πράγματα παρέχειν, τῆς μητρὸς αὐτῶν οὐ δεξαμένης τὸν ὅρκον.", "st": "40.10"}, {"sp": "N", "t": "συγχωρηθέντων δὲ τούτων—τί ἂν ὑμῖν μακρολογοίην; ὡς γὰρ πρὸς τὸν διαιτητὴν ἀπήντησεν, παραβᾶσα πάντα τὰ ὡμολογημένα ἡ Πλαγγὼν δέχεταί τε τὴν πρόκλησιν καὶ ὄμνυσιν ἐν τῷ Δελφινίῳ ἄλλον ὅρκον ἐναντίον τῷ προτέρῳ, ὡς καὶ ὑμῶν οἱ πολλοὶ ἴσασιν· περιβόητος γὰρ ἡ πρᾶξις ἐγένετο. καὶ οὕτως ὁ πατήρ μου διὰ τὴν ἑαυτοῦ πρόκλησιν ἀναγκασθεὶς ἐμμεῖναι τῇ διαίτῃ, ἐπὶ μὲν τοῖς γεγενημένοις ἠγανάκτει καὶ βαρέως ἔφερεν, καὶ εἰς τὴν οἰκίαν οὐδ’ ὣς εἰσδέξασθαι τούτους ἠξίωσεν, εἰς δὲ τοὺς φράτερας ἠναγκάσθη εἰσαγαγεῖν. καὶ τοῦτον μὲν ἐνέγραψε Βοιωτόν, τὸν δ’ ἕτερον Πάμφιλον.", "st": "40.11"}, {"sp": "N", "t": "ἐμὲ δ’ εὐθὺς ἔπειθε περὶ ὀκτωκαίδεκ’ ἔτη γεγενημένον τὴν Εὐφήμου γῆμαι θυγατέρα, βουλόμενος παῖδας ἐξ ἐμοῦ γενομένους ἐπιδεῖν. ἐγὼ δέ, ὦ ἄνδρες δικασταί, νομίζων δεῖν καὶ πρότερον καὶ ἐπειδὴ οὗτοι ἐλύπουν αὐτὸν δικαζόμενοι καὶ πράγματα παρέχοντε, ἐμὲ τοὐναντίον εὐφραίνειν ἅπαντα ποιοῦντα ὅσα ἐκείνῳ χαριεῖσθαι μέλλοιμι, ἐπείσθην αὐτῷ.", "st": "40.12"}, {"sp": "N", "t": "γήμαντος δέ μου τὸν τρόπον τοῦτον, ἐκεῖνος μὲν τὸ θυγάτριόν μοι ἐπιδὼν γενόμενον, οὐ πολλοῖς ἔτεσιν ὕστερον ἀρρωστήσας ἐτελεύτησεν· ἐγὼ δ’, ὦ ἄνδρες δικασταί, ζῶντος μὲν τοῦ πατρὸς οὐδὲν ᾤμην δεῖν ἐναντιοῦσθαι αὐτῷ, τελευτήσαντος δὲ ἐκείνου εἰσεδεξάμην τε τούτους εἰς τὴν οἰκίαν καὶ τῶν ὄντων ἁπάντων μετέδωκα, οὐχ ὡς ἀδελφοῖς οὖσιν (οὐδὲ γὰρ ὑμῶν τοὺς πολλοὺς λελήθασιν ὃν τρόπον οὗτοι γεγόνασιν), νομίζων δ’ ἀναγκαῖον εἶναί μοι, ἐπειδὴ ὁ πατὴρ ἐξηπατήθη, πείθεσθαι τοῖς νόμοις τοῖς ὑμετέροις.", "st": "40.13"}, {"sp": "N", "t": "καὶ οὕτως ὑπ’ ἐμοῦ εἰς τὴν οἰκίαν εἰσδεχθέντες, ὡς ἐνεμόμεθα τὰ πατρῷα, ἀξιοῦντος ἐμοῦ ἀπολαβεῖν τὴν τῆς μητρὸς προῖκα ἀντενεκάλουν καὶ οὗτοι, καὶ ἔφασαν ὀφείλεσθαι καὶ τῇ αὑτῶν μητρὶ τὴν ἴσην προῖκα. συμβουλευσάντων δ’ ἡμῖν τῶν παρόντων, τὰ μὲν ἄλλα πάντα ἐνειμάμεθα, τὴν δὲ οἰκίαν καὶ τοὺς παῖδας τοὺς διακόνους τοῦ πατρὸς ἐξαιρέτους ἐποιησάμεθα,", "st": "40.14"}, {"sp": "N", "t": "ἵν’ ἐκ μὲν τῆς οἰκίας, ὁποτέροις ἂν ἡμῶν φαίνηται ὀφειλομένη ἡ προίξ, οὗτοι αὐτὴν κομίσωνται, ἐκ δὲ τῶν παίδων κοινῶν ὄντων, ἐάν τι οὗτοι τῶν πατρῴων ἐπιζητῶσιν, πυνθάνωνται, καὶ βασανίζοντες αὐτοὺς καὶ ἄλλῳ ὅτῳ ἂν τρόπῳ βούλωνται ζητοῦντες. ὅτι δὲ καὶ ταῦτ’ ἀληθῆ λέγω, ἐκ τούτων τῶν μαρτυριῶν εἴσεσθε.", "st": "40.15"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ", "st": "40.15"}, {"sp": "N", "t": "μετὰ ταῦτα τοίνυν οὗτοί τε ἐμοὶ δίκας ἔλαχον ὑπὲρ ὧν ἐνεκάλουν κἀγὼ τούτοις ὑπὲρ τῆς προικός. καὶ τὸ μὲν πρῶτον παραγραψάμενοι Σόλωνα Ἑρχιέα διαιτητὴν τούτῳ ἐπετρέψαμεν δικάσαι περὶ ὧν ἐνεκαλοῦμεν ἀλλήλοις· ὡς δ’ οὐκ ἀπήντων οὗτοι, ἀλλ’ ἐφυγοδίκουν καὶ χρόνος διετρίβετο συχνός, τῷ μὲν Σόλωνι συνέβη τελευτῆσαι τὸν βίον, οὗτοι δὲ πάλιν ἐξ ὑπαρχῆς λαγχάνουσί μοι τὰς δίκας, καὶ ἐγὼ τούτῳ, προσκαλεσάμενος αὐτὸν καὶ ἐπιγραψάμενος ἐπὶ τὸ ἔγκλημα Βοιωτόν· τοῦτο γὰρ αὐτῷ ὁ πατὴρ ἔθετο τοὔνομα.", "st": "40.16"}, {"sp": "N", "t": "περὶ μὲν οὖν ὧν οὗτοί μοι ἐδικάζοντο, παρόντος τούτου καὶ ἀντιδικοῦντος καὶ οὐκ ἔχοντος ἐπιδεῖξαι οὐδὲν ὧν ἐνεκάλουν, ἀπεδιῄτησέν μου ὁ διαιτητής· καὶ οὗτος συνειδὼς αὑτῷ ἀδίκως ἐγκαλοῦντι οὔτε ἐφῆκεν εἰς τὸ δικαστήριον, οὔτε νῦν περὶ ἐκείνων εἴληχέ μοι δίκην οὐδεμίαν, ἀλλὰ περὶ ἄλλων τινῶν, λύσειν τοῖς ἐγκλήμασι τούτοις τὴν δίκην ταύτην οἰόμενος. ἣν δ’ ἐγὼ τοῦτον ἐδίωκον τότε περὶ τῆς προικός, ἐπιδημοῦντος τούτου ἐνθάδε καὶ οὐκ ἀπαντήσαντος πρὸς τὸν διαιτητήν, ἐρήμην κατεδιῄτησεν αὐτοῦ.", "st": "40.17"}, {"sp": "N", "t": "οὑτοσὶ δέ, ὦ ἄνδρες δικασταί, οὔτε ἠντεδίκει τότε παρὼν οὔτε ἔφη με καταδιαιτήσασθαι τὴν δίκην αὑτοῦ· οὐ γὰρ εἶναι Βοιωτὸν αὑτῷ ὄνομα, ἀλλὰ Μαντίθεον, καὶ οὕτως ὀνόματι ἀμφισβητῶν ἔργῳ τὴν προῖκά με τῆς μητρὸς ἀποστερεῖ. ἀπορῶν δ’ ἐγὼ τί ἄν τις χρήσαιτο τῷ πράγματι, οὕτω πάλιν τὴν αὐτὴν ταύτην δίκην λαχὼν αὐτῷ Μαντιθέῳ ἑνδεκάτῳ ἔτει νῦν εἰς ὑμᾶς καταπέφευγα. ὡς δὲ καὶ ταῦτ’ ἀληθῆ λέγω, ἀναγνώσεται ὑμῖν ⟨τὰς⟩ περὶ τούτων μαρτυρίας.", "st": "40.18"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "40.18"}, {"sp": "N", "t": "ὅτι μὲν τοίνυν, ὦ ἄνδρες δικασταί, ἥ τε μήτηρ μου τάλαντον ἐπενεγκαμένη προῖκα, ἐκδοθεῖσα ὑπὸ τῶν ἀδελφῶν τῶν αὑτῆς, ὥσπερ οἱ νόμοι κελεύουσιν, συνῴκησεν τῷ πατρί, καὶ ὃν τρόπον ἐγὼ τούτους εἰσεδεξάμην εἰς τὴν οἰκίαν τοῦ πατρὸς τελευτήσαντος, καὶ ὅτι ἀπέφυγον αὐτοὺς τὰς δίκας ἅς μοι ἐνεκάλουν, ταῦτα μὲν πάντα καὶ μεμαρτύρηται ὑμῖν καὶ ἐπιδέδεικται. ἴθι δὴ λαβὲ καὶ τὸν περὶ τῆς προικὸς νόμον τουτονί.", "st": "40.19"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "40.19"}, {"sp": "N", "t": "οὕτω τοίνυν τοῦ νόμου ἔχοντος, οἶμαι τουτονὶ Βοιωτὸν ἢ Μαντίθεον ἢ ὅ τι ποτ’ ἄλλο χαίρει προσαγορευόμενος, δικαίαν μὲν ἀπολογίαν καὶ ἀληθινὴν οὐδεμίαν ἕξειν εἰπεῖν, ἐπιχειρήσειν δὲ τῇ τόλμῃ καὶ τῇ θρασύτητι τῇ ἑαυτοῦ πιστεύοντα περιιστάναι τὰς αὑτῶν συμφορὰς εἰς ἐμέ, ἅπερ καὶ ἰδίᾳ ποιεῖν εἴωθεν, λέγων ὡς δημευθείσης τῆς [τοῦ] Παμφίλου οὐσίας, ὃς ἦν πατὴρ τῆς Πλαγγόνος, τὰ περιγενόμενα χρήματα ὁ πατὴρ ὁ ἐμὸς ἔλαβεν ἐκ τοῦ βουλευτηρίου, καὶ οὕτως ἀποφαίνειν πειρώμενος τὴν μὲν αὑτοῦ μητέρα ἐπενεγκαμένην προῖκα πλέον ἢ ἑκατὸν μνᾶς, τὴν δ’ ἐμὴν ἄπροικον φάσκων συνοικῆσαι.", "st": "40.20"}, {"sp": "N", "t": "ταῦτα διέξεισιν, ὦ ἄνδρες δικασταί, οὔτε μαρτυρίαν οὐδεμίαν ἐμβεβλημένος ὑπὲρ τούτων οὔτ’ ἀγνοῶν ὡς οὐδὲν ὑγιὲς λέγει, ἀλλ’ ἀκριβῶς εἰδὼς ὅτι ὁμολογῶν μὲν ἀδικεῖν ἐν ὑμῖν οὐδείς πω ἀπέφυγεν, ψευδόμενος δὲ καὶ παραγωγὰς λέγων ἤδη τις δίκην οὐκ ἔδωκεν. ἵνα οὖν μὴ ἐξαπατηθῆτε ὑπ’ αὐτοῦ, βέλτιον εἶναί μοι δοκεῖ βραχέα καὶ περὶ τούτου πρὸς ὑμᾶς εἰπεῖν.", "st": "40.21"}, {"sp": "N", "t": "ἐὰν γὰρ λέγῃ ὡς ἡ μὲν ἐμὴ μήτηρ οὐκ ἐπηνέγκατο προῖκα, ἡ δὲ τούτων ἐπηνέγκατο, ἐνθυμεῖσθε ὅτι περιφανῶς ψεύδεται. πρῶτον μὲν γὰρ ὁ Πάμφιλος ὁ πατὴρ τῆς τούτου μητρὸς πέντε τάλαντα τῷ δημοσίῳ ὀφείλων ἐτελεύτησεν, καὶ τοσούτου ἐδέησεν περιγενέσθαι τι τοῖς ἐκείνου παισὶν τῆς οὐσίας ἀπογραφείσης καὶ δημευθείσης, ὥστε οὐδὲ τὸ ὄφλημα πᾶν ὑπὲρ αὐτοῦ ἐκτέτεισται, ἀλλ’ ἔτι καὶ νῦν ὁ Πάμφιλος ὀφείλων τῷ δημοσίῳ ἐγγέγραπται. πῶς οὖν οἷόν τε τὸν ἐμὸν πατέρα χρήματα λαβεῖν ἐκ τῆς Παμφίλου οὐσίας, ἣ οὐδὲ αὐτὸ τὸ ὄφλημα ἱκανὴ ἐγένετο τῇ πόλει ἐκτεῖσαι;", "st": "40.22"}, {"sp": "N", "t": "ἔπειτα, ὦ ἄνδρες δικασταί, ἐνθυμεῖσθε ὅτι, εἰ τὰ μάλιστα περιεγένετο τὰ χρήματα ταῦτα, ὥσπερ οὗτοί φασιν, οὐκ ἂν ὁ ἐμὸς πατὴρ αὐτὰ ἔλαβεν, ἀλλ’ οἱ τοῦ Παμφίλου υἱεῖς, Βοιωτὸς καὶ Ἡδύλος καὶ Εὐθύδημος, οἳ οὐκ ἂν δήπου ἐπὶ μὲν τῷ τἀλλότρια λαμβάνειν ὅτι ἂν οὖν ἐποίουν, ὡς καὶ ὑμεῖς ἅπαντες ἴστε, τὰ δ’ αὑτῶν τὸν ἐμὸν πατέρα περιεῖδον κομισάμενον.", "st": "40.23"}, {"sp": "N", "t": "ὅτι μὲν τοίνυν ἥ γε τούτων μήτηρ οὐκ ἐπηνέγκατο προῖκα, ἀλλ’ οὗτοι τοῦτο ψεύδονται, ἱκανῶς ὑμᾶς μεμαθηκέναι νομίζω· ὅτι δὲ ἡ ἐμὴ μήτηρ ἐπηνέγκατο, ῥᾳδίως ἐγὼ δείξω. πρῶτον μὲν γὰρ Πολυαράτου θυγάτηρ ἦν, ὃς καὶ ὑφ’ ὑμῶν ἐτιμᾶτο καὶ πολλὴν οὐσίαν ἐκέκτητο· ἔπειτα μεμαρτύρηται ὑμῖν ὡς καὶ ἡ ἀδελφὴ αὐτῆς τοσαύτην προῖκα ἐπενεγκαμένη Ἐρυξιμάχῳ συνῴκησεν, τῷ Χαβρίου κηδεστῇ.", "st": "40.24"}, {"sp": "N", "t": "πρὸς δὲ τούτοις φαίνεταί μου ἡ μήτηρ τὸ πρῶτον ἐκδοθεῖσα Κλεομέδοντι, οὗ φασι τὸν πατέρα Κλέωνα τῶν ὑμετέρων προγόνων στρατηγοῦντα, Λακεδαιμονίων πολλοὺς ἐν Πύλῳ ζῶντας λαβόντα, μάλιστα πάντων ἐν τῇ πόλει εὐδοκιμῆσαι· ὥστε οὔτε τὸν ἐκείνου προσῆκεν υἱὸν ἄπροικον αὐτὴν γῆμαι, οὔτε Μενέξενον καὶ Βάθυλλον εἰκός ἐστιν, αὐτούς τε οὐσίαν πολλὴν κεκτημένους καὶ Κλεομέδοντος τελευτήσαντος κομισαμένους τὴν προῖκα, ἀποστερῆσαι τὴν ἀδελφὴν τὴν ἑαυτῶν, ἀλλὰ προσθέντας αὐτοὺς ἐκδοῦναι τῷ ἡμετέρῳ πατρί, καθάπερ καὶ αὐτοὶ πρὸς ὑμᾶς καὶ οἱ ἄλλοι μεμαρτυρήκασιν.", "st": "40.25"}, {"sp": "N", "t": "χωρὶς δὲ τούτων ἐνθυμήθητε, διὰ τί ἄν ποτε ὁ πατήρ, εἴπερ ἡ μὲν ἐμὴ μήτηρ μὴ ἦν ἐγγυητὴ μηδὲ ἠνέγκατο προῖκα, ἡ δὲ τούτων ἠνέγκατο, τοὺς μὲν οὐκ ἔφη αὑτοῦ υἱεῖς εἶναι, ἐμὲ δὲ καὶ ἐποιεῖτο καὶ ἐπαίδευεν; ὅτι νὴ Δία, ὡς οὗτοι φήσουσιν, ἐμοὶ χαριζόμενος καὶ τῇ ἐμῇ μητρὶ τούτους ἠτίμαζεν.", "st": "40.26"}, {"sp": "N", "t": "ἀλλ’ ἐκείνη μὲν ἔτι παῖδα μικρὸν ἐμὲ καταλιποῦσα αὐτὴ τὸν βίον ἐτελεύτησεν, ἡ δὲ τούτων μήτηρ Πλαγγὼν καὶ πρότερον καὶ μετὰ ταῦτα εὐπρεπὴς τὴν ὄψιν οὖσα ἐπλησίαζεν αὐτῷ· ὥστε πολὺ μᾶλλον εἰκὸς ἦν αὐτὸν διὰ τὴν ζῶσαν γυναῖκα, ἧς ἐρῶν ἐτύγχανε, τὸν τῆς τεθνεώσης υἱὸν ἀτιμάζειν, ἢ δι’ ἐμὲ καὶ τὴν τετελευτηκυῖαν τοὺς ἐκ τῆς ζώσης καὶ πλησιαζούσης αὐτῷ παῖδας μὴ ποιεῖσθαι.", "st": "40.27"}, {"sp": "N", "t": "καίτοι οὗτός γε εἰς τοῦτο τόλμης ἥκει, ὥστε φησὶ τὸν πατέρα μου δεκάτην ὑπὲρ αὑτοῦ ἑστιᾶσαι. καὶ περὶ τούτου μόνον Τιμοκράτους καὶ Προμάχου ἐμβέβληται μαρτυρίας, οἳ οὔτε γένει προσήκουσί μου τῷ πατρὶ οὐδὲν οὔτε φίλοι ἦσαν ἐκείνῳ. οὕτω δὲ φανερῶς τὰ ψευδῆ μεμαρτυρήκασιν, ὥστε ὃν πάντων ὑμῶν εἰδότων οὑτοσὶ δίκην λαχὼν ἄκοντα ἠνάγκασε ποιήσασθαι αὑτόν, τοῦτον οὗτοι, ὥσπερ κλητῆρες, δύο μόνοι ὄντες μαρτυροῦσιν δεκάτην ὑπὲρ τούτου ἑστιᾶσαι.", "st": "40.28"}, {"sp": "N", "t": "οἷς τίς ἂν ὑμῶν πιστεύσειεν; καὶ μὴν οὐδ’ ἐκεῖνό γε εἰπεῖν αὐτῷ ἐνδέχεται, ὡς μικρὸν μὲν ὄντα ἐποιεῖτο αὐτὸν ὁ πατήρ, μείζω δὲ γενόμενον τῇ μητρὶ ὀργισθείς τι τῇ τούτων ἠτίμαζεν· πολὺ γὰρ δήπου μᾶλλον εἰώθασιν, ὧν ἂν ἐν αὑτοῖς διενεχθῶσιν γυνὴ καὶ ἀνήρ, διαλλάττεσθαι διὰ τοὺς παῖδας ἢ διὰ τὰς πρὸς ἑαυτοὺς ὀργὰς τοὺς κοινοὺς παῖδας πρὸς μισεῖν. ὥστε ἐὰν μὲν ἐπιχειρῇ ταῦτα λέγειν, μὴ ἐπιτρέπετε ἀναισχυντεῖν.", "st": "40.29"}, {"sp": "N", "t": "ἂν δὲ λέγῃ περὶ τῶν δικῶν ἃς ἀπεδιῄτησέν μου ὁ διαιτητής, καὶ φάσκῃ ὑπ’ ἐμοῦ ἀπαράσκευος ληφθῆναι, πρῶτον μὲν μέμνησθε ὅτι οὐκ ὀλίγος χρόνος ἐγένετο, ἐν ᾧ ἔδει παρασκευάσασθαι αὐτόν, ἀλλ’ ἔτη πολλά, ἔπειθ’ ὅτι οὗτος ἦν ὁ διώκων, ὥστε πολὺ μᾶλλον ἦν εἰκὸς ἐμὲ ὑπὸ τούτου ἀπαράσκευον ληφθῆναι ἢ τοῦτον ὑπ’ ἐμοῦ.", "st": "40.30"}, {"sp": "N", "t": "ἔτι δὲ πάντες ὑμῖν οἱ πρὸς τῷ διαιτητῇ παρόντες μεμαρτυρήκασιν ὡς οὗτος παρὼν αὐτός, ὅτε ἀπεδιῄτησέ μου ὁ διαιτητής, οὔτε ἐφῆκεν εἰς τὸ δικαστήριον ἐνέμεινέ τε τῇ διαίτῃ. καίτοι ἄτοπον δοκεῖ μοι εἶναι, εἰ οἱ μὲν ἄλλοι, ὅταν οἴωνται ἀδικεῖσθαι, καὶ τὰς πάνυ μικρὰς δίκας εἰς ὑμᾶς ἐφιᾶσιν, οὗτος δέ μοι περὶ προικὸς δίκην ταλάντου λαχών, ταύτης, ὡς αὐτός φησιν, ἀδίκως ἀποδιαιτηθείσης ἐνέμεινεν.", "st": "40.31"}, {"sp": "N", "t": "νὴ Δί’, ἀπράγμων γάρ τις ἴσως ἐστὶν ἄνθρωπος καὶ οὐ φιλόδικος. ἐβουλόμην τἄν, ὦ ἄνδρες δικασταί, τοιοῦτον αὐτὸν εἶναι. νυνὶ δὲ ὑμεῖς μὲν οὕτως ἐστὲ κοινοὶ καὶ φιλάνθρωποι, ὥστε οὐδὲ τοὺς τῶν τριάκοντα υἱεῖς φυγαδεῦσαι ἐκ τῆς πόλεως ἠξιώσατε· οὗτος δὲ ἐμοὶ μετὰ Μενεκλέους τοῦ πάντων τούτων ἀρχιτέκτονος ἐπιβουλεύσας, καὶ ἐξ ἀντιλογίας καὶ λοιδορίας πληγὰς συναψάμενος, ἐπιτεμὼν τὴν κεφαλὴν ⟨τὴν⟩ αὑτοῦ τραύματος εἰς Ἄρειον πάγον με προσεκαλέσατο, ὡς φυγαδεύσων ἐκ τῆς πόλεως.", "st": "40.32"}, {"sp": "N", "t": "καὶ εἰ μὴ Εὐθύδικος ὁ ἰατρός, πρὸς ὃν οὗτοι τὸ πρῶτον ἦλθον δεόμενοι ἐπιτεμεῖν τὴν κεφαλὴν αὐτοῦ, πρὸς τὴν ἐξ Ἀρείου πάγου βουλὴν εἶπεν τὴν ἀλήθειαν πᾶσαν, τοιαύτην ἂν δίκην οὗτος εἰλήφει παρ’ ἐμοῦ ⟨τοῦ⟩ μηδὲν ἀδικοῦντος, ἣν ὑμεῖς οὐδὲ κατὰ τῶν τὰ μέγιστ’ ἀδικούντων ὑμᾶς ἐπιχειρήσαιτ’ ἂν ποιήσασθαι. ἵνα δὲ μὴ δοκῶ διαβάλλειν αὐτόν, ἀνάγνωθί μοι τὰς μαρτυρίας.", "st": "40.33"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "40.33"}, {"sp": "N", "t": "τοῦτον μὲν τοίνυν οὕτω μέγαν καὶ φοβερὸν ἀγῶνά μοι οὐχ ὡς εὐήθης ὤν, ἀλλ’ ὡς ἐπίβουλος καὶ κακοῦργος κατεσκεύασεν. μετὰ δὲ ταῦτα ἀντὶ τοῦ ὀνόματος οὗ ἔθετο αὐτῷ ὁ πατὴρ Βοιωτόν, ὥσπερ καὶ πρὸς ὑμᾶς μεμαρτύρηται, ἐπειδὴ ἐκεῖνος ἐτελεύτησε, Μαντίθεον ἑαυτὸν ἐγγράψας εἰς τοὺς δημότας, καὶ τοῦ αὐτοῦ ἐμοὶ καὶ πατρὸς καὶ δήμου προσαγορευόμενος, οὐ μόνον τὴν δίκην ταύτην, περὶ ἧς νυνὶ δικάζομαι, ἀνάδικον ἐποίησεν, ἀλλὰ καὶ χειροτονησάντων ὑμῶν ἐμὲ ταξίαρχον, ἧκεν αὐτὸς ἐπὶ τὸ δικαστήριον δοκιμασθησόμενος, δίκην δὲ ἐξούλης ὠφληκώς, ταύτην οὐκ αὐτὸς ὠφληκέναι φησίν, ἀλλ’ ἐμέ.", "st": "40.34"}, {"sp": "N", "t": "ὡς δ’ ἐν κεφαλαίῳ εἰπεῖν, κακά μοι παρέχων ἠνάγκασέ με λαχεῖν αὑτῷ δίκην περὶ τοῦ ὀνόματος, οὐχ ἵνα χρήματα παρ’ αὐτοῦ λάβω, ὦ ἄνδρες δικασταί, ἀλλ’ ἵνα, ἐὰν ὑμῖν δοκῶ δεινὰ πάσχειν καὶ βλάπτεσθαι μεγάλα, οὑτοσὶ καλῆται Βοιωτός, ὥσπερ ὁ πατὴρ αὐτῷ ἔθετο. ὅτι τοίνυν ἀληθῆ καὶ ταῦτα λέγω, λαβέ μοι καὶ τὰς περὶ τούτων μαρτυρίας.", "st": "40.35"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "40.35"}, {"sp": "N", "t": "πρὸς τούτοις τοίνυν καὶ ὅτι ἐγὼ στρατευόμενος καὶ μετὰ Ἀμεινίου ξενολογήσας, ἄλλοθέν τε χρήματα εὐπορήσας καὶ ἐκ Μυτιλήνης παρὰ τοῦ ὑμετέρου προξένου Ἀπολλωνίδου καὶ παρὰ τῶν φίλων τῆς πόλεως λαβὼν τριακοσίους στατῆρας Φωκαιᾶς, ἀνήλωσα εἰς τοὺς στρατιώτας, ἵνα πρᾶξίς τις πραχθείη καὶ ὑμῖν καὶ ἐκείνοις συμφέρουσα,", "st": "40.36"}, {"sp": "N", "t": "περὶ τούτων μοι δικάζεται ὡς πατρικὸν κεκομισμένῳ χρέως παρὰ τῆς πόλεως τῆς Μυτιληναίων, Καμμῦ τῷ τυραννοῦντι Μυτιλήνης ὑπηρετῶν, ὃς καὶ ὑμῖν κοινῇ καὶ ἐμοὶ ἰδίᾳ ἐχθρός ἐστιν. ὅτι δὲ ὁ πατὴρ ἡμῶν, ἣν ἐψηφίσαντο αὐτῷ δωρεὰν οἱ Μυτιληναῖοι, εὐθὺς αὐτὸς ἐκομίσατο, καὶ ὡς οὐδὲν ὠφείλετο αὐτῷ χρέως ἐν Μυτιλήνῃ, τῶν ὑμετέρων φίλων παρέξομαι μαρτυρίαν.", "st": "40.37"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ.", "st": "40.37"}, {"sp": "N", "t": "ἔχων τοίνυν, ὦ ἄνδρες δικασταί, καὶ ἄλλα πολλὰ καὶ δεινὰ λέγειν, ἃ οὗτος καὶ εἰς ἐμὲ καὶ εἰς ὑμῶν ἐνίους ἡμάρτηκεν, ἀναγκάζομαι διὰ τὸ ὀλίγον εἶναί μοι τὸ ὕδωρ παραλιπεῖν. νομίζω δὲ καὶ ἐκ τούτων ὑμῖν ἱκανῶς ἐπιδεδεῖχθαι, ὡς οὐ τοῦ αὐτοῦ ἀνθρώπου ἐστίν, ἀγῶνα μέν μοι περὶ φυγῆς κατασκευάζειν καὶ δίκας οὐδὲν προσηκούσας δικάζεσθαι, πρὸς δὲ τὸν διαιτητὴν ἀπαντᾶν ἀπαράσκευον. ὥστε περὶ μὲν τούτων ἂν ἐπιχειρῇ λέγειν, οὐκ οἴομαι ὑμᾶς ἀποδέξεσθαι.", "st": "40.38"}, {"sp": "N", "t": "ἂν δὲ λέγῃ ὡς ἀξιοῦντος αὐτοῦ ἐπιτρέψαι Κόνωνι τῷ Τιμοθέου περὶ ἁπάντων ἐγὼ οὐκ ἐβουλόμην ἐπιτρέπειν, ἐνθυμεῖσθε ὡς ἐξαπατᾶν ὑμᾶς ἐπιχειρήσει. ἐγὼ γὰρ περὶ μὲν ὧν αἱ δίκαι οὔπω τέλος εἶχον, ἕτοιμος ἦν ἐπιτρέπειν καὶ Κόνωνι καὶ ἄλλῳ διαιτητῇ ἴσῳ, ὅτῳ οὗτος βούλοιτο· περὶ δὲ ὧν τρὶς πρὸς τὸν διαιτητὴν ἀπαντήσαντος τούτου καὶ ἀντιδικοῦντος ὁ μὲν διαιτητὴς ἀπέγνω μου, οὗτος δὲ [ἐν] τοῖς γνωσθεῖσιν ἐνέμεινεν, ὡς καὶ ὑμῖν μεμαρτύρηται, οὐκ ᾤμην δίκαιον εἶναι ταῦτα πάλιν ἀνάδικα γίγνεσθαι·", "st": "40.39"}, {"sp": "N", "t": "τί γὰρ ἂν ἦν πέρας ἡμῖν τοῦ διαλυθῆναι, εἰ τὰ κατὰ τοὺς νόμους διαιτηθέντα λύσας ἑτέρῳ διαιτητῇ ἐπέτρεψα περὶ τῶν αὐτῶν ἐγκλημάτων, ἄλλως τε καὶ ἀκριβῶς εἰδὼς ὅτι, εἰ καὶ πρὸς τοὺς ἄλλους μὴ ἐπιεικές ἐστιν ταῖς διαίταις ἰσχυρίζεσθαι, πρός γε τοῦτον ἁπάντων δικαιότατον ἦν οὕτως προσφέρεσθαι.", "st": "40.40"}, {"sp": "N", "t": "φέρε γάρ, εἴ τις αὐτὸν ξενίας γράψαιτο λέγων ὡς διομνύμενος ὁ πατὴρ οὐκ ἔφη τοῦτον υἱὸν αὑτοῦ εἶναι, ἔσθ’ ὅτῳ ἂν ἄλλῳ ἰσχυρίζοιτο πρὸς ταῦτα ἢ διότι τῆς μητρὸς αὐτῶν ὀμοσάσης καὶ τοῦ διαιτητοῦ καταγνόντος ἠναγκάσθη ὁ πατὴρ ἡμῶν ἐμμεῖναι τῇ διαίτῃ;", "st": "40.41"}, {"sp": "N", "t": "οὐκοῦν δεινόν, εἰ οὗτος αὐτὸς κατὰ γνῶσιν διαιτητοῦ ὑμέτερος πολίτης γεγενημένος καὶ πρὸς ἐμὲ τὴν οὐσίαν νειμάμενος καὶ τυχὼν τῶν μετρίων ἁπάντων, ἃς ἐγὼ δίκας τοῦτον ἀπέφυγον παρόντα καὶ ἀντιδικοῦντα καὶ τοῖς γνωσθεῖσιν ἐμμένοντα, ταύτας ἀναδίκους ἀξιῶν γίγνεσθαι δίκαιόν τι δοκοίη λέγειν ὑμῖν, ὥσπερ, ὅταν μὲν τούτῳ συμφέρῃ, δέον εἶναι κυρίας τὰς διαίτας, ὅταν δὲ μὴ συμφέρῃ, προσῆκον τὴν τούτου γνώμην κυριωτέραν γενέσθαι τῶν κατὰ τοὺς ὑμετέρους νόμους γνωσθέντων.", "st": "40.42"}, {"sp": "N", "t": "ὃς οὕτως ἐπίβουλός ἐστιν, ὥστε καὶ τὴν δίαιταν ταύτην ἐπιτρέπειν με προὐκαλεῖτο, οὐχ ὅπως ἀπαλλαγῇ πρός με, ἀλλ’ ἵνα, ὥσπερ καὶ πρότερον ἕνδεκα ἔτη διήγαγε κακουργῶν, οὕτως καὶ νῦν τὰ ἀποδιαιτηθέντα μου λύσας ἐξ ἀρχῆς με συκοφαντῇ καὶ τὴν δίκην ταύτην ἐκκρούῃ.", "st": "40.43"}, {"sp": "N", "t": "τεκμήριον δὲ τούτου μέγιστον· οὔτε γὰρ τὴν πρόκλησιν ἐδέχετο, ἣν ἐγὼ κατὰ τοὺς νόμους προὐκαλούμην αὐτόν, πρότερόν τε Ξενίππῳ, ὃν οὗτος προὐβάλετο διαιτητήν, ἐπιτρέψαντός μου περὶ τῆς τοῦ ὀνόματος δίκης, ἀπηγόρευσεν αὑτῷ μὴ διαιτᾶν. ὅτι δὲ καὶ ταῦτ’ ἀληθῆ λέγω, ἐκ τῆς μαρτυρίας καὶ τῆς προκλήσεως εἴσεσθε.", "st": "40.44"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ. ΠΡΟΚΛΗΣΙΣ.", "st": "40.44"}, {"sp": "N", "t": "ταύτην τοίνυν τὴν πρόκλησιν οὐ δεξάμενος, ἀλλ’ ἐνεδρεύων με καὶ τὴν δίκην ὅτι πλεῖστον χρόνον ἐκκρούειν βουλόμενος, κατηγορήσει, ὡς ἐγὼ πυνθάνομαι, οὐ μόνον ἐμοῦ, ἀλλὰ καὶ τοῦ πατρός, λέγων ὡς ἐκεῖνος ἐμοὶ χαριζόμενος πολλὰ τοῦτον ἠδίκησεν. ὑμεῖς δ’, ὦ ἄνδρες δικασταί, μάλιστα μέν, ὥσπερ αὐτοὶ οὐκ ἂν ἀξιώσαιτε κακῶς ἀκούειν ὑπὸ τῶν ὑμετέρων παίδων, οὕτω μηδὲ τούτῳ ἐπιτρέπετε περὶ τοῦ πατρὸς βλασφημεῖν·", "st": "40.45"}, {"sp": "N", "t": "καὶ γὰρ ἂν εἴη δεινόν, εἰ αὐτοὶ μὲν πρὸς τοὺς ἐπὶ τῆς ὀλιγαρχίας πολλοὺς τῶν πολιτῶν ἀκρίτους ἀποκτείναντας διαλλαγέντες ἐμμένετε ταῖς ὁμολογίαις, ὥσπερ χρὴ τοὺς καλοὺς κἀγαθοὺς ἄνδρας, τούτῳ δὲ πρὸς τὸν πατέρα ζῶντα καὶ διαλυθέντι καὶ πολλὰ παρὰ τὸ δίκαιον πλεονεκτήσαντι νῦν μνησικακεῖν ἐπιτρέψετε καὶ κακῶς λέγειν ἐκεῖνον.", "st": "40.46"}, {"sp": "N", "t": "μηδαμῶς, ὦ ἄνδρες δικασταί, ἀλλὰ μάλιστα μὲν κωλύετε αὐτὸν ταῦτα ποιεῖν, ἂν δ’ ἄρα βιάζηται ὑμᾶς καὶ λοιδορῆται, ἐνθυμεῖσθε ὅτι αὐτὸς ἑαυτοῦ καταμαρτυρεῖ μὴ ἐξ ἐκείνου γεγενῆσθαι. οἱ μὲν γὰρ φύσει παῖδες ὄντες, κἂν πρὸς ζῶντας τοὺς πατέρας διενεχθῶσιν, ἀλλ’ οὖν τελευτήσαντας αὐτοὺς ἐπαινοῦσιν· οἱ δὲ νομιζόμενοι μὲν υἱεῖς, μὴ ὄντες δὲ γένει ἐξ ἐκείνων, ῥᾳδίως μὲν αὐτοῖς διαφέρονται ζῶσιν, οὐδὲν δὲ φροντίζουσι περὶ τεθνεώτων αὐτῶν βλασφημοῦντες.", "st": "40.47"}, {"sp": "N", "t": "χωρὶς δὲ τούτων ἐνθυμεῖσθε ὡς ἄτοπόν ἐστιν, εἰ οὗτος τὸν πατέρα ὡς ἁμαρτόντα εἰς αὑτὸν λοιδορήσει, διὰ τὰ ἐκείνου ἁμαρτήματα ὑμέτερος πολίτης γεγενημένος. κἀγὼ μὲν διὰ τὴν τούτων μητέρα τὰ δύο μέρη τῆς οὐσίας ἀφαιρεθείς, ὅμως ὑμᾶς αἰσχύνομαι λέγειν περὶ ἐκείνης τι φλαῦρον·", "st": "40.48"}, {"sp": "N", "t": "οὗτος δ’, ὃν ἠνάγκασεν αὑτῷ πατέρα γενέσθαι, τοῦτον οὐκ αἰσχύνεται ψέγων ἐναντίον ὑμῶν, ἀλλ’ εἰς τοῦτο ἀμαθίας ἥκει, ὥστε τῶν νόμων ἀπαγορευόντων μηδὲ τοὺς τῶν ἄλλων πατέρας κακῶς λέγειν τεθνεῶτας, οὗτος, οὗ φησιν υἱὸς εἶναι, τοῦτον λοιδορήσει, ᾧ προσῆκεν καὶ εἴ τις ἄλλος ἐβλασφήμει περὶ αὐτοῦ ἀγανακτεῖν.", "st": "40.49"}, {"sp": "N", "t": "οἴομαι δ’ αὐτόν, ὦ ἄνδρες δικασταί, ἐπειδὰν τῶν ἄλλων ἀπορῇ, κακῶς τέ με ἐπιχειρήσειν λέγειν καὶ διαβάλλειν πειράσεσθαι, διεξιόνθ’ ὡς ἐγὼ μὲν καὶ ἐτράφην καὶ ἐπαιδεύθην καὶ ἔγημα ἐν τῇ τοῦ πατρὸς οἰκίᾳ, αὐτὸς δὲ οὐδενὸς τούτων μετέσχεν. ὑμεῖς δ’ ἐνθυμεῖσθ’ ὅτι ἐμὲ μὲν ἡ μήτηρ παῖδα καταλιποῦσα ἐτελεύτησεν, ὥστε μοι ἱκανὸν ἦν ἀπὸ τοῦ τόκου τῆς προικὸς καὶ τρέφεσθαι καὶ παιδεύεσθαι·", "st": "40.50"}, {"sp": "N", "t": "ἡ δὲ τούτων μήτηρ Πλαγγών, τρέφουσα μεθ’ αὑτῆς τούτους καὶ θεραπαίνας συχνὰς καὶ αὐτὴ πολυτελῶς ζῶσα, καὶ εἰς ταῦτα τὸν πατέρα τὸν ἐμὸν χορηγὸν ἑαυτῇ ὑπὸ τῆς ἐπιθυμίας ἔχουσα καὶ πολλὰ δαπανᾶν ἀναγκάζουσα, οὐκ ἴσα δήπου τῆς ἐκείνου οὐσίας ἐμοὶ ἀνήλωκεν, ὥστε πολὺ μᾶλλον προσήκει ἐμὲ τούτοις ἐγκαλεῖν ἢ αὐτὸν ἐγκλήματ’ ἔχειν ὑπὸ τούτων.", "st": "40.51"}, {"sp": "N", "t": "ὃς πρὸς τοῖς ἄλλοις εἴκοσι μὲν μνᾶς δανεισάμενος μετὰ τοῦ πατρὸς παρὰ Βλεπαίου τοῦ τραπεζίτου εἰς ὠνήν τινα μετάλλων, ἐπειδὴ ὁ πατὴρ ἐτελεύτησεν, τὰ μὲν μέταλλα πρὸς τούτους ἐνειμάμην, τὸ δάνειον δ’ αὐτὸς εἰσεπράχθην, ἑτέρας δὲ χιλίας εἰς τὴν τοῦ πατρὸς ταφὴν παρὰ Λυσιστράτου Θορικίου δανεισάμενος ἰδίᾳ ἐκτέτεικα. ὡς δ’ ἀληθῆ καὶ ταῦτα λέγω, ἐκ τούτων τῶν μαρτυριῶν εἴσεσθε.", "st": "40.52"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ.", "st": "40.52"}, {"sp": "N", "t": "τοσαῦτα τοίνυν ἐμοῦ ἐλαττουμένου φανερῶς, οὑτοσὶ νῦν σχετλιάζων καὶ δεινοπαθῶν καὶ τὴν προῖκά με τῆς μητρὸς ἀποστερήσει; ἀλλ’ ὑμεῖς, ὦ ἄνδρες δικασταί, πρὸς Διὸς καὶ θεῶν, μὴ καταπλαγῆτε ὑπὸ τῆς κραυγῆς τῆς τούτου· πολὺς γάρ, πολὺς καὶ τολμηρός ἐστιν ἅνθρωπος, καὶ οὕτως κακοῦργος, ὥστε περὶ ὧν ἂν μὴ ἔχῃ μαρτυρίας παρασχέσθαι, ταῦτα φήσει ὑμᾶς εἰδέναι, ὦ ἄνδρες δικασταί, ὃ πάντες ποιοῦσιν οἱ μηδὲν ὑγιὲς λέγοντες.", "st": "40.53"}, {"sp": "N", "t": "ὑμεῖς οὖν, ἐάν τι τοιοῦτον τεχνάζῃ, μὴ ἐπιτρέπετε αὐτῷ, ἀλλ’ ἐξελέγχετε, καὶ ὅ τι ἂν μὴ ἕκαστος ὑμῶν εἰδῇ, μηδὲ τὸν πλησίον δοκιμαζέτω εἰδέναι, ἀλλ’ ἀξιούτω τοῦτον ἀποδεικνύναι σαφῶς ὑπὲρ ὧν ἂν λέγῃ, καὶ μὴ ὑμᾶς φάσκοντα εἰδέναι, περὶ ὧν αὐτὸς οὐδὲν ἕξει εἰπεῖν δίκαιον, ἀποδιδράσκειν τὴν ἀλήθειαν, ἐπεὶ καὶ ἐγώ, ὦ ἄνδρες δικασταί, πάντων ὑμῶν εἰδότων ὃν τρόπον ἀναγκασθεὶς ὁ πατήρ μου ἐποιήσατο τούτους, οὐδὲν ἧττον δικάζομαι νῦν αὐτοῖς καὶ μάρτυρας ὑποδίκους παρέσχημαι.", "st": "40.54"}, {"sp": "N", "t": "καίτοι οὐκ ἴσος γ’ ἡμῖν ἐστιν ὁ κίνδυνος, ἀλλ’ ἐμοὶ μέν, ἐὰν ὑμεῖς νυνὶ ὑπὸ τούτων ἐξαπατηθῆτε, οὐκ ἐξέσται ἔτι δικάσασθαι περὶ τῆς προικός· τούτοις δ’, εἰ φασὶν ἀδίκως ἀποδιαιτῆσαί μου τὸν διαιτητὴν τὰς δίκας, καὶ τότ’ ἐξῆν εἰς ὑμᾶς ἐφεῖναι καὶ νῦν ἐγγενήσεται πάλιν, ἐὰν βούλωνται, παρ’ ἐμοῦ λαβεῖν ἐν ὑμῖν τὸ δίκαιον.", "st": "40.55"}, {"sp": "N", "t": "καὶ ἐγὼ μέν, ἐάν, ὃ μὴ γένοιτο, ὑμεῖς με ἐγκαταλίπητε, οὐχ ἕξω ὁπόθεν προῖκα ἐπιδῶ τῇ θυγατρί, ἧς τῇ μὲν φύσει πατήρ εἰμι, τὴν δ’ ἡλικίαν αὐτῆς εἰ ἴδοιτε, οὐκ ἂν θυγατέρα μου ἀλλ’ ἀδελφὴν εἶναι αὐτὴν νομίσαιτε· οὗτοι δέ, ἐὰν ὑμεῖς μοι βοηθήσητε, οὐδὲν ἐκ τῶν ἰδίων ἀποτείσουσιν, ἀλλ’ ἐκ τῆς οἰκίας τὰ ἐμὰ ἐμοὶ ἀποδώσουσιν, ἣν ἐξειλόμεθα μὲν κοινῇ πάντες εἰς τὴν ἔκτεισιν τῆς προικός, οἰκοῦντες δὲ αὐτὴν οὗτοι μόνοι διατελοῦσιν.", "st": "40.56"}, {"sp": "N", "t": "οὔτε γὰρ ἁρμόττει μοι θυγατέρα ἐπίγαμον ἔχοντι οἰκεῖν μετὰ τοιούτων, οἳ οὐ μόνον αὐτοὶ ἀσελγῶς ζῶσιν, ἀλλὰ καὶ ὁμοίους αὑτοῖς ἑτέρους πολλοὺς εἰς τὴν οἰκίαν εἰσάγουσιν, οὔτε μὰ τὸν Δία ἀσφαλὲς εἶναί μοι νομίζω συζῆν τούτοις ἐν τῷ αὐτῷ· ὅπου γὰρ οὕτω φανερῶς μοι ἐπιβουλεύσαντες εἰς Ἄρειον πάγον ἀγῶνα κατεσκεύασαν, τίνος ἂν οὗτοι ἢ φαρμακείας ἢ ἄλλης κακουργίας τοιαύτης ὑμῖν ἀποσχέσθαι δοκοῦσιν;", "st": "40.57"}, {"sp": "N", "t": "οἵ γε πρὸς τοῖς ἄλλοις (ἀρτίως γὰρ καὶ τοῦτο ἀνεμνήσθην) εἰς τοσαύτην ὑπερβολὴν τόλμης ἥκουσιν, ὥστε καὶ Κρίτωνος μαρτυρίαν ἐνεβάλοντο, ὡς ἐώνηται τὸ τρίτον παρ’ ἐμοῦ μέρος τῆς οἰκίας· ἥν, ὅτι ψευδής ἐστι, ῥᾳδίως εἴσεσθε. πρῶτον μὲν γὰρ οὐχ οὕτω μετρίως ζῇ Κρίτων ὥστε παρ’ ἑτέρου οἰκίαν ὠνεῖσθαι, ἀλλ’ οὕτως πολυτελῶς καὶ ἀσώτως ὥστε πρὸς τοῖς ἑαυτοῦ καὶ τὰ τῶν ἄλλων ἀναλίσκειν· ἔπειτα οὐ μαρτυρεῖ τούτῳ νῦν, ἀλλ’ ἐμοὶ ἀντιδικεῖ· τίς γὰρ ὑμῶν οὐκ οἶδεν ὅτι μάρτυρες μέν εἰσιν οὗτοι, οἷς μὴ μέτεστι τοῦ πράγματος περὶ οὗ ἡ δίκη ἐστίν, ἀντίδικοι δ’ οἱ κοινωνοῦντες τῶν πραγμάτων περὶ ὧν ἂν δικάζηταί τις αὐτοῖς; ὃ Κρίτωνι συμβέβηκεν.", "st": "40.58"}, {"sp": "N", "t": "ἔτι δὲ τοσούτων ὑμῶν ὄντων, ὦ ἄνδρες δικασταί, καὶ τῶν ἄλλων Ἀθηναίων [πολλῶν], ἄλλος μὲν οὐδεὶς αὐτῷ παραγενέσθαι μεμαρτύρηκε, Τιμοκράτης δὲ μόνος, ὥσπερ ἀπὸ μηχανῆς, μαρτυρεῖ μὲν δεκάτην ἑστιᾶσαι τούτῳ τὸν ἐμὸν πατέρα, ἡλικιώτης ὢν τοῦ νυνὶ φεύγοντος τὴν δίκην, φησὶν δὲ πάντα ἁπλῶς εἰδέναι ἃ δὴ τούτοις συμφέρει, μαρτυρεῖ δὲ νυνὶ μόνος Κρίτωνι παρεῖναι, ὅτε παρ’ ἐμοῦ τὴν οἰκίαν ἐωνεῖτο. ὃ τίς ἂν ὑμῶν πιστεύσειεν; ἄλλως τε καὶ ὅτι οὐ περὶ τῆς οἰκίας, πότερα ἐώνηται Κρίτων αὐτὴν ἢ μή, νυνὶ δικάζομαι, ἀλλὰ περὶ προικός, ἣν ἐνεγκαμένης τῆς μητρὸς οἱ νόμοι κελεύουσιν ἐμὲ κομίζεσθαι.", "st": "40.59"}, {"sp": "N", "t": "ὥστε καθάπερ ὑμῖν ἐγὼ καὶ ἐκ μαρτύρων πολλῶν καὶ ἐκ τεκμηρίων ἐπέδειξα, ἐπενεγκαμένην μὲν τὴν μητέρα μου τάλαντον προῖκα, οὐ κομισάμενον δὲ τοῦτ’ ἐμὲ ἐκ τῆς πατρῴας οὐσίας, ἐξαίρετον δ’ ἡμῖν γενομένην τὴν οἰκίαν εἰς ταῦτα, οὕτω κελεύετε καὶ τοῦτον ἐπιδεικνύναι ὑμῖν, ἢ ὡς οὐκ ἀληθῆ λέγω, ἢ ὡς οὐ προσήκει μοι κομίσασθαι τὴν προῖκα· περὶ τούτων γὰρ ὑμεῖς νυνὶ τὴν ψῆφον οἴσετε.", "st": "40.60"}, {"sp": "N", "t": "ἐὰν δὲ μὴ ἔχων περὶ ὧν φεύγει τὴν δίκην μήτε μάρτυρας ἀξιόχρεως παρασχέσθαι μήτ’ ἄλλο πιστὸν μηδέν, ἑτέρους παρεμβάλλῃ λόγους κακουργῶν, καὶ βοᾷ καὶ σχετλιάζῃ μηδὲν πρὸς τὸ πρᾶγμα, πρὸς Διὸς καὶ θεῶν μὴ ἐπιτρέπετε αὐτῷ, ἀλλὰ βοηθεῖτέ μοι τὰ δίκαια, ἐξ ἁπάντων τῶν εἰρημένων ἐνθυμούμενοι, ὅτι πολὺ δικαιότερόν ἐστι τὴν τῆς ἐμῆς μητρὸς προῖκα τῇ ἐμῇ θυγατρὶ εἰς ἔκδοσιν ὑμᾶς ψηφίσασθαι, ἢ Πλαγγόνα καὶ τούτους πρὸς τοῖς ἄλλοις καὶ τὴν οἰκίαν τὴν εἰς τὴν προῖκα ἐξαίρετον γενομένην ἀφελέσθαι ἡμᾶς παρὰ πάντα τὰ δίκαια.", "st": "40.61"}], []);})();
